// 자동 생성 파일 — 고치지 마세요. 원본: chrome-extension/*/shared, 만들기: node studio-app/scripts/sync-ext.mjs
// 공실뉴스 스튜디오 앱이 로그인 뒤 /api/studio/prompts 로 받아 메모리에만 두는 확장 파일 묶음 (서버 전용)
export const STUDIO_EXT_VERSION = "59c9c8caa7b2";
export const STUDIO_EXT_FILES: Record<string, string> = {
 "gongsil/prompt.js": "/* ══════════════════════════════════════════════════════════════\n   공실뉴스 전용 프롬프트 — 기사 기본틀은 여기 한 곳에만 있다\n\n   일반 매물과 경매·공매 물건을 함께 쓴다. 경매·공매 물건은 서버에서 받을 때\n   saleKind(\"경매\"·\"공매\")가 붙어 오므로, 그것으로 어느 지시문을 쓸지 가른다.\n   ══════════════════════════════════════════════════════════════ */\n\n/* 경매·공매 물건인가 */\nfunction gwIsAuction(v) {\n  return Boolean(v && v.saleKind);\n}\n\n/* ── 매물 정보를 프롬프트에 넣을 줄로 만든다 ──\n   상세 표는 매물 종류마다 항목이 다르다. 그래서 정해진 목록을 쓰지 않고\n   화면에서 읽어온 것을 순서 그대로 전부 넘긴다.\n   값이 없는 항목은 아예 쓰지 않는다 — AI 가 빈칸을 상상하지 않도록. */\nfunction gwFactLines(v) {\n  const lines = [];\n  const seen = new Set();\n\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  if (gwIsAuction(v)) {\n    push(\"물건\", v.title);\n    push(\"가격 요약\", v.priceText);\n    for (const f of v.fields || []) push(f.label, f.value);\n    return lines.join(\"\\n\");\n  }\n\n  push(\"매물\", v.title);\n  push(\"금액\", v.priceText);\n  for (const f of v.fields || []) push(f.label, f.value);\n  push(\"특징\", Array.isArray(v.themes) ? v.themes.join(\" \") : v.themes);\n  push(\"주변환경\", v.infra);\n\n  return lines.join(\"\\n\");\n}\n\n/* 표에서 라벨로 값 하나 꺼내기 */\nfunction gwField(v, ...labels) {\n  for (const want of labels) {\n    const hit = (v.fields || []).find((f) => f.label === want);\n    if (hit) return hit.value;\n  }\n  return \"\";\n}\n\n/* 기사 본문에 넣을 매물 표기 이름 */\nfunction gwSubjectName(v) {\n  if (gwIsAuction(v)) {\n    return (\n      (v.title && v.title.trim()) ||\n      gwField(v, \"물건명\", \"소재지(지번)\", \"소재지\") ||\n      \"해당 물건\"\n    );\n  }\n  return (\n    (v.title && v.title.trim()) ||\n    gwField(v, \"단지명\", \"건물명\", \"소재지\") ||\n    \"해당 매물\"\n  );\n}\n\n/* ══════════════════════════════════════════════════════════════\n   수정 요청 — 같은 대화에 이어 붙인다\n\n   매물 정보를 다시 설명하지 않는다. AI 가 앞서 쓴 기사를 기억하고 있다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildRevisePrompt(request, vacancy) {\n  const keep = gwIsAuction(vacancy)\n    ? `- [물건 정보]에 있던 조건(감정가·최저입찰가·유찰 횟수·입찰 일정·면적·주소·관리번호)은 바꾸거나 새로 만들지 마십시오.\n- 투자 권유, 낙찰가·수익 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문은 넣지 마십시오.`\n    : \"- [매물 정보]에 있던 매물 조건(면적·금액·층·주소·번호)은 바꾸거나 새로 만들지 마십시오.\";\n  return `위에서 작성한 기사를 아래 요청대로 고쳐 주십시오.\n\n요청: ${request}\n\n[지킬 것]\n${keep}\n- 그 밖에는 요청하신 대로 자유롭게 고치십시오.\n  분량을 늘리라고 하면 실제로 그만큼 늘리십시오. 앞서 드린 분량 지시는 이 요청으로 대체됩니다.\n- 설명이나 인사말 없이, 고친 기사 전체를 처음과 똑같은 JSON 형식으로\n  \\`\\`\\`json 코드블록 하나에 다시 출력하십시오.\n- body는 문자열 하나가 아니라 문단별 문자열 배열입니다. 배열 항목 하나에 문단 하나만 넣으십시오.\n- 배열 항목 안에 실제 줄바꿈을 넣지 말고, 후행 쉼표 없이 JSON.parse가 가능한 유효한 JSON인지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"subtitle1\": \"\",\n  \"subtitle2\": \"\",\n  \"subtitle3\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   기사 이미지 만들기\n\n   기사 본문에 밀착한 장면을 요구하되, 작업창에서 스타일이나 기사 일부를\n   직접 지정할 수 있다. 입력이 없으면 AI 가 본문에서 핵심 장면을 고른다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_IMAGE_STYLE = {\n  news: {\n    label: \"보도 실사\",\n    prompt: \"한국 언론사의 현장 취재 사진처럼 자연스럽고 사실적인 장면. 과장 없는 담담한 조명과 구도.\",\n  },\n  building: {\n    label: \"건물 전경\",\n    prompt: \"건물의 전체 외관과 출입 동선이 잘 보이는 넓은 구도. 정면 또는 자연스러운 3/4 시점의 사실적인 건축 보도사진.\",\n  },\n  area: {\n    label: \"거리·상권\",\n    prompt: \"건물 하나보다 도로, 보행 환경, 주변 건물과 상권의 분위기가 함께 드러나는 넓은 현장 보도사진.\",\n  },\n  animation: {\n    label: \"애니메이션 일러스트\",\n    prompt: \"부동산 경제 기사에 어울리는 세련된 애니메이션풍 편집 일러스트. 특정 작품이나 작가의 화풍을 모방하지 말고 독창적으로 표현.\",\n  },\n  infographic: {\n    label: \"통계 도표·인포그래픽\",\n    prompt: \"경제 기사에 쓰는 깔끔한 데이터 인포그래픽. 확인된 숫자만 시각화하고, 비교 자료가 없으면 추세나 비교 그래프를 만들지 말고 핵심 수치 카드 형태로 구성.\",\n  },\n};\n\nfunction gwBuildImagePrompt(vacancy, article, opts) {\n  const o = opts || {};\n  const auction = gwIsAuction(vacancy);\n  const subject = vacancy ? gwSubjectName(vacancy) : \"해당 매물\";\n  const where = !vacancy ? \"\"\n    : auction ? gwField(vacancy, \"소재지(지번)\", \"소재지(도로명)\", \"소재지\")\n    : gwField(vacancy, \"소재지\");\n  const kind = !vacancy ? \"\"\n    : auction ? gwField(vacancy, \"물건종류\", \"용도분류\")\n    : gwField(vacancy, \"매물종류\", \"용도구분\", \"주용도\");\n  const style = GW_IMAGE_STYLE[o.style] || GW_IMAGE_STYLE.news;\n  const customStyle = String(o.customStyle || \"\").trim();\n  const request = String(o.request || \"\").trim();\n  const articleText = [article && article.title, article && article.body]\n    .filter(Boolean)\n    .join(\"\\n\")\n    .trim();\n  const focus = (request || articleText || subject).slice(0, 1600);\n  const noun = auction ? \"물건\" : \"매물\";\n  const facts = vacancy ? gwFactLines(vacancy) : `- 확인된 ${noun} 정보 없음`;\n  const focusRule = request\n    ? \"아래 사용자의 장면 묘사 지시와 기사 문장을 충실히 반영하여 장면을 연출하십시오.\"\n    : \"아래 기사 내용에서 가장 시각적으로 전달력이 높은 한 가지 핵심을 스스로 골라 장면으로 만드십시오.\";\n  /* 화풍을 직접 쓰면 글자 없는 그림으로 — 예전에 고른 통계 도표가 남아 글자가 들어가지 않게 */\n  const textRule = o.style === \"infographic\" && !customStyle\n    ? \"- 한글 문구는 꼭 필요한 짧은 항목명만 쓰고, 숫자와 단위는 아래 확인된 사실과 정확히 일치시킬 것\"\n    : \"- 이미지 안에 글자, 숫자, 로고, 워터마크를 넣지 말 것\";\n\n  const styleSection = customStyle\n    ? `[선택한 화풍·스타일]\\n사용자 직접 지정 화풍: \"${customStyle}\"\\n- 사용자가 원하는 위 화풍·스타일과 시각적 분위기를 1순위로 엄격히 적용하여 표현하십시오.`\n    : `[선택한 화풍·스타일]\\n${style.label}\\n${style.prompt}`;\n\n  return `위 기사에 넣을 이미지 1장을 만들어 주십시오.\n\n${styleSection}\n\n[이미지로 표현할 장면]\n${focusRule}\n${focus}\n\n[확인된 ${noun} 사실]\n${facts}\n\n[기본 장면 정보]\n- 대상: ${subject}${kind ? ` (${kind})` : \"\"}\n- 위치: ${where || \"대한민국 도심\"}\n- 기사 제목: ${(article && article.title) || \"\"}\n\n[조건]\n- ${o.ratio || \"가로 16:9\"} 비율\n- 위 확인된 사실에 없는 숫자, 통계, 건물명, 업체명, 시설을 만들지 말 것\n- 비교 수치나 증감률이 없으면 임의의 그래프, 비율, 순위를 만들지 말 것\n${textRule}\n- 사람 얼굴과 존재하지 않는 상호·간판 이름을 넣지 말 것\n- 사용자가 지정한 화풍과 시각적 스타일을 최우선으로 반영하되, 사실 정보와 충돌하면 사실을 우선할 것\n\n이미지 1장만 출력하고 설명은 붙이지 마십시오.`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   분량과 기사 스타일 — 작업창에서 고른다\n\n   예전에는 \"600~900자\"가 코드에 박혀 있어, 사장님이 3,000자를 요청해도\n   먼저 준 지시가 이겼다. 이제 여기서 고른 것이 프롬프트로 간다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_LENGTH = {\n  short:  { label: \"짧게\",  chars: \"700~1,000자\",   paras: \"4~5개\",   sections: \"3~4개\" },\n  normal: { label: \"보통\",  chars: \"1,400~1,800자\", paras: \"7~9개\",   sections: \"5~6개\" },\n  long:   { label: \"길게\",  chars: \"2,800~3,500자\", paras: \"12~16개\", sections: \"7~9개\" },\n};\n\nconst GW_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief:\n      \"현재 방식처럼 도입부터 결론까지 문단이 자연스럽게 이어지는 뉴스 기사입니다. \" +\n      \"매물 조건과 지역·수요·계약 전 확인 사항을 기사 흐름 안에서 풀어 주십시오.\",\n    subs: \"1) 입지와 교통  2) 면적·구조  3) 거래 조건\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief:\n      \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 \" +\n      \"독자가 내용을 빠르게 훑어볼 수 있게 작성하십시오.\",\n    subs: \"1) 핵심 매물 조건  2) 입지와 수요  3) 계약 전 확인 사항\",\n  },\n};\n\n/* 경매·공매 물건일 때의 기사 스타일 — 이름은 같고 설명·부제 구성만 다르다 */\nconst GW_AUCTION_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief:\n      \"도입부터 결론까지 문단이 자연스럽게 이어지는 경매·공매 뉴스 기사입니다. \" +\n      \"가격 조건과 물건 현황, 지역, 입찰 일정과 입찰 전 확인할 점을 기사 흐름 안에서 풀어 주십시오.\",\n    subs: \"1) 가격 — 감정가·최저입찰가·유찰  2) 물건 현황과 입지  3) 입찰 일정·방법\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief:\n      \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 \" +\n      \"독자가 내용을 빠르게 훑어볼 수 있게 작성하십시오.\",\n    subs: \"1) 핵심 가격 조건  2) 물건 현황과 입지  3) 입찰 일정과 확인할 점\",\n  },\n};\n\n/* 소제목 기사 본문 규칙 — 일반·경매 공통 */\nfunction gwBodyStyle(o, len) {\n  return o.kind === \"summary\"\n    ? `- 첫 문단은 소제목 없이 기사 전체 핵심을 요약한 리드문으로 쓰십시오.\n- 그 다음부터는 반드시 \"■ 소제목\"을 한 줄에 단독으로 쓰고, 바로 다음 줄에 해당 내용을 설명하는 문단을 쓰십시오.\n- \"■ 소제목 + 설명 문단\" 묶음을 ${len.sections}로 구성하십시오.\n- 소제목 앞에는 정확히 ■ 기호 하나만 쓰십시오. ##, 번호, 불릿 목록, 굵은 글씨 표시는 쓰지 마십시오.`\n    : `- 일반 뉴스 기사처럼 도입부터 결론까지 자연스러운 문단으로 이어 쓰십시오.\n- 본문 중간에 소제목, ■ 기호, 번호, 불릿 목록을 넣지 마십시오.`;\n}\n\n/* 기사 JSON 출력 형식 — 일반·경매 공통 */\nconst GW_ARTICLE_OUTPUT = `[출력 형식]\n설명이나 인사말 없이, 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 반드시 JSON 배열이어야 하며, 각 문단과 \"■ 소제목\" 한 줄을 각각 별도 문자열 항목으로 넣으십시오.\n- 문자열 항목 안에 실제 줄바꿈을 넣지 마십시오. 문단 구분은 배열 항목으로만 표현하십시오.\n- 모든 문자열은 큰따옴표로 감싸고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한 유효한 JSON인지 괄호와 쉼표를 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"subtitle1\": \"\",\n  \"subtitle2\": \"\",\n  \"subtitle3\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n\n/* ══════════════════════════════════════════════════════════════\n   기사 작성 프롬프트\n\n   핵심은 두 구역을 가르는 것이다.\n   - 사실 구역: 표에 있는 것만. 지어내면 표시광고 문제가 된다\n   - 해설 구역: 기자가 아는 일반 지식으로 쓴다. 여기가 AI 를 쓰는 값어치다\n\n   전에는 둘 다 막아 놔서 AI 가 표를 문장으로 옮겨 적는 일밖에 못 했다.\n   경매·공매 물건은 아래 gwBuildAuctionPrompt 로 넘긴다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildPrompt(v, opts) {\n  if (gwIsAuction(v)) return gwBuildAuctionPrompt(v, opts);\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = GW_KIND[o.kind] || GW_KIND.news;\n  const facts = gwFactLines(v);\n  const subject = gwSubjectName(v);\n  const bodyStyle = gwBodyStyle(o, len);\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경제 담당 기자입니다.\n아래 매물을 소재로 기사 1건을 작성하십시오.\n\n[매물 정보 — 확인된 사실]\n${facts}\n\n════════ 두 구역을 구분해서 쓰십시오 ════════\n\n【사실 구역】 위 [매물 정보]에 적힌 것\n- 면적·금액·층수·방·주소·번호·관리비 등 이 매물의 조건은\n  한 글자도 바꾸거나 더하지 마십시오.\n- 위에 없는 항목(준공연도·옵션·주차 등)을 추측해 채우지 마십시오.\n  없으면 그 이야기를 아예 하지 마십시오.\n- 소재지가 시·군·동까지만 주어졌다면 기사도 거기까지만 쓰십시오.\n\n【해설 구역】 기자로서 쓰는 부분   ★ 기사 분량의 절반 이상을 여기에 쓰십시오\n당신이 아는 일반 지식으로 자유롭게 쓰십시오.\n- 이 지역이 어떤 곳인지 — 업무지구·학군·상권·교통의 성격, 동네 분위기\n- 위 조건들이 실제로 무엇을 뜻하는지 — 이 면적과 구조가 어떤 쓰임에 맞는지\n- 어떤 임차인·수요자에게 맞는 물건인지, 반대로 누구에게는 맞지 않는지\n- 이런 조건의 물건을 볼 때 계약 전 확인해야 할 점\n- 같은 종류의 물건을 고를 때 쓰는 일반적인 판단 기준\n\n해설 구역에서도 다음은 금지합니다.\n- 구체적 수치 예측 — \"3년 내 20% 상승\", \"수익률 6% 예상\"\n- 단정 — \"확실하다\", \"보장된다\", \"반드시 오른다\"\n- 이 매물의 스펙이나 가격을 지어내기\n- 실재하지 않는 단지명·업체명·기관명을 만들어 쓰기\n- 특정 시점의 시세 수치를 아는 것처럼 쓰기\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 【해설 구역】을 더 쓰십시오.\n  매물 스펙을 다시 늘어놓아 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했습니다\" 아닌 \"~했다\")\n- 매물은 \"${subject}\"로 지칭\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [공실열람 보도] 로 시작\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${kind.subs}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${bodyStyle}\n              마지막 문단은 \"자세한 내용은 공실뉴스 공실열람에서 확인할 수 있다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·매물종류·거래구분을 포함할 것\n\n${GW_ARTICLE_OUTPUT}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 기사 작성 프롬프트\n\n   두 구역을 가른다.\n   - 사실 구역: 서버에서 받은 물건 정보에 있는 것만. 가격·일정을 지어내면 큰 사고다\n   - 해설 구역: 경매·공매 제도와 지역에 대한 기자의 일반 지식\n   투자 권유·낙찰가 예측은 어느 구역에서도 쓰지 않는다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildAuctionPrompt(v, opts) {\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = GW_AUCTION_KIND[o.kind] || GW_AUCTION_KIND.news;\n  const facts = gwFactLines(v);\n  const subject = gwSubjectName(v);\n  const saleKind = v && v.saleKind === \"경매\" ? \"경매\" : \"공매\";\n  const saleName = saleKind === \"공매\" ? \"공매(온비드)\" : \"법원 경매\";\n  const bodyStyle = gwBodyStyle(o, len);\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경매·공매 담당 기자입니다.\n아래 ${saleName} 물건을 소재로 기사 1건을 작성하십시오.\n\n[물건 정보 — 확인된 사실]\n${facts}\n\n════════ 두 구역을 구분해서 쓰십시오 ════════\n\n【사실 구역】 위 [물건 정보]에 적힌 것\n- 감정가·최저입찰가·감정가 대비 비율·유찰 횟수·입찰 시작/마감·개찰일시·입찰보증금·면적·주소·관리번호(사건번호)·공고번호·집행기관은\n  한 글자도 바꾸거나 더하지 마십시오. 금액은 원 단위 숫자와 억·만원 표기가 일치해야 합니다.\n- 위에 없는 항목(권리관계·임차인·선순위 채권·체납액·건물 연식 등)을 추측해 채우지 마십시오.\n  없으면 그 이야기를 아예 하지 마십시오.\n- 소재지가 주어진 범위까지만 쓰십시오.\n- 입찰 일정이 없으면 날짜를 만들지 마십시오.\n\n【해설 구역】 기자로서 쓰는 부분   ★ 기사 분량의 절반 가까이를 여기에 쓰십시오\n당신이 아는 일반 지식으로 쓰십시오.\n- 이 지역이 어떤 곳인지 — 업무지구·학군·상권·교통의 성격\n- 이 물건 종류와 면적이 일반적으로 어떤 쓰임에 맞는지\n- ${saleKind} 제도의 일반 설명 — 유찰되면 최저입찰가가 어떻게 낮아지는지, 입찰보증금, 개찰 절차, 명도의 의미 등\n- ${saleKind} 물건을 볼 때 일반적으로 확인하는 점 — 현장 상태, 점유·명도, 권리관계, 추가 비용(관리비 체납 등)\n\n해설 구역에서도 다음은 금지합니다.\n- 투자 권유 — \"싸게 살 기회\", \"놓치지 말아야 할\", \"적극 추천\", \"수익이 기대된다\"\n- 낙찰가·낙찰가율·수익률·시세 상승 예측\n- 단정 — \"안전한 물건이다\", \"권리상 문제가 없다\", \"반드시 낙찰된다\"\n- 이 물건의 조건이나 가격을 지어내기\n- 실재하지 않는 단지명·업체명·기관명을 만들어 쓰기\n\n[넣지 말 것]\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호)\n- \"본 정보는 참고용 데이터이며… 법적 책임을 지지 않습니다\" 같은 입찰 전 법적 주의사항 안내문\n  (단, 마지막 문단의 한 줄 확인 문구는 아래 [구성]대로 넣으십시오)\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 【해설 구역】을 더 쓰십시오.\n  물건 정보를 다시 늘어놓아 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했습니다\" 아닌 \"~했다\")\n- 물건은 \"${subject}\"로 지칭\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [공실열람 ${saleKind}] 로 시작. 지역·물건 종류·최저입찰가(또는 유찰 횟수)를 담을 것\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${kind.subs}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${bodyStyle}\n              첫 문단에 ${saleKind} 구분, 소재지, 물건 종류, 감정가와 최저입찰가를 밝힐 것\n              마지막 문단은 \"권리관계와 물건 상태는 입찰 전 공고문과 현장에서 직접 확인할 필요가 있다. 자세한 내용은 공실뉴스 공실열람 경매/공매에서 확인할 수 있다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·물건 종류·\"${saleKind}\"를 포함할 것\n\n${GW_ARTICLE_OUTPUT}`;\n}\n",
 "gongsil/blog-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   네이버 블로그 초안 전용 프롬프트\n\n   기사 작성 프롬프트와 분리한다. 블로그에서 스타일이나 분량을 바꿔도\n   2번 '초안 다듬기'의 기사 프롬프트에는 아무 영향이 없다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_BLOG_LENGTH = {\n  short:  { label: \"짧게\", chars: \"700~1,000자\", paras: \"5~7개\" },\n  normal: { label: \"중간\", chars: \"1,500~2,000자\", paras: \"9~12개\" },\n  long:   { label: \"길게\", chars: \"2,500~3,500자\", paras: \"14~20개\" },\n};\n\nconst GW_BLOG_STYLE = {\n  listing: {\n    label: \"기본 매물소개형\",\n    fit: \"모든 매물\",\n    titleExample: \"논현동 아크로힐스 매매 15억, 3룸 남향\",\n    guide:\n      \"깔끔하고 정보 중심으로 쓴다. 제목과 첫 문단에서 지역·매물·거래 조건을 분명히 보여 주고, \" +\n      \"본문은 핵심 조건, 입지, 내부 구성, 확인할 점의 순서로 정리한다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 3~4개, 명사형으로 짧게 (예: ■ 입지와 교통 / ■ 내부 구성 / ■ 계약 전 확인할 점). \" +\n      \"핵심 요약 → 입지 → 내부 구성 → 확인할 점 순서\",\n  },\n  visit: {\n    label: \"현장답사형\",\n    fit: \"아파트·상가·빌딩\",\n    titleExample: \"논현동 아크로힐스, 단지 안팎을 사진으로 살펴보니\",\n    guide:\n      \"현장을 차례로 둘러보는 듯한 흐름으로 쓴다. 다만 실제 방문·촬영·인터뷰를 했다고 거짓말하지 말고, \" +\n      \"제공된 기사와 사진에서 확인할 수 있는 동선과 인상만 관찰형 문장으로 풀어낸다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 3~5개, 둘러보는 동선 순서의 장소형 (예: ■ 단지 입구에서 / ■ 거실과 주방 / ■ 주변 거리). \" +\n      \"바깥에서 안으로, 다시 주변으로 이어지는 흐름\",\n  },\n  story: {\n    label: \"스토리텔링형\",\n    fit: \"주택·아파트\",\n    titleExample: \"강남에서 15억으로 찾는다면?\",\n    guide:\n      \"독자가 실제로 집이나 매물을 찾는 상황, 또는 한 가지 질문으로 시작한다. \" +\n      \"과장된 허구의 고객 사례는 만들지 말고 확인된 조건을 따라 자연스럽게 해답을 제시한다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 1~2개, 질문형 (예: ■ 15억이면 무엇을 먼저 봐야 할까?). \" +\n      \"상황 제시 → 질문 → 확인된 조건으로 해답 순서. 소제목보다 문단 흐름을 중시\",\n  },\n  report: {\n    label: \"분석·리포트형\",\n    fit: \"빌딩·토지·투자매물\",\n    titleExample: \"논현동 50억 건물, 조건을 하나씩 살펴보니\",\n    guide:\n      \"조건과 장점, 한계, 계약 전 확인 사항을 균형 있게 분석한다. \" +\n      \"확인되지 않은 수익률·시세·개발 호재를 추정하지 않는다.\",\n    design: \"news\",\n    structure:\n      \"소제목 4~5개, 명사형으로 고정 (■ 핵심 조건 / ■ 장점 / ■ 한계와 확인할 부분 / ■ 계약 전 체크포인트). \" +\n      \"각 구역은 1~2문단\",\n  },\n  consult: {\n    label: \"친근한 해설형\",\n    fit: \"실수요 매물\",\n    titleExample: \"방 3개 아파트 매물, 어떤 가구에 맞을까\",\n    guide:\n      \"매물 조건을 독자가 이해하기 쉽게 풀어 설명하는 해설 기사로 쓴다. 부드러운 존댓말은 허용하지만 \" +\n      \"권유하지 말고, 어떤 가구에 맞는 조건인지와 확인할 점을 객관적으로 짚는다.\",\n    design: \"qna\",\n    structure:\n      \"소제목 3~4개, 고객이 실제로 물어볼 질문형 (예: ■ 관리비는 얼마인가요? / ■ 주차는 가능한가요?). \" +\n      \"각 소제목 바로 다음 문단이 그 질문에 대한 답\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\",\n    fit: \"SNS 연계 매물\",\n    titleExample: \"[매물] 강남 논현동 아파트 15억 매매 등록\",\n    guide:\n      \"속보 기사처럼 첫 두 문장에 무엇이 어디에 얼마로 나왔는지를 짧게 전한다. 문장을 짧게 끊고 사실만 빠르게 전달하되, \" +\n      \"낚시성 표현·과도한 감탄·확인되지 않은 단정은 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 0~2개, 한 줄로 짧게. 강한 첫 두 문장 → 핵심 조건 3가지 → 한 줄 정리. \" +\n      \"문단은 1~2문장으로 짧게 끊을 것\",\n  },\n};\n\nfunction gwBlogFactLines(v) {\n  if (!v || typeof v !== \"object\") return \"- 별도 매물표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n\n  const lines = [];\n  const seen = new Set();\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  push(\"매물\", v.title);\n  push(\"금액\", v.priceText);\n  for (const field of v.fields || []) push(field.label, field.value);\n  push(\"특징\", Array.isArray(v.themes) ? v.themes.join(\" \") : v.themes);\n  push(\"주변환경\", v.infra);\n  return lines.length ? lines.join(\"\\n\") : \"- 별도 매물표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n}\n\nfunction gwBlogArticleText(article) {\n  const a = article || {};\n  const subtitles = Array.isArray(a.subtitles) ? a.subtitles : [];\n  return [\n    `[제목] ${String(a.title || \"\").trim()}`,\n    subtitles.length ? `[부제] ${subtitles.join(\" / \")}` : \"\",\n    `[본문]\\n${String(a.body || \"\").trim()}`,\n  ].filter(Boolean).join(\"\\n\");\n}\n\nfunction gwBuildBlogPrompt(source, opts) {\n  if (source && source.vacancy && source.vacancy.saleKind) return gwBuildAuctionBlogPrompt(source, opts);\n  const input = source || {};\n  const o = opts || {};\n  const style = GW_BLOG_STYLE[o.style] || GW_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = input.article || {};\n\n  return `당신은 부동산 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 공실뉴스 기사와 확인된 매물 정보를 참고해 블로그 초안 1건을 작성하십시오.\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n[확인된 매물 정보]\n${gwBlogFactLines(input.vacancy)}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 매물: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n- 같은 매물 조건을 반복해 분량을 억지로 늘리지 말 것\n\n[보도 원칙 — 모든 스타일 공통, 가장 먼저 지킬 것]\n- 이 글은 \"공실뉴스에 이런 매물이 나왔다\"는 객관적인 매물 보도입니다. 위 스타일은 전개 방식만 정하고 이 틀은 바꾸지 않습니다\n- 3인칭 전달체로 쓸 것 (예: \"~로 등록됐다\", \"~인 것으로 나타났다\", \"~로 확인된다\"). 기본·분석·속보형은 기사체(~다), 현장답사·스토리텔링·해설형은 부드러운 존댓말(~습니다)도 허용\n- 첫 문단에서 공실뉴스에 등록된 매물이라는 점과 소재지·매물 종류·거래 조건을 밝힐 것 (예: \"공실뉴스에 서울 강남구 논현동 아파트 매매 매물이 등록됐다.\")\n- 출처를 분명히 할 것 (예: \"공실뉴스에 등록된 매물 정보에 따르면\")\n- 권유·호객·광고 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"연락 주세요\", \"놓치지 마세요\", \"강력 추천\", \"지금이 기회\" 등\n- 독자에게 직접 권하는 2인칭 문장을 쓰지 말 것. 조언이 필요하면 \"~라면 ~를 확인할 필요가 있다\"처럼 객관적으로 쓸 것\n- 위치·학군·지하철역·버스정류장·쇼핑시설·병원 등 주변 정보는 기사 가치가 있으므로 적극 전할 것. 단 [확인된 매물 정보]와 [참조 기사]에 있는 것만 쓰고, 자료에 없는 거리·도보 시간은 만들지 말 것\n- 중개사무소 이름·연락처·링크는 본문에 쓰지 말 것 (글 끝 \"매물 정보 출처\"에 자동으로 들어갑니다)\n\n[가장 중요한 사실 원칙]\n- 금액·면적·층·방·주소·관리비·입주일·주차·옵션 등 매물 고유 조건은\n  [확인된 매물 정보] 또는 [참조 기사]에 실제로 있는 내용만 쓸 것\n- 두 자료가 다르면 [확인된 매물 정보]를 우선할 것\n- 없는 수치, 현장 방문, 인터뷰, 고객 반응, 시세, 수익률, 개발 호재를 만들어내지 말 것\n- 소재지가 시·군·동까지만 공개됐다면 더 상세한 주소를 추측하지 말 것\n- 장점과 함께 계약 전 직접 확인할 점도 균형 있게 안내할 것\n\n[블로그 구성]\n- title: 검색어를 억지로 나열하지 않은 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 모바일에서도 읽기 쉽도록 한 문단을 2~4문장으로 짧게 구성할 것\n- 첫 문단은 2문장 이내의 핵심 요약으로 쓸 것 (인사말 없이 바로 본론, 위 보도 원칙의 첫 문단 규칙 포함). 이 문단은 블로그 맨 위 요약으로 쓰입니다\n- 소제목은 위 [선택한 스타일]의 구성대로 넣고, 한 줄짜리 독립 문단으로 쓰며 반드시 \"■ \"로 시작할 것\n  (\"■\"는 소제목 위치를 알리는 표시이며 화면 모양은 블로그 디자인이 따로 정합니다)\n- 소제목 바로 다음에는 반드시 본문 문단이 올 것 (소제목을 연달아 쓰거나 글 맨 끝에 두지 말 것)\n- 마지막 문단은 매물 조건과 확인할 점을 객관적으로 정리하는 한 문단으로 쓸 것. 권유·연락처·문의 안내·링크는 쓰지 말 것\n- 기사 문장을 그대로 길게 복사하지 말고 블로그 독자를 위한 새 문장으로 재구성할 것\n- keywords: 지역명·매물 종류·거래 조건을 포함한 검색용 핵심어 7~12개. # 기호는 제외할 것\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nfunction gwBuildBlogRevisePrompt(request, vacancy) {\n  if (vacancy && vacancy.saleKind) return gwBuildAuctionBlogRevisePrompt(request);\n  return `위에서 작성한 블로그 글을 아래 요청대로 고쳐 주십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 매물의 금액·면적·층·주소·번호 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 사용자의 수정 요청을 반영하되 과장 광고, 허위 방문, 허위 고객 사례를 만들지 마십시오.\n- 소제목 문단은 처음처럼 \"■ \"로 시작하고, 첫 문단은 핵심 요약으로 유지하십시오.\n- \"공실뉴스에 이런 매물이 나왔다\"는 객관적 보도 형식을 유지하고, 권유·호객 표현이나 중개사무소 연락처를 넣지 마십시오.\n- 고친 블로그 글 전체를 다시 출력하십시오. 수정된 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n- body는 문단별 문자열 배열이며 JSON.parse가 가능한 유효한 JSON이어야 합니다.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 물건 블로그 — 스타일 이름·순서는 일반 매물과 같고,\n   예시·지침·사실 원칙이 경매·공매에 맞춰져 있다.\n   블로그 탭은 gwBlogStyles(vacancy) 로 어느 쪽 스타일을 쓸지 고른다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_AUCTION_BLOG_STYLE = {\n  listing: {\n    label: \"기본 물건소개형\",\n    fit: \"모든 물건\",\n    titleExample: \"역삼동 오피스텔 공매, 최저입찰가 291만원\",\n    guide:\n      \"깔끔하고 정보 중심으로 쓴다. 제목과 첫 문단에서 경매·공매 구분, 지역, 물건 종류, 감정가와 최저입찰가를 분명히 보여 주고, \" +\n      \"본문은 가격 조건, 물건 현황과 입지, 입찰 일정, 확인할 점의 순서로 정리한다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 3~4개, 명사형으로 짧게 (예: ■ 가격 조건 / ■ 물건 현황과 입지 / ■ 입찰 일정 / ■ 입찰 전 확인할 점). \" +\n      \"핵심 요약 → 가격 → 현황·입지 → 일정 → 확인할 점 순서\",\n  },\n  visit: {\n    label: \"현장답사형\",\n    fit: \"아파트·상가·빌딩\",\n    titleExample: \"역삼동 경매 오피스텔, 주변을 사진으로 살펴보니\",\n    guide:\n      \"물건 주변을 차례로 둘러보는 듯한 흐름으로 쓴다. 다만 실제 방문·촬영·인터뷰를 했다고 거짓말하지 말고, \" +\n      \"제공된 기사와 사진·지도·로드뷰에서 확인할 수 있는 동선과 인상만 관찰형 문장으로 풀어낸다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 3~5개, 둘러보는 동선 순서의 장소형 (예: ■ 건물 외관 / ■ 진입로와 주변 거리 / ■ 가까운 교통). \" +\n      \"바깥에서 주변으로 이어지는 흐름. 마지막 소제목은 입찰 조건 정리\",\n  },\n  story: {\n    label: \"스토리텔링형\",\n    fit: \"주택·아파트\",\n    titleExample: \"감정가의 절반에 나온 아파트, 무엇을 봐야 할까?\",\n    guide:\n      \"독자가 경매·공매 물건을 처음 살펴보는 상황, 또는 한 가지 질문으로 시작한다. \" +\n      \"과장된 허구의 사례는 만들지 말고 확인된 조건을 따라 자연스럽게 해답을 제시한다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 1~2개, 질문형 (예: ■ 유찰이 거듭되면 무엇이 달라질까?). \" +\n      \"상황 제시 → 질문 → 확인된 조건으로 해답 순서. 소제목보다 문단 흐름을 중시\",\n  },\n  report: {\n    label: \"분석·리포트형\",\n    fit: \"빌딩·토지·상가\",\n    titleExample: \"3회 유찰된 논현동 건물, 입찰 조건을 살펴보니\",\n    guide:\n      \"가격 조건과 물건 현황, 한계, 입찰 전 확인 사항을 균형 있게 분석한다. \" +\n      \"확인되지 않은 낙찰가·수익률·시세·개발 호재를 추정하지 않는다.\",\n    design: \"news\",\n    structure:\n      \"소제목 4~5개, 명사형으로 고정 (■ 핵심 가격 조건 / ■ 물건 현황 / ■ 한계와 확인할 부분 / ■ 입찰 일정과 방법). \" +\n      \"각 구역은 1~2문단\",\n  },\n  consult: {\n    label: \"친근한 해설형\",\n    fit: \"주거용 물건\",\n    titleExample: \"공매 오피스텔, 입찰 절차는 어떻게 될까\",\n    guide:\n      \"경매·공매 물건의 조건과 입찰 절차를 독자가 이해하기 쉽게 풀어 설명하는 해설 기사로 쓴다. 부드러운 존댓말은 허용하지만 \" +\n      \"권유하지 말고, 조건의 의미와 확인할 점을 객관적으로 짚는다.\",\n    design: \"qna\",\n    structure:\n      \"소제목 3~4개, 독자가 실제로 물어볼 질문형 (예: ■ 최저입찰가는 어떻게 정해졌나요? / ■ 입찰보증금은 얼마인가요?). \" +\n      \"각 소제목 바로 다음 문단이 그 질문에 대한 답\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\",\n    fit: \"SNS 연계 물건\",\n    titleExample: \"[공매] 강남 역삼동 오피스텔 최저가 291만원\",\n    guide:\n      \"속보 기사처럼 첫 두 문장에 어떤 물건이 어디서 얼마에 경매·공매로 나왔는지를 짧게 전한다. 문장을 짧게 끊고 사실만 빠르게 전달하되, \" +\n      \"낚시성 표현·과도한 감탄·확인되지 않은 단정은 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 0~2개, 한 줄로 짧게. 강한 첫 두 문장 → 핵심 조건 3가지(감정가·최저입찰가·입찰 일정) → 한 줄 정리. \" +\n      \"문단은 1~2문장으로 짧게 끊을 것\",\n  },\n};\n\nfunction gwAuctionBlogFactLines(v) {\n  if (!v || typeof v !== \"object\") return \"- 별도 물건표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n\n  const lines = [];\n  const seen = new Set();\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  push(\"물건\", v.title);\n  push(\"가격 요약\", v.priceText);\n  for (const field of v.fields || []) push(field.label, field.value);\n  return lines.length ? lines.join(\"\\n\") : \"- 별도 물건표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n}\n\nfunction gwBuildAuctionBlogPrompt(source, opts) {\n  const input = source || {};\n  const o = opts || {};\n  const style = GW_AUCTION_BLOG_STYLE[o.style] || GW_AUCTION_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = input.article || {};\n\n  const saleKind = input.vacancy && input.vacancy.saleKind === \"공매\" ? \"공매\" : \"경매\";\n\n  return `당신은 부동산 경매·공매 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 공실뉴스 기사와 확인된 ${saleKind} 물건 정보를 참고해 블로그 초안 1건을 작성하십시오.\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n[확인된 물건 정보]\n${gwAuctionBlogFactLines(input.vacancy)}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 물건: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n- 같은 물건 조건을 반복해 분량을 억지로 늘리지 말 것\n\n[보도 원칙 — 모든 스타일 공통, 가장 먼저 지킬 것]\n- 이 글은 \"공실뉴스 공실열람에 이런 ${saleKind} 물건이 나왔다\"는 객관적인 보도입니다. 위 스타일은 전개 방식만 정하고 이 틀은 바꾸지 않습니다\n- 3인칭 전달체로 쓸 것 (예: \"~로 나왔다\", \"~인 것으로 나타났다\", \"~로 확인된다\"). 기본·분석·속보형은 기사체(~다), 현장답사·스토리텔링·해설형은 부드러운 존댓말(~습니다)도 허용\n- 첫 문단에서 ${saleKind} 물건이라는 점과 소재지·물건 종류·감정가·최저입찰가를 밝힐 것 (예: \"서울 강남구 역삼동 오피스텔이 ${saleKind}로 나왔다.\")\n- 출처를 분명히 할 것 (예: \"공실뉴스 공실열람의 ${saleKind} 물건 정보에 따르면\")\n- 투자 권유·호객 표현 금지: \"싸게 살 기회\", \"놓치지 마세요\", \"추천합니다\", \"지금이 기회\", \"수익이 기대된다\" 등\n- 낙찰가·낙찰가율·수익률·시세 상승을 예측하지 말 것\n- 독자에게 직접 권하는 2인칭 문장을 쓰지 말 것. 조언이 필요하면 \"~라면 ~를 확인할 필요가 있다\"처럼 객관적으로 쓸 것\n- 위치·교통·주변 시설 정보는 적극 전하되, [확인된 물건 정보]와 [참조 기사]에 있는 것만 쓰고 거리·도보 시간을 만들지 말 것\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호), \"본 정보는 참고용이며 법적 책임을 지지 않는다\"는 식의 입찰 전 법적 주의사항 안내문은 쓰지 말 것\n- 링크는 본문에 쓰지 말 것 (글 끝 \"물건 정보 출처\"에 자동으로 들어갑니다)\n\n[가장 중요한 사실 원칙]\n- 감정가·최저입찰가·유찰 횟수·입찰 일정·입찰보증금·면적·주소·관리번호(사건번호)·집행기관은\n  [확인된 물건 정보] 또는 [참조 기사]에 실제로 있는 내용만 쓸 것\n- 두 자료가 다르면 [확인된 물건 정보]를 우선할 것\n- 권리관계·임차인·체납액·현장 방문·인터뷰·낙찰 결과를 만들어내지 말 것\n- 입찰 일정이 없으면 날짜를 만들지 말 것\n- 가격 조건과 함께 입찰 전 직접 확인할 점(현장 상태·점유와 명도·권리관계)도 균형 있게 짚을 것\n\n[블로그 구성]\n- title: 검색어를 억지로 나열하지 않은 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 모바일에서도 읽기 쉽도록 한 문단을 2~4문장으로 짧게 구성할 것\n- 첫 문단은 2문장 이내의 핵심 요약으로 쓸 것 (인사말 없이 바로 본론, 위 보도 원칙의 첫 문단 규칙 포함). 이 문단은 블로그 맨 위 요약으로 쓰입니다\n- 소제목은 위 [선택한 스타일]의 구성대로 넣고, 한 줄짜리 독립 문단으로 쓰며 반드시 \"■ \"로 시작할 것\n  (\"■\"는 소제목 위치를 알리는 표시이며 화면 모양은 블로그 디자인이 따로 정합니다)\n- 소제목 바로 다음에는 반드시 본문 문단이 올 것 (소제목을 연달아 쓰거나 글 맨 끝에 두지 말 것)\n- 마지막 문단은 가격·일정 조건과 입찰 전 확인할 점을 객관적으로 정리하는 한 문단으로 쓸 것. 권유·연락처·링크는 쓰지 말 것\n- 기사 문장을 그대로 길게 복사하지 말고 블로그 독자를 위한 새 문장으로 재구성할 것\n- keywords: 지역명·물건 종류·\"${saleKind}\"를 포함한 검색용 핵심어 7~12개. # 기호는 제외할 것\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nfunction gwBuildAuctionBlogRevisePrompt(request) {\n  return `위에서 작성한 블로그 글을 아래 요청대로 고쳐 주십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 물건의 감정가·최저입찰가·유찰 횟수·입찰 일정·면적·주소·관리번호 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 사용자의 수정 요청을 반영하되 과장 광고, 허위 방문, 허위 고객 사례를 만들지 마십시오.\n- 소제목 문단은 처음처럼 \"■ \"로 시작하고, 첫 문단은 핵심 요약으로 유지하십시오.\n- \"공실뉴스 공실열람에 이런 경매·공매 물건이 나왔다\"는 객관적 보도 형식을 유지하고, 투자 권유·낙찰가 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문을 넣지 마십시오.\n- 고친 블로그 글 전체를 다시 출력하십시오. 수정된 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n- body는 문단별 문자열 배열이며 JSON.parse가 가능한 유효한 JSON이어야 합니다.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* 물건 종류에 맞는 블로그 스타일 표 — 경매·공매면 경매용 */\nfunction gwBlogStyles(vacancy) {\n  return vacancy && vacancy.saleKind ? GW_AUCTION_BLOG_STYLE : GW_BLOG_STYLE;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_BLOG_LENGTH,\n    GW_BLOG_STYLE,\n    GW_AUCTION_BLOG_STYLE,\n    gwBlogStyles,\n    gwBlogFactLines,\n    gwAuctionBlogFactLines,\n    gwBlogArticleText,\n    gwBuildBlogPrompt,\n    gwBuildBlogRevisePrompt,\n  };\n}\n",
 "gongsil/article-json.js": "/* ══════════════════════════════════════════════════════════════\n   AI 기사 JSON 읽기\n\n   새 형식은 body 를 문단 배열로 받는다. 긴 본문을 JSON 문자열 하나에 넣을 때\n   생기는 줄바꿈·괄호 오류를 피하기 위해서다. 예전 문자열 형식도 계속 받으며,\n   AI 가 흔히 만드는 원시 줄바꿈·후행 쉼표·body 닫기 괄호 오류는 안전하게\n   복구한다. eval 은 사용하지 않는다.\n   ══════════════════════════════════════════════════════════════ */\n(() => {\n  \"use strict\";\n\n  function extractCandidate(rawText) {\n    const text = String(rawText || \"\").trim();\n    if (!text) return \"\";\n\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced && fenced[1]) return fenced[1].trim();\n\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first !== -1 && last > first ? text.slice(first, last + 1).trim() : \"\";\n  }\n\n  function hasCompleteObject(rawText) {\n    const text = String(rawText || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n\n    for (let i = first; i < text.length; i += 1) {\n      const ch = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') inString = true;\n      else if (ch === \"{\") depth += 1;\n      else if (ch === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n\n    return false;\n  }\n\n  function escapeRawControlsInStrings(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n\n      if (inString) {\n        if (escaped) {\n          out += ch;\n          escaped = false;\n        } else if (ch === \"\\\\\") {\n          out += ch;\n          escaped = true;\n        } else if (ch === '\"') {\n          out += ch;\n          inString = false;\n        } else if (ch === \"\\n\") {\n          out += \"\\\\n\";\n        } else if (ch === \"\\r\") {\n          if (input[i + 1] === \"\\n\") i += 1;\n          out += \"\\\\n\";\n        } else if (ch === \"\\t\") {\n          out += \"\\\\t\";\n        } else {\n          out += ch;\n        }\n      } else {\n        out += ch;\n        if (ch === '\"') inString = true;\n      }\n    }\n\n    return out;\n  }\n\n  function stripTrailingCommas(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n      if (inString) {\n        out += ch;\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') {\n        inString = true;\n        out += ch;\n        continue;\n      }\n\n      if (ch === \",\") {\n        let next = i + 1;\n        while (next < input.length && /\\s/.test(input[next])) next += 1;\n        if (input[next] === \"}\" || input[next] === \"]\") continue;\n      }\n\n      out += ch;\n    }\n\n    return out;\n  }\n\n  function repairCommonJson(candidate) {\n    return stripTrailingCommas(escapeRawControlsInStrings(candidate));\n  }\n\n  function keyMatch(input, key, fromIndex = 0) {\n    const escapedKey = key.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n    const regex = new RegExp(`\"${escapedKey}\"\\\\s*:`, \"g\");\n    regex.lastIndex = fromIndex;\n    return regex.exec(input);\n  }\n\n  function extractSection(input, key, nextKeys) {\n    const current = keyMatch(input, key);\n    if (!current) return \"\";\n\n    const start = current.index + current[0].length;\n    let end = input.length;\n    for (const nextKey of nextKeys || []) {\n      const next = keyMatch(input, nextKey, start);\n      if (next && next.index < end) end = next.index;\n    }\n\n    let section = input.slice(start, end).trim();\n    section = section.replace(/,\\s*$/, \"\").trim();\n    return section;\n  }\n\n  function manualUnquote(value) {\n    let text = String(value || \"\").trim();\n    while (text.startsWith('\"') && /[}\\]]$/.test(text)) {\n      text = text.slice(0, -1).trim();\n    }\n    if (text.startsWith('\"')) text = text.slice(1);\n    if (text.endsWith('\"')) text = text.slice(0, -1);\n\n    return text\n      .replace(/\\\\r\\\\n/g, \"\\n\")\n      .replace(/\\\\n/g, \"\\n\")\n      .replace(/\\\\t/g, \"\\t\")\n      .replace(/\\\\\"/g, '\"')\n      .replace(/\\\\\\\\/g, \"\\\\\")\n      .trim();\n  }\n\n  function parseLooseValue(section) {\n    let value = String(section || \"\").trim().replace(/,\\s*$/, \"\").trim();\n    if (!value) return \"\";\n\n    /* 스크린샷처럼 문자열 body 뒤에 잘못 붙은 ] 를 제거한다. */\n    if (value.startsWith('\"')) {\n      while (value.endsWith(\"]\")) value = value.slice(0, -1).trim();\n    }\n\n    const attempts = [value, repairCommonJson(value)];\n    if (value.startsWith(\"[\") && !value.endsWith(\"]\")) {\n      attempts.push(repairCommonJson(value + \"]\"));\n    }\n\n    for (const attempt of attempts) {\n      try {\n        return JSON.parse(attempt);\n      } catch (_error) {\n        /* 다음 안전한 복구를 시도한다. */\n      }\n    }\n\n    if (value.startsWith(\"[\")) {\n      const strings = [];\n      const regex = /\"((?:\\\\.|[^\"\\\\])*)\"/g;\n      let match;\n      while ((match = regex.exec(value))) strings.push(manualUnquote(`\"${match[1]}\"`));\n      if (strings.length) return strings;\n    }\n\n    return manualUnquote(value);\n  }\n\n  function normalizeBody(value) {\n    if (Array.isArray(value)) {\n      return value\n        .map((item) => {\n          if (typeof item === \"string\") return item.trim();\n          if (item && typeof item === \"object\") {\n            return String(item.text || item.content || item.paragraph || \"\").trim();\n          }\n          return \"\";\n        })\n        .filter(Boolean)\n        .join(\"\\n\\n\");\n    }\n\n    if (value && typeof value === \"object\") {\n      return normalizeBody(value.paragraphs || value.body || value.content || value.text || \"\");\n    }\n\n    return typeof value === \"string\" ? value.trim() : \"\";\n  }\n\n  function normalizeArticle(data) {\n    if (!data || typeof data !== \"object\") return null;\n\n    const title = String(data.title || \"\").trim();\n    const subtitleValues = Array.isArray(data.subtitles)\n      ? data.subtitles\n      : [data.subtitle1, data.subtitle2, data.subtitle3];\n    const subtitles = subtitleValues\n      .map((value) => String(value || \"\").trim())\n      .filter(Boolean)\n      .slice(0, 3);\n    const body = normalizeBody(data.body || data.paragraphs || data.content || \"\");\n    const rawKeywords = Array.isArray(data.keywords)\n      ? data.keywords\n      : String(data.keywords || \"\").split(/[,\\n]/);\n    const keywords = rawKeywords\n      .map((keyword) => String(keyword || \"\").replace(/^#/, \"\").trim())\n      .filter(Boolean);\n\n    if (!title || !body) return null;\n    return { title, subtitles, body, keywords };\n  }\n\n  function parseLooseArticle(candidate) {\n    const title = parseLooseValue(extractSection(candidate, \"title\", [\"subtitle1\", \"subtitles\", \"body\"]));\n    const subtitlesValue = parseLooseValue(extractSection(candidate, \"subtitles\", [\"body\"]));\n    const subtitle1 = parseLooseValue(extractSection(candidate, \"subtitle1\", [\"subtitle2\", \"subtitle3\", \"body\"]));\n    const subtitle2 = parseLooseValue(extractSection(candidate, \"subtitle2\", [\"subtitle3\", \"body\"]));\n    const subtitle3 = parseLooseValue(extractSection(candidate, \"subtitle3\", [\"body\"]));\n    const body = parseLooseValue(extractSection(candidate, \"body\", [\"keywords\"]));\n\n    let keywordsSection = extractSection(candidate, \"keywords\", []);\n    while (keywordsSection.endsWith(\"}\")) keywordsSection = keywordsSection.slice(0, -1).trim();\n    const keywords = parseLooseValue(keywordsSection);\n\n    return {\n      title,\n      subtitles: Array.isArray(subtitlesValue)\n        ? subtitlesValue\n        : [subtitle1, subtitle2, subtitle3].filter(Boolean),\n      body,\n      keywords: Array.isArray(keywords) ? keywords : [],\n    };\n  }\n\n  function parse(rawText) {\n    if (!rawText || !String(rawText).trim()) {\n      return { ok: false, reason: \"AI 응답이 비어 있습니다.\" };\n    }\n\n    const candidate = extractCandidate(rawText);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON 을 찾지 못했습니다.\" };\n\n    let data = null;\n    let repaired = false;\n\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repairCommonJson(candidate));\n        repaired = true;\n      } catch (_repairError) {\n        data = parseLooseArticle(candidate);\n        repaired = true;\n      }\n    }\n\n    const article = normalizeArticle(data);\n    if (!article) {\n      return { ok: false, reason: \"AI 응답에 제목 또는 본문이 없거나 복구할 수 없는 JSON 입니다.\" };\n    }\n\n    return { ok: true, article, repaired };\n  }\n\n  const api = { parse, hasCompleteObject, extractCandidate, repairCommonJson, normalizeBody };\n  globalThis.GWArticleJson = api;\n\n  if (typeof module !== \"undefined\" && module.exports) {\n    module.exports = api;\n  }\n})();\n",
 "gongsil/naver-blog.js": "/* 네이버 블로그 탭과 글쓰기 탭을 구분하는 공통 규칙 */\n(function initNaverBlog(global) {\n  \"use strict\";\n\n  const HOME_URL = \"https://blog.naver.com/\";\n  const WRITE_URL = \"https://blog.naver.com/GoBlogWrite.naver\";\n\n  function isNaverBlogUrl(rawUrl) {\n    try {\n      const url = new URL(rawUrl);\n      return url.protocol === \"https:\" && (\n        url.hostname === \"blog.naver.com\" ||\n        url.hostname === \"blog.editor.naver.com\"\n      );\n    } catch (_) {\n      return false;\n    }\n  }\n\n  function isLikelyWriteUrl(rawUrl) {\n    if (!isNaverBlogUrl(rawUrl)) return false;\n    const value = String(rawUrl).toLowerCase();\n    return (\n      value.includes(\"goblogwrite\") ||\n      value.includes(\"postwrite\") ||\n      value.includes(\"postwriteform\") ||\n      value.includes(\"redirect=write\") ||\n      value.includes(\"blog.editor.naver.com\")\n    );\n  }\n\n  function selectLikelyWriteTab(tabs) {\n    return (Array.isArray(tabs) ? tabs : [])\n      .filter((tab) => tab && tab.id && isLikelyWriteUrl(tab.url))\n      .sort((a, b) => {\n        if (Boolean(a.active) !== Boolean(b.active)) return a.active ? -1 : 1;\n        return (b.lastAccessed || 0) - (a.lastAccessed || 0);\n      })[0] || null;\n  }\n\n  function splitParagraphs(body) {\n    return String(body || \"\")\n      .split(/\\n{2,}|\\n/)\n      .map((value) => value.trim())\n      .filter(Boolean);\n  }\n\n  /* 대표가 아닌 사진을 문단 사이 칸(0 = 첫 문단 앞, n = n번째 문단 뒤)에 배치한다.\n     insertAfterParagraph가 있으면 그 칸, 없으면 두 문단마다 한 장씩, 남으면 글 끝. */\n  function layoutMediaSlots(paragraphCount, media) {\n    const slots = Array.from({ length: paragraphCount + 1 }, () => []);\n    const automatic = [];\n\n    (Array.isArray(media) ? media : []).forEach((item, index) => {\n      if (!item || item.isCover) return;\n      if (Number.isInteger(item.insertAfterParagraph)) {\n        const slot = Math.max(0, Math.min(item.insertAfterParagraph, paragraphCount));\n        slots[slot].push({ media: item, index });\n      } else {\n        automatic.push({ media: item, index });\n      }\n    });\n\n    let autoIndex = 0;\n    for (let slot = 2; slot < paragraphCount && autoIndex < automatic.length; slot += 2) {\n      slots[slot].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    while (autoIndex < automatic.length) {\n      slots[paragraphCount].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    return slots;\n  }\n\n  function escapeHtml(value) {\n    return String(value).replace(/[&<>\"']/g, (ch) => ({\n      \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\",\n    })[ch]);\n  }\n\n  /* ── 블로그 디자인 ──\n     네이버 편집기가 붙여넣기로 받아들이는 요소만 쓴다 (2026-09-25 실제 화면에서 확인):\n     <blockquote> → 인용구(따옴표형), <hr> → 구분선, <table> → 표, 문단 정렬·글자색·크기·링크.\n     굵게(<b>·<strong>·font-weight)는 붙여넣기로 적용되지 않으므로 소제목은 크기와 색으로 강조한다.\n     붙여넣기 조각을 빈 문단으로 끝내지 않으면 다음 조각이 마지막 문단에 이어 붙고 글자색·크기도 번진다.\n     문단 순서는 모든 디자인이 같다. 그래서 사진 위치(문단 사이 칸)가 미리보기와 어긋나지 않는다. */\n  const DESIGNS = {\n    basic: { label: \"기본형\", hint: \"요약 인용구 · 매물표 · 큰 소제목. 어떤 매물에나 무난합니다.\" },\n    magazine: { label: \"매거진형\", hint: \"가운데 정렬 · 번호 소제목 · 핵심 문장 강조. 고급·신축 매물에 어울립니다.\" },\n    qna: { label: \"Q&A형\", hint: \"소제목을 질문으로, 본문을 답변으로. 질문형 검색에 유리합니다.\" },\n    news: { label: \"뉴스기사형\", hint: \"큰 리드문 · 기사체 · 공실뉴스 서명. 언론사 느낌을 살립니다.\" },\n  };\n  /* 경매·공매 물건일 때 바뀌는 디자인 설명 */\n  const AUCTION_HINTS = {\n    basic: \"요약 인용구 · 물건표 · 큰 소제목. 어떤 물건에나 무난합니다.\",\n    magazine: \"가운데 정렬 · 번호 소제목 · 핵심 문장 강조. 아파트·건물 물건에 어울립니다.\",\n  };\n  function designHint(design, auction) {\n    return (auction && AUCTION_HINTS[design]) || DESIGNS[design]?.hint || \"\";\n  }\n  const ACCENT = \"#2563eb\";\n  const MUTED = \"#888888\";\n  const SKY = \"#dbeafe\"; // 매거진형 소제목 하늘색 배경(형광펜)\n  const BLANK = \"<p><br></p>\";\n  const SITE_URL = \"https://www.gongsilnews.com\"; // gongsilnews.com은 www로 넘어간다. 로그인 쿠키도 www에 있다\n\n  /* 매물표 항목: 부동산 인터넷 표시·광고 필수 항목 순서.\n     소재지·매물종류·거래형태는 출처 API(listing), 나머지는 공실광고정보 탭 항목(vacancy.fields)에서 찾는다. */\n  const FACT_ORDER = [\n    /^(금액)$/,\n    /관리비/,\n    /면적/,\n    /해당층|총층|건물규모/,\n    /방\\/욕실|방수|욕실/,\n    /방향/,\n    /준공|사용승인/,\n    /주차/,\n    /입주가능|사용 가능일/,\n  ];\n\n  /* 경매·공매 물건표 항목: 경매·공매 물건을 볼 때 먼저 찾는 순서.\n     소재지·물건종류는 출처 API(listing), 나머지는 서버에서 받은 물건 정보(vacancy.fields)에서 찾는다.\n     정보제공처 연락처와 입찰 전 주의사항은 서버가 애초에 보내지 않는다. */\n  const AUCTION_FACT_ORDER = [\n    /^구분$/,\n    /^감정가$/,\n    /^최저입찰가$/,\n    /감정가 대비/,\n    /유찰/,\n    /토지면적|건물면적/,\n    /입찰 시작|입찰 마감|개찰일시/,\n    /입찰보증금$/,\n    /명도책임/,\n    /관리번호|사건번호/,\n    /집행기관|관할법원/,\n  ];\n\n  /* 경매·공매 물건인가 — 출처 API 나 물건 정보에 경매·공매 구분이 붙어 있다 */\n  const isAuction = (vacancy, listing) => Boolean(listing?.saleKind || vacancy?.saleKind);\n\n  function isHeading(paragraph) {\n    return String(paragraph).startsWith(\"■\");\n  }\n\n  function stripHeading(paragraph) {\n    return String(paragraph).replace(/^■\\s*/, \"\");\n  }\n\n  /* 매물표: 표시·광고 필수 항목을 정해진 순서로 (개수 제한 없음) */\n  function factRows(vacancy, listing) {\n    const rows = [];\n    const seen = new Set();\n    const push = (label, value) => {\n      const text = value == null ? \"\" : String(value).trim();\n      if (!label || !text || text === \"-\" || seen.has(label)) return;\n      seen.add(label);\n      rows.push([label, text]);\n    };\n    const fields = (Array.isArray(vacancy?.fields) ? vacancy.fields : []).filter((field) => field && field.label);\n\n    if (isAuction(vacancy, listing)) {\n      push(\"소재지\", fields.find((field) => field.label === \"소재지(지번)\")?.value || listing?.location);\n      push(\"물건종류\", listing?.propertyType || fields.find((field) => field.label === \"물건종류\")?.value);\n      AUCTION_FACT_ORDER.forEach((pattern) => {\n        fields.filter((field) => pattern.test(field.label)).forEach((field) => push(field.label, field.value));\n      });\n      if (!seen.has(\"최저입찰가\")) push(\"가격\", vacancy?.priceText);\n      return rows;\n    }\n\n    push(\"소재지\", listing?.location);\n    push(\"매물종류\", listing?.propertyType);\n    push(\"거래형태\", listing?.tradeType || fields.find((field) => /거래구분/.test(field.label))?.value);\n    FACT_ORDER.forEach((pattern) => {\n      fields.filter((field) => pattern.test(field.label)).forEach((field) => push(field.label, field.value));\n    });\n    if (!seen.has(\"금액\")) push(\"금액\", vacancy?.priceText);\n    return rows;\n  }\n\n  /* 링크: 매물 고정 상세 주소 → 없으면 처음 매물을 본 공실뉴스 주소 */\n  function listingUrl(vacancy, listing) {\n    if (listing?.detailUrl) return listing.detailUrl;\n    const url = String(vacancy?.url || \"\");\n    return /^https:\\/\\/([a-z0-9-]+\\.)?gongsilnews\\.com\\//i.test(url) ? url : \"\";\n  }\n\n  function formatDate(value) {\n    const date = value ? new Date(value) : new Date();\n    if (Number.isNaN(date.getTime())) return \"\";\n    const pad = (n) => String(n).padStart(2, \"0\");\n    return `${date.getFullYear()}.${pad(date.getMonth() + 1)}.${pad(date.getDate())}`;\n  }\n\n  /* 전송 전 검사: 표시·광고 필수 정보가 빠졌으면 이유를 돌려준다 */\n  function listingProblems(listing, auction = false) {\n    /* 경매·공매: 물건 정보를 서버에서 받았는지만 본다 */\n    if (auction || listing?.saleKind) {\n      if (!listing) return [\"경매·공매 물건 정보\"];\n      return listing.saleKind ? [] : [\"경매·공매 구분\"];\n    }\n    if (!listing) return [\"매물 출처 정보(중개사무소)\"];\n    const owner = listing.owner || {};\n    if (owner.type !== \"agency\") return owner.name ? [] : [\"등록자 이름\"];\n    return [\n      [\"중개사무소 명칭\", owner.name],\n      [\"대표자\", owner.ceo],\n      [\"등록번호\", owner.regNo],\n      [\"소재지\", owner.address],\n      [\"연락처\", owner.phone],\n    ].filter(([, value]) => !String(value || \"\").trim()).map(([label]) => label);\n  }\n\n  /* 글 끝 \"매물 정보 출처\" — 모든 디자인 공통. 문의처가 아니라 출처로 표현한다. */\n  function sourceBlockLines(listing, url) {\n    /* 경매·공매: 정보제공처(온비드 고객센터) 연락처와 입찰 전 법적 주의사항 안내문은 넣지 않는다 */\n    if (listing?.saleKind) {\n      const saleKind = listing.saleKind;\n      const lines = [`공실뉴스 공실열람 ${saleKind} 물건 정보 (${formatDate(listing.capturedAt)} 기준)`];\n      const numberLabel = listing.caseLabel || (saleKind === \"공매\" ? \"관리번호\" : \"사건번호\");\n      const parts = [\n        listing.caseNo ? `${numberLabel} ${listing.caseNo}` : \"\",\n        listing.agency ? `${saleKind === \"공매\" ? \"집행기관\" : \"관할법원\"} ${listing.agency}` : \"\",\n      ].filter(Boolean);\n      if (parts.length) lines.push(parts.join(\" | \"));\n      lines.push(\"※ 입찰 조건은 공고 시점 기준이며 변경될 수 있습니다.\");\n      return { lines, url };\n    }\n    const owner = listing?.owner || {};\n    const lines = [`공실뉴스 매물 등록 정보 (${formatDate(listing?.capturedAt)} 기준)`];\n    if (owner.type === \"agency\") {\n      lines.push(`등록 중개사무소: ${owner.name}${owner.ceo ? ` | 대표 ${owner.ceo}` : \"\"}`);\n      lines.push(`등록번호 ${owner.regNo} | ${owner.address}`);\n      lines.push(`전화 ${owner.phone}`);\n    } else if (owner.name) {\n      lines.push(`등록자: ${owner.name} (일반회원 등록 매물)`);\n    }\n    lines.push(\"※ 매물 조건은 등록 시점 기준이며 실제와 다를 수 있습니다.\");\n    return { lines, url };\n  }\n\n  function paragraphHtml(text, { align, size, color, background, bold } = {}) {\n    let inner = escapeHtml(text);\n    const styles = [\n      size ? `font-size:${size}px` : \"\",\n      color ? `color:${color}` : \"\",\n      background ? `background-color:${background}` : \"\",\n      bold ? \"font-weight:700\" : \"\",\n    ].filter(Boolean).join(\";\");\n    if (styles) inner = `<span style=\"${styles}\">${inner}</span>`;\n    return align ? `<p style=\"text-align:${align}\">${inner}</p>` : `<p>${inner}</p>`;\n  }\n\n  function quoteHtml(text) {\n    return `<blockquote><p>${escapeHtml(text)}</p></blockquote>`;\n  }\n\n  function tableHtml(rows) {\n    if (!rows.length) return \"\";\n    const body = rows\n      .map(([label, value]) => `<tr><td><b>${escapeHtml(label)}</b></td><td>${escapeHtml(value)}</td></tr>`)\n      .join(\"\");\n    return `<table><tbody>${body}</tbody></table>`;\n  }\n\n  function linkHtml(url, text, align) {\n    if (!url) return \"\";\n    const style = align ? ` style=\"text-align:${align}\"` : \"\";\n    return `<p${style}><a href=\"${escapeHtml(url)}\">${escapeHtml(text)}</a></p>`;\n  }\n\n  function firstSentence(text) {\n    const match = /^(.+?[.!?])(\\s|$)/.exec(String(text || \"\").trim());\n    return match ? match[1] : String(text || \"\").trim();\n  }\n\n  /* 네이버 편집기에 차례로 붙여넣을 조각을 만든다.\n     글 조각은 HTML, 사진은 media 배열의 위치만 담는다.\n     글 조각은 사진이 끼어들 때만 끊고, 문단 뒤와 조각 끝에는 빈 문단을 둔다. */\n  function buildNaverBlocks(body, media, options = {}) {\n    const design = DESIGNS[options.design] ? options.design : \"basic\";\n    const list = Array.isArray(media) ? media : [];\n    const paragraphs = splitParagraphs(body);\n    const slots = layoutMediaSlots(paragraphs.length, list);\n    const rows = factRows(options.vacancy, options.listing);\n    const noun = isAuction(options.vacancy, options.listing) ? \"물건\" : \"매물\";\n    const url = listingUrl(options.vacancy, options.listing);\n    const blocks = [];\n    let buffer = [];\n\n    const flush = () => {\n      if (!buffer.length) return;\n      if (buffer[buffer.length - 1] !== BLANK) buffer.push(BLANK);\n      blocks.push({ type: \"html\", html: buffer.join(\"\") });\n      buffer = [];\n    };\n    // 문단 뒤에는 빈 문단 한 칸 (tight: 번호처럼 바로 아래 줄과 붙어야 하는 문단)\n    const html = (value, { tight = false } = {}) => {\n      if (!value) return;\n      buffer.push(value);\n      if (!tight && value.startsWith(\"<p\")) buffer.push(BLANK);\n    };\n    const addImages = (indexes) => {\n      if (!indexes.length) return;\n      flush();\n      indexes.forEach((index) => blocks.push({ type: \"image\", mediaIndex: index }));\n    };\n\n    const leadIndex = paragraphs.length && !isHeading(paragraphs[0]) ? 0 : -1;\n    const firstHeadingIndex = paragraphs.findIndex(isHeading);\n    let headingNumber = 0;\n    let answerPending = false;\n    let pullQuote = \"\";\n    let pullQuoteDone = false;\n\n    // 대표 사진 (뉴스기사형은 사진 설명을 작게 붙인다)\n    const coverIndex = list.findIndex((item) => item && item.isCover);\n    if (coverIndex >= 0) {\n      addImages([coverIndex]);\n      const caption = String(list[coverIndex].caption || \"\").trim();\n      if (design === \"news\" && caption) html(paragraphHtml(caption, { align: \"center\", size: 13, color: MUTED }));\n    }\n    if (design === \"magazine\" && options.title) {\n      html(paragraphHtml(options.title, { align: \"center\", size: 24, bold: true }));\n    }\n    addImages(slots[0].map((item) => item.index));\n\n    // 도입부가 끝나고 첫 소제목이 오기 전에 넣는 장식\n    const afterIntro = () => {\n      if (design === \"basic\") {\n        html(tableHtml(rows));\n        html(\"<hr>\");\n      } else if (design === \"magazine\") {\n        html(\"<hr>\");\n      }\n    };\n\n    let carried = [];\n    paragraphs.forEach((paragraph, index) => {\n      if (index === firstHeadingIndex) afterIntro();\n\n      if (index === leadIndex) {\n        if (design === \"basic\" || design === \"qna\") html(quoteHtml(paragraph));\n        else if (design === \"magazine\") html(paragraphHtml(paragraph, { align: \"center\", color: MUTED }));\n        else html(paragraphHtml(paragraph, { size: 17, bold: true }));\n        if (design === \"qna\") html(tableHtml(rows));\n      } else if (isHeading(paragraph)) {\n        const text = stripHeading(paragraph);\n        headingNumber += 1;\n        if (design === \"magazine\" && headingNumber === 2 && pullQuote) {\n          html(quoteHtml(pullQuote));\n          pullQuoteDone = true;\n        }\n        if (design === \"basic\") {\n          html(paragraphHtml(`■ ${text}`, { size: 19, bold: true }), { tight: true });\n        } else if (design === \"magazine\") {\n          html(paragraphHtml(String(headingNumber).padStart(2, \"0\"), { align: \"center\", color: ACCENT, bold: true }), { tight: true });\n          html(paragraphHtml(text, { align: \"center\", size: 19, background: SKY, bold: true }), { tight: true });\n        } else if (design === \"qna\") {\n          html(paragraphHtml(/^Q[.\\s]/.test(text) ? text : `Q. ${text}`, { size: 19, color: ACCENT, bold: true }), { tight: true });\n          answerPending = true;\n        } else {\n          html(paragraphHtml(text, { size: 19, bold: true }), { tight: true });\n        }\n      } else if (design === \"qna\" && answerPending) {\n        html(`<p><span style=\"color:${ACCENT}\">A.</span> ${escapeHtml(paragraph)}</p>`);\n        answerPending = false;\n      } else {\n        if (design === \"magazine\" && headingNumber === 1 && !pullQuote) pullQuote = firstSentence(paragraph);\n        html(paragraphHtml(paragraph, design === \"magazine\" ? { align: \"center\" } : {}));\n      }\n\n      // 소제목과 첫 문단 사이에는 사진을 두지 않는다 — 다음 문단 뒤로 넘긴다\n      const images = [...carried, ...slots[index + 1].map((item) => item.index)];\n      if (isHeading(paragraph) && index < paragraphs.length - 1) {\n        carried = images;\n      } else {\n        carried = [];\n        addImages(images);\n      }\n    });\n    addImages(carried);\n\n    if (firstHeadingIndex < 0) afterIntro();\n\n    // 글 끝: 디자인별 마무리\n    if (design === \"magazine\") {\n      if (pullQuote && !pullQuoteDone) html(quoteHtml(pullQuote));\n      html(\"<hr>\");\n      html(tableHtml(rows));\n    } else if (design === \"qna\") {\n      if (leadIndex < 0) html(tableHtml(rows));\n    } else if (design === \"news\") {\n      if (rows.length) {\n        html(paragraphHtml(noun === \"물건\" ? \"[물건 정보]\" : \"[매물 정보]\", { size: 17, bold: true }), { tight: true });\n        html(tableHtml(rows));\n      }\n    }\n\n    // 모든 디자인 공통: 매물 정보 출처 (표시·광고 필수 정보) + 고정 상세 링크 + 공실뉴스 서명\n    const source = sourceBlockLines(options.listing, url);\n    html(\"<hr>\");\n    html(paragraphHtml(`[${noun} 정보 출처]`, { size: 13, color: MUTED, bold: true }), { tight: true });\n    source.lines.forEach((line) => html(paragraphHtml(line, { size: 13, color: MUTED }), { tight: true }));\n    html(BLANK, { tight: true });\n    html(linkHtml(source.url, noun === \"물건\" ? \"▶ 공실뉴스 경매·공매 물건 상세 보기\" : \"▶ 공실뉴스 매물 상세 보기\"));\n    html(paragraphHtml(\"공실뉴스 · gongsilnews.com\", { size: 13, color: MUTED }));\n    flush();\n    return blocks;\n  }\n\n  /* 발행 창 태그 칸용: # 제거, 중복 제거, 네이버 최대 30개 */\n  function normalizeTags(keywords) {\n    const seen = new Set();\n    return (Array.isArray(keywords) ? keywords : [])\n      .map((keyword) => String(keyword || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n      .filter((keyword) => keyword && !seen.has(keyword) && seen.add(keyword))\n      .slice(0, 30);\n  }\n\n  const api = {\n    HOME_URL, WRITE_URL, isNaverBlogUrl, isLikelyWriteUrl, selectLikelyWriteTab,\n    splitParagraphs, layoutMediaSlots, buildNaverBlocks, normalizeTags,\n    DESIGNS, designHint, factRows, listingProblems, SITE_URL,\n    sourceBlockLines, listingUrl, // SNS 글 끝 출처·링크도 블로그와 같은 문구를 쓴다 (sns.js)\n  };\n  global.GWNaverBlog = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})(typeof globalThis !== \"undefined\" ? globalThis : self);\n",
 "gongsil/sns-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   3 · SNS 작성 — 페이스북 · 인스타그램 · 스레드\n\n   - AI 에 한 번 요청해 세 플랫폼 글을 함께 받는다 (무료 체험도 \"SNS\" 1번).\n   - 블로그와 같은 객관 보도 원칙: \"공실뉴스에 이런 매물이 나왔다\". 스레드만 말투를 대화체로.\n   - 링크·출처(표시·광고 필수 정보)·해시태그는 AI 가 아니라 코드가 붙인다 (gwSnsCompose).\n   - 사진은 2번 기사 사진을 플랫폼별로 다시 고르고 비율대로 자른다 (gwSnsPickMedia · sns.js).\n   기획: docs/2026-10-03_sns_writer_tabs_meeting.md\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_SNS_CHANNELS = {\n  facebook: {\n    label: \"페이스북\",\n    badge: \"Facebook\",\n    homeUrl: \"https://www.facebook.com/\",\n    ratio: 1, // 정사각 1:1\n    ratioText: \"정사각 1:1\",\n    size: [1080, 1080],\n    maxMedia: 10,\n    maxChars: 0, // 사실상 제한 없음\n    maxTags: 5,\n  },\n  instagram: {\n    label: \"인스타그램\",\n    badge: \"Instagram\",\n    homeUrl: \"https://www.instagram.com/\",\n    ratio: 4 / 5, // 세로 4:5\n    ratioText: \"세로 4:5\",\n    size: [1080, 1350],\n    maxMedia: 10,\n    maxChars: 2200,\n    maxTags: 30,\n  },\n  threads: {\n    label: \"스레드\",\n    badge: \"Threads\",\n    homeUrl: \"https://www.threads.com/\",\n    ratio: 0, // 원본 비율\n    ratioText: \"원본 비율\",\n    size: [1600, 1600],\n    maxMedia: 10,\n    maxChars: 500, // 글 하나마다\n    maxTags: 1,\n  },\n};\n\nconst GW_SNS_ORDER = [\"facebook\", \"instagram\", \"threads\"];\n\nfunction gwSnsNoun(vacancy) {\n  return vacancy && vacancy.saleKind ? \"물건\" : \"매물\";\n}\n\nfunction gwBuildSnsPrompt(source) {\n  const input = source || {};\n  const noun = gwSnsNoun(input.vacancy);\n  const auction = noun === \"물건\";\n\n  return `당신은 부동산 정보를 정확하게 전하는 공실뉴스의 SNS 에디터입니다.\n아래 공실뉴스 기사와 확인된 ${noun} 정보로 페이스북·인스타그램·스레드 글을 한 번에 작성하십시오.\n세 글은 같은 사실을 전하지만 플랫폼마다 모양이 다릅니다. 같은 문장을 돌려 쓰지 마십시오.\n\n[참조 기사]\n${gwBlogArticleText(input.article)}\n\n[확인된 ${noun} 정보]\n${gwBlogFactLines(input.vacancy)}\n\n[보도 원칙 — 세 플랫폼 공통, 가장 먼저 지킬 것]\n- \"공실뉴스에 이런 ${noun}이 나왔다\"는 객관적인 ${auction ? \"물건\" : \"매물\"} 소식입니다. 광고 문구가 아닙니다\n- 권유·호객·광고 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"연락 주세요\", \"DM 주세요\", \"놓치지 마세요\", \"급매\", \"지금이 기회\", \"역대급\" 등\n- 금액·면적·층·주소·관리비·입주일·주차·옵션 등 고유 조건은 위 두 자료에 실제로 있는 것만 쓸 것. 두 자료가 다르면 [확인된 ${noun} 정보]를 우선\n- 없는 수치·시세·수익률·개발 호재·현장 방문·고객 반응을 만들지 말 것. 자료에 없는 거리·도보 시간도 만들지 말 것\n- 소재지가 동까지만 공개됐다면 더 자세한 주소를 추측하지 말 것\n- 중개사무소 이름·연락처·링크·\"프로필 링크\" 안내는 쓰지 말 것 (글 끝에 자동으로 붙습니다)\n\n[페이스북 — facebook]\n- 기사 소개형. 첫 문단 1~2문장이 피드에서 \"더 보기\" 전에 보이는 곳이므로 무엇이 어디에 어떤 조건으로 나왔는지 결론부터\n- 문단 3~5개, 문단마다 2~3문장, 전체 300~600자. 기사체 또는 부드러운 존댓말\n- 순서: 결론 → 위치·면적·금액 → 특징 → 주변 교통·생활 정보 → 확인할 점 한 문장\n- hashtags: 3~5개 (지역명·${noun} 종류 중심)\n\n[인스타그램 — instagram]\n- 사진이 주인공이고 글은 짧은 설명입니다. 한 줄에 정보 하나\n- lines 첫 줄: 25자 안팎의 훅 (지역 + ${noun} 핵심, 이모지 1개). 예: \"양재역 인근 36평 사무실 📍\"\n- 이어서 핵심 정보 3~5줄, 줄마다 알맞은 이모지 하나로 시작 (📍 위치 · 📐 면적 · 💰 금액 · 🚇 교통 · ✅ 특징 · 🏢 건물 등)\n- 마지막 1~2줄: 조건을 객관적으로 정리하는 한 문장\n- 전체 lines 6~10줄, 500자 이내\n- hashtags: 8~12개 (지역·동네·${noun} 종류·용도·거래 형태). 띄어쓰기 없이\n\n[스레드 — threads]\n- 말하듯 쓰는 짧은 글. 부드러운 존댓말 대화체(~네요, ~입니다)는 허용하되 사실 원칙은 같습니다\n- posts 첫 글: 450자 이내. 이것만 읽어도 무엇이 어디에 얼마로 나왔는지 알 수 있게\n- 첫 글은 독자의 생각을 묻는 질문 한 문장으로 끝낼 것 (예: \"이 조건이면 어떤 팀에 맞을까요?\"). 문의·연락을 유도하는 질문은 금지\n- 이어 쓰기 글 0~2개 (posts 둘째·셋째 항목): 교통·주변·확인할 점. 글마다 300자 이내\n- topic: 주제 태그 1개 (지역+${noun} 종류, 예: \"양재역사무실\")\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- 배열 한 항목에 문단(줄·글) 하나만 넣고, 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n- hashtags·topic 에는 # 기호를 넣지 마십시오. 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"facebook\": { \"paragraphs\": [\"첫 문단\", \"둘째 문단\"], \"hashtags\": [] },\n  \"instagram\": { \"lines\": [\"훅 한 줄\", \"📍 ...\"], \"hashtags\": [] },\n  \"threads\": { \"posts\": [\"첫 글\"], \"topic\": \"\" }\n}\n\\`\\`\\``;\n}\n\n/* 플랫폼 하나만 고친다 — 고친 플랫폼만 같은 JSON 모양으로 받는다 */\nfunction gwBuildSnsRevisePrompt(channel, request) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const shape = {\n    facebook: '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }',\n    instagram: '{ \"instagram\": { \"lines\": [], \"hashtags\": [] } }',\n    threads: '{ \"threads\": { \"posts\": [], \"topic\": \"\" } }',\n  }[channel] || '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }';\n  return `위에서 작성한 SNS 글 중 [${info.label}] 글만 아래 요청대로 고쳐 주십시오. 다른 플랫폼 글은 출력하지 마십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 금액·면적·층·주소 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 처음의 보도 원칙(권유·호객 표현 금지, 연락처·링크 쓰지 않기)과 ${info.label} 형식 규칙을 그대로 지키십시오.\n\n[출력 형식]\n설명 없이 아래 모양의 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n\\`\\`\\`json\n${shape}\n\\`\\`\\``;\n}\n\n/* ── AI 답변 → 편집용 모양 ──\n   facebook: { body: \"문단\\n\\n문단\", hashtags: [] }\n   instagram: { body: \"줄\\n줄\", hashtags: [] }\n   threads: { posts: [\"글\", …], topic: \"\" }\n   답변에 있는 플랫폼만 돌려준다 (수정 답변은 하나만 온다). */\nfunction gwSnsCleanTags(tags, max) {\n  const seen = new Set();\n  return (Array.isArray(tags) ? tags : String(tags || \"\").split(/[\\s,]+/))\n    .map((tag) => String(tag || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n    .filter((tag) => tag && !seen.has(tag) && seen.add(tag))\n    .slice(0, max || 30);\n}\n\nfunction gwSnsLines(value) {\n  return (Array.isArray(value) ? value : String(value || \"\").split(/\\n+/))\n    .map((line) => String(line == null ? \"\" : line).trim())\n    .filter(Boolean);\n}\n\nfunction gwSnsNormalize(data) {\n  if (!data || typeof data !== \"object\") return null;\n  const out = {};\n  const fb = data.facebook;\n  if (fb && typeof fb === \"object\") {\n    const paragraphs = gwSnsLines(fb.paragraphs || fb.text || fb.body);\n    if (paragraphs.length) out.facebook = { body: paragraphs.join(\"\\n\\n\"), hashtags: gwSnsCleanTags(fb.hashtags, GW_SNS_CHANNELS.facebook.maxTags) };\n  }\n  const ig = data.instagram;\n  if (ig && typeof ig === \"object\") {\n    const lines = gwSnsLines(ig.lines || ig.caption || ig.body);\n    if (lines.length) out.instagram = { body: lines.join(\"\\n\"), hashtags: gwSnsCleanTags(ig.hashtags, GW_SNS_CHANNELS.instagram.maxTags) };\n  }\n  const th = data.threads;\n  if (th && typeof th === \"object\") {\n    const posts = gwSnsLines(th.posts || th.text || th.body);\n    if (posts.length) out.threads = { posts, topic: gwSnsCleanTags([th.topic], 1)[0] || \"\" };\n  }\n  return Object.keys(out).length ? out : null;\n}\n\nfunction gwSnsParse(raw) {\n  const parsed = GWYoutubeJson.parseObject(raw); // ```json 상자 꺼내기·깨진 JSON 고치기는 유튜브와 같다\n  if (!parsed.ok) return parsed;\n  const posts = gwSnsNormalize(parsed.data);\n  if (!posts) return { ok: false, reason: \"페이스북·인스타그램·스레드 글을 찾지 못했습니다.\" };\n  return { ok: true, posts, repaired: parsed.repaired };\n}\n\n/* ── 글 끝에 붙는 것: 링크 · 출처(표시·광고 필수 정보) · 해시태그 ──\n   출처 문구는 블로그와 같다 (GWNaverBlog.sourceBlockLines). */\nfunction gwSnsSourceText(listing, noun) {\n  if (!listing) return \"\";\n  const { lines } = GWNaverBlog.sourceBlockLines(listing, \"\");\n  return [`[${noun} 정보 출처]`, ...lines].join(\"\\n\");\n}\n\nfunction gwSnsCompose(channel, post, ctx) {\n  const c = ctx || {};\n  const noun = c.noun || \"매물\";\n  const url = c.url || \"\";\n  const source = gwSnsSourceText(c.listing, noun);\n  const tagLine = (tags) => (tags || []).map((tag) => `#${tag}`).join(\" \");\n\n  if (channel === \"threads\") {\n    const posts = (post?.posts || []).map((text) => String(text || \"\").trim()).filter(Boolean);\n    if (!posts.length) return { posts: [], text: \"\" };\n    if (post.topic) posts[0] = `${posts[0]}\\n\\n#${post.topic}`;\n    const tail = [url ? `▶ 공실뉴스에서 ${noun} 자세히 보기\\n${url}` : \"\", source].filter(Boolean).join(\"\\n\\n\");\n    if (tail) {\n      const last = posts.length - 1;\n      if (posts[last].length + tail.length + 2 <= GW_SNS_CHANNELS.threads.maxChars) posts[last] = `${posts[last]}\\n\\n${tail}`;\n      else posts.push(tail);\n    }\n    return { posts, text: posts.join(\"\\n\\n―――\\n\\n\") };\n  }\n\n  const body = String(post?.body || \"\").trim();\n  if (!body) return { posts: [], text: \"\" };\n  const parts = [body];\n  if (channel === \"instagram\") {\n    /* 인스타 캡션의 링크는 눌리지 않는다 — 프로필 링크 안내를 먼저, 주소는 복사해 갈 수 있게 글자로 함께 */\n    parts.push(url\n      ? `자세한 ${noun} 정보는 프로필 링크 → 공실뉴스\\n${url}`\n      : `자세한 ${noun} 정보는 프로필 링크 → 공실뉴스`);\n  } else if (url) {\n    parts.push(`▶ 공실뉴스에서 ${noun} 자세히 보기\\n${url}`);\n  }\n  if (source) parts.push(source);\n  const tags = tagLine(post.hashtags);\n  if (tags) parts.push(tags);\n  const text = parts.join(\"\\n\\n\");\n  return { posts: [text], text };\n}\n\n/* ── 사진 고르기: 2번 기사 사진 → 플랫폼별 순서·장수 ──\n   - 실제 사진(대표 먼저) → 공실목록 캡처(proof) → 지도·로드뷰 카드 → AI 이미지 순.\n   - 플랫폼 허용 장수(페이스북 4, 스레드 4, 인스타 10)까지 최대한 담고, 화면에서 직접 고르거나 뺄 수 있게 한다.\n   - 대표(1번)는 실제 사진이 있으면 반드시 실제 사진 — AI 이미지로 매물 사진을 대신하지 않는다. */\nfunction gwSnsIsAi(item) {\n  return Boolean(item && item.kind === \"ai\" && !item.real);\n}\n\nfunction gwSnsPickMedia(channel, media) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const list = (Array.isArray(media) ? media : []).filter((item) => item && item.url);\n  const isCard = (item) => item.kind === \"map\" || item.kind === \"roadview\";\n  const isProof = (item) => item.kind === \"proof\";\n  const real = list.filter((item) => !gwSnsIsAi(item) && !isCard(item) && !isProof(item));\n  real.sort((a, b) => Number(Boolean(b.isCover)) - Number(Boolean(a.isCover)));\n  const proofs = list.filter(isProof);\n  const cards = list.filter(isCard);\n  const ai = list.filter(gwSnsIsAi);\n  return [...real, ...proofs, ...cards, ...ai]\n    .slice(0, info.maxMedia)\n    .map((item) => ({ url: item.url, kind: item.kind || \"photo\", caption: item.caption || \"\", ai: gwSnsIsAi(item) }));\n}\n\n/* 1번(대표) 자리에 AI 이미지를 둘 수 있는가 — 실제 사진이 하나라도 있으면 안 된다 */\nfunction gwSnsCanLead(list, index) {\n  const item = list && list[index];\n  if (!item || !item.ai) return true;\n  return !list.some((other) => other && !other.ai);\n}\n\n/* AI 이미지가 올라갈 사진에 섞여 있으면 \"게시할 때 AI 레이블을 켜세요\" 안내.\n   메타(페이스북·인스타·스레드)의 AI 레이블은 사진·영상용이라, 실제 사진만 올리면 켤 필요가 없다. */\nconst GW_SNS_AI_LABEL_WHERE = {\n  facebook: \"게시물 만들기 창의 이름 아래 [AI 레이블] 단추를 눌러 켜 주세요.\",\n  instagram: \"공유하기 전 캡션 화면의 [고급 설정]에서 [AI 레이블 추가]를 켜 주세요.\",\n  threads: \"게시하기 전 글쓰기 화면의 [AI 레이블] 설정을 켜 주세요.\",\n};\n\nfunction gwSnsAiLabelNote(channel, media) {\n  const info = GW_SNS_CHANNELS[channel];\n  if (!info) return \"\";\n  const count = (Array.isArray(media) ? media : []).slice(0, info.maxMedia).filter((item) => item && item.ai).length;\n  if (!count) return \"\";\n  return `AI로 만든 이미지 ${count}장이 들어 있습니다 — ${GW_SNS_AI_LABEL_WHERE[channel]}`;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_SNS_CHANNELS, GW_SNS_ORDER, gwBuildSnsPrompt, gwBuildSnsRevisePrompt,\n    gwSnsNormalize, gwSnsParse, gwSnsCompose, gwSnsPickMedia, gwSnsCanLead, gwSnsCleanTags, gwSnsAiLabelNote,\n  };\n}\n",
 "gongsil/youtube-json.js": "/* AI가 작성한 유튜브 장면 JSON 검증·정규화 */\n(() => {\n  \"use strict\";\n\n  function extract(raw) {\n    const text = String(raw || \"\").trim();\n    if (!text) return \"\";\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced?.[1]) return fenced[1].trim();\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first >= 0 && last > first ? text.slice(first, last + 1) : \"\";\n  }\n\n  function hasCompleteObject(raw) {\n    const text = String(raw || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n    for (let i = first; i < text.length; i += 1) {\n      const char = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (char === \"\\\\\") escaped = true;\n        else if (char === '\"') inString = false;\n        continue;\n      }\n      if (char === '\"') inString = true;\n      else if (char === \"{\") depth += 1;\n      else if (char === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n    return false;\n  }\n\n  function repair(raw) {\n    let output = \"\";\n    let inString = false;\n    let escaped = false;\n    for (let i = 0; i < raw.length; i += 1) {\n      const char = raw[i];\n      if (inString) {\n        if (escaped) {\n          output += char;\n          escaped = false;\n        } else if (char === \"\\\\\") {\n          output += char;\n          escaped = true;\n        } else if (char === '\"') {\n          output += char;\n          inString = false;\n        } else if (char === \"\\n\" || char === \"\\r\") {\n          if (char === \"\\r\" && raw[i + 1] === \"\\n\") i += 1;\n          output += \"\\\\n\";\n        } else if (char === \"\\t\") output += \"\\\\t\";\n        else output += char;\n        continue;\n      }\n      if (char === '\"') {\n        inString = true;\n        output += char;\n        continue;\n      }\n      if (char === \",\") {\n        let next = i + 1;\n        while (next < raw.length && /\\s/.test(raw[next])) next += 1;\n        if (raw[next] === \"}\" || raw[next] === \"]\") continue;\n      }\n      output += char;\n    }\n    return output;\n  }\n\n  function cleanText(value) {\n    return String(value == null ? \"\" : value).trim();\n  }\n\n  function normalizeScene(scene, index) {\n    if (!scene || typeof scene !== \"object\") return null;\n    const narration = cleanText(scene.narration || scene.script || scene.voiceover || scene.text);\n    const heading = cleanText(scene.heading || scene.title || `장면 ${index + 1}`);\n    const caption = cleanText(scene.caption || scene.subtitle || scene.onScreenText);\n    const visualPrompt = cleanText(scene.visualPrompt || scene.imagePrompt || scene.visual || scene.screen);\n    const visualType = cleanText(scene.visualType || scene.shotType || \"auto\");\n    if (!narration) return null;\n    return {\n      sceneId: cleanText(scene.sceneId),\n      heading,\n      narration,\n      caption,\n      visualType,\n      visualPrompt,\n    };\n  }\n\n  function normalize(data) {\n    if (!data || typeof data !== \"object\") return null;\n    const title = cleanText(data.title || data.videoTitle);\n    const description = cleanText(data.description || data.videoDescription);\n    const rawScenes = Array.isArray(data.scenes) ? data.scenes : [];\n    const scenes = rawScenes.map(normalizeScene).filter(Boolean);\n    if (!title || !scenes.length) return null;\n    return { title, description, scenes };\n  }\n\n  function parse(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    let data;\n    let repaired = false;\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repair(candidate));\n        repaired = true;\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n    const script = normalize(data);\n    if (!script) return { ok: false, reason: \"제목 또는 유효한 장면 대본이 없습니다.\" };\n    return { ok: true, script, repaired };\n  }\n\n  /* 모양을 따지지 않고 JSON 객체만 꺼낸다 — 완성 대본·장면 설명처럼 형식이 다른 답변에 쓴다 */\n  function parseObject(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    try {\n      return { ok: true, data: JSON.parse(candidate), repaired: false };\n    } catch (_strictError) {\n      try {\n        return { ok: true, data: JSON.parse(repair(candidate)), repaired: true };\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n  }\n\n  const api = { extract, hasCompleteObject, normalize, parse, parseObject };\n  globalThis.GWYoutubeJson = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})();\n\n",
 "gongsil/youtube-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   4 · 유튜브 대본 — AI 지시문\n\n   2번 초안 다듬기의 기사와 1번에서 가져온 물건 정보를 자료로 쓴다.\n   기사 프롬프트(prompt.js)와 분리해, 여기서 무엇을 바꿔도 기사 작성에는 영향이 없다.\n\n   일반 매물과 경매·공매 물건은 지시문이 다르다.\n   경매·공매 물건은 1번에서 가져올 때 saleKind(\"경매\"·\"공매\")가 붙어 오므로 그것으로 가른다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_YT_VIDEO_TYPE = {\n  listing: { label: \"매물 소개\", structure: \"훅 → 위치 → 핵심 조건 → 장점 → 확인할 점 → 마무리\" },\n  news: { label: \"부동산 뉴스\", structure: \"헤드라인 → 배경 → 핵심 사실 → 의미 → 확인할 점\" },\n  area: { label: \"지역 분석\", structure: \"지역 소개 → 교통 → 생활권 → 물건 조건 → 정리\" },\n};\n\n/* 경매·공매 물건 — 칩 자리(listing·news·area)는 같고 이름과 흐름이 다르다 */\nconst GW_YT_AUCTION_VIDEO_TYPE = {\n  listing: {\n    label: \"물건 소개\",\n    structure: \"훅 → 위치·물건 종류 → 가격(감정가·최저입찰가·유찰) → 입찰 일정·방법 → 입찰 전 확인할 점 → 마무리\",\n  },\n  news: {\n    label: \"경매 뉴스\",\n    structure: \"헤드라인 → 어떤 물건이 나왔나 → 가격과 유찰 → 이 조건이 뜻하는 것 → 입찰 전 확인할 점\",\n  },\n  area: {\n    label: \"지역 분석\",\n    structure: \"지역 소개 → 교통 → 생활권 → 물건 조건과 가격 → 입찰 일정 → 정리\",\n  },\n};\n\nconst GW_YT_DURATION = {\n  short: { label: \"60초 쇼츠\", seconds: 60, chars: \"약 280~380자\" },\n  medium: { label: \"약 2분\", seconds: 120, chars: \"약 600~850자\" },\n  long: { label: \"약 5분\", seconds: 300, chars: \"약 1,500~2,100자\" },\n};\n\nconst GW_YT_TONE = {\n  news: { label: \"뉴스형\", prompt: \"정확하고 신뢰감 있는 뉴스 앵커형\" },\n  friendly: { label: \"친근한 설명\", prompt: \"부드럽고 친근한 설명형 (존댓말)\" },\n  expert: { label: \"전문가 분석\", prompt: \"차분하고 논리적인 부동산 전문가 분석형\" },\n};\n\n/* 경매·공매 물건인가 */\nconst gwYtIsAuction = (vacancy) => Boolean(vacancy && vacancy.saleKind);\n\n/* 물건 종류에 맞는 콘텐츠 유형 표 */\nfunction gwYtVideoTypes(vacancy) {\n  return gwYtIsAuction(vacancy) ? GW_YT_AUCTION_VIDEO_TYPE : GW_YT_VIDEO_TYPE;\n}\n\nfunction gwYtSourceText(source) {\n  const input = source || {};\n  const article = input.article || {};\n  const lines = [];\n  const push = (label, value) => {\n    const text = String(value == null ? \"\" : value).trim();\n    if (text) lines.push(`[${label}] ${text}`);\n  };\n  push(\"기사 제목\", article.title);\n  push(\"기사 부제\", Array.isArray(article.subtitles) ? article.subtitles.join(\" / \") : \"\");\n  push(\"기사 본문\", article.body);\n\n  const facts = input.vacancy && typeof gwFactLines === \"function\" ? gwFactLines(input.vacancy) : \"\";\n  return lines.join(\"\\n\") + (facts ? `\\n\\n[물건 정보 — 확인된 사실]\\n${facts}` : \"\");\n}\n\n/* ══════════════════════════════════════════════════════════════\n   대본 쓰기 — AI 는 읽을 원고 전체(완성 대본)만 쓴다\n   ══════════════════════════════════════════════════════════════ */\nconst GW_YT_SCRIPT_SHAPE = `\\`\\`\\`json\n{\n  \"title\": \"유튜브 제목\",\n  \"narration\": [\"읽을 원고 첫 문단\", \"둘째 문단\"]\n}\n\\`\\`\\``;\n\n/* 원고 모양·출력 형식 — 일반·경매 공통 */\nconst GW_YT_OUTPUT = `[출력 형식]\n설명이나 인사말 없이 아래 형식의 유효한 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- narration 은 문단별 문자열 배열입니다. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n\nfunction gwBuildYtScriptPrompt(source, settings) {\n  if (gwYtIsAuction(source && source.vacancy)) return gwBuildYtAuctionScriptPrompt(source, settings);\n  const s = settings || {};\n  const type = GW_YT_VIDEO_TYPE[s.videoType] || GW_YT_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 유튜브 대본 작가입니다.\n아래 공실뉴스 기사와 확인된 물건 정보만 사용해 ${type.label} 영상의 내레이션 원고를 작성하십시오.\n\n${gwYtSourceText(source)}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[보도 원칙]\n- \"공실뉴스에 이런 물건이 나왔다\"는 객관적인 소개입니다. 3인칭 전달체로 쓰십시오.\n- 권유·호객 표현을 쓰지 마십시오: \"지금 바로 문의하세요\", \"놓치지 마세요\", \"강력 추천\", \"지금이 기회\" 등.\n- 중개사무소 이름·전화번호를 원고에 넣지 마십시오.\n\n[사실 원칙]\n- 자료에 없는 가격·면적·주소·시세·수익률·교통 시간·개발 호재·인터뷰를 만들지 마십시오.\n- 숫자와 고유명사는 자료 그대로 쓰십시오.\n- 실제 사진으로 확인되지 않은 내부·외관을 사실처럼 단정하지 마십시오.\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 마지막은 핵심 조건과 확인할 점을 정리하고 \"자세한 내용은 공실뉴스에서 확인할 수 있습니다.\"로 맺습니다.\n\n${GW_YT_OUTPUT}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 물건 대본\n\n   기사(경매 기사 프롬프트)와 같은 원칙을 따른다.\n   - 가격·일정·번호는 자료 그대로. 지어내면 큰 사고다\n   - 경매·공매 제도의 일반 설명은 해도 되지만, 투자 권유·낙찰가 예측은 어디서도 하지 않는다\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildYtAuctionScriptPrompt(source, settings) {\n  const s = settings || {};\n  const type = GW_YT_AUCTION_VIDEO_TYPE[s.videoType] || GW_YT_AUCTION_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n  const vacancy = (source && source.vacancy) || {};\n  const saleKind = vacancy.saleKind === \"공매\" ? \"공매\" : \"경매\";\n  const saleName = saleKind === \"공매\" ? \"공매(온비드)\" : \"법원 경매\";\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경매·공매 담당 유튜브 대본 작가입니다.\n아래 공실뉴스 기사와 확인된 ${saleName} 물건 정보만 사용해 ${type.label} 영상의 내레이션 원고를 작성하십시오.\n\n${gwYtSourceText(source)}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[보도 원칙]\n- \"공실뉴스 공실열람에 이런 ${saleKind} 물건이 나왔다\"는 객관적인 소개입니다. 3인칭 전달체로 쓰십시오.\n- 투자 권유·호객 표현을 쓰지 마십시오: \"싸게 살 기회\", \"놓치지 마세요\", \"지금이 기회\", \"강력 추천\", \"수익이 기대된다\", \"반값에 잡으세요\" 등.\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호)를 넣지 마십시오.\n- \"본 정보는 참고용이며 법적 책임을 지지 않습니다\" 같은 입찰 전 법적 주의사항 안내문을 읽지 마십시오.\n\n[사실 원칙]\n- 감정가·최저입찰가·감정가 대비 비율·유찰 횟수·입찰 시작/마감·개찰일시·입찰보증금·면적·주소·사건번호(관리번호)·집행기관(관할법원)은 자료 그대로 쓰십시오.\n- 금액은 귀로 듣기 쉽게 억·만원 단위로 읽되(예: 2억 9,100만원) 자료의 숫자와 한 자리도 달라지면 안 됩니다.\n- 입찰 일정이 자료에 없으면 날짜를 만들지 마십시오.\n- 자료에 없는 권리관계·임차인·선순위 채권·체납액·건물 연식·낙찰 결과를 만들지 마십시오.\n- 낙찰가·낙찰가율·수익률·시세 상승을 예측하지 마십시오.\n- \"안전한 물건이다\", \"권리상 문제가 없다\", \"반드시 낙찰된다\" 같은 단정을 하지 마십시오.\n- 실제 사진으로 확인되지 않은 내부·외관을 사실처럼 단정하지 마십시오.\n\n[해설로 쓸 수 있는 것]\n- ${saleKind} 제도의 일반 설명은 한두 문장으로 짧게 넣어도 됩니다 — 유찰되면 최저입찰가가 낮아지는 구조, 입찰보증금, 개찰 절차, 명도의 의미 등.\n- ${saleKind} 물건을 볼 때 일반적으로 확인하는 점 — 현장 상태, 점유와 명도, 권리관계, 관리비 체납 같은 추가 비용.\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다. 지역·물건 종류와 함께 최저입찰가나 유찰 횟수처럼 자료에 있는 사실로 시작하십시오. 과장하지 마십시오.\n- 첫 부분에서 ${saleKind} 물건이라는 점, 소재지, 물건 종류, 감정가와 최저입찰가를 밝히십시오.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 마지막은 가격·일정 조건을 정리하고 \"권리관계와 물건 상태는 입찰 전 공고문과 현장에서 직접 확인할 필요가 있습니다. 자세한 내용은 공실뉴스 공실열람에서 확인할 수 있습니다.\"로 맺습니다.\n- title 은 [공실열람 ${saleKind}] 로 시작하고 지역·물건 종류·최저입찰가(또는 유찰 횟수)를 담으십시오.\n\n${GW_YT_OUTPUT}`;\n}\n\n/* 수정 요청 — 같은 대화에 이어 붙인다. 작업창에서 직접 고친 원고를 함께 보낸다. */\nfunction gwBuildYtRevisePrompt(full, request, vacancy) {\n  const current = {\n    title: full?.title || \"\",\n    narration: String(full?.text || \"\").split(/\\n{2,}/).map((p) => p.trim()).filter(Boolean),\n  };\n  const keep = gwYtIsAuction(vacancy)\n    ? `- 감정가·최저입찰가·유찰 횟수·입찰 일정·입찰보증금·면적·주소·사건번호(관리번호) 등 사실과 숫자는 바꾸거나 새로 만들지 마십시오.\n- 투자 권유, 낙찰가·수익 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문을 넣지 마십시오.`\n    : `- 기사와 물건 정보의 사실·숫자는 바꾸거나 새로 만들지 마십시오.\n- 권유·호객 표현과 중개사무소 연락처를 넣지 마십시오.`;\n  return `아래 현재 유튜브 원고를 요청대로 고쳐 주십시오.\n\n[수정 요청]\n${String(request || \"\").trim()}\n\n[현재 원고]\n${JSON.stringify(current, null, 2)}\n\n[지킬 것]\n${keep}\n- 읽을 문장만 쓰고, 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 원고 전체를 빠짐없이 다시 출력하십시오. 고친 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n}\n\n/* ── 원고 길이 — 한국어 내레이션은 1초에 약 5.5글자(공백 제외)로 읽는다고 본다 ── */\nconst GW_YT_CHARS_PER_SEC = 5.5;\n\nconst gwYtCharCount = (text) => String(text || \"\").replace(/\\s/g, \"\").length;\n\nfunction gwYtSpeechSeconds(text) {\n  return Math.round(gwYtCharCount(text) / GW_YT_CHARS_PER_SEC);\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_YT_VIDEO_TYPE,\n    GW_YT_AUCTION_VIDEO_TYPE,\n    GW_YT_DURATION,\n    GW_YT_TONE,\n    gwYtVideoTypes,\n    gwYtSourceText,\n    gwBuildYtScriptPrompt,\n    gwBuildYtAuctionScriptPrompt,\n    gwBuildYtRevisePrompt,\n    gwYtCharCount,\n    gwYtSpeechSeconds,\n  };\n}\n",
 "gongsil/content-naver.js": "/* 네이버 블로그 SmartEditor ONE 글쓰기 화면\n\n   - 발행 버튼은 대신 누르지 않는다.\n   - 비어 있는 새 글에만 제목과 본문을 넣는다.\n   - 편집기는 mainFrame 안에 있으므로 manifest의 all_frames로 각 프레임에서 실행한다.\n   - 글과 사진은 숨은 input_buffer iframe에 붙여넣기 이벤트로 넣는다 (아래 clickAt·pasteInto).\n   - 태그는 사용자가 발행 창을 열면 태그 칸에 채운다.\n*/\n(() => {\n  \"use strict\";\n\n  const TITLE_SELECTORS = [\n    \".se-documentTitle .se-title-text[contenteditable='true']\",\n    \".se-title-text[contenteditable='true']\",\n    \".se-documentTitle textarea\",\n    \".se-title-textarea\",\n    \".se-documentTitle .se-title-text\",\n    \".se-title-text\",\n    \"textarea[placeholder*='제목']\",\n    \"input[placeholder*='제목']\",\n    \"[contenteditable='true'][data-placeholder*='제목']\",\n  ];\n\n  const BODY_SELECTORS = [\n    \".se-component.se-text .se-component-content .se-text-paragraph[contenteditable='true']\",\n    \".se-component-content .se-text-paragraph[contenteditable='true']\",\n    \".se-component.se-text .se-text-paragraph[contenteditable='true']\",\n    \".se-section-text .se-text-paragraph[contenteditable='true']\",\n    \".se-component-content .se-text-paragraph\",\n    \".se-content .se-text-paragraph[contenteditable='true']\",\n    \".se-content [contenteditable='true']\",\n    \".se-main-container [contenteditable='true']\",\n    \"[contenteditable='true'][data-placeholder*='본문']\",\n  ];\n\n  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n\n  function collectRoots() {\n    const roots = [];\n    const seen = new Set();\n\n    function visit(doc) {\n      if (!doc || seen.has(doc)) return;\n      seen.add(doc);\n      roots.push(doc);\n\n      for (const frame of doc.querySelectorAll(\"iframe\")) {\n        try {\n          if (frame.contentDocument) visit(frame.contentDocument);\n        } catch (_) {\n          /* 다른 출처 iframe은 해당 프레임의 content script가 직접 처리한다. */\n        }\n      }\n    }\n\n    visit(document);\n    return roots;\n  }\n\n  function overlaps(candidate, excluded) {\n    return excluded.some((item) => item && (\n      candidate === item || candidate.contains(item) || item.contains(candidate)\n    ));\n  }\n\n  function pick(selectors, excluded = []) {\n    const excludedList = Array.isArray(excluded) ? excluded : [excluded];\n    for (const root of collectRoots()) {\n      for (const selector of selectors) {\n        for (const candidate of root.querySelectorAll(selector)) {\n          if (!candidate || overlaps(candidate, excludedList)) continue;\n          const style = candidate.ownerDocument.defaultView?.getComputedStyle(candidate);\n          if (style && (style.display === \"none\" || style.visibility === \"hidden\")) continue;\n          return candidate;\n        }\n      }\n    }\n    return null;\n  }\n\n  function normalizeTarget(candidate, kind) {\n    if (!candidate) return null;\n    if (/^(TEXTAREA|INPUT)$/i.test(candidate.tagName) || candidate.isContentEditable) return candidate;\n\n    const inner = candidate.querySelector?.(\"[contenteditable='true'], textarea, input\");\n    if (inner) return inner;\n\n    // SmartEditor ONE의 일부 버전은 실제 편집 문단에 contenteditable 속성을 늦게 붙인다.\n    if (kind === \"title\" && candidate.matches?.(\".se-title-text\")) return candidate;\n    if (kind === \"body\" && candidate.matches?.(\".se-text-paragraph\")) return candidate;\n    return null;\n  }\n\n  function findEditor() {\n    const rawTitle = pick(TITLE_SELECTORS);\n    const title = normalizeTarget(rawTitle, \"title\");\n    const rawBody = pick(BODY_SELECTORS, [rawTitle, title]);\n    const body = normalizeTarget(rawBody, \"body\");\n    return { title, body };\n  }\n\n  function wakeBodyEditor(title) {\n    const container = pick([\".se-content\", \".se-main-container\"], title ? [title] : []);\n    if (!container) return;\n    container.click();\n    container.focus?.();\n  }\n\n  async function waitForEditor(timeoutMs = 12000) {\n    const until = Date.now() + timeoutMs;\n    let found = findEditor();\n    while ((!found.title || !found.body) && Date.now() < until) {\n      wakeBodyEditor(found.title);\n      await sleep(250);\n      found = findEditor();\n    }\n    return found;\n  }\n\n  function cleanText(value) {\n    return String(value || \"\").replace(/[\\u200B\\uFEFF]/g, \"\").trim();\n  }\n\n  function currentText(el) {\n    if (!el) return \"\";\n    const value = /^(TEXTAREA|INPUT)$/i.test(el.tagName) ? el.value : el.innerText || el.textContent;\n    const text = cleanText(value);\n    const placeholder = cleanText(\n      el.getAttribute(\"placeholder\") ||\n      el.getAttribute(\"data-placeholder\") ||\n      el.getAttribute(\"aria-placeholder\") ||\n      \"\"\n    );\n    const editorPrompt = /^(제목|본문을 입력해 주세요[.!]?|내용을 입력해 주세요[.!]?|글감과 함께 나의 일상을 기록해보세요[.!]?)$/;\n    return text && text !== placeholder && !editorPrompt.test(text) ? text : \"\";\n  }\n\n  function dispatchInput(el, text) {\n    const view = el.ownerDocument.defaultView;\n    try {\n      el.dispatchEvent(new view.InputEvent(\"input\", {\n        bubbles: true,\n        cancelable: true,\n        composed: true,\n        inputType: \"insertText\",\n        data: text,\n      }));\n    } catch (_) {\n      el.dispatchEvent(new view.Event(\"input\", { bubbles: true, cancelable: true }));\n    }\n    el.dispatchEvent(new view.Event(\"change\", { bubbles: true }));\n  }\n\n  function setFormValue(el, text) {\n    const view = el.ownerDocument.defaultView;\n    const proto = el.tagName === \"TEXTAREA\" ? view.HTMLTextAreaElement.prototype : view.HTMLInputElement.prototype;\n    const setter = Object.getOwnPropertyDescriptor(proto, \"value\")?.set;\n    if (setter) setter.call(el, text);\n    else el.value = text;\n    dispatchInput(el, text);\n  }\n\n  /* SmartEditor ONE은 보이는 문단에 직접 입력을 받지 않는다.\n     제목·본문을 눌러 편집기 커서를 옮긴 뒤, 숨은 input_buffer iframe에 붙여넣기 이벤트를 보내야\n     편집기가 자기 문서 데이터로 받아들인다. (2026-09-25 실제 글쓰기 화면에서 확인) */\n  function clickAt(el) {\n    const view = el.ownerDocument.defaultView;\n    const rect = el.getBoundingClientRect();\n    const init = {\n      bubbles: true,\n      cancelable: true,\n      view,\n      button: 0,\n      clientX: rect.left + 5,\n      clientY: rect.top + rect.height / 2,\n    };\n    [\"mousedown\", \"mouseup\", \"click\"].forEach((type) => el.dispatchEvent(new view.MouseEvent(type, init)));\n  }\n\n  function findInputBuffer(doc) {\n    const frame = doc.querySelector(\"iframe[id*='input_buffer'], iframe[class*='input_buffer']\");\n    try {\n      return frame?.contentDocument?.body || null;\n    } catch (_) {\n      return null;\n    }\n  }\n\n  function pasteInto(doc, { html, text, file }) {\n    const target = findInputBuffer(doc);\n    if (!target) throw new Error(\"네이버 편집기 입력창(input_buffer)을 찾지 못했습니다. 글쓰기 화면을 새로고침(F5)해 주세요.\");\n    const view = target.ownerDocument.defaultView;\n    const transfer = new view.DataTransfer();\n    if (file) transfer.items.add(file);\n    if (html) transfer.setData(\"text/html\", html);\n    if (text) transfer.setData(\"text/plain\", text);\n    const event = new view.ClipboardEvent(\"paste\", { clipboardData: transfer, bubbles: true, cancelable: true });\n    target.dispatchEvent(event);\n    return event.defaultPrevented;\n  }\n\n  function htmlToText(html) {\n    const box = document.createElement(\"div\");\n    box.innerHTML = html;\n    return Array.from(box.children).map((node) => node.textContent).join(\"\\n\");\n  }\n\n  function extensionFor(type) {\n    if (/png/i.test(type)) return \"png\";\n    if (/webp/i.test(type)) return \"webp\";\n    if (/gif/i.test(type)) return \"gif\";\n    return \"jpg\";\n  }\n\n  function dataUrlToFile(dataUrl, index) {\n    const match = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(String(dataUrl || \"\"));\n    if (!match) return null;\n    const type = match[1] && match[1].startsWith(\"image/\") ? match[1] : \"image/jpeg\";\n    const raw = match[2] ? atob(match[3]) : decodeURIComponent(match[3]);\n    const bytes = new Uint8Array(raw.length);\n    for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);\n    return new File([bytes], `gongsil-blog-${Date.now()}-${index + 1}.${extensionFor(type)}`, { type });\n  }\n\n  /* 편집기 요소는 .se-components-wrap 아래에 있다. 빈 새 글 = 제목(se-documentTitle) + 본문 문단(se-text) 하나. */\n  function bodyComponents(doc) {\n    return Array.from(doc.querySelectorAll(\".se-components-wrap .se-component\"))\n      .filter((component) => !component.classList.contains(\"se-documentTitle\"));\n  }\n\n  function countEditorImages(doc) {\n    return bodyComponents(doc).reduce((count, component) => {\n      if (component.classList.contains(\"se-image\")) return count + 1;\n      if (component.classList.contains(\"se-imageGroup\")) return count + component.querySelectorAll(\"img\").length;\n      return count;\n    }, 0);\n  }\n\n  function bodyHasContent(doc, body) {\n    if (currentText(body)) return true;\n    return bodyComponents(doc).length > 1;\n  }\n\n  /* ── 발행 창 태그 칸: 사용자가 [발행]을 눌러 창이 열리면 태그를 채운다 ── */\n  let pendingTags = [];\n  let tagObserver = null;\n\n  function pressEnter(el) {\n    const view = el.ownerDocument.defaultView;\n    const init = { bubbles: true, cancelable: true, key: \"Enter\", code: \"Enter\", keyCode: 13, which: 13 };\n    [\"keydown\", \"keypress\", \"keyup\"].forEach((type) => el.dispatchEvent(new view.KeyboardEvent(type, init)));\n  }\n\n  async function fillTags(input) {\n    const tags = pendingTags;\n    pendingTags = [];\n    input.dataset.gwTagsFilled = \"1\";\n    for (const tag of tags) {\n      input.focus();\n      setFormValue(input, tag);\n      await sleep(80);\n      pressEnter(input);\n      await sleep(150);\n    }\n  }\n\n  function watchPublishTags(doc, tags) {\n    pendingTags = tags;\n    tagObserver?.disconnect();\n    if (!tags.length) return;\n    const check = () => {\n      if (!pendingTags.length) {\n        tagObserver?.disconnect();\n        return;\n      }\n      const input = Array.from(doc.querySelectorAll(\"input[placeholder*='태그']\"))\n        .find((item) => !item.dataset.gwTagsFilled && item.getBoundingClientRect().width > 0);\n      if (input) fillTags(input);\n    };\n    tagObserver = new MutationObserver(check);\n    tagObserver.observe(doc.body, { childList: true, subtree: true });\n    // 30분 안에 발행 창을 열지 않으면 감시를 끝낸다\n    setTimeout(() => tagObserver?.disconnect(), 30 * 60 * 1000);\n  }\n\n  async function applyBlogDraft(payload) {\n    const titleText = cleanText(payload?.title);\n    const blocks = Array.isArray(payload?.blocks) ? payload.blocks : [];\n    if (!titleText || !blocks.some((block) => block.type === \"html\")) {\n      return { ok: false, error: \"블로그 제목과 본문이 비어 있습니다.\" };\n    }\n\n    const editor = await waitForEditor();\n    if (!editor.title || !editor.body) {\n      return { ok: false, error: \"네이버 블로그 제목 또는 본문 입력칸을 찾지 못했습니다.\" };\n    }\n    const doc = editor.body.ownerDocument;\n    if (!findInputBuffer(doc)) {\n      return { ok: false, error: \"네이버 편집기 입력창을 찾지 못했습니다. 글쓰기 화면을 새로고침(F5)한 뒤 다시 보내 주세요.\" };\n    }\n\n    // 본문이 비어 있어야 보낸다. 제목만 같은 글로 들어가 있으면(이전 시도) 제목은 건너뛰고 본문만 넣는다.\n    const existingTitle = currentText(editor.title);\n    if (bodyHasContent(doc, editor.body) || (existingTitle && existingTitle !== titleText)) {\n      return {\n        ok: false,\n        error: \"네이버 글쓰기 화면에 이미 내용이 있습니다. 새 글쓰기 화면에서 다시 전송해 주세요.\",\n      };\n    }\n\n    if (!existingTitle) {\n      clickAt(editor.title);\n      await sleep(300);\n      if (!pasteInto(doc, { text: titleText })) {\n        return { ok: false, error: \"네이버 편집기가 제목 입력을 받지 않았습니다. 글쓰기 화면을 새로고침(F5)해 주세요.\" };\n      }\n      await sleep(300);\n    }\n\n    clickAt(editor.body);\n    await sleep(300);\n\n    const imagesBefore = countEditorImages(doc);\n    let imagesSent = 0;\n    for (let index = 0; index < blocks.length; index += 1) {\n      const block = blocks[index];\n      if (block.type === \"html\") {\n        if (!pasteInto(doc, { html: block.html, text: htmlToText(block.html) })) {\n          return { ok: false, error: \"네이버 편집기가 본문 입력을 받지 않았습니다. 글쓰기 화면을 새로고침(F5)해 주세요.\" };\n        }\n        await sleep(300);\n      } else if (block.type === \"image\" && block.dataUrl) {\n        const file = dataUrlToFile(block.dataUrl, index);\n        if (!file) continue;\n        pasteInto(doc, { file });\n        imagesSent += 1;\n        await sleep(1200); // 편집기가 사진 칸을 만들고 커서를 사진 뒤로 옮길 시간\n      }\n    }\n\n    // 사진은 업로드가 끝나야 칸이 확정되므로 잠시 기다리며 센다\n    let imagesInserted = 0;\n    for (let waited = 0; waited <= 6000; waited += 500) {\n      imagesInserted = Math.min(imagesSent, Math.max(0, countEditorImages(doc) - imagesBefore));\n      if (imagesInserted >= imagesSent) break;\n      await sleep(500);\n    }\n\n    watchPublishTags(doc, Array.isArray(payload?.tags) ? payload.tags : []);\n\n    return { ok: true, imagesInserted };\n  }\n\n  chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {\n    if (msg?.type === \"GW_PING_NAVER_WRITE\") {\n      waitForEditor(2500)\n        .then((editor) => sendResponse({\n          ok: Boolean(editor.title && editor.body),\n          hasTitle: Boolean(editor.title),\n          hasBody: Boolean(editor.body),\n          frameUrl: location.href,\n        }))\n        .catch(() => sendResponse({ ok: false, frameUrl: location.href }));\n      return true;\n    }\n\n    if (msg?.type === \"GW_APPLY_BLOG_DRAFT\") {\n      applyBlogDraft(msg.payload)\n        .then(sendResponse)\n        .catch((error) => sendResponse({ ok: false, error: error.message || String(error) }));\n      return true;\n    }\n\n    return false;\n  });\n})();\n",
 "interior/interior-spec.js": "/* ══════════════════════════════════════════════════════════════\n   아파트 내부 인테리어 예측 시뮬레이터 — 인테리어 조건과 프롬프트\n\n   공실뉴스 웹 시뮬레이터(marketing/home-interior)의 선택지와 프롬프트를\n   글자 그대로 옮겨 왔다. 웹 시뮬레이터는 2026-10-01 삭제했으므로 이제 이 파일이 원본이다.\n   (옛 원본은 git 이력의 marketing/home-interior/constants.ts · services/geminiService.ts)\n\n   웹 시뮬레이터와 다른 점\n   1) 웹은 API 의 responseSchema 로 JSON 형식을 넘겼다. 채팅 화면에는 그 방법이 없어\n      같은 스키마(필드 이름·설명 원문)를 글로 덧붙인다.\n   2) 채팅 화면용 문장은 원문 뒤에만 덧붙인다 (리모델링 작성기와 같은 원칙).\n\n   함수·변수 이름(rm…, RM_…)은 리모델링 작성기(remodeling10)와 같게 두었다.\n   sim.js · panel.js 를 그대로 쓰기 위해서다.\n   ══════════════════════════════════════════════════════════════ */\n\n/* 공간 유형 — 하나만 고른다 (웹은 드롭다운) */\nconst RM_ROOMS = [\n  { id: \"living-room\", name: \"거실 (Living Room)\" },\n  { id: \"bedroom\", name: \"침실 (Bedroom)\" },\n  { id: \"kitchen\", name: \"주방/다이닝 (Kitchen/Dining)\" },\n  { id: \"bathroom\", name: \"욕실 (Bathroom)\" },\n  { id: \"entrance\", name: \"현관/복도 (Entrance/Hallway)\" },\n  { id: \"balcony\", name: \"발코니/베란다 (Balcony)\" },\n];\n\nconst RM_OPTIONS = {\n  style: [\n    { id: \"modern\", name: \"모던 & 심플 (Modern & Simple)\" },\n    { id: \"scandinavian\", name: \"북유럽/스칸디나비안 (Scandinavian)\" },\n    { id: \"minimalist\", name: \"미니멀리즘 (Minimalist)\" },\n    { id: \"industrial\", name: \"인더스트리얼 (Industrial)\" },\n    { id: \"classic\", name: \"클래식/앤티크 (Classic)\" },\n    { id: \"korean-modern\", name: \"한옥 모던/젠 스타일 (Korean Modern)\" },\n  ],\n  ceiling: [\n    { id: \"flat\", name: \"평천장 (Flat/General)\" },\n    { id: \"well\", name: \"우물천장/등박스 (Tray/Coffered)\" },\n    { id: \"exposed\", name: \"노출 천장 (Exposed Concrete)\" },\n    { id: \"molding\", name: \"웨인스코팅/몰딩 (Molded)\" },\n    { id: \"wood-beam\", name: \"서까래/우드 빔 (Wood Beams)\" },\n    { id: \"louver\", name: \"루버/격자 포인트 (Louver/Grid)\" },\n  ],\n  floor: [\n    { id: \"light-wood\", name: \"밝은 우드 마루 (Light Wood)\" },\n    { id: \"dark-wood\", name: \"짙은 우드 마루 (Dark Wood)\" },\n    { id: \"porcelain-tile\", name: \"포세린 타일 (Matte Tile)\" },\n    { id: \"marble\", name: \"대리석/폴리싱 타일 (Marble)\" },\n    { id: \"herringbone\", name: \"헤링본 패턴 (Herringbone)\" },\n    { id: \"concrete\", name: \"노출 콘크리트/에폭시 (Concrete)\" },\n  ],\n  wall: [\n    { id: \"white-wallpaper\", name: \"화이트 실크벽지\" },\n    { id: \"paint-color\", name: \"컬러 페인트 도장\" },\n    { id: \"wood-panel\", name: \"템바보드/우드 패널\" },\n    { id: \"stone-tile\", name: \"석재/아트월 타일\" },\n    { id: \"brick\", name: \"파벽돌 포인트\" },\n    { id: \"wainscoting\", name: \"웨인스코팅 (몰딩)\" },\n  ],\n  lighting: [\n    { id: \"warm-white\", name: \"전구색 (따뜻한 느낌)\" },\n    { id: \"daylight\", name: \"주광색 (밝고 환한 느낌)\" },\n    { id: \"indirect\", name: \"간접 조명 중심 (은은함)\" },\n    { id: \"spotlight\", name: \"스포트라이트/트랙 조명\" },\n    { id: \"pendant\", name: \"포인트 펜던트 조명\" },\n    { id: \"chandelier\", name: \"샹들리에/고급 조명\" },\n  ],\n  furniture: [\n    { id: \"wood-rattan\", name: \"우드 & 라탄\" },\n    { id: \"fabric-beige\", name: \"패브릭 (베이지/그레이)\" },\n    { id: \"leather-dark\", name: \"가죽 (다크/카멜)\" },\n    { id: \"metal-glass\", name: \"메탈 & 유리\" },\n    { id: \"pastel\", name: \"파스텔 포인트\" },\n    { id: \"vivid\", name: \"비비드 포인트\" },\n  ],\n};\n\n/* 화면에 보이는 순서와 이름 — 웹 시뮬레이터 \"2. 인테리어 조건 입력\"과 같다 */\nconst RM_GROUPS = [\n  { key: \"style\", label: \"인테리어 스타일\" },\n  { key: \"ceiling\", label: \"천장 스타일\" },\n  { key: \"floor\", label: \"바닥재\" },\n  { key: \"wall\", label: \"벽면 마감\" },\n  { key: \"furniture\", label: \"가구 톤/소재\" },\n  { key: \"lighting\", label: \"조명 분위기\" },\n];\n\n/* 예측 이미지는 1장으로 고정한다 (웹 시뮬레이터는 1~5개). 한 장이면 결과표가 바로 나오고 기사 사진도 명확하다 */\nconst RM_VERSIONS = [1];\nconst RM_RATIOS = [\n  /* 원본과 같게 — 기본값. 방 사진을 다른 비율로 강제하면 창·문이 잘리거나 방이 넓게 왜곡된다 */\n  { id: \"original\", name: \"원본 (같은 구도)\" },\n  { id: \"1:1\", name: \"1:1 (정방형)\" },\n  { id: \"4:3\", name: \"4:3 (표준)\" },\n  { id: \"3:2\", name: \"3:2 (사진)\" },\n  { id: \"16:9\", name: \"16:9 (와이드)\" },\n];\n\n/* 웹 시뮬레이터의 처음 선택값 (id 로 둔다) — 각 항목의 첫 번째\n   버전 수는 1개로 고정한다 (웹은 2개) */\nfunction rmDefaultDesign() {\n  return {\n    roomType: \"living-room\",\n    style: [\"modern\"],\n    ceiling: [\"flat\"],\n    floor: [\"light-wood\"],\n    wall: [\"white-wallpaper\"],\n    lighting: [\"warm-white\"],\n    furniture: [\"wood-rattan\"],\n    versions: 1,\n    aspectRatio: \"original\",\n  };\n}\n\n/* 고른 id → 이름 목록 */\nfunction rmNames(key, ids) {\n  const list = RM_OPTIONS[key] || [];\n  return (ids || []).map((id) => (list.find((o) => o.id === id) || {}).name).filter(Boolean);\n}\n\n/* 공간 유형 id → 이름 */\nfunction rmRoomName(id) {\n  return (RM_ROOMS.find((r) => r.id === id) || RM_ROOMS[0]).name;\n}\n\n/* \"거실 (Living Room)\" → \"거실\" — 결과표·기사에 쓰는 짧은 이름 */\nfunction rmRoomShort(id) {\n  return rmRoomName(id).replace(/\\s*\\(.*\\)\\s*$/, \"\");\n}\n\n/* ── 프롬프트 1: 설계 지시서 (웹 시뮬레이터 원문) ── */\nfunction rmBuildSpecPrompt(design) {\n  const n = design || rmDefaultDesign();\n  const join = (key) => rmNames(key, n[key]).join(\", \");\n  return `\n    역할: 당신은 '아파트 내부 인테리어 예측 시뮬레이터'의 수석 인테리어 디자이너입니다.\n    목표: 사용자가 제공한 공간 정보와 설계 조건을 바탕으로, 사실적인 \"인테리어 예측 렌더\" 이미지를 생성하기 위한 상세한 지시사항과 요약 정보를 JSON 형식으로 생성합니다. 이 JSON의 모든 텍스트는 한국어로 작성되어야 하지만, 'imagePrompt'와 'versionDiffsEn' 필드만은 이미지 생성 모델의 성능을 위해 영어로 작성해야 합니다.\n\n    사용자 입력:\n    - 공간 유형: ${rmRoomName(n.roomType)}\n    - 인테리어 스타일: ${join(\"style\")}\n    - 천장 스타일: ${join(\"ceiling\")}\n    - 바닥재: ${join(\"floor\")}\n    - 벽면 마감: ${join(\"wall\")}\n    - 조명 분위기: ${join(\"lighting\")}\n    - 가구 톤/소재: ${join(\"furniture\")}\n    - 생성 버전 수: ${n.versions}\n\n    핵심 원칙 준수 (JSON 생성 시 이 원칙들을 반영해주세요):\n    - 구조 보존: 원본 공간의 창문 위치, 구조벽, 천장 높이 등은 유지.\n    - 현실성: 포토리얼리스틱 스타일, 과장된 CG 금지. 자연스러운 빛 반사 및 그림자.\n    - 스타일 일관성: 선택된 인테리어 스타일, 천장 마감, 조명에 맞는 가구 배치와 소품 선정.\n    - 디테일: 바닥재의 패턴(헤링본 등), 벽지의 질감, 조명의 색온도 반영.\n    - 텍스트 제한: 이미지 생성 프롬프트(imagePrompt) 작성 시, 이미지 내에 한글 텍스트(Hangul)가 절대 포함되지 않도록 명시하세요.\n\n    출력 형식(JSON):\n    반드시 아래 스키마를 따르는 JSON 객체를 생성해주세요.\n\n${rmSpecSchemaText(n.versions)}\n\n    ※ imagePrompt 에는 카메라 위치·렌즈·시점·구도·화각(eye-level, wide-angle, two-point perspective 등)을 쓰지 마십시오.\n      구도는 첨부할 원본 사진을 그대로 따르고, imagePrompt 는 실내의 마감재·색·가구·조명·소품만 설명하십시오.\n    ※ 이미지는 아직 만들지 말고, 위 JSON 객체 하나만 코드 블록으로 출력하십시오. 설명 문장은 덧붙이지 마십시오.`;\n}\n\n/* 웹 시뮬레이터가 responseSchema 로 넘기던 형식을 글로 적는다 (필드 설명 원문) */\nfunction rmSpecSchemaText(versions) {\n  return `{\n  \"imagePrompt\": \"string — Photorealistic interior design rendering of an apartment room. Key features include...\",\n  \"constraints\": \"string — 반드시 유지해야 할 창문 위치, 내력벽, 천장고 등 공간 구조 제약 사항.\",\n  \"designSpec\": {\n    \"roomType\": \"string — 대상 공간 유형.\",\n    \"style\": \"string — 적용된 인테리어 스타일.\",\n    \"ceiling\": \"string — 천장 마감 및 스타일.\",\n    \"floor\": \"string — 바닥재 사양.\",\n    \"wall\": \"string — 벽면 마감 사양.\",\n    \"lighting\": \"string — 조명 및 분위기.\",\n    \"furniture\": \"string — 주요 가구 및 소재 톤.\"\n  },\n  \"versionDiffsEn\": [\"string — 각 버전을 차별화할 핵심 변경사항 (가구 배치, 포인트 컬러, 조명 변화 등)을 ${versions}개 항목으로 요약. 이 내용은 기본 imagePrompt에 추가되어 사용됩니다. (영어로 작성)\"],\n  \"versionDiffsKo\": [\"string — versionDiffsEn의 각 항목을 자연스러운 한국어로 번역한 내용. ${versions}개의 항목으로 요약. 이 내용은 사용자에게 표시됩니다. (한국어로 작성)\"],\n  \"disclaimer\": \"string — 결과물은 개념 시뮬레이션이며, 실제 시공 가능 여부 및 견적과는 차이가 있을 수 있다는 주의 문구.\"\n}\n필수 필드: imagePrompt, constraints, designSpec, versionDiffsEn, versionDiffsKo, disclaimer`;\n}\n\n/* ── 프롬프트 2: 예측 이미지 (웹 시뮬레이터 원문 — 글자 하나 바꾸지 않는다) ──\n   웹은 ${imagePrompt}. Version-specific change: ${versionDiffsEn[i]} 를 INSTRUCTIONS 에 넣었다.\n\n   원문은 그대로 두고, 채팅 화면용 보충 문장은 원문 뒤에만 덧붙인다.\n   - \"원본\" 비율을 고르면 원문의 ${aspectRatio} 자리에 \"the same as the source photo\" 를 넣는다 (값만 바뀌고 문장은 원문 그대로).\n   - 구도 유지 보충: 리모델링 작성기에서 AI 가 시점을 바꿔 다시 그린 일이 있어 같은 문장을 붙인다. */\nfunction rmBuildImagePrompt(spec, versionIndex, aspectRatio) {\n  const diff = (spec && spec.versionDiffsEn && spec.versionDiffsEn[versionIndex]) || \"Apply base design.\";\n  const prompt = `${(spec && spec.imagePrompt) || \"\"}. Version-specific change: ${diff}`;\n  const ratio = !aspectRatio || aspectRatio === \"original\" ? \"the same as the source photo\" : aspectRatio;\n  return `\n    **PRIMARY GOAL:** Generate a photorealistic interior design rendering based on the provided source image(s) and the following instructions.\n    \n    **INSTRUCTIONS:** ${prompt}.\n    \n    **CRITICAL RULES:**\n    1.  **Preserve Room Structure:** Strictly maintain the room's shape, ceiling height, window locations, and door positions from the source image. Do not move structural walls.\n    2.  **Photorealism Only:** The output MUST be a high-fidelity, photorealistic image. Avoid any CG, cartoonish, or overly stylized looks. Lighting and shadows must be natural.\n    3.  **Correct Perspective:** Ensure the perspective matches the original photo. Correct any lens distortion.\n    4.  **Interior Focus:** Focus on the interior design elements: flooring, wall finishes, furniture, and lighting.\n    5.  **Privacy Blurring:** Automatically blur any personal photos in frames or recognizable faces.\n    6.  **Aspect Ratio:** The final image aspect ratio must be exactly ${ratio}.\n    7.  **No Korean Text:** Do NOT render any Korean text (Hangul) in the image. Any posters or books should have English or abstract text.\n    `.trim() + RM_IMAGE_APPENDIX;\n}\n\n/* 원문 뒤에 붙이는 채팅 화면용 보충 문장 — 원문 문장은 건드리지 않는다 */\nconst RM_IMAGE_APPENDIX = `\n\n[Additional note for this chat]\n- Use the attached photo(s) of the current room as the source and edit them: keep the same camera position, angle and framing as the source photo, and keep every window, door and wall where it is.\n- Generate the image now.`;\n\n/* ── AI 답변에서 설계 지시서 JSON 을 꺼낸다 ──\n   코드 블록·앞뒤 설명이 섞여도 첫 번째로 닫히는 { } 를 찾는다. 흔한 오류(끝 쉼표·둥근 따옴표)는 고쳐 본다. */\nfunction rmParseSpec(text) {\n  const raw = String(text || \"\");\n  const start = raw.indexOf(\"{\");\n  if (start < 0) return { ok: false, reason: \"AI 답변에서 JSON 을 찾지 못했습니다.\" };\n  let depth = 0, inStr = false, esc = false, end = -1;\n  for (let i = start; i < raw.length; i++) {\n    const c = raw[i];\n    if (inStr) {\n      if (esc) esc = false;\n      else if (c === \"\\\\\") esc = true;\n      else if (c === '\"') inStr = false;\n      continue;\n    }\n    if (c === '\"') inStr = true;\n    else if (c === \"{\") depth++;\n    else if (c === \"}\") { depth--; if (depth === 0) { end = i; break; } }\n  }\n  if (end < 0) return { ok: false, reason: \"AI 답변의 JSON 이 끝나지 않았습니다. 답변이 다 나온 뒤 다시 눌러 주세요.\" };\n  let body = raw.slice(start, end + 1);\n  let obj = null;\n  for (const fix of [\n    (s) => s,\n    (s) => s.replace(/[“”]/g, '\"').replace(/[‘’]/g, \"'\"),\n    (s) => s.replace(/[“”]/g, '\"').replace(/,\\s*([}\\]])/g, \"$1\"),\n  ]) {\n    try { obj = JSON.parse(fix(body)); break; } catch (_) { /* 다음 방법 */ }\n  }\n  if (!obj) return { ok: false, reason: \"AI 답변의 JSON 을 읽지 못했습니다. AI 탭에서 'JSON 형식으로 다시 출력해줘'라고 요청한 뒤 다시 눌러 주세요.\" };\n\n  const arr = (v) => (Array.isArray(v) ? v.map((x) => String(x || \"\").trim()).filter(Boolean) : []);\n  const spec = {\n    imagePrompt: String(obj.imagePrompt || \"\").trim(),\n    constraints: String(obj.constraints || \"\").trim(),\n    designSpec: obj.designSpec && typeof obj.designSpec === \"object\" ? obj.designSpec : {},\n    versionDiffsEn: arr(obj.versionDiffsEn),\n    versionDiffsKo: arr(obj.versionDiffsKo),\n    disclaimer: String(obj.disclaimer || \"\").trim(),\n  };\n  if (!spec.imagePrompt) return { ok: false, reason: \"지시서에 imagePrompt 가 없습니다. AI 탭에서 스키마대로 다시 출력해 달라고 요청해 주세요.\" };\n  return { ok: true, spec };\n}\n\n/* 결과표의 디자인 사양 이름 — 웹 시뮬레이터 SPEC_LABELS 와 같다 */\nconst RM_SPEC_LABELS = {\n  roomType: \"공간 유형\",\n  style: \"스타일\",\n  ceiling: \"천장 마감\",\n  floor: \"바닥재\",\n  wall: \"벽면 마감\",\n  lighting: \"조명\",\n  furniture: \"가구/소품\",\n};\n",
 "interior/interior-cost.js": "/* ══════════════════════════════════════════════════════════════\n   예상 공사비 — 단가표 × 공간 면적\n\n   AI 에게 금액을 묻지 않는다. 그럴듯하지만 근거 없는 숫자가 나온다.\n   여기서 계산한 범위를 결과표에 싣고, 기사·블로그·유튜브는 이 숫자만 쓴다.\n\n   ⚠ 단가는 업계 일반 수준으로 잡은 초안이다(자재+시공, 부가세·설계비 제외).\n     사장님이 확정하면 이 표만 고친다. 단위: 만 원.\n   ══════════════════════════════════════════════════════════════ */\n\nconst RM_COST_NOTICE = \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다.\";\n\nconst RM_UNIT = {\n  /* 바닥재 — 만원/m² (바닥 면적) */\n  floor: {\n    \"light-wood\": [8, 15],\n    \"dark-wood\": [8, 15],\n    \"porcelain-tile\": [10, 18],\n    \"marble\": [12, 22],\n    \"herringbone\": [12, 22],\n    \"concrete\": [6, 12],\n  },\n  /* 벽면 마감 — 만원/m² (창·문을 뺀 벽 면적) */\n  wall: {\n    \"white-wallpaper\": [1.5, 3],\n    \"paint-color\": [2, 4],\n    \"wood-panel\": [8, 15],\n    \"stone-tile\": [12, 25],\n    \"brick\": [6, 12],\n    \"wainscoting\": [5, 10],\n  },\n  /* 천장 — 만원/m² (천장 면적 = 바닥 면적) */\n  ceiling: {\n    \"flat\": [2, 4],\n    \"well\": [6, 12],\n    \"exposed\": [3, 6],\n    \"molding\": [4, 8],\n    \"wood-beam\": [8, 15],\n    \"louver\": [8, 15],\n  },\n  /* 조명 — 한 공간당 */\n  lighting: {\n    \"warm-white\": [20, 50],\n    \"daylight\": [20, 50],\n    \"indirect\": [50, 150],\n    \"spotlight\": [40, 120],\n    \"pendant\": [20, 80],\n    \"chandelier\": [50, 300],\n  },\n  /* 공간 유형별 설비 — 한 건당 (욕실 도기·수전·방수, 주방 싱크대·상판, 현관 중문·신발장) */\n  room: {\n    \"bathroom\": { label: \"욕실 설비 (방수·도기·수전)\", cost: [500, 1000] },\n    \"kitchen\": { label: \"주방 가구 (싱크대·상판)\", cost: [400, 1000] },\n    \"entrance\": { label: \"중문·신발장\", cost: [150, 400] },\n  },\n  /* 철거·폐기물·보양 — 위 합계의 비율 */\n  overhead: [0.15, 0.25],\n  /* 벽 중 창·문이 차지하는 비율 */\n  openingRatio: 0.25,\n};\n\n/* 공간 유형별 처음 면적(m²) — 국민평형(84m²) 아파트 기준의 흔한 크기 */\nconst RM_ROOM_AREA = {\n  \"living-room\": 25,\n  \"bedroom\": 12,\n  \"kitchen\": 12,\n  \"bathroom\": 5,\n  \"entrance\": 5,\n  \"balcony\": 6,\n};\n\n/* 공사비 기준 입력의 처음 값 */\nfunction rmDefaultCostBase(roomType) {\n  return { area: RM_ROOM_AREA[roomType] || RM_ROOM_AREA[\"living-room\"], height: 2.3 };\n}\n\n/* 여러 개를 고르면 평균 단가 (한 공간에 섞어 쓰는 것으로 본다) */\nfunction rmAvg(table, ids) {\n  const hits = (ids || []).map((id) => table[id]).filter(Boolean);\n  if (!hits.length) return [0, 0];\n  const sum = hits.reduce((a, [lo, hi]) => [a[0] + lo, a[1] + hi], [0, 0]);\n  return [sum[0] / hits.length, sum[1] / hits.length];\n}\n\nfunction rmSum(table, ids) {\n  return (ids || []).map((id) => table[id]).filter(Boolean).reduce((a, [lo, hi]) => [a[0] + lo, a[1] + hi], [0, 0]);\n}\n\n/* 만 원 → \"1억 2,000만 원\" */\nfunction rmWon(man) {\n  const v = Math.round(Number(man) || 0);\n  if (v <= 0) return \"0원\";\n  const eok = Math.floor(v / 10000);\n  const rest = v % 10000;\n  if (eok && rest) return `${eok}억 ${rest.toLocaleString()}만 원`;\n  if (eok) return `${eok}억 원`;\n  return `${rest.toLocaleString()}만 원`;\n}\n\n/* 10만 원 단위로 반올림 (만 원 기준 10 단위) — 방 하나 공사라 백만 원 단위는 너무 거칠다 */\nconst rmRound = (man) => Math.round((Number(man) || 0) / 10) * 10;\n\n/* ── 계산 ──\n   base: { area 공간 바닥 면적(m²), height 천장 높이(m) }  design: 인테리어 조건(id)\n   바닥·천장 면적 = area / 벽 면적 = 둘레(정사각형으로 봄 4√area) × 천장 높이 × (1 − 창·문 비율)\n   가구·가전·소품은 사는 물건이라 공사비에 넣지 않는다 */\nfunction rmEstimateCost(base, design) {\n  const d = design || {};\n  const b = Object.assign(rmDefaultCostBase(d.roomType), base || {});\n  const area = Math.max(0, Number(b.area) || 0);\n  const height = Math.max(0, Number(b.height) || 0);\n  const wallArea = 4 * Math.sqrt(area) * height * (1 - RM_UNIT.openingRatio);\n\n  const items = [];\n  const push = (label, basis, [lo, hi]) => { if (hi > 0) items.push({ label, basis, min: lo, max: hi }); };\n\n  const fl = rmAvg(RM_UNIT.floor, d.floor);\n  push(\"바닥재\", `${rmNames(\"floor\", d.floor).join(\", \") || \"-\"} · 바닥 ${Math.round(area)}m²`, [fl[0] * area, fl[1] * area]);\n\n  const wl = rmAvg(RM_UNIT.wall, d.wall);\n  push(\"벽면 마감\", `${rmNames(\"wall\", d.wall).join(\", \") || \"-\"} · 벽 ${Math.round(wallArea)}m²`, [wl[0] * wallArea, wl[1] * wallArea]);\n\n  const ce = rmAvg(RM_UNIT.ceiling, d.ceiling);\n  push(\"천장\", `${rmNames(\"ceiling\", d.ceiling).join(\", \") || \"-\"} · 천장 ${Math.round(area)}m²`, [ce[0] * area, ce[1] * area]);\n\n  push(\"조명\", rmNames(\"lighting\", d.lighting).join(\", \"), rmSum(RM_UNIT.lighting, d.lighting));\n\n  const room = RM_UNIT.room[d.roomType];\n  if (room) push(room.label, \"한 건\", room.cost);\n\n  const sub = items.reduce((a, it) => [a[0] + it.min, a[1] + it.max], [0, 0]);\n  const [oLo, oHi] = RM_UNIT.overhead;\n  if (sub[1] > 0) {\n    items.push({ label: \"철거·폐기물·보양\", basis: `위 합계의 ${oLo * 100}~${oHi * 100}%`, min: sub[0] * oLo, max: sub[1] * oHi });\n  }\n\n  const total = items.reduce((a, it) => [a[0] + it.min, a[1] + it.max], [0, 0]);\n  const min = rmRound(total[0]);\n  const max = rmRound(total[1]);\n  const pyeong = Math.round((area / 3.3058) * 10) / 10;\n  return {\n    base: { area, height },\n    /* \"거실 25m²(약 7.6평) · 천장 높이 2.3m\" — 결과표·기사가 같은 문장을 쓴다 */\n    basisText: `${rmRoomShort(d.roomType)} ${area}m²(약 ${pyeong}평) · 천장 높이 ${height}m`,\n    /* \"바닥 약 25m² · 벽 약 35m²\" — 결과표의 면적 줄 */\n    areaText: `바닥 약 ${Math.round(area)}m² · 벽 약 ${Math.round(wallArea)}m²`,\n    area: Math.round(area),\n    wallArea: Math.round(wallArea),\n    items: items.map((it) => ({ ...it, min: rmRound(it.min), max: rmRound(it.max) })),\n    min,\n    max,\n    rangeText: `약 ${rmWon(min)} ~ ${rmWon(max)}`,\n    notice: RM_COST_NOTICE,\n    excludes: \"부가세·설계비·가구·가전·소품 구입비 제외\",\n  };\n}\n",
 "interior/prompt.js": "/* ══════════════════════════════════════════════════════════════\n   공실뉴스 전용 프롬프트 — 기사 기본틀은 여기 한 곳에만 있다\n\n   일반 매물과 경매·공매 물건을 함께 쓴다. 경매·공매 물건은 서버에서 받을 때\n   saleKind(\"경매\"·\"공매\")가 붙어 오므로, 그것으로 어느 지시문을 쓸지 가른다.\n   ══════════════════════════════════════════════════════════════ */\n\n/* 경매·공매 물건인가 */\nfunction gwIsAuction(v) {\n  return Boolean(v && v.saleKind);\n}\n\n/* ── 매물 정보를 프롬프트에 넣을 줄로 만든다 ──\n   상세 표는 매물 종류마다 항목이 다르다. 그래서 정해진 목록을 쓰지 않고\n   화면에서 읽어온 것을 순서 그대로 전부 넘긴다.\n   값이 없는 항목은 아예 쓰지 않는다 — AI 가 빈칸을 상상하지 않도록. */\nfunction gwFactLines(v) {\n  const lines = [];\n  const seen = new Set();\n\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  if (gwIsAuction(v)) {\n    push(\"물건\", v.title);\n    push(\"가격 요약\", v.priceText);\n    for (const f of v.fields || []) push(f.label, f.value);\n    return lines.join(\"\\n\");\n  }\n\n  push(\"매물\", v.title);\n  push(\"금액\", v.priceText);\n  for (const f of v.fields || []) push(f.label, f.value);\n  push(\"특징\", Array.isArray(v.themes) ? v.themes.join(\" \") : v.themes);\n  push(\"주변환경\", v.infra);\n\n  return lines.join(\"\\n\");\n}\n\n/* 표에서 라벨로 값 하나 꺼내기 */\nfunction gwField(v, ...labels) {\n  for (const want of labels) {\n    const hit = (v.fields || []).find((f) => f.label === want);\n    if (hit) return hit.value;\n  }\n  return \"\";\n}\n\n/* 기사 본문에 넣을 매물 표기 이름 */\nfunction gwSubjectName(v) {\n  if (gwIsAuction(v)) {\n    return (\n      (v.title && v.title.trim()) ||\n      gwField(v, \"물건명\", \"소재지(지번)\", \"소재지\") ||\n      \"해당 물건\"\n    );\n  }\n  return (\n    (v.title && v.title.trim()) ||\n    gwField(v, \"단지명\", \"건물명\", \"소재지\") ||\n    \"해당 매물\"\n  );\n}\n\n/* ══════════════════════════════════════════════════════════════\n   수정 요청 — 같은 대화에 이어 붙인다\n\n   매물 정보를 다시 설명하지 않는다. AI 가 앞서 쓴 기사를 기억하고 있다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildRevisePrompt(request, vacancy) {\n  const keep = gwIsAuction(vacancy)\n    ? `- [물건 정보]에 있던 조건(감정가·최저입찰가·유찰 횟수·입찰 일정·면적·주소·관리번호)은 바꾸거나 새로 만들지 마십시오.\n- 투자 권유, 낙찰가·수익 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문은 넣지 마십시오.`\n    : \"- [매물 정보]에 있던 매물 조건(면적·금액·층·주소·번호)은 바꾸거나 새로 만들지 마십시오.\";\n  return `위에서 작성한 기사를 아래 요청대로 고쳐 주십시오.\n\n요청: ${request}\n\n[지킬 것]\n${keep}\n- 그 밖에는 요청하신 대로 자유롭게 고치십시오.\n  분량을 늘리라고 하면 실제로 그만큼 늘리십시오. 앞서 드린 분량 지시는 이 요청으로 대체됩니다.\n- 설명이나 인사말 없이, 고친 기사 전체를 처음과 똑같은 JSON 형식으로\n  \\`\\`\\`json 코드블록 하나에 다시 출력하십시오.\n- body는 문자열 하나가 아니라 문단별 문자열 배열입니다. 배열 항목 하나에 문단 하나만 넣으십시오.\n- 배열 항목 안에 실제 줄바꿈을 넣지 말고, 후행 쉼표 없이 JSON.parse가 가능한 유효한 JSON인지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"subtitle1\": \"\",\n  \"subtitle2\": \"\",\n  \"subtitle3\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   기사 이미지 만들기\n\n   기사 본문에 밀착한 장면을 요구하되, 작업창에서 스타일이나 기사 일부를\n   직접 지정할 수 있다. 입력이 없으면 AI 가 본문에서 핵심 장면을 고른다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_IMAGE_STYLE = {\n  news: {\n    label: \"보도 실사\",\n    prompt: \"한국 언론사의 현장 취재 사진처럼 자연스럽고 사실적인 장면. 과장 없는 담담한 조명과 구도.\",\n  },\n  building: {\n    label: \"건물 전경\",\n    prompt: \"건물의 전체 외관과 출입 동선이 잘 보이는 넓은 구도. 정면 또는 자연스러운 3/4 시점의 사실적인 건축 보도사진.\",\n  },\n  area: {\n    label: \"거리·상권\",\n    prompt: \"건물 하나보다 도로, 보행 환경, 주변 건물과 상권의 분위기가 함께 드러나는 넓은 현장 보도사진.\",\n  },\n  animation: {\n    label: \"애니메이션 일러스트\",\n    prompt: \"부동산 경제 기사에 어울리는 세련된 애니메이션풍 편집 일러스트. 특정 작품이나 작가의 화풍을 모방하지 말고 독창적으로 표현.\",\n  },\n  infographic: {\n    label: \"통계 도표·인포그래픽\",\n    prompt: \"경제 기사에 쓰는 깔끔한 데이터 인포그래픽. 확인된 숫자만 시각화하고, 비교 자료가 없으면 추세나 비교 그래프를 만들지 말고 핵심 수치 카드 형태로 구성.\",\n  },\n};\n\nfunction gwBuildImagePrompt(vacancy, article, opts) {\n  const o = opts || {};\n  const auction = gwIsAuction(vacancy);\n  const subject = vacancy ? gwSubjectName(vacancy) : \"해당 매물\";\n  const where = !vacancy ? \"\"\n    : auction ? gwField(vacancy, \"소재지(지번)\", \"소재지(도로명)\", \"소재지\")\n    : gwField(vacancy, \"소재지\");\n  const kind = !vacancy ? \"\"\n    : auction ? gwField(vacancy, \"물건종류\", \"용도분류\")\n    : gwField(vacancy, \"매물종류\", \"용도구분\", \"주용도\");\n  const style = GW_IMAGE_STYLE[o.style] || GW_IMAGE_STYLE.news;\n  const request = String(o.request || \"\").trim();\n  const customStyle = String(o.customStyle || \"\").trim().slice(0, 50); // 직접 입력한 화풍\n  const articleText = [article && article.title, article && article.body]\n    .filter(Boolean)\n    .join(\"\\n\")\n    .trim();\n  const focus = (request || articleText || subject).slice(0, 1600);\n  const noun = auction ? \"물건\" : \"매물\";\n  const facts = vacancy ? gwFactLines(vacancy) : `- 확인된 ${noun} 정보 없음`;\n  const focusRule = request\n    ? \"아래 입력이 기사 문장이면 그중 시각적으로 표현할 핵심 장면을 고르고, 연출 지시이면 그대로 반영하십시오.\"\n    : \"아래 기사 내용에서 가장 시각적으로 전달력이 높은 한 가지 핵심을 스스로 골라 장면으로 만드십시오.\";\n  /* 화풍을 직접 쓰면 글자 없는 그림으로 — 예전에 고른 통계 도표가 남아 글자가 들어가지 않게 */\n  const textRule = o.style === \"infographic\" && !customStyle\n    ? \"- 한글 문구는 꼭 필요한 짧은 항목명만 쓰고, 숫자와 단위는 아래 확인된 사실과 정확히 일치시킬 것\"\n    : \"- 이미지 안에 글자, 숫자, 로고, 워터마크를 넣지 말 것\";\n\n  return `위 기사에 넣을 이미지 1장을 만들어 주십시오.\n\n${customStyle\n    ? `[화풍·스타일] 사용자 직접 지정: \"${customStyle}\"\n- 이 화풍·그림체를 가장 먼저 지켜 표현하십시오.`\n    : `[선택한 스타일] ${style.label}\n${style.prompt}`}\n\n[이미지로 표현할 내용]\n${focusRule}\n${focus}\n\n[확인된 ${noun} 사실]\n${facts}\n\n[기본 장면 정보]\n- 대상: ${subject}${kind ? ` (${kind})` : \"\"}\n- 위치: ${where || \"대한민국 도심\"}\n- 기사 제목: ${(article && article.title) || \"\"}\n\n[조건]\n- ${o.ratio || \"가로 16:9\"} 비율\n- 위 확인된 사실에 없는 숫자, 통계, 건물명, 업체명, 시설을 만들지 말 것\n- 비교 수치나 증감률이 없으면 임의의 그래프, 비율, 순위를 만들지 말 것\n${textRule}\n- 사람 얼굴과 존재하지 않는 상호·간판 이름을 넣지 말 것\n- 사용자가 입력한 요청은 반영하되, 확인된 사실과 충돌하면 사실을 우선할 것\n\n이미지 1장만 출력하고 설명은 붙이지 마십시오.`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   분량과 기사 스타일 — 작업창에서 고른다\n\n   예전에는 \"600~900자\"가 코드에 박혀 있어, 사장님이 3,000자를 요청해도\n   먼저 준 지시가 이겼다. 이제 여기서 고른 것이 프롬프트로 간다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_LENGTH = {\n  short:  { label: \"짧게\",  chars: \"700~1,000자\",   paras: \"4~5개\",   sections: \"3~4개\" },\n  normal: { label: \"보통\",  chars: \"1,400~1,800자\", paras: \"7~9개\",   sections: \"5~6개\" },\n  long:   { label: \"길게\",  chars: \"2,800~3,500자\", paras: \"12~16개\", sections: \"7~9개\" },\n};\n\nconst GW_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief:\n      \"현재 방식처럼 도입부터 결론까지 문단이 자연스럽게 이어지는 뉴스 기사입니다. \" +\n      \"매물 조건과 지역·수요·계약 전 확인 사항을 기사 흐름 안에서 풀어 주십시오.\",\n    subs: \"1) 입지와 교통  2) 면적·구조  3) 거래 조건\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief:\n      \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 \" +\n      \"독자가 내용을 빠르게 훑어볼 수 있게 작성하십시오.\",\n    subs: \"1) 핵심 매물 조건  2) 입지와 수요  3) 계약 전 확인 사항\",\n  },\n};\n\n/* 경매·공매 물건일 때의 기사 스타일 — 이름은 같고 설명·부제 구성만 다르다 */\nconst GW_AUCTION_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief:\n      \"도입부터 결론까지 문단이 자연스럽게 이어지는 경매·공매 뉴스 기사입니다. \" +\n      \"가격 조건과 물건 현황, 지역, 입찰 일정과 입찰 전 확인할 점을 기사 흐름 안에서 풀어 주십시오.\",\n    subs: \"1) 가격 — 감정가·최저입찰가·유찰  2) 물건 현황과 입지  3) 입찰 일정·방법\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief:\n      \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 \" +\n      \"독자가 내용을 빠르게 훑어볼 수 있게 작성하십시오.\",\n    subs: \"1) 핵심 가격 조건  2) 물건 현황과 입지  3) 입찰 일정과 확인할 점\",\n  },\n};\n\n/* 소제목 기사 본문 규칙 — 일반·경매 공통 */\nfunction gwBodyStyle(o, len) {\n  return o.kind === \"summary\"\n    ? `- 첫 문단은 소제목 없이 기사 전체 핵심을 요약한 리드문으로 쓰십시오.\n- 그 다음부터는 반드시 \"■ 소제목\"을 한 줄에 단독으로 쓰고, 바로 다음 줄에 해당 내용을 설명하는 문단을 쓰십시오.\n- \"■ 소제목 + 설명 문단\" 묶음을 ${len.sections}로 구성하십시오.\n- 소제목 앞에는 정확히 ■ 기호 하나만 쓰십시오. ##, 번호, 불릿 목록, 굵은 글씨 표시는 쓰지 마십시오.`\n    : `- 일반 뉴스 기사처럼 도입부터 결론까지 자연스러운 문단으로 이어 쓰십시오.\n- 본문 중간에 소제목, ■ 기호, 번호, 불릿 목록을 넣지 마십시오.`;\n}\n\n/* 기사 JSON 출력 형식 — 일반·경매 공통 */\nconst GW_ARTICLE_OUTPUT = `[출력 형식]\n설명이나 인사말 없이, 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 반드시 JSON 배열이어야 하며, 각 문단과 \"■ 소제목\" 한 줄을 각각 별도 문자열 항목으로 넣으십시오.\n- 문자열 항목 안에 실제 줄바꿈을 넣지 마십시오. 문단 구분은 배열 항목으로만 표현하십시오.\n- 모든 문자열은 큰따옴표로 감싸고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한 유효한 JSON인지 괄호와 쉼표를 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"subtitle1\": \"\",\n  \"subtitle2\": \"\",\n  \"subtitle3\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n\n/* ══════════════════════════════════════════════════════════════\n   기사 작성 프롬프트\n\n   핵심은 두 구역을 가르는 것이다.\n   - 사실 구역: 표에 있는 것만. 지어내면 표시광고 문제가 된다\n   - 해설 구역: 기자가 아는 일반 지식으로 쓴다. 여기가 AI 를 쓰는 값어치다\n\n   전에는 둘 다 막아 놔서 AI 가 표를 문장으로 옮겨 적는 일밖에 못 했다.\n   경매·공매 물건은 아래 gwBuildAuctionPrompt 로 넘긴다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildPrompt(v, opts) {\n  if (gwIsAuction(v)) return gwBuildAuctionPrompt(v, opts);\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = GW_KIND[o.kind] || GW_KIND.news;\n  const facts = gwFactLines(v);\n  const subject = gwSubjectName(v);\n  const bodyStyle = gwBodyStyle(o, len);\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경제 담당 기자입니다.\n아래 매물을 소재로 기사 1건을 작성하십시오.\n\n[매물 정보 — 확인된 사실]\n${facts}\n\n════════ 두 구역을 구분해서 쓰십시오 ════════\n\n【사실 구역】 위 [매물 정보]에 적힌 것\n- 면적·금액·층수·방·주소·번호·관리비 등 이 매물의 조건은\n  한 글자도 바꾸거나 더하지 마십시오.\n- 위에 없는 항목(준공연도·옵션·주차 등)을 추측해 채우지 마십시오.\n  없으면 그 이야기를 아예 하지 마십시오.\n- 소재지가 시·군·동까지만 주어졌다면 기사도 거기까지만 쓰십시오.\n\n【해설 구역】 기자로서 쓰는 부분   ★ 기사 분량의 절반 이상을 여기에 쓰십시오\n당신이 아는 일반 지식으로 자유롭게 쓰십시오.\n- 이 지역이 어떤 곳인지 — 업무지구·학군·상권·교통의 성격, 동네 분위기\n- 위 조건들이 실제로 무엇을 뜻하는지 — 이 면적과 구조가 어떤 쓰임에 맞는지\n- 어떤 임차인·수요자에게 맞는 물건인지, 반대로 누구에게는 맞지 않는지\n- 이런 조건의 물건을 볼 때 계약 전 확인해야 할 점\n- 같은 종류의 물건을 고를 때 쓰는 일반적인 판단 기준\n\n해설 구역에서도 다음은 금지합니다.\n- 구체적 수치 예측 — \"3년 내 20% 상승\", \"수익률 6% 예상\"\n- 단정 — \"확실하다\", \"보장된다\", \"반드시 오른다\"\n- 이 매물의 스펙이나 가격을 지어내기\n- 실재하지 않는 단지명·업체명·기관명을 만들어 쓰기\n- 특정 시점의 시세 수치를 아는 것처럼 쓰기\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 【해설 구역】을 더 쓰십시오.\n  매물 스펙을 다시 늘어놓아 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했습니다\" 아닌 \"~했다\")\n- 매물은 \"${subject}\"로 지칭\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [공실열람 보도] 로 시작\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${kind.subs}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${bodyStyle}\n              마지막 문단은 \"자세한 내용은 공실뉴스 공실열람에서 확인할 수 있다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·매물종류·거래구분을 포함할 것\n\n${GW_ARTICLE_OUTPUT}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 기사 작성 프롬프트\n\n   두 구역을 가른다.\n   - 사실 구역: 서버에서 받은 물건 정보에 있는 것만. 가격·일정을 지어내면 큰 사고다\n   - 해설 구역: 경매·공매 제도와 지역에 대한 기자의 일반 지식\n   투자 권유·낙찰가 예측은 어느 구역에서도 쓰지 않는다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildAuctionPrompt(v, opts) {\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = GW_AUCTION_KIND[o.kind] || GW_AUCTION_KIND.news;\n  const facts = gwFactLines(v);\n  const subject = gwSubjectName(v);\n  const saleKind = v && v.saleKind === \"경매\" ? \"경매\" : \"공매\";\n  const saleName = saleKind === \"공매\" ? \"공매(온비드)\" : \"법원 경매\";\n  const bodyStyle = gwBodyStyle(o, len);\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경매·공매 담당 기자입니다.\n아래 ${saleName} 물건을 소재로 기사 1건을 작성하십시오.\n\n[물건 정보 — 확인된 사실]\n${facts}\n\n════════ 두 구역을 구분해서 쓰십시오 ════════\n\n【사실 구역】 위 [물건 정보]에 적힌 것\n- 감정가·최저입찰가·감정가 대비 비율·유찰 횟수·입찰 시작/마감·개찰일시·입찰보증금·면적·주소·관리번호(사건번호)·공고번호·집행기관은\n  한 글자도 바꾸거나 더하지 마십시오. 금액은 원 단위 숫자와 억·만원 표기가 일치해야 합니다.\n- 위에 없는 항목(권리관계·임차인·선순위 채권·체납액·건물 연식 등)을 추측해 채우지 마십시오.\n  없으면 그 이야기를 아예 하지 마십시오.\n- 소재지가 주어진 범위까지만 쓰십시오.\n- 입찰 일정이 없으면 날짜를 만들지 마십시오.\n\n【해설 구역】 기자로서 쓰는 부분   ★ 기사 분량의 절반 가까이를 여기에 쓰십시오\n당신이 아는 일반 지식으로 쓰십시오.\n- 이 지역이 어떤 곳인지 — 업무지구·학군·상권·교통의 성격\n- 이 물건 종류와 면적이 일반적으로 어떤 쓰임에 맞는지\n- ${saleKind} 제도의 일반 설명 — 유찰되면 최저입찰가가 어떻게 낮아지는지, 입찰보증금, 개찰 절차, 명도의 의미 등\n- ${saleKind} 물건을 볼 때 일반적으로 확인하는 점 — 현장 상태, 점유·명도, 권리관계, 추가 비용(관리비 체납 등)\n\n해설 구역에서도 다음은 금지합니다.\n- 투자 권유 — \"싸게 살 기회\", \"놓치지 말아야 할\", \"적극 추천\", \"수익이 기대된다\"\n- 낙찰가·낙찰가율·수익률·시세 상승 예측\n- 단정 — \"안전한 물건이다\", \"권리상 문제가 없다\", \"반드시 낙찰된다\"\n- 이 물건의 조건이나 가격을 지어내기\n- 실재하지 않는 단지명·업체명·기관명을 만들어 쓰기\n\n[넣지 말 것]\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호)\n- \"본 정보는 참고용 데이터이며… 법적 책임을 지지 않습니다\" 같은 입찰 전 법적 주의사항 안내문\n  (단, 마지막 문단의 한 줄 확인 문구는 아래 [구성]대로 넣으십시오)\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 【해설 구역】을 더 쓰십시오.\n  물건 정보를 다시 늘어놓아 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했습니다\" 아닌 \"~했다\")\n- 물건은 \"${subject}\"로 지칭\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [공실열람 ${saleKind}] 로 시작. 지역·물건 종류·최저입찰가(또는 유찰 횟수)를 담을 것\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${kind.subs}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${bodyStyle}\n              첫 문단에 ${saleKind} 구분, 소재지, 물건 종류, 감정가와 최저입찰가를 밝힐 것\n              마지막 문단은 \"권리관계와 물건 상태는 입찰 전 공고문과 현장에서 직접 확인할 필요가 있다. 자세한 내용은 공실뉴스 공실열람 경매/공매에서 확인할 수 있다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·물건 종류·\"${saleKind}\"를 포함할 것\n\n${GW_ARTICLE_OUTPUT}`;\n}\n",
 "interior/interior-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   인테리어 결과표 → 기사 · 블로그 · 유튜브 대본 지시문\n\n   원자료는 1 · 시뮬레이션의 결과표 하나다.\n   - 결과표에 있는 인테리어 조건·예측 모습·예상 공사비만 사실로 쓴다\n   - 공사비는 확장이 계산한 범위를 그대로 쓰고, AI 가 새 금액을 만들지 않는다\n   - \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다\" 를 반드시 넣는다\n   - 개념 시뮬레이션이다. 실제 공사 계획·확정된 공사처럼 쓰지 않는다\n\n   출력 JSON 형식은 기사 작성기와 같다 (article-json · 블로그 · youtube-json 이 그대로 읽는다).\n   함수 이름(gwBuildRemodel…)은 리모델링 작성기와 같게 두었다 — blog-prompt · youtube-prompt 가 이 이름으로 부른다.\n   ══════════════════════════════════════════════════════════════ */\n\n/* 결과표 → \"확인된 사실\" 글 */\nfunction rmResultFactLines(r) {\n  if (!r) return \"(결과표 없음)\";\n  const lines = [];\n  const seen = new Set(); // 같은 항목(예: 소재지)이 결과표와 매물 정보에 겹치면 한 번만\n  const push = (k, v) => {\n    const t = String(v == null ? \"\" : v).trim();\n    const key = `${k}:${t}`;\n    if (!t || seen.has(key)) return;\n    seen.add(key);\n    lines.push(`- ${k}: ${t}`);\n  };\n  if (rmIsListing(r)) {\n    lines.push(r.saleKind\n      ? `[공실뉴스 ${r.saleKind} 물건 정보 — 공실열람에 게재된 확인된 사실]`\n      : \"[공실뉴스 매물 정보 — 공실열람에 등록된 확인된 사실]\");\n    push(r.saleKind ? `${r.saleKind} 물건` : \"매물\", r.title);\n    push(\"소재지\", r.location);\n    push(\"금액\", r.priceText);\n    for (const f of (r.vacancyFacts || []).slice(0, 20)) push(f.label, f.value);\n    push(\"특징\", (r.themes || []).join(\" \"));\n    push(\"주변환경\", r.infra);\n  } else {\n    lines.push(\"[대상 공간 — 사용자가 직접 올린 실내 사진 (공실 매물 아님)]\");\n    push(\"대상\", r.title);\n    push(\"소재지\", r.location);\n  }\n  lines.push(\"\");\n  lines.push(\"[인테리어 조건 — 사용자가 고른 것]\");\n  for (const [label, names] of Object.entries(r.design || {})) push(label, (names || []).join(\", \"));\n  lines.push(\"\");\n  lines.push(\"[예측 결과 — AI 시뮬레이션]\");\n  const spec = r.designSpec || {};\n  for (const key of Object.keys(RM_SPEC_LABELS)) push(`디자인 사양 · ${RM_SPEC_LABELS[key]}`, spec[key]);\n  (r.versions || []).forEach((v) => push(`예측 버전 ${v.index}`, v.diffKo));\n  push(\"보존한 구조\", r.constraints);\n  lines.push(\"\");\n  const c = r.cost;\n  if (c) {\n    lines.push(\"[예상 공사비 — 공실뉴스 단가표로 계산한 개략 범위. 이 숫자만 쓸 것]\");\n    push(\"합계\", c.rangeText);\n    push(\"계산 기준\", `${c.basisText} (${c.areaText})`);\n    for (const it of c.items) push(`항목 · ${it.label}`, `${rmWon(it.min)} ~ ${rmWon(it.max)} (${it.basis || \"\"})`);\n    push(\"제외\", c.excludes);\n    push(\"필수 문구\", c.notice);\n  }\n  push(\"주의\", r.disclaimer);\n  return lines.join(\"\\n\");\n}\n\n/* 공실열람에서 가져온 매물인가 — 매물이면 \"이 가격에 나온 집\" 이야기로 쓴다 */\nfunction rmIsListing(r) {\n  return Boolean(r && (r.vacancyId || r.priceText || (r.vacancyFacts || []).length));\n}\n\n/* 결과표의 공간 이름 (\"거실\") — 옛 결과표에는 없을 수 있다 */\nconst rmRoomOf = (r) => (r && r.roomName) || \"실내\";\n\n/* \"거실을\" · \"주방/다이닝을\" · \"발코니/베란다를\" — 마지막 글자 받침으로 을/를을 고른다 */\nfunction rmObj(word) {\n  const code = String(word).charCodeAt(String(word).length - 1) - 0xac00;\n  return word + (code >= 0 && code <= 11171 && code % 28 ? \"을\" : \"를\");\n}\n\n/* 공실 매물일 때의 글 흐름 — 매물 보도로 열고 시뮬레이션으로 잇는다 */\nfunction rmStoryFlow(r) {\n  const room = rmRoomOf(r);\n  return rmIsListing(r)\n    ? `[글의 흐름 — 공실 매물]\n${r.saleKind\n    ? `① 첫 문단: 이 집이 ${r.saleKind}로 나왔다는 것부터 연다 (소재지·단지·면적·감정가·최저입찰가)\n   예: \"서울 송파구 잠실동 전용 84㎡ 아파트가 ${r.saleKind}로 나왔다. 감정가 20억 원, 최저입찰가 16억 원이다.\"`\n    : `① 첫 문단: 공실뉴스(공실열람)에 이 집이 어떤 조건으로 나왔는지 매물 보도로 연다 (소재지·단지·면적·거래 구분·금액)\n   예: \"공실뉴스 공실열람에 서울 송파구 잠실동 전용 84㎡ 아파트가 전세 8억 원에 나왔다.\"`}\n② 지금 집의 조건 — 면적·층·방 수·입주 가능일·특징 등 [공실뉴스 매물 정보]에 있는 것\n③ 이 집 ${rmObj(room)} [인테리어 조건]으로 꾸미면 어떤 모습이 예상되는지 — 시뮬레이션 결과\n④ 예상 공사비 — [예상 공사비]의 범위 그대로, 필수 문구와 함께\n⑤ 해설 — 어떤 수요층에 어울리는 인테리어인지, 매매·임대에 미칠 수 있는 영향, 공사 전에 확인할 점\n매물 금액과 예상 공사비는 각각 사실로 나란히 전하고, 둘을 더하거나 나눈 비율·총비용을 계산하지 마십시오.`\n    : `[글의 흐름 — 직접 올린 사진]\n① 어떤 공간(${room})을 시뮬레이션했는지 ② 고른 인테리어 조건 ③ 예측된 모습 ④ 예상 공사비 ⑤ 해설과 확인할 점\n공실 매물이 아니므로 금액·매물 조건을 쓰지 마십시오.`;\n}\n\n/* 해설로 쓸 수 있는 것 / 없는 것 — 가능성은 쓰되 단정·수치는 쓰지 않는다 */\nconst RM_OPINION_RULES = `[해설 원칙 — 기자로서 판단을 쓰는 부분]\n쓸 수 있는 것 (반드시 \"~일 수 있다\", \"~를 검토해 볼 만하다\", \"~할 여지가 있다\" 같은 가능성 표현으로):\n- 매물 조건(면적·방 수·주변환경 등)에 비추어 어떤 수요층(신혼부부·자녀 가구·1인 가구 등)에 어울리는 인테리어일 수 있는지\n  예: \"방 3개 중형 면적이라 밝은 우드와 화이트 톤이 자녀를 둔 가구에 무난하게 받아들여질 수 있다\"\n- 인테리어 개선이 집의 첫인상·임차 수요·매매 협상에 긍정적으로 작용할 여지가 있다는 점\n  예: \"낡은 마감을 바꾸면 집을 보러 온 사람의 첫인상이 달라질 여지가 있다\"\n- 고른 마감재의 일반적인 성격과 장단점 — 관리·내구성·청소·분위기\n  예: \"대리석 느낌의 폴리싱 타일은 고급스러워 보이지만 겨울철 발이 차가울 수 있다\"\n- 실제로 진행하려면 확인할 점 — 정밀 견적, 관리사무소 공사 신고·이웃 동의, 공사 기간과 소음, 전·월세라면 집주인 동의와 원상복구\n쓸 수 없는 것:\n- 수치 전망: \"집값 1억 상승\", \"전세가 20% 인상\", \"수익률 ○%\", \"몇 년 안에 회수\"\n- 단정·보장: \"반드시\", \"확실히\", \"무조건 이득\", \"보장된다\"\n- 근거 없는 해설: [결과표]에 없는 단지 시설·개발 호재·시세를 지어내서 판단의 근거로 쓰기\n- 매수·계약 권유: \"지금 사야 한다\", \"놓치지 마라\"\n- 특정 인테리어 업체·브랜드·제품 이름`;\n\n/* 모든 글에 공통으로 박는 원칙 */\nconst RM_FACT_RULES = `[사실 원칙 — 가장 먼저 지킬 것]\n- 이 글의 소재는 \"실내 인테리어 예측 시뮬레이션\"입니다. 실제 공사 계획이나 이미 끝난 공사가 아닙니다.\n  \"~로 바뀌었다\", \"공사한다\"처럼 확정된 일로 쓰지 말고 \"~로 꾸미면 이런 모습이 예상된다\", \"시뮬레이션해 보니\"처럼 쓰십시오.\n- 인테리어 조건·예측 결과·공사비는 위 [결과표]에 있는 것만 쓰십시오. 없는 자재·가구·가전·업체·일정을 만들지 마십시오.\n- 매물 금액·면적·층 등 매물 조건은 [공실뉴스 매물 정보]에 있는 그대로 쓰십시오. 한 글자도 바꾸지 마십시오.\n- 공사비는 [예상 공사비]의 범위를 그대로 쓰고, 새 금액·평당 단가·집값 상승폭을 만들지 마십시오.\n- 공사비를 말할 때는 반드시 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다\"라는 뜻을 함께 쓰십시오.\n- 공사비는 [결과표]의 공간 하나({공간}) 기준입니다. 집 전체 공사비처럼 쓰지 마십시오.\n- 소재지·매물 조건은 [결과표]에 있는 범위까지만 쓰십시오. 동·호수 등 더 상세한 주소를 추측하지 마십시오.\n- 구조 변경(벽 철거·확장)이 가능하다고 단정하지 마십시오. 필요하면 \"전문가 확인이 필요하다\"로 쓰십시오.\n- 중개사무소 이름·연락처·링크는 쓰지 마십시오.`;\n\n/* 공간 이름을 넣은 사실 원칙 */\nconst rmFactRules = (r) => RM_FACT_RULES.replace(\"{공간}\", rmRoomOf(r));\n\n/* ═════════════ 기사 ═════════════ */\nconst RM_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief: \"도입부터 결론까지 문단이 자연스럽게 이어지는 뉴스 기사입니다. 아래 [글의 흐름] 순서대로 풀어 주십시오.\",\n    subs: \"1) 어떤 집이 어떤 조건으로 나왔나  2) 인테리어를 바꾸면 어떤 모습인가  3) 예상 공사비와 검토할 점\",\n    subsPhoto: \"1) 어떤 공간을 시뮬레이션했나  2) 어떤 조건으로 꾸미면 어떤 모습인가  3) 예상 공사비와 확인할 점\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief: \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 독자가 빠르게 훑어볼 수 있게 쓰십시오. 소제목 순서는 아래 [글의 흐름]을 따르십시오.\",\n    subs: \"1) 매물 조건  2) 예측 인테리어의 특징  3) 예상 공사비와 검토할 점\",\n    subsPhoto: \"1) 대상 공간과 인테리어 조건  2) 예측 인테리어의 특징  3) 예상 공사비와 확인할 점\",\n  },\n};\n\nfunction gwBuildRemodelArticlePrompt(result, opts) {\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = RM_KIND[o.kind] || RM_KIND.news;\n  const listing = rmIsListing(result);\n  const room = rmRoomOf(result);\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 주거·인테리어 담당 기자입니다.\n아래 결과표를 소재로 기사 1건을 작성하십시오.\n${listing\n    ? `독자가 \"공실뉴스에 이 조건으로 나온 집의 ${rmObj(room)} 이렇게 꾸미면 이런 모습이 되고 공사비는 대략 이 정도\"를 알 수 있게 씁니다.`\n    : `독자가 \"이 ${rmObj(room)} 이런 조건으로 꾸미면 이렇게 달라지고, 공사비는 대략 이 정도\"를 알 수 있게 씁니다.`}\n\n[결과표 — 확인된 사실]\n${rmResultFactLines(result)}\n\n${rmFactRules(result)}\n\n${rmStoryFlow(result)}\n\n${RM_OPINION_RULES}\n- ★ 해설(⑤)에 기사 분량의 3분의 1 이상을 쓰십시오.\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 해설 구역을 더 쓰십시오. 결과표 항목을 되풀이해 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했다\", \"~로 예상된다\")\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [인테리어 시뮬레이션] 으로 시작${listing ? `\\n              지역·주택 종류·금액과 공간(${room})을 넣을 것 (예: [인테리어 시뮬레이션] 잠실동 84㎡ 전세 8억 아파트, 거실 바꾸면)` : \"\"}\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${listing ? kind.subs : kind.subsPhoto}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${gwBodyStyle(o, len)}\n              공사비 문단에는 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요하다\"는 문장을 넣을 것\n              마지막 문단은 \"이번 결과는 공실뉴스 인테리어 예측 시뮬레이션으로 만든 개념 이미지로, 실제 공사 전에는 현장 실측과 정밀 견적이 필요하다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·주택 종류·인테리어·공간(${room})·주요 스타일을 포함할 것${listing ? \"·거래 구분\" : \"\"}\n\n${GW_ARTICLE_OUTPUT}`;\n}\n\n/* ═════════════ 블로그 ═════════════\n   칩 자리(listing·visit·story·report·consult·shortform)는 기사 작성기와 같고 뜻만 인테리어용이다. */\nconst RM_BLOG_STYLE = {\n  listing: {\n    label: \"인테리어 소개형\", fit: \"모든 집\", design: \"basic\",\n    titleExample: \"잠실동 84㎡ 아파트 거실, 모던 스타일로 바꾸면\",\n    guide: \"깔끔하고 정보 중심으로 쓴다. 첫 문단에서 어떤 집의 어떤 공간을 어떤 조건으로 시뮬레이션했는지 밝히고, 예측 모습과 공사비를 정리한다.\",\n    structure: \"소제목 3~4개 (예: ■ 지금 모습 / ■ 고른 인테리어 조건 / ■ 예측된 모습 / ■ 예상 공사비와 확인할 점)\",\n  },\n  visit: {\n    label: \"전·후 비교형\", fit: \"구축 아파트\", design: \"magazine\",\n    titleExample: \"낡은 벽지·장판이 우드·화이트로… 전후를 비교해 보니\",\n    guide: \"현재 모습과 예측 인테리어를 부분별로 나란히 비교한다(바닥·벽·천장·조명·가구). 실제 공사를 한 것처럼 쓰지 않는다.\",\n    structure: \"소제목 4~5개, 부분별 비교 (예: ■ 바닥 / ■ 벽과 천장 / ■ 조명 / ■ 가구와 분위기 / ■ 예상 공사비)\",\n  },\n  story: {\n    label: \"스토리텔링형\", fit: \"신혼·이사 준비\", design: \"magazine\",\n    titleExample: \"20년 된 아파트 거실, 이렇게 꾸미면 달라질까?\",\n    guide: \"질문이나 상황으로 시작해 시뮬레이션 과정을 따라가듯 풀어 쓴다. 인물·사례를 지어내지 않는다.\",\n    structure: \"소제목 3~4개 (예: ■ 질문 하나 / ■ 조건을 골라 보니 / ■ 달라진 모습 / ■ 비용과 현실)\",\n  },\n  report: {\n    label: \"공사비 분석형\", fit: \"매매·임대 준비\", design: \"news\",\n    titleExample: \"거실 인테리어, 항목별로 얼마나 들까\",\n    guide: \"예상 공사비를 항목별로 풀어 설명한다. 결과표의 계산 기준과 범위만 쓰고, 새 금액·집값 상승폭을 만들지 않는다.\",\n    structure: \"소제목 4~5개 (예: ■ 계산 기준 / ■ 바닥·벽·천장 / ■ 조명과 설비 / ■ 부대비용 / ■ 확인할 점)\",\n  },\n  consult: {\n    label: \"친근한 해설형\", fit: \"실거주자\", design: \"qna\",\n    titleExample: \"헤링본 마루와 포세린 타일, 무엇이 다를까\",\n    guide: \"고른 마감재·조명·가구 톤을 쉬운 말로 풀어 설명한다. 부드러운 존댓말(~습니다)을 쓰되 권유 표현은 쓰지 않는다.\",\n    structure: \"소제목 3~5개, 질문형 (예: ■ 이 바닥재는 어떤 재료일까 / ■ 조명을 바꾸면 무엇이 달라질까 / ■ 비용은)\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\", fit: \"SNS 연계\", design: \"news\",\n    titleExample: \"[인테리어] 잠실동 84㎡ 거실 예측 공개\",\n    guide: \"짧은 문장으로 사실만 빠르게 전한다.\",\n    structure: \"소제목 2~3개, 짧게 (예: ■ 무엇을 바꿨나 / ■ 얼마나 드나)\",\n  },\n};\n\nfunction gwBuildRemodelBlogPrompt(source, opts) {\n  const o = opts || {};\n  const style = RM_BLOG_STYLE[o.style] || RM_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = (source && source.article) || {};\n  const r = source && source.remodel;\n  return `당신은 부동산·인테리어 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 인테리어 시뮬레이션 결과표와 공실뉴스 기사를 참고해 블로그 초안 1건을 작성하십시오.\n\n[결과표 — 확인된 사실]\n${rmResultFactLines(r)}\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n${rmFactRules(r)}\n\n${rmStoryFlow(r)}\n선택한 스타일에 맞게 순서와 비중은 조절해도 되지만, 공실 매물이면 첫 문단은 반드시 매물 보도(①)로 여십시오.\n\n${RM_OPINION_RULES}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 독자: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n\n[보도 원칙]\n- 이 글은 ${rmIsListing(r)\n    ? \"\\\"공실뉴스에 이런 매물이 나왔고, 실내를 이렇게 꾸미면 이런 모습이 예상된다\\\"는 객관적인 보도입니다. 중개사무소 정보는 본문에 쓰지 말고 글 끝 출처에 맡기십시오\"\n    : \"\\\"공실뉴스 인테리어 예측 시뮬레이션으로 이 공간을 꾸며 보니\\\"라는 객관적인 소개입니다\"}. 3인칭 전달체로 쓰십시오.\n- 첫 문단에서 ${rmIsListing(r) ? \"소재지·주택 종류·거래 구분·금액과, 실내 인테리어 시뮬레이션을 해 봤다는 점\" : \"대상 공간과 시뮬레이션이라는 점\"}을 밝히십시오.\n- 권유·호객 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"지금이 기회\" 등.\n\n[블로그 구성]\n- title: 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 한 문단을 2~4문장으로 짧게. 첫 문단은 2문장 이내의 핵심 요약\n- 소제목은 한 줄짜리 독립 문단으로 쓰고 반드시 \"■ \"로 시작할 것. 소제목 바로 다음에는 본문 문단이 올 것\n- 공사비를 다룬 문단에 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다\"를 넣을 것\n- 마지막 문단은 시뮬레이션 결과와 확인할 점(현장 실측·정밀 견적·관리사무소 공사 신고)을 객관적으로 정리할 것\n- 기사 문장을 그대로 길게 복사하지 말 것\n- keywords: 지역명·주택 종류·인테리어·공간·스타일을 포함한 검색용 핵심어 7~12개. # 제외\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ═════════════ 유튜브 ═════════════ */\nconst RM_YT_VIDEO_TYPE = {\n  listing: { label: \"인테리어 소개\", structure: \"훅(전·후 한 문장) → 대상 집과 공간 → 고른 조건 → 예측 모습 → 예상 공사비 → 확인할 점 → 마무리\" },\n  news: { label: \"전·후 비교\", structure: \"헤드라인 → 지금 모습 → 바닥·벽·천장·조명·가구 부분별 비교 → 예상 공사비 → 정리\" },\n  area: { label: \"공사비 분석\", structure: \"질문 훅(얼마나 들까) → 계산 기준 → 항목별 공사비 → 부대비용 → 확인할 점 → 정리\" },\n};\n\nfunction gwBuildRemodelYtPrompt(source, settings) {\n  const s = settings || {};\n  const type = RM_YT_VIDEO_TYPE[s.videoType] || RM_YT_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n  const article = (source && source.article) || {};\n  const r = source && source.remodel;\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 유튜브 대본 작가입니다.\n아래 인테리어 시뮬레이션 결과표와 공실뉴스 기사만 사용해 \"${type.label}\" 영상의 내레이션 원고를 작성하십시오.\n\n[결과표 — 확인된 사실]\n${rmResultFactLines(r)}\n\n[참조 기사]\n[기사 제목] ${article.title || \"\"}\n[기사 본문] ${article.body || \"\"}\n\n${rmFactRules(r)}\n\n${RM_OPINION_RULES}\n${rmIsListing(r)\n    ? \"- 공실 매물이므로 원고 앞부분(훅 다음)에서 소재지·주택 종류·거래 구분·금액을 밝히고, 그다음 인테리어 시뮬레이션으로 넘어가십시오. 중개사무소 이름·전화번호는 원고에 넣지 마십시오.\"\n    : \"- 공실 매물이 아니므로 금액·매물 조건을 말하지 마십시오.\"}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 공사비를 말한 뒤에는 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다.\"를 읽으십시오.\n- 마지막은 \"이번 결과는 인테리어 예측 시뮬레이션입니다. 자세한 내용은 공실뉴스에서 확인할 수 있습니다.\"로 맺습니다.\n\n${GW_YT_OUTPUT}`;\n}\n",
 "interior/article-json.js": "/* ══════════════════════════════════════════════════════════════\n   AI 기사 JSON 읽기\n\n   새 형식은 body 를 문단 배열로 받는다. 긴 본문을 JSON 문자열 하나에 넣을 때\n   생기는 줄바꿈·괄호 오류를 피하기 위해서다. 예전 문자열 형식도 계속 받으며,\n   AI 가 흔히 만드는 원시 줄바꿈·후행 쉼표·body 닫기 괄호 오류는 안전하게\n   복구한다. eval 은 사용하지 않는다.\n   ══════════════════════════════════════════════════════════════ */\n(() => {\n  \"use strict\";\n\n  function extractCandidate(rawText) {\n    const text = String(rawText || \"\").trim();\n    if (!text) return \"\";\n\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced && fenced[1]) return fenced[1].trim();\n\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first !== -1 && last > first ? text.slice(first, last + 1).trim() : \"\";\n  }\n\n  function hasCompleteObject(rawText) {\n    const text = String(rawText || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n\n    for (let i = first; i < text.length; i += 1) {\n      const ch = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') inString = true;\n      else if (ch === \"{\") depth += 1;\n      else if (ch === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n\n    return false;\n  }\n\n  function escapeRawControlsInStrings(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n\n      if (inString) {\n        if (escaped) {\n          out += ch;\n          escaped = false;\n        } else if (ch === \"\\\\\") {\n          out += ch;\n          escaped = true;\n        } else if (ch === '\"') {\n          out += ch;\n          inString = false;\n        } else if (ch === \"\\n\") {\n          out += \"\\\\n\";\n        } else if (ch === \"\\r\") {\n          if (input[i + 1] === \"\\n\") i += 1;\n          out += \"\\\\n\";\n        } else if (ch === \"\\t\") {\n          out += \"\\\\t\";\n        } else {\n          out += ch;\n        }\n      } else {\n        out += ch;\n        if (ch === '\"') inString = true;\n      }\n    }\n\n    return out;\n  }\n\n  function stripTrailingCommas(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n      if (inString) {\n        out += ch;\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') {\n        inString = true;\n        out += ch;\n        continue;\n      }\n\n      if (ch === \",\") {\n        let next = i + 1;\n        while (next < input.length && /\\s/.test(input[next])) next += 1;\n        if (input[next] === \"}\" || input[next] === \"]\") continue;\n      }\n\n      out += ch;\n    }\n\n    return out;\n  }\n\n  function repairCommonJson(candidate) {\n    return stripTrailingCommas(escapeRawControlsInStrings(candidate));\n  }\n\n  function keyMatch(input, key, fromIndex = 0) {\n    const escapedKey = key.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n    const regex = new RegExp(`\"${escapedKey}\"\\\\s*:`, \"g\");\n    regex.lastIndex = fromIndex;\n    return regex.exec(input);\n  }\n\n  function extractSection(input, key, nextKeys) {\n    const current = keyMatch(input, key);\n    if (!current) return \"\";\n\n    const start = current.index + current[0].length;\n    let end = input.length;\n    for (const nextKey of nextKeys || []) {\n      const next = keyMatch(input, nextKey, start);\n      if (next && next.index < end) end = next.index;\n    }\n\n    let section = input.slice(start, end).trim();\n    section = section.replace(/,\\s*$/, \"\").trim();\n    return section;\n  }\n\n  function manualUnquote(value) {\n    let text = String(value || \"\").trim();\n    while (text.startsWith('\"') && /[}\\]]$/.test(text)) {\n      text = text.slice(0, -1).trim();\n    }\n    if (text.startsWith('\"')) text = text.slice(1);\n    if (text.endsWith('\"')) text = text.slice(0, -1);\n\n    return text\n      .replace(/\\\\r\\\\n/g, \"\\n\")\n      .replace(/\\\\n/g, \"\\n\")\n      .replace(/\\\\t/g, \"\\t\")\n      .replace(/\\\\\"/g, '\"')\n      .replace(/\\\\\\\\/g, \"\\\\\")\n      .trim();\n  }\n\n  function parseLooseValue(section) {\n    let value = String(section || \"\").trim().replace(/,\\s*$/, \"\").trim();\n    if (!value) return \"\";\n\n    /* 스크린샷처럼 문자열 body 뒤에 잘못 붙은 ] 를 제거한다. */\n    if (value.startsWith('\"')) {\n      while (value.endsWith(\"]\")) value = value.slice(0, -1).trim();\n    }\n\n    const attempts = [value, repairCommonJson(value)];\n    if (value.startsWith(\"[\") && !value.endsWith(\"]\")) {\n      attempts.push(repairCommonJson(value + \"]\"));\n    }\n\n    for (const attempt of attempts) {\n      try {\n        return JSON.parse(attempt);\n      } catch (_error) {\n        /* 다음 안전한 복구를 시도한다. */\n      }\n    }\n\n    if (value.startsWith(\"[\")) {\n      const strings = [];\n      const regex = /\"((?:\\\\.|[^\"\\\\])*)\"/g;\n      let match;\n      while ((match = regex.exec(value))) strings.push(manualUnquote(`\"${match[1]}\"`));\n      if (strings.length) return strings;\n    }\n\n    return manualUnquote(value);\n  }\n\n  function normalizeBody(value) {\n    if (Array.isArray(value)) {\n      return value\n        .map((item) => {\n          if (typeof item === \"string\") return item.trim();\n          if (item && typeof item === \"object\") {\n            return String(item.text || item.content || item.paragraph || \"\").trim();\n          }\n          return \"\";\n        })\n        .filter(Boolean)\n        .join(\"\\n\\n\");\n    }\n\n    if (value && typeof value === \"object\") {\n      return normalizeBody(value.paragraphs || value.body || value.content || value.text || \"\");\n    }\n\n    return typeof value === \"string\" ? value.trim() : \"\";\n  }\n\n  function normalizeArticle(data) {\n    if (!data || typeof data !== \"object\") return null;\n\n    const title = String(data.title || \"\").trim();\n    const subtitleValues = Array.isArray(data.subtitles)\n      ? data.subtitles\n      : [data.subtitle1, data.subtitle2, data.subtitle3];\n    const subtitles = subtitleValues\n      .map((value) => String(value || \"\").trim())\n      .filter(Boolean)\n      .slice(0, 3);\n    const body = normalizeBody(data.body || data.paragraphs || data.content || \"\");\n    const rawKeywords = Array.isArray(data.keywords)\n      ? data.keywords\n      : String(data.keywords || \"\").split(/[,\\n]/);\n    const keywords = rawKeywords\n      .map((keyword) => String(keyword || \"\").replace(/^#/, \"\").trim())\n      .filter(Boolean);\n\n    if (!title || !body) return null;\n    return { title, subtitles, body, keywords };\n  }\n\n  function parseLooseArticle(candidate) {\n    const title = parseLooseValue(extractSection(candidate, \"title\", [\"subtitle1\", \"subtitles\", \"body\"]));\n    const subtitlesValue = parseLooseValue(extractSection(candidate, \"subtitles\", [\"body\"]));\n    const subtitle1 = parseLooseValue(extractSection(candidate, \"subtitle1\", [\"subtitle2\", \"subtitle3\", \"body\"]));\n    const subtitle2 = parseLooseValue(extractSection(candidate, \"subtitle2\", [\"subtitle3\", \"body\"]));\n    const subtitle3 = parseLooseValue(extractSection(candidate, \"subtitle3\", [\"body\"]));\n    const body = parseLooseValue(extractSection(candidate, \"body\", [\"keywords\"]));\n\n    let keywordsSection = extractSection(candidate, \"keywords\", []);\n    while (keywordsSection.endsWith(\"}\")) keywordsSection = keywordsSection.slice(0, -1).trim();\n    const keywords = parseLooseValue(keywordsSection);\n\n    return {\n      title,\n      subtitles: Array.isArray(subtitlesValue)\n        ? subtitlesValue\n        : [subtitle1, subtitle2, subtitle3].filter(Boolean),\n      body,\n      keywords: Array.isArray(keywords) ? keywords : [],\n    };\n  }\n\n  function parse(rawText) {\n    if (!rawText || !String(rawText).trim()) {\n      return { ok: false, reason: \"AI 응답이 비어 있습니다.\" };\n    }\n\n    const candidate = extractCandidate(rawText);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON 을 찾지 못했습니다.\" };\n\n    let data = null;\n    let repaired = false;\n\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repairCommonJson(candidate));\n        repaired = true;\n      } catch (_repairError) {\n        data = parseLooseArticle(candidate);\n        repaired = true;\n      }\n    }\n\n    const article = normalizeArticle(data);\n    if (!article) {\n      return { ok: false, reason: \"AI 응답에 제목 또는 본문이 없거나 복구할 수 없는 JSON 입니다.\" };\n    }\n\n    return { ok: true, article, repaired };\n  }\n\n  const api = { parse, hasCompleteObject, extractCandidate, repairCommonJson, normalizeBody };\n  globalThis.GWArticleJson = api;\n\n  if (typeof module !== \"undefined\" && module.exports) {\n    module.exports = api;\n  }\n})();\n",
 "interior/blog-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   네이버 블로그 초안 전용 프롬프트\n\n   기사 작성 프롬프트와 분리한다. 블로그에서 스타일이나 분량을 바꿔도\n   2번 '초안 다듬기'의 기사 프롬프트에는 아무 영향이 없다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_BLOG_LENGTH = {\n  short:  { label: \"짧게\", chars: \"700~1,000자\", paras: \"5~7개\" },\n  normal: { label: \"중간\", chars: \"1,500~2,000자\", paras: \"9~12개\" },\n  long:   { label: \"길게\", chars: \"2,500~3,500자\", paras: \"14~20개\" },\n};\n\nconst GW_BLOG_STYLE = {\n  listing: {\n    label: \"기본 매물소개형\",\n    fit: \"모든 매물\",\n    titleExample: \"논현동 아크로힐스 매매 15억, 3룸 남향\",\n    guide:\n      \"깔끔하고 정보 중심으로 쓴다. 제목과 첫 문단에서 지역·매물·거래 조건을 분명히 보여 주고, \" +\n      \"본문은 핵심 조건, 입지, 내부 구성, 확인할 점의 순서로 정리한다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 3~4개, 명사형으로 짧게 (예: ■ 입지와 교통 / ■ 내부 구성 / ■ 계약 전 확인할 점). \" +\n      \"핵심 요약 → 입지 → 내부 구성 → 확인할 점 순서\",\n  },\n  visit: {\n    label: \"현장답사형\",\n    fit: \"아파트·상가·빌딩\",\n    titleExample: \"논현동 아크로힐스, 단지 안팎을 사진으로 살펴보니\",\n    guide:\n      \"현장을 차례로 둘러보는 듯한 흐름으로 쓴다. 다만 실제 방문·촬영·인터뷰를 했다고 거짓말하지 말고, \" +\n      \"제공된 기사와 사진에서 확인할 수 있는 동선과 인상만 관찰형 문장으로 풀어낸다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 3~5개, 둘러보는 동선 순서의 장소형 (예: ■ 단지 입구에서 / ■ 거실과 주방 / ■ 주변 거리). \" +\n      \"바깥에서 안으로, 다시 주변으로 이어지는 흐름\",\n  },\n  story: {\n    label: \"스토리텔링형\",\n    fit: \"주택·아파트\",\n    titleExample: \"강남에서 15억으로 찾는다면?\",\n    guide:\n      \"독자가 실제로 집이나 매물을 찾는 상황, 또는 한 가지 질문으로 시작한다. \" +\n      \"과장된 허구의 고객 사례는 만들지 말고 확인된 조건을 따라 자연스럽게 해답을 제시한다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 1~2개, 질문형 (예: ■ 15억이면 무엇을 먼저 봐야 할까?). \" +\n      \"상황 제시 → 질문 → 확인된 조건으로 해답 순서. 소제목보다 문단 흐름을 중시\",\n  },\n  report: {\n    label: \"분석·리포트형\",\n    fit: \"빌딩·토지·투자매물\",\n    titleExample: \"논현동 50억 건물, 조건을 하나씩 살펴보니\",\n    guide:\n      \"조건과 장점, 한계, 계약 전 확인 사항을 균형 있게 분석한다. \" +\n      \"확인되지 않은 수익률·시세·개발 호재를 추정하지 않는다.\",\n    design: \"news\",\n    structure:\n      \"소제목 4~5개, 명사형으로 고정 (■ 핵심 조건 / ■ 장점 / ■ 한계와 확인할 부분 / ■ 계약 전 체크포인트). \" +\n      \"각 구역은 1~2문단\",\n  },\n  consult: {\n    label: \"친근한 해설형\",\n    fit: \"실수요 매물\",\n    titleExample: \"방 3개 아파트 매물, 어떤 가구에 맞을까\",\n    guide:\n      \"매물 조건을 독자가 이해하기 쉽게 풀어 설명하는 해설 기사로 쓴다. 부드러운 존댓말은 허용하지만 \" +\n      \"권유하지 말고, 어떤 가구에 맞는 조건인지와 확인할 점을 객관적으로 짚는다.\",\n    design: \"qna\",\n    structure:\n      \"소제목 3~4개, 고객이 실제로 물어볼 질문형 (예: ■ 관리비는 얼마인가요? / ■ 주차는 가능한가요?). \" +\n      \"각 소제목 바로 다음 문단이 그 질문에 대한 답\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\",\n    fit: \"SNS 연계 매물\",\n    titleExample: \"[매물] 강남 논현동 아파트 15억 매매 등록\",\n    guide:\n      \"속보 기사처럼 첫 두 문장에 무엇이 어디에 얼마로 나왔는지를 짧게 전한다. 문장을 짧게 끊고 사실만 빠르게 전달하되, \" +\n      \"낚시성 표현·과도한 감탄·확인되지 않은 단정은 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 0~2개, 한 줄로 짧게. 강한 첫 두 문장 → 핵심 조건 3가지 → 한 줄 정리. \" +\n      \"문단은 1~2문장으로 짧게 끊을 것\",\n  },\n};\n\nfunction gwBlogFactLines(v) {\n  if (!v || typeof v !== \"object\") return \"- 별도 매물표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n\n  const lines = [];\n  const seen = new Set();\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  push(\"매물\", v.title);\n  push(\"금액\", v.priceText);\n  for (const field of v.fields || []) push(field.label, field.value);\n  push(\"특징\", Array.isArray(v.themes) ? v.themes.join(\" \") : v.themes);\n  push(\"주변환경\", v.infra);\n  return lines.length ? lines.join(\"\\n\") : \"- 별도 매물표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n}\n\nfunction gwBlogArticleText(article) {\n  const a = article || {};\n  const subtitles = Array.isArray(a.subtitles) ? a.subtitles : [];\n  return [\n    `[제목] ${String(a.title || \"\").trim()}`,\n    subtitles.length ? `[부제] ${subtitles.join(\" / \")}` : \"\",\n    `[본문]\\n${String(a.body || \"\").trim()}`,\n  ].filter(Boolean).join(\"\\n\");\n}\n\nfunction gwBuildBlogPrompt(source, opts) {\n  /* 인테리어 작성기: 결과표가 원자료다 */\n  if (source && source.remodel && typeof gwBuildRemodelBlogPrompt === \"function\") return gwBuildRemodelBlogPrompt(source, opts);\n  if (source && source.vacancy && source.vacancy.saleKind) return gwBuildAuctionBlogPrompt(source, opts);\n  const input = source || {};\n  const o = opts || {};\n  const style = GW_BLOG_STYLE[o.style] || GW_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = input.article || {};\n\n  return `당신은 부동산 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 공실뉴스 기사와 확인된 매물 정보를 참고해 블로그 초안 1건을 작성하십시오.\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n[확인된 매물 정보]\n${gwBlogFactLines(input.vacancy)}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 매물: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n- 같은 매물 조건을 반복해 분량을 억지로 늘리지 말 것\n\n[보도 원칙 — 모든 스타일 공통, 가장 먼저 지킬 것]\n- 이 글은 \"공실뉴스에 이런 매물이 나왔다\"는 객관적인 매물 보도입니다. 위 스타일은 전개 방식만 정하고 이 틀은 바꾸지 않습니다\n- 3인칭 전달체로 쓸 것 (예: \"~로 등록됐다\", \"~인 것으로 나타났다\", \"~로 확인된다\"). 기본·분석·속보형은 기사체(~다), 현장답사·스토리텔링·해설형은 부드러운 존댓말(~습니다)도 허용\n- 첫 문단에서 공실뉴스에 등록된 매물이라는 점과 소재지·매물 종류·거래 조건을 밝힐 것 (예: \"공실뉴스에 서울 강남구 논현동 아파트 매매 매물이 등록됐다.\")\n- 출처를 분명히 할 것 (예: \"공실뉴스에 등록된 매물 정보에 따르면\")\n- 권유·호객·광고 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"연락 주세요\", \"놓치지 마세요\", \"강력 추천\", \"지금이 기회\" 등\n- 독자에게 직접 권하는 2인칭 문장을 쓰지 말 것. 조언이 필요하면 \"~라면 ~를 확인할 필요가 있다\"처럼 객관적으로 쓸 것\n- 위치·학군·지하철역·버스정류장·쇼핑시설·병원 등 주변 정보는 기사 가치가 있으므로 적극 전할 것. 단 [확인된 매물 정보]와 [참조 기사]에 있는 것만 쓰고, 자료에 없는 거리·도보 시간은 만들지 말 것\n- 중개사무소 이름·연락처·링크는 본문에 쓰지 말 것 (글 끝 \"매물 정보 출처\"에 자동으로 들어갑니다)\n\n[가장 중요한 사실 원칙]\n- 금액·면적·층·방·주소·관리비·입주일·주차·옵션 등 매물 고유 조건은\n  [확인된 매물 정보] 또는 [참조 기사]에 실제로 있는 내용만 쓸 것\n- 두 자료가 다르면 [확인된 매물 정보]를 우선할 것\n- 없는 수치, 현장 방문, 인터뷰, 고객 반응, 시세, 수익률, 개발 호재를 만들어내지 말 것\n- 소재지가 시·군·동까지만 공개됐다면 더 상세한 주소를 추측하지 말 것\n- 장점과 함께 계약 전 직접 확인할 점도 균형 있게 안내할 것\n\n[블로그 구성]\n- title: 검색어를 억지로 나열하지 않은 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 모바일에서도 읽기 쉽도록 한 문단을 2~4문장으로 짧게 구성할 것\n- 첫 문단은 2문장 이내의 핵심 요약으로 쓸 것 (인사말 없이 바로 본론, 위 보도 원칙의 첫 문단 규칙 포함). 이 문단은 블로그 맨 위 요약으로 쓰입니다\n- 소제목은 위 [선택한 스타일]의 구성대로 넣고, 한 줄짜리 독립 문단으로 쓰며 반드시 \"■ \"로 시작할 것\n  (\"■\"는 소제목 위치를 알리는 표시이며 화면 모양은 블로그 디자인이 따로 정합니다)\n- 소제목 바로 다음에는 반드시 본문 문단이 올 것 (소제목을 연달아 쓰거나 글 맨 끝에 두지 말 것)\n- 마지막 문단은 매물 조건과 확인할 점을 객관적으로 정리하는 한 문단으로 쓸 것. 권유·연락처·문의 안내·링크는 쓰지 말 것\n- 기사 문장을 그대로 길게 복사하지 말고 블로그 독자를 위한 새 문장으로 재구성할 것\n- keywords: 지역명·매물 종류·거래 조건을 포함한 검색용 핵심어 7~12개. # 기호는 제외할 것\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nfunction gwBuildBlogRevisePrompt(request, vacancy) {\n  if (vacancy && vacancy.saleKind) return gwBuildAuctionBlogRevisePrompt(request);\n  return `위에서 작성한 블로그 글을 아래 요청대로 고쳐 주십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 매물의 금액·면적·층·주소·번호 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 사용자의 수정 요청을 반영하되 과장 광고, 허위 방문, 허위 고객 사례를 만들지 마십시오.\n- 소제목 문단은 처음처럼 \"■ \"로 시작하고, 첫 문단은 핵심 요약으로 유지하십시오.\n- \"공실뉴스에 이런 매물이 나왔다\"는 객관적 보도 형식을 유지하고, 권유·호객 표현이나 중개사무소 연락처를 넣지 마십시오.\n- 고친 블로그 글 전체를 다시 출력하십시오. 수정된 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n- body는 문단별 문자열 배열이며 JSON.parse가 가능한 유효한 JSON이어야 합니다.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 물건 블로그 — 스타일 이름·순서는 일반 매물과 같고,\n   예시·지침·사실 원칙이 경매·공매에 맞춰져 있다.\n   블로그 탭은 gwBlogStyles(vacancy) 로 어느 쪽 스타일을 쓸지 고른다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_AUCTION_BLOG_STYLE = {\n  listing: {\n    label: \"기본 물건소개형\",\n    fit: \"모든 물건\",\n    titleExample: \"역삼동 오피스텔 공매, 최저입찰가 291만원\",\n    guide:\n      \"깔끔하고 정보 중심으로 쓴다. 제목과 첫 문단에서 경매·공매 구분, 지역, 물건 종류, 감정가와 최저입찰가를 분명히 보여 주고, \" +\n      \"본문은 가격 조건, 물건 현황과 입지, 입찰 일정, 확인할 점의 순서로 정리한다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 3~4개, 명사형으로 짧게 (예: ■ 가격 조건 / ■ 물건 현황과 입지 / ■ 입찰 일정 / ■ 입찰 전 확인할 점). \" +\n      \"핵심 요약 → 가격 → 현황·입지 → 일정 → 확인할 점 순서\",\n  },\n  visit: {\n    label: \"현장답사형\",\n    fit: \"아파트·상가·빌딩\",\n    titleExample: \"역삼동 경매 오피스텔, 주변을 사진으로 살펴보니\",\n    guide:\n      \"물건 주변을 차례로 둘러보는 듯한 흐름으로 쓴다. 다만 실제 방문·촬영·인터뷰를 했다고 거짓말하지 말고, \" +\n      \"제공된 기사와 사진·지도·로드뷰에서 확인할 수 있는 동선과 인상만 관찰형 문장으로 풀어낸다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 3~5개, 둘러보는 동선 순서의 장소형 (예: ■ 건물 외관 / ■ 진입로와 주변 거리 / ■ 가까운 교통). \" +\n      \"바깥에서 주변으로 이어지는 흐름. 마지막 소제목은 입찰 조건 정리\",\n  },\n  story: {\n    label: \"스토리텔링형\",\n    fit: \"주택·아파트\",\n    titleExample: \"감정가의 절반에 나온 아파트, 무엇을 봐야 할까?\",\n    guide:\n      \"독자가 경매·공매 물건을 처음 살펴보는 상황, 또는 한 가지 질문으로 시작한다. \" +\n      \"과장된 허구의 사례는 만들지 말고 확인된 조건을 따라 자연스럽게 해답을 제시한다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 1~2개, 질문형 (예: ■ 유찰이 거듭되면 무엇이 달라질까?). \" +\n      \"상황 제시 → 질문 → 확인된 조건으로 해답 순서. 소제목보다 문단 흐름을 중시\",\n  },\n  report: {\n    label: \"분석·리포트형\",\n    fit: \"빌딩·토지·상가\",\n    titleExample: \"3회 유찰된 논현동 건물, 입찰 조건을 살펴보니\",\n    guide:\n      \"가격 조건과 물건 현황, 한계, 입찰 전 확인 사항을 균형 있게 분석한다. \" +\n      \"확인되지 않은 낙찰가·수익률·시세·개발 호재를 추정하지 않는다.\",\n    design: \"news\",\n    structure:\n      \"소제목 4~5개, 명사형으로 고정 (■ 핵심 가격 조건 / ■ 물건 현황 / ■ 한계와 확인할 부분 / ■ 입찰 일정과 방법). \" +\n      \"각 구역은 1~2문단\",\n  },\n  consult: {\n    label: \"친근한 해설형\",\n    fit: \"주거용 물건\",\n    titleExample: \"공매 오피스텔, 입찰 절차는 어떻게 될까\",\n    guide:\n      \"경매·공매 물건의 조건과 입찰 절차를 독자가 이해하기 쉽게 풀어 설명하는 해설 기사로 쓴다. 부드러운 존댓말은 허용하지만 \" +\n      \"권유하지 말고, 조건의 의미와 확인할 점을 객관적으로 짚는다.\",\n    design: \"qna\",\n    structure:\n      \"소제목 3~4개, 독자가 실제로 물어볼 질문형 (예: ■ 최저입찰가는 어떻게 정해졌나요? / ■ 입찰보증금은 얼마인가요?). \" +\n      \"각 소제목 바로 다음 문단이 그 질문에 대한 답\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\",\n    fit: \"SNS 연계 물건\",\n    titleExample: \"[공매] 강남 역삼동 오피스텔 최저가 291만원\",\n    guide:\n      \"속보 기사처럼 첫 두 문장에 어떤 물건이 어디서 얼마에 경매·공매로 나왔는지를 짧게 전한다. 문장을 짧게 끊고 사실만 빠르게 전달하되, \" +\n      \"낚시성 표현·과도한 감탄·확인되지 않은 단정은 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 0~2개, 한 줄로 짧게. 강한 첫 두 문장 → 핵심 조건 3가지(감정가·최저입찰가·입찰 일정) → 한 줄 정리. \" +\n      \"문단은 1~2문장으로 짧게 끊을 것\",\n  },\n};\n\nfunction gwAuctionBlogFactLines(v) {\n  if (!v || typeof v !== \"object\") return \"- 별도 물건표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n\n  const lines = [];\n  const seen = new Set();\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  push(\"물건\", v.title);\n  push(\"가격 요약\", v.priceText);\n  for (const field of v.fields || []) push(field.label, field.value);\n  return lines.length ? lines.join(\"\\n\") : \"- 별도 물건표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n}\n\nfunction gwBuildAuctionBlogPrompt(source, opts) {\n  const input = source || {};\n  const o = opts || {};\n  const style = GW_AUCTION_BLOG_STYLE[o.style] || GW_AUCTION_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = input.article || {};\n\n  const saleKind = input.vacancy && input.vacancy.saleKind === \"공매\" ? \"공매\" : \"경매\";\n\n  return `당신은 부동산 경매·공매 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 공실뉴스 기사와 확인된 ${saleKind} 물건 정보를 참고해 블로그 초안 1건을 작성하십시오.\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n[확인된 물건 정보]\n${gwAuctionBlogFactLines(input.vacancy)}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 물건: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n- 같은 물건 조건을 반복해 분량을 억지로 늘리지 말 것\n\n[보도 원칙 — 모든 스타일 공통, 가장 먼저 지킬 것]\n- 이 글은 \"공실뉴스 공실열람에 이런 ${saleKind} 물건이 나왔다\"는 객관적인 보도입니다. 위 스타일은 전개 방식만 정하고 이 틀은 바꾸지 않습니다\n- 3인칭 전달체로 쓸 것 (예: \"~로 나왔다\", \"~인 것으로 나타났다\", \"~로 확인된다\"). 기본·분석·속보형은 기사체(~다), 현장답사·스토리텔링·해설형은 부드러운 존댓말(~습니다)도 허용\n- 첫 문단에서 ${saleKind} 물건이라는 점과 소재지·물건 종류·감정가·최저입찰가를 밝힐 것 (예: \"서울 강남구 역삼동 오피스텔이 ${saleKind}로 나왔다.\")\n- 출처를 분명히 할 것 (예: \"공실뉴스 공실열람의 ${saleKind} 물건 정보에 따르면\")\n- 투자 권유·호객 표현 금지: \"싸게 살 기회\", \"놓치지 마세요\", \"추천합니다\", \"지금이 기회\", \"수익이 기대된다\" 등\n- 낙찰가·낙찰가율·수익률·시세 상승을 예측하지 말 것\n- 독자에게 직접 권하는 2인칭 문장을 쓰지 말 것. 조언이 필요하면 \"~라면 ~를 확인할 필요가 있다\"처럼 객관적으로 쓸 것\n- 위치·교통·주변 시설 정보는 적극 전하되, [확인된 물건 정보]와 [참조 기사]에 있는 것만 쓰고 거리·도보 시간을 만들지 말 것\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호), \"본 정보는 참고용이며 법적 책임을 지지 않는다\"는 식의 입찰 전 법적 주의사항 안내문은 쓰지 말 것\n- 링크는 본문에 쓰지 말 것 (글 끝 \"물건 정보 출처\"에 자동으로 들어갑니다)\n\n[가장 중요한 사실 원칙]\n- 감정가·최저입찰가·유찰 횟수·입찰 일정·입찰보증금·면적·주소·관리번호(사건번호)·집행기관은\n  [확인된 물건 정보] 또는 [참조 기사]에 실제로 있는 내용만 쓸 것\n- 두 자료가 다르면 [확인된 물건 정보]를 우선할 것\n- 권리관계·임차인·체납액·현장 방문·인터뷰·낙찰 결과를 만들어내지 말 것\n- 입찰 일정이 없으면 날짜를 만들지 말 것\n- 가격 조건과 함께 입찰 전 직접 확인할 점(현장 상태·점유와 명도·권리관계)도 균형 있게 짚을 것\n\n[블로그 구성]\n- title: 검색어를 억지로 나열하지 않은 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 모바일에서도 읽기 쉽도록 한 문단을 2~4문장으로 짧게 구성할 것\n- 첫 문단은 2문장 이내의 핵심 요약으로 쓸 것 (인사말 없이 바로 본론, 위 보도 원칙의 첫 문단 규칙 포함). 이 문단은 블로그 맨 위 요약으로 쓰입니다\n- 소제목은 위 [선택한 스타일]의 구성대로 넣고, 한 줄짜리 독립 문단으로 쓰며 반드시 \"■ \"로 시작할 것\n  (\"■\"는 소제목 위치를 알리는 표시이며 화면 모양은 블로그 디자인이 따로 정합니다)\n- 소제목 바로 다음에는 반드시 본문 문단이 올 것 (소제목을 연달아 쓰거나 글 맨 끝에 두지 말 것)\n- 마지막 문단은 가격·일정 조건과 입찰 전 확인할 점을 객관적으로 정리하는 한 문단으로 쓸 것. 권유·연락처·링크는 쓰지 말 것\n- 기사 문장을 그대로 길게 복사하지 말고 블로그 독자를 위한 새 문장으로 재구성할 것\n- keywords: 지역명·물건 종류·\"${saleKind}\"를 포함한 검색용 핵심어 7~12개. # 기호는 제외할 것\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nfunction gwBuildAuctionBlogRevisePrompt(request) {\n  return `위에서 작성한 블로그 글을 아래 요청대로 고쳐 주십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 물건의 감정가·최저입찰가·유찰 횟수·입찰 일정·면적·주소·관리번호 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 사용자의 수정 요청을 반영하되 과장 광고, 허위 방문, 허위 고객 사례를 만들지 마십시오.\n- 소제목 문단은 처음처럼 \"■ \"로 시작하고, 첫 문단은 핵심 요약으로 유지하십시오.\n- \"공실뉴스 공실열람에 이런 경매·공매 물건이 나왔다\"는 객관적 보도 형식을 유지하고, 투자 권유·낙찰가 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문을 넣지 마십시오.\n- 고친 블로그 글 전체를 다시 출력하십시오. 수정된 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n- body는 문단별 문자열 배열이며 JSON.parse가 가능한 유효한 JSON이어야 합니다.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* 물건 종류에 맞는 블로그 스타일 표 — 경매·공매면 경매용 */\nfunction gwBlogStyles(vacancy) {\n  if (typeof RM_BLOG_STYLE !== \"undefined\") return RM_BLOG_STYLE; // 인테리어 작성기\n  return vacancy && vacancy.saleKind ? GW_AUCTION_BLOG_STYLE : GW_BLOG_STYLE;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_BLOG_LENGTH,\n    GW_BLOG_STYLE,\n    GW_AUCTION_BLOG_STYLE,\n    gwBlogStyles,\n    gwBlogFactLines,\n    gwAuctionBlogFactLines,\n    gwBlogArticleText,\n    gwBuildBlogPrompt,\n    gwBuildBlogRevisePrompt,\n  };\n}\n",
 "interior/naver-blog.js": "/* 네이버 블로그 탭과 글쓰기 탭을 구분하는 공통 규칙 */\n(function initNaverBlog(global) {\n  \"use strict\";\n\n  const HOME_URL = \"https://blog.naver.com/\";\n  const WRITE_URL = \"https://blog.naver.com/GoBlogWrite.naver\";\n\n  function isNaverBlogUrl(rawUrl) {\n    try {\n      const url = new URL(rawUrl);\n      return url.protocol === \"https:\" && (\n        url.hostname === \"blog.naver.com\" ||\n        url.hostname === \"blog.editor.naver.com\"\n      );\n    } catch (_) {\n      return false;\n    }\n  }\n\n  function isLikelyWriteUrl(rawUrl) {\n    if (!isNaverBlogUrl(rawUrl)) return false;\n    const value = String(rawUrl).toLowerCase();\n    return (\n      value.includes(\"goblogwrite\") ||\n      value.includes(\"postwrite\") ||\n      value.includes(\"postwriteform\") ||\n      value.includes(\"redirect=write\") ||\n      value.includes(\"blog.editor.naver.com\")\n    );\n  }\n\n  function selectLikelyWriteTab(tabs) {\n    return (Array.isArray(tabs) ? tabs : [])\n      .filter((tab) => tab && tab.id && isLikelyWriteUrl(tab.url))\n      .sort((a, b) => {\n        if (Boolean(a.active) !== Boolean(b.active)) return a.active ? -1 : 1;\n        return (b.lastAccessed || 0) - (a.lastAccessed || 0);\n      })[0] || null;\n  }\n\n  function splitParagraphs(body) {\n    return String(body || \"\")\n      .split(/\\n{2,}|\\n/)\n      .map((value) => value.trim())\n      .filter(Boolean);\n  }\n\n  /* 대표가 아닌 사진을 문단 사이 칸(0 = 첫 문단 앞, n = n번째 문단 뒤)에 배치한다.\n     insertAfterParagraph가 있으면 그 칸, 없으면 두 문단마다 한 장씩, 남으면 글 끝. */\n  function layoutMediaSlots(paragraphCount, media) {\n    const slots = Array.from({ length: paragraphCount + 1 }, () => []);\n    const automatic = [];\n\n    (Array.isArray(media) ? media : []).forEach((item, index) => {\n      if (!item || item.isCover) return;\n      if (Number.isInteger(item.insertAfterParagraph)) {\n        const slot = Math.max(0, Math.min(item.insertAfterParagraph, paragraphCount));\n        slots[slot].push({ media: item, index });\n      } else {\n        automatic.push({ media: item, index });\n      }\n    });\n\n    let autoIndex = 0;\n    for (let slot = 2; slot < paragraphCount && autoIndex < automatic.length; slot += 2) {\n      slots[slot].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    while (autoIndex < automatic.length) {\n      slots[paragraphCount].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    return slots;\n  }\n\n  function escapeHtml(value) {\n    return String(value).replace(/[&<>\"']/g, (ch) => ({\n      \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\",\n    })[ch]);\n  }\n\n  /* ── 블로그 디자인 ──\n     네이버 편집기가 붙여넣기로 받아들이는 요소만 쓴다 (2026-09-25 실제 화면에서 확인):\n     <blockquote> → 인용구(따옴표형), <hr> → 구분선, <table> → 표, 문단 정렬·글자색·크기·링크.\n     굵게(<b>·<strong>·font-weight)는 붙여넣기로 적용되지 않으므로 소제목은 크기와 색으로 강조한다.\n     붙여넣기 조각을 빈 문단으로 끝내지 않으면 다음 조각이 마지막 문단에 이어 붙고 글자색·크기도 번진다.\n     문단 순서는 모든 디자인이 같다. 그래서 사진 위치(문단 사이 칸)가 미리보기와 어긋나지 않는다. */\n  const DESIGNS = {\n    basic: { label: \"기본형\", hint: \"요약 인용구 · 매물표 · 큰 소제목. 어떤 매물에나 무난합니다.\" },\n    magazine: { label: \"매거진형\", hint: \"가운데 정렬 · 번호 소제목 · 핵심 문장 강조. 고급·신축 매물에 어울립니다.\" },\n    qna: { label: \"Q&A형\", hint: \"소제목을 질문으로, 본문을 답변으로. 질문형 검색에 유리합니다.\" },\n    news: { label: \"뉴스기사형\", hint: \"큰 리드문 · 기사체 · 공실뉴스 서명. 언론사 느낌을 살립니다.\" },\n  };\n  /* 경매·공매 물건일 때 바뀌는 디자인 설명 */\n  const AUCTION_HINTS = {\n    basic: \"요약 인용구 · 물건표 · 큰 소제목. 어떤 물건에나 무난합니다.\",\n    magazine: \"가운데 정렬 · 번호 소제목 · 핵심 문장 강조. 아파트·건물 물건에 어울립니다.\",\n  };\n  function designHint(design, auction) {\n    return (auction && AUCTION_HINTS[design]) || DESIGNS[design]?.hint || \"\";\n  }\n  const ACCENT = \"#2563eb\";\n  const MUTED = \"#888888\";\n  const SKY = \"#dbeafe\"; // 매거진형 소제목 하늘색 배경(형광펜)\n  const BLANK = \"<p><br></p>\";\n  const SITE_URL = \"https://www.gongsilnews.com\"; // gongsilnews.com은 www로 넘어간다. 로그인 쿠키도 www에 있다\n\n  /* 매물표 항목: 부동산 인터넷 표시·광고 필수 항목 순서.\n     소재지·매물종류·거래형태는 출처 API(listing), 나머지는 공실광고정보 탭 항목(vacancy.fields)에서 찾는다. */\n  const FACT_ORDER = [\n    /^(금액)$/,\n    /관리비/,\n    /면적/,\n    /해당층|총층|건물규모/,\n    /방\\/욕실|방수|욕실/,\n    /방향/,\n    /준공|사용승인/,\n    /주차/,\n    /입주가능|사용 가능일/,\n  ];\n\n  /* 경매·공매 물건표 항목: 경매·공매 물건을 볼 때 먼저 찾는 순서.\n     소재지·물건종류는 출처 API(listing), 나머지는 서버에서 받은 물건 정보(vacancy.fields)에서 찾는다.\n     정보제공처 연락처와 입찰 전 주의사항은 서버가 애초에 보내지 않는다. */\n  const AUCTION_FACT_ORDER = [\n    /^구분$/,\n    /^감정가$/,\n    /^최저입찰가$/,\n    /감정가 대비/,\n    /유찰/,\n    /토지면적|건물면적/,\n    /입찰 시작|입찰 마감|개찰일시/,\n    /입찰보증금$/,\n    /명도책임/,\n    /관리번호|사건번호/,\n    /집행기관|관할법원/,\n  ];\n\n  /* 경매·공매 물건인가 — 출처 API 나 물건 정보에 경매·공매 구분이 붙어 있다 */\n  const isAuction = (vacancy, listing) => Boolean(listing?.saleKind || vacancy?.saleKind);\n\n  function isHeading(paragraph) {\n    return String(paragraph).startsWith(\"■\");\n  }\n\n  function stripHeading(paragraph) {\n    return String(paragraph).replace(/^■\\s*/, \"\");\n  }\n\n  /* 매물표: 표시·광고 필수 항목을 정해진 순서로 (개수 제한 없음) */\n  function factRows(vacancy, listing) {\n    const rows = [];\n    const seen = new Set();\n    const push = (label, value) => {\n      const text = value == null ? \"\" : String(value).trim();\n      if (!label || !text || text === \"-\" || seen.has(label)) return;\n      seen.add(label);\n      rows.push([label, text]);\n    };\n    const fields = (Array.isArray(vacancy?.fields) ? vacancy.fields : []).filter((field) => field && field.label);\n\n    if (isAuction(vacancy, listing)) {\n      push(\"소재지\", fields.find((field) => field.label === \"소재지(지번)\")?.value || listing?.location);\n      push(\"물건종류\", listing?.propertyType || fields.find((field) => field.label === \"물건종류\")?.value);\n      AUCTION_FACT_ORDER.forEach((pattern) => {\n        fields.filter((field) => pattern.test(field.label)).forEach((field) => push(field.label, field.value));\n      });\n      if (!seen.has(\"최저입찰가\")) push(\"가격\", vacancy?.priceText);\n      return rows;\n    }\n\n    push(\"소재지\", listing?.location);\n    push(\"매물종류\", listing?.propertyType);\n    push(\"거래형태\", listing?.tradeType || fields.find((field) => /거래구분/.test(field.label))?.value);\n    FACT_ORDER.forEach((pattern) => {\n      fields.filter((field) => pattern.test(field.label)).forEach((field) => push(field.label, field.value));\n    });\n    if (!seen.has(\"금액\")) push(\"금액\", vacancy?.priceText);\n    return rows;\n  }\n\n  /* 링크: 매물 고정 상세 주소 → 없으면 처음 매물을 본 공실뉴스 주소 */\n  function listingUrl(vacancy, listing) {\n    if (listing?.detailUrl) return listing.detailUrl;\n    const url = String(vacancy?.url || \"\");\n    return /^https:\\/\\/([a-z0-9-]+\\.)?gongsilnews\\.com\\//i.test(url) ? url : \"\";\n  }\n\n  function formatDate(value) {\n    const date = value ? new Date(value) : new Date();\n    if (Number.isNaN(date.getTime())) return \"\";\n    const pad = (n) => String(n).padStart(2, \"0\");\n    return `${date.getFullYear()}.${pad(date.getMonth() + 1)}.${pad(date.getDate())}`;\n  }\n\n  /* 전송 전 검사: 표시·광고 필수 정보가 빠졌으면 이유를 돌려준다 */\n  function listingProblems(listing, auction = false) {\n    /* 경매·공매: 물건 정보를 서버에서 받았는지만 본다 */\n    if (auction || listing?.saleKind) {\n      if (!listing) return [\"경매·공매 물건 정보\"];\n      return listing.saleKind ? [] : [\"경매·공매 구분\"];\n    }\n    if (!listing) return [\"매물 출처 정보(중개사무소)\"];\n    const owner = listing.owner || {};\n    if (owner.type !== \"agency\") return owner.name ? [] : [\"등록자 이름\"];\n    return [\n      [\"중개사무소 명칭\", owner.name],\n      [\"대표자\", owner.ceo],\n      [\"등록번호\", owner.regNo],\n      [\"소재지\", owner.address],\n      [\"연락처\", owner.phone],\n    ].filter(([, value]) => !String(value || \"\").trim()).map(([label]) => label);\n  }\n\n  /* 글 끝 \"매물 정보 출처\" — 모든 디자인 공통. 문의처가 아니라 출처로 표현한다. */\n  function sourceBlockLines(listing, url) {\n    /* 경매·공매: 정보제공처(온비드 고객센터) 연락처와 입찰 전 법적 주의사항 안내문은 넣지 않는다 */\n    if (listing?.saleKind) {\n      const saleKind = listing.saleKind;\n      const lines = [`공실뉴스 공실열람 ${saleKind} 물건 정보 (${formatDate(listing.capturedAt)} 기준)`];\n      const numberLabel = listing.caseLabel || (saleKind === \"공매\" ? \"관리번호\" : \"사건번호\");\n      const parts = [\n        listing.caseNo ? `${numberLabel} ${listing.caseNo}` : \"\",\n        listing.agency ? `${saleKind === \"공매\" ? \"집행기관\" : \"관할법원\"} ${listing.agency}` : \"\",\n      ].filter(Boolean);\n      if (parts.length) lines.push(parts.join(\" | \"));\n      lines.push(\"※ 입찰 조건은 공고 시점 기준이며 변경될 수 있습니다.\");\n      return { lines, url };\n    }\n    /* 인테리어 작성기: 예측 이미지·공사비의 출처는 모든 글에 붙인다 */\n    const REMODEL_LINE = \"인테리어 예측 이미지·예상 공사비: 공실뉴스 인테리어 예측 시뮬레이션 (대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다)\";\n\n    /* 직접 올린 사진 — 공실 매물이 아니다 */\n    if (!listing && !url) {\n      return { lines: [`공실뉴스 인테리어 예측 시뮬레이션 결과 (${formatDate()} 기준)`, REMODEL_LINE], url };\n    }\n\n    const owner = listing?.owner || {};\n    const lines = [`공실뉴스 매물 등록 정보 (${formatDate(listing?.capturedAt)} 기준)`];\n    const office = (label, a) => {\n      lines.push(`${label}: ${a.name}${a.ceo ? ` | 대표 ${a.ceo}` : \"\"}`);\n      const reg = [a.regNo ? `등록번호 ${a.regNo}` : \"\", a.address || \"\"].filter(Boolean).join(\" | \");\n      if (reg) lines.push(reg);\n      if (a.phone) lines.push(`전화 ${a.phone}`);\n    };\n    if (owner.type === \"agency\" && owner.name) {\n      office(\"등록 중개사무소\", owner);\n    } else if (owner.name) {\n      lines.push(`등록자: ${owner.name} (일반회원 등록 매물)`);\n    } else {\n      lines.push(\"매물 정보 출처: 공실뉴스 공실열람\");\n    }\n    lines.push(\"※ 매물 조건은 등록 시점 기준이며 실제와 다를 수 있습니다.\");\n    lines.push(REMODEL_LINE);\n    return { lines, url };\n  }\n\n  function paragraphHtml(text, { align, size, color, background, bold } = {}) {\n    let inner = escapeHtml(text);\n    const styles = [\n      size ? `font-size:${size}px` : \"\",\n      color ? `color:${color}` : \"\",\n      background ? `background-color:${background}` : \"\",\n      bold ? \"font-weight:700\" : \"\",\n    ].filter(Boolean).join(\";\");\n    if (styles) inner = `<span style=\"${styles}\">${inner}</span>`;\n    return align ? `<p style=\"text-align:${align}\">${inner}</p>` : `<p>${inner}</p>`;\n  }\n\n  function quoteHtml(text) {\n    return `<blockquote><p>${escapeHtml(text)}</p></blockquote>`;\n  }\n\n  function tableHtml(rows) {\n    if (!rows.length) return \"\";\n    const body = rows\n      .map(([label, value]) => `<tr><td><b>${escapeHtml(label)}</b></td><td>${escapeHtml(value)}</td></tr>`)\n      .join(\"\");\n    return `<table><tbody>${body}</tbody></table>`;\n  }\n\n  function linkHtml(url, text, align) {\n    if (!url) return \"\";\n    const style = align ? ` style=\"text-align:${align}\"` : \"\";\n    return `<p${style}><a href=\"${escapeHtml(url)}\">${escapeHtml(text)}</a></p>`;\n  }\n\n  function firstSentence(text) {\n    const match = /^(.+?[.!?])(\\s|$)/.exec(String(text || \"\").trim());\n    return match ? match[1] : String(text || \"\").trim();\n  }\n\n  /* 네이버 편집기에 차례로 붙여넣을 조각을 만든다.\n     글 조각은 HTML, 사진은 media 배열의 위치만 담는다.\n     글 조각은 사진이 끼어들 때만 끊고, 문단 뒤와 조각 끝에는 빈 문단을 둔다. */\n  function buildNaverBlocks(body, media, options = {}) {\n    const design = DESIGNS[options.design] ? options.design : \"basic\";\n    const list = Array.isArray(media) ? media : [];\n    const paragraphs = splitParagraphs(body);\n    const slots = layoutMediaSlots(paragraphs.length, list);\n    const rows = factRows(options.vacancy, options.listing);\n    const noun = isAuction(options.vacancy, options.listing) ? \"물건\" : \"매물\";\n    const url = listingUrl(options.vacancy, options.listing);\n    const blocks = [];\n    let buffer = [];\n\n    const flush = () => {\n      if (!buffer.length) return;\n      if (buffer[buffer.length - 1] !== BLANK) buffer.push(BLANK);\n      blocks.push({ type: \"html\", html: buffer.join(\"\") });\n      buffer = [];\n    };\n    // 문단 뒤에는 빈 문단 한 칸 (tight: 번호처럼 바로 아래 줄과 붙어야 하는 문단)\n    const html = (value, { tight = false } = {}) => {\n      if (!value) return;\n      buffer.push(value);\n      if (!tight && value.startsWith(\"<p\")) buffer.push(BLANK);\n    };\n    const addImages = (indexes) => {\n      if (!indexes.length) return;\n      flush();\n      indexes.forEach((index) => blocks.push({ type: \"image\", mediaIndex: index }));\n    };\n\n    const leadIndex = paragraphs.length && !isHeading(paragraphs[0]) ? 0 : -1;\n    const firstHeadingIndex = paragraphs.findIndex(isHeading);\n    let headingNumber = 0;\n    let answerPending = false;\n    let pullQuote = \"\";\n    let pullQuoteDone = false;\n\n    // 대표 사진 (뉴스기사형은 사진 설명을 작게 붙인다)\n    const coverIndex = list.findIndex((item) => item && item.isCover);\n    if (coverIndex >= 0) {\n      addImages([coverIndex]);\n      const caption = String(list[coverIndex].caption || \"\").trim();\n      if (design === \"news\" && caption) html(paragraphHtml(caption, { align: \"center\", size: 13, color: MUTED }));\n    }\n    if (design === \"magazine\" && options.title) {\n      html(paragraphHtml(options.title, { align: \"center\", size: 24, bold: true }));\n    }\n    addImages(slots[0].map((item) => item.index));\n\n    // 도입부가 끝나고 첫 소제목이 오기 전에 넣는 장식\n    const afterIntro = () => {\n      if (design === \"basic\") {\n        html(tableHtml(rows));\n        html(\"<hr>\");\n      } else if (design === \"magazine\") {\n        html(\"<hr>\");\n      }\n    };\n\n    let carried = [];\n    paragraphs.forEach((paragraph, index) => {\n      if (index === firstHeadingIndex) afterIntro();\n\n      if (index === leadIndex) {\n        if (design === \"basic\" || design === \"qna\") html(quoteHtml(paragraph));\n        else if (design === \"magazine\") html(paragraphHtml(paragraph, { align: \"center\", color: MUTED }));\n        else html(paragraphHtml(paragraph, { size: 17, bold: true }));\n        if (design === \"qna\") html(tableHtml(rows));\n      } else if (isHeading(paragraph)) {\n        const text = stripHeading(paragraph);\n        headingNumber += 1;\n        if (design === \"magazine\" && headingNumber === 2 && pullQuote) {\n          html(quoteHtml(pullQuote));\n          pullQuoteDone = true;\n        }\n        if (design === \"basic\") {\n          html(paragraphHtml(`■ ${text}`, { size: 19, bold: true }), { tight: true });\n        } else if (design === \"magazine\") {\n          html(paragraphHtml(String(headingNumber).padStart(2, \"0\"), { align: \"center\", color: ACCENT, bold: true }), { tight: true });\n          html(paragraphHtml(text, { align: \"center\", size: 19, background: SKY, bold: true }), { tight: true });\n        } else if (design === \"qna\") {\n          html(paragraphHtml(/^Q[.\\s]/.test(text) ? text : `Q. ${text}`, { size: 19, color: ACCENT, bold: true }), { tight: true });\n          answerPending = true;\n        } else {\n          html(paragraphHtml(text, { size: 19, bold: true }), { tight: true });\n        }\n      } else if (design === \"qna\" && answerPending) {\n        html(`<p><span style=\"color:${ACCENT}\">A.</span> ${escapeHtml(paragraph)}</p>`);\n        answerPending = false;\n      } else {\n        if (design === \"magazine\" && headingNumber === 1 && !pullQuote) pullQuote = firstSentence(paragraph);\n        html(paragraphHtml(paragraph, design === \"magazine\" ? { align: \"center\" } : {}));\n      }\n\n      // 소제목과 첫 문단 사이에는 사진을 두지 않는다 — 다음 문단 뒤로 넘긴다\n      const images = [...carried, ...slots[index + 1].map((item) => item.index)];\n      if (isHeading(paragraph) && index < paragraphs.length - 1) {\n        carried = images;\n      } else {\n        carried = [];\n        addImages(images);\n      }\n    });\n    addImages(carried);\n\n    if (firstHeadingIndex < 0) afterIntro();\n\n    // 글 끝: 디자인별 마무리\n    if (design === \"magazine\") {\n      if (pullQuote && !pullQuoteDone) html(quoteHtml(pullQuote));\n      html(\"<hr>\");\n      html(tableHtml(rows));\n    } else if (design === \"qna\") {\n      if (leadIndex < 0) html(tableHtml(rows));\n    } else if (design === \"news\") {\n      if (rows.length) {\n        html(paragraphHtml(noun === \"물건\" ? \"[물건 정보]\" : \"[매물 정보]\", { size: 17, bold: true }), { tight: true });\n        html(tableHtml(rows));\n      }\n    }\n\n    // 모든 디자인 공통: 매물 정보 출처 (표시·광고 필수 정보) + 고정 상세 링크 + 공실뉴스 서명\n    const source = sourceBlockLines(options.listing, url);\n    html(\"<hr>\");\n    html(paragraphHtml(`[${noun} 정보 출처]`, { size: 13, color: MUTED, bold: true }), { tight: true });\n    source.lines.forEach((line) => html(paragraphHtml(line, { size: 13, color: MUTED }), { tight: true }));\n    html(BLANK, { tight: true });\n    html(linkHtml(source.url, noun === \"물건\" ? \"▶ 공실뉴스 경매·공매 물건 상세 보기\" : \"▶ 공실뉴스 매물 상세 보기\"));\n    html(paragraphHtml(\"공실뉴스 · gongsilnews.com\", { size: 13, color: MUTED }));\n    flush();\n    return blocks;\n  }\n\n  /* 발행 창 태그 칸용: # 제거, 중복 제거, 네이버 최대 30개 */\n  function normalizeTags(keywords) {\n    const seen = new Set();\n    return (Array.isArray(keywords) ? keywords : [])\n      .map((keyword) => String(keyword || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n      .filter((keyword) => keyword && !seen.has(keyword) && seen.add(keyword))\n      .slice(0, 30);\n  }\n\n  const api = {\n    HOME_URL, WRITE_URL, isNaverBlogUrl, isLikelyWriteUrl, selectLikelyWriteTab,\n    splitParagraphs, layoutMediaSlots, buildNaverBlocks, normalizeTags,\n    DESIGNS, designHint, factRows, listingProblems, SITE_URL,\n    sourceBlockLines, listingUrl, // SNS 글 끝 출처·링크도 블로그와 같은 문구를 쓴다 (sns.js)\n  };\n  global.GWNaverBlog = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})(typeof globalThis !== \"undefined\" ? globalThis : self);\n",
 "interior/youtube-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   4 · 유튜브 대본 — AI 지시문\n\n   2번 초안 다듬기의 기사와 1번에서 가져온 물건 정보를 자료로 쓴다.\n   기사 프롬프트(prompt.js)와 분리해, 여기서 무엇을 바꿔도 기사 작성에는 영향이 없다.\n\n   일반 매물과 경매·공매 물건은 지시문이 다르다.\n   경매·공매 물건은 1번에서 가져올 때 saleKind(\"경매\"·\"공매\")가 붙어 오므로 그것으로 가른다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_YT_VIDEO_TYPE = {\n  listing: { label: \"매물 소개\", structure: \"훅 → 위치 → 핵심 조건 → 장점 → 확인할 점 → 마무리\" },\n  news: { label: \"부동산 뉴스\", structure: \"헤드라인 → 배경 → 핵심 사실 → 의미 → 확인할 점\" },\n  area: { label: \"지역 분석\", structure: \"지역 소개 → 교통 → 생활권 → 물건 조건 → 정리\" },\n};\n\n/* 경매·공매 물건 — 칩 자리(listing·news·area)는 같고 이름과 흐름이 다르다 */\nconst GW_YT_AUCTION_VIDEO_TYPE = {\n  listing: {\n    label: \"물건 소개\",\n    structure: \"훅 → 위치·물건 종류 → 가격(감정가·최저입찰가·유찰) → 입찰 일정·방법 → 입찰 전 확인할 점 → 마무리\",\n  },\n  news: {\n    label: \"경매 뉴스\",\n    structure: \"헤드라인 → 어떤 물건이 나왔나 → 가격과 유찰 → 이 조건이 뜻하는 것 → 입찰 전 확인할 점\",\n  },\n  area: {\n    label: \"지역 분석\",\n    structure: \"지역 소개 → 교통 → 생활권 → 물건 조건과 가격 → 입찰 일정 → 정리\",\n  },\n};\n\nconst GW_YT_DURATION = {\n  short: { label: \"60초 쇼츠\", seconds: 60, chars: \"약 280~380자\" },\n  medium: { label: \"약 2분\", seconds: 120, chars: \"약 600~850자\" },\n  long: { label: \"약 5분\", seconds: 300, chars: \"약 1,500~2,100자\" },\n};\n\nconst GW_YT_TONE = {\n  news: { label: \"뉴스형\", prompt: \"정확하고 신뢰감 있는 뉴스 앵커형\" },\n  friendly: { label: \"친근한 설명\", prompt: \"부드럽고 친근한 설명형 (존댓말)\" },\n  expert: { label: \"전문가 분석\", prompt: \"차분하고 논리적인 부동산 전문가 분석형\" },\n};\n\n/* 경매·공매 물건인가 */\nconst gwYtIsAuction = (vacancy) => Boolean(vacancy && vacancy.saleKind);\n\n/* 물건 종류에 맞는 콘텐츠 유형 표 */\nfunction gwYtVideoTypes(vacancy) {\n  if (typeof RM_YT_VIDEO_TYPE !== \"undefined\") return RM_YT_VIDEO_TYPE; // 인테리어 작성기\n  return gwYtIsAuction(vacancy) ? GW_YT_AUCTION_VIDEO_TYPE : GW_YT_VIDEO_TYPE;\n}\n\nfunction gwYtSourceText(source) {\n  const input = source || {};\n  const article = input.article || {};\n  const lines = [];\n  const push = (label, value) => {\n    const text = String(value == null ? \"\" : value).trim();\n    if (text) lines.push(`[${label}] ${text}`);\n  };\n  push(\"기사 제목\", article.title);\n  push(\"기사 부제\", Array.isArray(article.subtitles) ? article.subtitles.join(\" / \") : \"\");\n  push(\"기사 본문\", article.body);\n\n  const facts = input.vacancy && typeof gwFactLines === \"function\" ? gwFactLines(input.vacancy) : \"\";\n  return lines.join(\"\\n\") + (facts ? `\\n\\n[물건 정보 — 확인된 사실]\\n${facts}` : \"\");\n}\n\n/* ══════════════════════════════════════════════════════════════\n   대본 쓰기 — AI 는 읽을 원고 전체(완성 대본)만 쓴다\n   ══════════════════════════════════════════════════════════════ */\nconst GW_YT_SCRIPT_SHAPE = `\\`\\`\\`json\n{\n  \"title\": \"유튜브 제목\",\n  \"narration\": [\"읽을 원고 첫 문단\", \"둘째 문단\"]\n}\n\\`\\`\\``;\n\n/* 원고 모양·출력 형식 — 일반·경매 공통 */\nconst GW_YT_OUTPUT = `[출력 형식]\n설명이나 인사말 없이 아래 형식의 유효한 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- narration 은 문단별 문자열 배열입니다. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n\nfunction gwBuildYtScriptPrompt(source, settings) {\n  /* 인테리어 작성기: 결과표가 원자료다 */\n  if (source && source.remodel && typeof gwBuildRemodelYtPrompt === \"function\") return gwBuildRemodelYtPrompt(source, settings);\n  if (gwYtIsAuction(source && source.vacancy)) return gwBuildYtAuctionScriptPrompt(source, settings);\n  const s = settings || {};\n  const type = GW_YT_VIDEO_TYPE[s.videoType] || GW_YT_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 유튜브 대본 작가입니다.\n아래 공실뉴스 기사와 확인된 물건 정보만 사용해 ${type.label} 영상의 내레이션 원고를 작성하십시오.\n\n${gwYtSourceText(source)}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[보도 원칙]\n- \"공실뉴스에 이런 물건이 나왔다\"는 객관적인 소개입니다. 3인칭 전달체로 쓰십시오.\n- 권유·호객 표현을 쓰지 마십시오: \"지금 바로 문의하세요\", \"놓치지 마세요\", \"강력 추천\", \"지금이 기회\" 등.\n- 중개사무소 이름·전화번호를 원고에 넣지 마십시오.\n\n[사실 원칙]\n- 자료에 없는 가격·면적·주소·시세·수익률·교통 시간·개발 호재·인터뷰를 만들지 마십시오.\n- 숫자와 고유명사는 자료 그대로 쓰십시오.\n- 실제 사진으로 확인되지 않은 내부·외관을 사실처럼 단정하지 마십시오.\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 마지막은 핵심 조건과 확인할 점을 정리하고 \"자세한 내용은 공실뉴스에서 확인할 수 있습니다.\"로 맺습니다.\n\n${GW_YT_OUTPUT}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 물건 대본\n\n   기사(경매 기사 프롬프트)와 같은 원칙을 따른다.\n   - 가격·일정·번호는 자료 그대로. 지어내면 큰 사고다\n   - 경매·공매 제도의 일반 설명은 해도 되지만, 투자 권유·낙찰가 예측은 어디서도 하지 않는다\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildYtAuctionScriptPrompt(source, settings) {\n  const s = settings || {};\n  const type = GW_YT_AUCTION_VIDEO_TYPE[s.videoType] || GW_YT_AUCTION_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n  const vacancy = (source && source.vacancy) || {};\n  const saleKind = vacancy.saleKind === \"공매\" ? \"공매\" : \"경매\";\n  const saleName = saleKind === \"공매\" ? \"공매(온비드)\" : \"법원 경매\";\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경매·공매 담당 유튜브 대본 작가입니다.\n아래 공실뉴스 기사와 확인된 ${saleName} 물건 정보만 사용해 ${type.label} 영상의 내레이션 원고를 작성하십시오.\n\n${gwYtSourceText(source)}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[보도 원칙]\n- \"공실뉴스 공실열람에 이런 ${saleKind} 물건이 나왔다\"는 객관적인 소개입니다. 3인칭 전달체로 쓰십시오.\n- 투자 권유·호객 표현을 쓰지 마십시오: \"싸게 살 기회\", \"놓치지 마세요\", \"지금이 기회\", \"강력 추천\", \"수익이 기대된다\", \"반값에 잡으세요\" 등.\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호)를 넣지 마십시오.\n- \"본 정보는 참고용이며 법적 책임을 지지 않습니다\" 같은 입찰 전 법적 주의사항 안내문을 읽지 마십시오.\n\n[사실 원칙]\n- 감정가·최저입찰가·감정가 대비 비율·유찰 횟수·입찰 시작/마감·개찰일시·입찰보증금·면적·주소·사건번호(관리번호)·집행기관(관할법원)은 자료 그대로 쓰십시오.\n- 금액은 귀로 듣기 쉽게 억·만원 단위로 읽되(예: 2억 9,100만원) 자료의 숫자와 한 자리도 달라지면 안 됩니다.\n- 입찰 일정이 자료에 없으면 날짜를 만들지 마십시오.\n- 자료에 없는 권리관계·임차인·선순위 채권·체납액·건물 연식·낙찰 결과를 만들지 마십시오.\n- 낙찰가·낙찰가율·수익률·시세 상승을 예측하지 마십시오.\n- \"안전한 물건이다\", \"권리상 문제가 없다\", \"반드시 낙찰된다\" 같은 단정을 하지 마십시오.\n- 실제 사진으로 확인되지 않은 내부·외관을 사실처럼 단정하지 마십시오.\n\n[해설로 쓸 수 있는 것]\n- ${saleKind} 제도의 일반 설명은 한두 문장으로 짧게 넣어도 됩니다 — 유찰되면 최저입찰가가 낮아지는 구조, 입찰보증금, 개찰 절차, 명도의 의미 등.\n- ${saleKind} 물건을 볼 때 일반적으로 확인하는 점 — 현장 상태, 점유와 명도, 권리관계, 관리비 체납 같은 추가 비용.\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다. 지역·물건 종류와 함께 최저입찰가나 유찰 횟수처럼 자료에 있는 사실로 시작하십시오. 과장하지 마십시오.\n- 첫 부분에서 ${saleKind} 물건이라는 점, 소재지, 물건 종류, 감정가와 최저입찰가를 밝히십시오.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 마지막은 가격·일정 조건을 정리하고 \"권리관계와 물건 상태는 입찰 전 공고문과 현장에서 직접 확인할 필요가 있습니다. 자세한 내용은 공실뉴스 공실열람에서 확인할 수 있습니다.\"로 맺습니다.\n- title 은 [공실열람 ${saleKind}] 로 시작하고 지역·물건 종류·최저입찰가(또는 유찰 횟수)를 담으십시오.\n\n${GW_YT_OUTPUT}`;\n}\n\n/* 수정 요청 — 같은 대화에 이어 붙인다. 작업창에서 직접 고친 원고를 함께 보낸다. */\nfunction gwBuildYtRevisePrompt(full, request, vacancy) {\n  const current = {\n    title: full?.title || \"\",\n    narration: String(full?.text || \"\").split(/\\n{2,}/).map((p) => p.trim()).filter(Boolean),\n  };\n  const keep = gwYtIsAuction(vacancy)\n    ? `- 감정가·최저입찰가·유찰 횟수·입찰 일정·입찰보증금·면적·주소·사건번호(관리번호) 등 사실과 숫자는 바꾸거나 새로 만들지 마십시오.\n- 투자 권유, 낙찰가·수익 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문을 넣지 마십시오.`\n    : `- 기사와 물건 정보의 사실·숫자는 바꾸거나 새로 만들지 마십시오.\n- 권유·호객 표현과 중개사무소 연락처를 넣지 마십시오.`;\n  return `아래 현재 유튜브 원고를 요청대로 고쳐 주십시오.\n\n[수정 요청]\n${String(request || \"\").trim()}\n\n[현재 원고]\n${JSON.stringify(current, null, 2)}\n\n[지킬 것]\n${keep}\n- 읽을 문장만 쓰고, 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 원고 전체를 빠짐없이 다시 출력하십시오. 고친 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n}\n\n/* ── 원고 길이 — 한국어 내레이션은 1초에 약 5.5글자(공백 제외)로 읽는다고 본다 ── */\nconst GW_YT_CHARS_PER_SEC = 5.5;\n\nconst gwYtCharCount = (text) => String(text || \"\").replace(/\\s/g, \"\").length;\n\nfunction gwYtSpeechSeconds(text) {\n  return Math.round(gwYtCharCount(text) / GW_YT_CHARS_PER_SEC);\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_YT_VIDEO_TYPE,\n    GW_YT_AUCTION_VIDEO_TYPE,\n    GW_YT_DURATION,\n    GW_YT_TONE,\n    gwYtVideoTypes,\n    gwYtSourceText,\n    gwBuildYtScriptPrompt,\n    gwBuildYtAuctionScriptPrompt,\n    gwBuildYtRevisePrompt,\n    gwYtCharCount,\n    gwYtSpeechSeconds,\n  };\n}\n",
 "interior/youtube-json.js": "/* AI가 작성한 유튜브 장면 JSON 검증·정규화 */\n(() => {\n  \"use strict\";\n\n  function extract(raw) {\n    const text = String(raw || \"\").trim();\n    if (!text) return \"\";\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced?.[1]) return fenced[1].trim();\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first >= 0 && last > first ? text.slice(first, last + 1) : \"\";\n  }\n\n  function hasCompleteObject(raw) {\n    const text = String(raw || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n    for (let i = first; i < text.length; i += 1) {\n      const char = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (char === \"\\\\\") escaped = true;\n        else if (char === '\"') inString = false;\n        continue;\n      }\n      if (char === '\"') inString = true;\n      else if (char === \"{\") depth += 1;\n      else if (char === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n    return false;\n  }\n\n  function repair(raw) {\n    let output = \"\";\n    let inString = false;\n    let escaped = false;\n    for (let i = 0; i < raw.length; i += 1) {\n      const char = raw[i];\n      if (inString) {\n        if (escaped) {\n          output += char;\n          escaped = false;\n        } else if (char === \"\\\\\") {\n          output += char;\n          escaped = true;\n        } else if (char === '\"') {\n          output += char;\n          inString = false;\n        } else if (char === \"\\n\" || char === \"\\r\") {\n          if (char === \"\\r\" && raw[i + 1] === \"\\n\") i += 1;\n          output += \"\\\\n\";\n        } else if (char === \"\\t\") output += \"\\\\t\";\n        else output += char;\n        continue;\n      }\n      if (char === '\"') {\n        inString = true;\n        output += char;\n        continue;\n      }\n      if (char === \",\") {\n        let next = i + 1;\n        while (next < raw.length && /\\s/.test(raw[next])) next += 1;\n        if (raw[next] === \"}\" || raw[next] === \"]\") continue;\n      }\n      output += char;\n    }\n    return output;\n  }\n\n  function cleanText(value) {\n    return String(value == null ? \"\" : value).trim();\n  }\n\n  function normalizeScene(scene, index) {\n    if (!scene || typeof scene !== \"object\") return null;\n    const narration = cleanText(scene.narration || scene.script || scene.voiceover || scene.text);\n    const heading = cleanText(scene.heading || scene.title || `장면 ${index + 1}`);\n    const caption = cleanText(scene.caption || scene.subtitle || scene.onScreenText);\n    const visualPrompt = cleanText(scene.visualPrompt || scene.imagePrompt || scene.visual || scene.screen);\n    const visualType = cleanText(scene.visualType || scene.shotType || \"auto\");\n    if (!narration) return null;\n    return {\n      sceneId: cleanText(scene.sceneId),\n      heading,\n      narration,\n      caption,\n      visualType,\n      visualPrompt,\n    };\n  }\n\n  function normalize(data) {\n    if (!data || typeof data !== \"object\") return null;\n    const title = cleanText(data.title || data.videoTitle);\n    const description = cleanText(data.description || data.videoDescription);\n    const rawScenes = Array.isArray(data.scenes) ? data.scenes : [];\n    const scenes = rawScenes.map(normalizeScene).filter(Boolean);\n    if (!title || !scenes.length) return null;\n    return { title, description, scenes };\n  }\n\n  function parse(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    let data;\n    let repaired = false;\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repair(candidate));\n        repaired = true;\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n    const script = normalize(data);\n    if (!script) return { ok: false, reason: \"제목 또는 유효한 장면 대본이 없습니다.\" };\n    return { ok: true, script, repaired };\n  }\n\n  /* 모양을 따지지 않고 JSON 객체만 꺼낸다 — 완성 대본·장면 설명처럼 형식이 다른 답변에 쓴다 */\n  function parseObject(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    try {\n      return { ok: true, data: JSON.parse(candidate), repaired: false };\n    } catch (_strictError) {\n      try {\n        return { ok: true, data: JSON.parse(repair(candidate)), repaired: true };\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n  }\n\n  const api = { extract, hasCompleteObject, normalize, parse, parseObject };\n  globalThis.GWYoutubeJson = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})();\n\n",
 "interior/sns-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   3 · SNS 작성 — 페이스북 · 인스타그램 · 스레드\n\n   - AI 에 한 번 요청해 세 플랫폼 글을 함께 받는다 (무료 체험도 \"SNS\" 1번).\n   - 인테리어 작성기: 공사 후 모습·예상 비용은 AI 시뮬레이션 \"예측\"이다. 글에서 확정처럼 쓰지 않고,\n     글 끝에 \"AI 예측 이미지\" 안내를 코드가 붙인다. 예측 이미지(kind \"ai\")는 실제 사진으로 치지 않는다 (AI 레이블 안내).\n   - 블로그와 같은 객관 보도 원칙. 스레드만 말투를 대화체로.\n   - 링크·출처(표시·광고 필수 정보)·해시태그는 AI 가 아니라 코드가 붙인다 (gwSnsCompose).\n   - 사진은 2번 기사 사진을 플랫폼별로 다시 고르고 비율대로 자른다 (gwSnsPickMedia · sns.js).\n   기획: docs/2026-10-03_sns_writer_tabs_meeting.md\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_SNS_CHANNELS = {\n  facebook: {\n    label: \"페이스북\",\n    badge: \"Facebook\",\n    homeUrl: \"https://www.facebook.com/\",\n    ratio: 1, // 정사각 1:1\n    ratioText: \"정사각 1:1\",\n    size: [1080, 1080],\n    maxMedia: 10,\n    maxChars: 0, // 사실상 제한 없음\n    maxTags: 5,\n  },\n  instagram: {\n    label: \"인스타그램\",\n    badge: \"Instagram\",\n    homeUrl: \"https://www.instagram.com/\",\n    ratio: 4 / 5, // 세로 4:5\n    ratioText: \"세로 4:5\",\n    size: [1080, 1350],\n    maxMedia: 10,\n    maxChars: 2200,\n    maxTags: 30,\n  },\n  threads: {\n    label: \"스레드\",\n    badge: \"Threads\",\n    homeUrl: \"https://www.threads.com/\",\n    ratio: 0, // 원본 비율\n    ratioText: \"원본 비율\",\n    size: [1600, 1600],\n    maxMedia: 10,\n    maxChars: 500, // 글 하나마다\n    maxTags: 1,\n  },\n};\n\nconst GW_SNS_ORDER = [\"facebook\", \"instagram\", \"threads\"];\n\nfunction gwSnsNoun(vacancy) {\n  return vacancy && vacancy.saleKind ? \"물건\" : \"매물\";\n}\n\nfunction gwBuildSnsPrompt(source) {\n  const input = source || {};\n  const noun = gwSnsNoun(input.vacancy);\n  const auction = noun === \"물건\";\n\n  return `당신은 부동산 정보를 정확하게 전하는 공실뉴스의 SNS 에디터입니다.\n아래 공실뉴스 기사와 확인된 ${noun} 정보로 페이스북·인스타그램·스레드 글을 한 번에 작성하십시오.\n세 글은 같은 사실을 전하지만 플랫폼마다 모양이 다릅니다. 같은 문장을 돌려 쓰지 마십시오.\n\n[참조 기사]\n${gwBlogArticleText(input.article)}\n\n[확인된 ${noun} 정보]\n${gwBlogFactLines(input.vacancy)}\n\n[보도 원칙 — 세 플랫폼 공통, 가장 먼저 지킬 것]\n- \"공실뉴스에 이런 ${noun}이 나왔다\"는 객관적인 ${auction ? \"물건\" : \"매물\"} 소식입니다. 광고 문구가 아닙니다\n- 권유·호객·광고 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"연락 주세요\", \"DM 주세요\", \"놓치지 마세요\", \"급매\", \"지금이 기회\", \"역대급\" 등\n- 금액·면적·층·주소·관리비·입주일·주차·옵션 등 고유 조건은 위 두 자료에 실제로 있는 것만 쓸 것. 두 자료가 다르면 [확인된 ${noun} 정보]를 우선\n- 없는 수치·시세·수익률·개발 호재·현장 방문·고객 반응을 만들지 말 것. 자료에 없는 거리·도보 시간도 만들지 말 것\n- 소재지가 동까지만 공개됐다면 더 자세한 주소를 추측하지 말 것\n- 중개사무소 이름·연락처·링크·\"프로필 링크\" 안내는 쓰지 말 것 (글 끝에 자동으로 붙습니다)\n- 공사 후 모습·예상 공사비는 공실뉴스 인테리어 AI 시뮬레이션의 \"예측\"입니다. 확정된 결과처럼 쓰지 말고 \"예측\", \"예상\", \"시뮬레이션에 따르면\"으로 쓸 것\n- 시공 업체를 추천하거나 공사를 권하지 말 것\n\n[페이스북 — facebook]\n- 기사 소개형. 첫 문단 1~2문장이 피드에서 \"더 보기\" 전에 보이는 곳이므로 무엇이 어디에 어떤 조건으로 나왔는지 결론부터\n- 문단 3~5개, 문단마다 2~3문장, 전체 300~600자. 기사체 또는 부드러운 존댓말\n- 순서: 결론 → 위치·면적·금액 → 특징 → 주변 교통·생활 정보 → 확인할 점 한 문장\n- hashtags: 3~5개 (지역명·${noun} 종류 중심)\n\n[인스타그램 — instagram]\n- 사진이 주인공이고 글은 짧은 설명입니다. 한 줄에 정보 하나\n- lines 첫 줄: 25자 안팎의 훅 (지역 + ${noun} 핵심, 이모지 1개). 예: \"양재역 인근 36평 사무실 📍\"\n- 이어서 핵심 정보 3~5줄, 줄마다 알맞은 이모지 하나로 시작 (📍 위치 · 📐 면적 · 💰 금액 · 🚇 교통 · ✅ 특징 · 🏢 건물 등)\n- 마지막 1~2줄: 조건을 객관적으로 정리하는 한 문장\n- 전체 lines 6~10줄, 500자 이내\n- hashtags: 8~12개 (지역·동네·${noun} 종류·용도·거래 형태). 띄어쓰기 없이\n\n[스레드 — threads]\n- 말하듯 쓰는 짧은 글. 부드러운 존댓말 대화체(~네요, ~입니다)는 허용하되 사실 원칙은 같습니다\n- posts 첫 글: 450자 이내. 이것만 읽어도 무엇이 어디에 얼마로 나왔는지 알 수 있게\n- 첫 글은 독자의 생각을 묻는 질문 한 문장으로 끝낼 것 (예: \"이 조건이면 어떤 팀에 맞을까요?\"). 문의·연락을 유도하는 질문은 금지\n- 이어 쓰기 글 0~2개 (posts 둘째·셋째 항목): 교통·주변·확인할 점. 글마다 300자 이내\n- topic: 주제 태그 1개 (지역+${noun} 종류, 예: \"양재역사무실\")\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- 배열 한 항목에 문단(줄·글) 하나만 넣고, 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n- hashtags·topic 에는 # 기호를 넣지 마십시오. 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"facebook\": { \"paragraphs\": [\"첫 문단\", \"둘째 문단\"], \"hashtags\": [] },\n  \"instagram\": { \"lines\": [\"훅 한 줄\", \"📍 ...\"], \"hashtags\": [] },\n  \"threads\": { \"posts\": [\"첫 글\"], \"topic\": \"\" }\n}\n\\`\\`\\``;\n}\n\n/* 플랫폼 하나만 고친다 — 고친 플랫폼만 같은 JSON 모양으로 받는다 */\nfunction gwBuildSnsRevisePrompt(channel, request) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const shape = {\n    facebook: '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }',\n    instagram: '{ \"instagram\": { \"lines\": [], \"hashtags\": [] } }',\n    threads: '{ \"threads\": { \"posts\": [], \"topic\": \"\" } }',\n  }[channel] || '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }';\n  return `위에서 작성한 SNS 글 중 [${info.label}] 글만 아래 요청대로 고쳐 주십시오. 다른 플랫폼 글은 출력하지 마십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 금액·면적·층·주소 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 처음의 보도 원칙(권유·호객 표현 금지, 연락처·링크 쓰지 않기)과 ${info.label} 형식 규칙을 그대로 지키십시오.\n\n[출력 형식]\n설명 없이 아래 모양의 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n\\`\\`\\`json\n${shape}\n\\`\\`\\``;\n}\n\n/* ── AI 답변 → 편집용 모양 ──\n   facebook: { body: \"문단\\n\\n문단\", hashtags: [] }\n   instagram: { body: \"줄\\n줄\", hashtags: [] }\n   threads: { posts: [\"글\", …], topic: \"\" }\n   답변에 있는 플랫폼만 돌려준다 (수정 답변은 하나만 온다). */\nfunction gwSnsCleanTags(tags, max) {\n  const seen = new Set();\n  return (Array.isArray(tags) ? tags : String(tags || \"\").split(/[\\s,]+/))\n    .map((tag) => String(tag || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n    .filter((tag) => tag && !seen.has(tag) && seen.add(tag))\n    .slice(0, max || 30);\n}\n\nfunction gwSnsLines(value) {\n  return (Array.isArray(value) ? value : String(value || \"\").split(/\\n+/))\n    .map((line) => String(line == null ? \"\" : line).trim())\n    .filter(Boolean);\n}\n\nfunction gwSnsNormalize(data) {\n  if (!data || typeof data !== \"object\") return null;\n  const out = {};\n  const fb = data.facebook;\n  if (fb && typeof fb === \"object\") {\n    const paragraphs = gwSnsLines(fb.paragraphs || fb.text || fb.body);\n    if (paragraphs.length) out.facebook = { body: paragraphs.join(\"\\n\\n\"), hashtags: gwSnsCleanTags(fb.hashtags, GW_SNS_CHANNELS.facebook.maxTags) };\n  }\n  const ig = data.instagram;\n  if (ig && typeof ig === \"object\") {\n    const lines = gwSnsLines(ig.lines || ig.caption || ig.body);\n    if (lines.length) out.instagram = { body: lines.join(\"\\n\"), hashtags: gwSnsCleanTags(ig.hashtags, GW_SNS_CHANNELS.instagram.maxTags) };\n  }\n  const th = data.threads;\n  if (th && typeof th === \"object\") {\n    const posts = gwSnsLines(th.posts || th.text || th.body);\n    if (posts.length) out.threads = { posts, topic: gwSnsCleanTags([th.topic], 1)[0] || \"\" };\n  }\n  return Object.keys(out).length ? out : null;\n}\n\nfunction gwSnsParse(raw) {\n  const parsed = GWYoutubeJson.parseObject(raw); // ```json 상자 꺼내기·깨진 JSON 고치기는 유튜브와 같다\n  if (!parsed.ok) return parsed;\n  const posts = gwSnsNormalize(parsed.data);\n  if (!posts) return { ok: false, reason: \"페이스북·인스타그램·스레드 글을 찾지 못했습니다.\" };\n  return { ok: true, posts, repaired: parsed.repaired };\n}\n\n/* ── 글 끝에 붙는 것: 링크 · 출처(표시·광고 필수 정보) · 해시태그 ──\n   출처 문구는 블로그와 같다 (GWNaverBlog.sourceBlockLines). */\nfunction gwSnsSourceText(listing, noun) {\n  if (!listing) return \"\";\n  const { lines } = GWNaverBlog.sourceBlockLines(listing, \"\");\n  return [`[${noun} 정보 출처]`, ...lines].join(\"\\n\");\n}\n\n/* 글 끝에 늘 붙는 안내 — 예측 이미지를 실제 모습으로 오해하지 않게 */\nconst GW_SNS_SIM_NOTICE = \"※ 공사 후 모습은 공실뉴스 인테리어 AI 예측 이미지이며 실제와 다를 수 있습니다.\";\n\nfunction gwSnsCompose(channel, post, ctx) {\n  const c = ctx || {};\n  const notice = c.notice === undefined ? GW_SNS_SIM_NOTICE : c.notice;\n  /* 매물과 연결되지 않은 시뮬레이션 — \"매물\"이라고 하지 않는다 */\n  const linkLine = (u) => (c.noVacancy ? `▶ 공실뉴스에서 더 보기\\n${u}` : `▶ 공실뉴스에서 ${c.noun || \"매물\"} 자세히 보기\\n${u}`);\n  const noun = c.noun || \"매물\";\n  const url = c.url || \"\";\n  const source = gwSnsSourceText(c.listing, noun);\n  const tagLine = (tags) => (tags || []).map((tag) => `#${tag}`).join(\" \");\n\n  if (channel === \"threads\") {\n    const posts = (post?.posts || []).map((text) => String(text || \"\").trim()).filter(Boolean);\n    if (!posts.length) return { posts: [], text: \"\" };\n    if (post.topic) posts[0] = `${posts[0]}\\n\\n#${post.topic}`;\n    const tail = [notice, url ? linkLine(url) : \"\", source || c.credit || \"\"].filter(Boolean).join(\"\\n\\n\");\n    if (tail) {\n      const last = posts.length - 1;\n      if (posts[last].length + tail.length + 2 <= GW_SNS_CHANNELS.threads.maxChars) posts[last] = `${posts[last]}\\n\\n${tail}`;\n      else posts.push(tail);\n    }\n    return { posts, text: posts.join(\"\\n\\n―――\\n\\n\") };\n  }\n\n  const body = String(post?.body || \"\").trim();\n  if (!body) return { posts: [], text: \"\" };\n  const parts = [body];\n  if (channel === \"instagram\") {\n    /* 인스타 캡션의 링크는 눌리지 않는다 — 프로필 링크 안내를 먼저, 주소는 복사해 갈 수 있게 글자로 함께 */\n    const what = c.noVacancy ? \"자세한 내용은\" : `자세한 ${noun} 정보는`;\n    parts.push(url ? `${what} 프로필 링크 → 공실뉴스\\n${url}` : `${what} 프로필 링크 → 공실뉴스`);\n  } else if (url) {\n    parts.push(linkLine(url));\n  }\n  if (notice) parts.push(notice);\n  if (source) parts.push(source);\n  else if (c.credit) parts.push(c.credit);\n  const tags = tagLine(post.hashtags);\n  if (tags) parts.push(tags);\n  const text = parts.join(\"\\n\\n\");\n  return { posts: [text], text };\n}\n\n/* ── 사진 고르기: 2번 기사 사진 → 플랫폼별 순서·장수 ──\n   - 실제 사진(대표 먼저) → 공실목록 캡처(proof) → 지도·로드뷰 카드 → AI 이미지 순.\n   - 플랫폼 허용 장수(페이스북 4, 스레드 4, 인스타 10)까지 최대한 담고, 화면에서 직접 고르거나 뺄 수 있게 한다.\n   - 대표(1번)는 실제 사진이 있으면 반드시 실제 사진 — AI 이미지로 매물 사진을 대신하지 않는다. */\n/* 시뮬레이션 예측 이미지는 real 표시가 있어도 AI 가 그린 그림이다 — AI 레이블 안내·대표 규칙에서 AI 로 친다 */\nfunction gwSnsIsAi(item) {\n  return Boolean(item && item.kind === \"ai\");\n}\n\nfunction gwSnsPickMedia(channel, media) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const list = (Array.isArray(media) ? media : []).filter((item) => item && item.url);\n  const isCard = (item) => item.kind === \"map\" || item.kind === \"roadview\";\n  const isProof = (item) => item.kind === \"proof\";\n  const real = list.filter((item) => !gwSnsIsAi(item) && !isCard(item) && !isProof(item));\n  real.sort((a, b) => Number(Boolean(b.isCover)) - Number(Boolean(a.isCover)));\n  const proofs = list.filter(isProof);\n  const cards = list.filter(isCard);\n  const ai = list.filter(gwSnsIsAi);\n  return [...real, ...proofs, ...cards, ...ai]\n    .slice(0, info.maxMedia)\n    .map((item) => ({ url: item.url, kind: item.kind || \"photo\", caption: item.caption || \"\", ai: gwSnsIsAi(item) }));\n}\n\n/* 1번(대표) 자리에 AI 이미지를 둘 수 있는가 — 실제 사진이 하나라도 있으면 안 된다 */\nfunction gwSnsCanLead(list, index) {\n  const item = list && list[index];\n  if (!item || !item.ai) return true;\n  return !list.some((other) => other && !other.ai);\n}\n\n/* AI 이미지가 올라갈 사진에 섞여 있으면 \"게시할 때 AI 레이블을 켜세요\" 안내.\n   메타(페이스북·인스타·스레드)의 AI 레이블은 사진·영상용이라, 실제 사진만 올리면 켤 필요가 없다. */\nconst GW_SNS_AI_LABEL_WHERE = {\n  facebook: \"게시물 만들기 창의 이름 아래 [AI 레이블] 단추를 눌러 켜 주세요.\",\n  instagram: \"공유하기 전 캡션 화면의 [고급 설정]에서 [AI 레이블 추가]를 켜 주세요.\",\n  threads: \"게시하기 전 글쓰기 화면의 [AI 레이블] 설정을 켜 주세요.\",\n};\n\nfunction gwSnsAiLabelNote(channel, media) {\n  const info = GW_SNS_CHANNELS[channel];\n  if (!info) return \"\";\n  const count = (Array.isArray(media) ? media : []).slice(0, info.maxMedia).filter((item) => item && item.ai).length;\n  if (!count) return \"\";\n  return `AI로 만든 이미지 ${count}장이 들어 있습니다 — ${GW_SNS_AI_LABEL_WHERE[channel]}`;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_SNS_CHANNELS, GW_SNS_ORDER, gwBuildSnsPrompt, gwBuildSnsRevisePrompt,\n    GW_SNS_SIM_NOTICE, gwSnsNormalize, gwSnsParse, gwSnsCompose, gwSnsPickMedia, gwSnsCanLead, gwSnsCleanTags, gwSnsAiLabelNote,\n  };\n}\n",
 "remodel/remodel-spec.js": "/* ══════════════════════════════════════════════════════════════\n   건물 외관 리모델링 예측 시뮬레이터 — 설계 조건과 프롬프트\n\n   공실뉴스 웹 시뮬레이터(/marketing/remodeling)의 선택지와 프롬프트를\n   글자 그대로 옮겨 왔다. 문장을 고치면 웹 시뮬레이터와 결과가 달라지니\n   바꿀 때는 두 곳을 같이 본다.\n\n   웹 시뮬레이터와 다른 점은 둘뿐이다.\n   1) 웹은 API 의 responseSchema 로 JSON 형식을 넘겼다. 채팅 화면에는 그 방법이 없어\n      같은 스키마(필드 이름·설명 원문)를 글로 덧붙인다.\n   2) 웹은 외장재를 영어 id 로 넣었다. 다른 항목처럼 한국어 이름으로 넣는다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst RM_OPTIONS = {\n  materials: [\n    { id: \"stone\", name: \"석재 (화강암, 대리석)\" },\n    { id: \"ceramic\", name: \"세라믹 패널\" },\n    { id: \"metal\", name: \"메탈 패널 (알루미늄 복합)\" },\n    { id: \"low-e-glass\", name: \"로이유리 (커튼월)\" },\n    { id: \"brick\", name: \"벽돌 (고벽돌, 점토벽돌)\" },\n    { id: \"stucco\", name: \"스타코 / 스터코플렉스\" },\n    { id: \"wood\", name: \"목재 사이딩\" },\n  ],\n  windows: [\n    { id: \"aluminum-system\", name: \"알루미늄 시스템창호\" },\n    { id: \"pvc-double\", name: \"PVC 이중창\" },\n    { id: \"curtain-wall\", name: \"커튼월 (유리)\" },\n    { id: \"wood-frame\", name: \"목재 프레임 창호\" },\n    { id: \"project-window\", name: \"프로젝트 창\" },\n    { id: \"fixed-window\", name: \"픽스 창 (고정창)\" },\n  ],\n  colors: [\n    { id: \"monochrome\", name: \"모노크롬 (화이트, 그레이, 블랙)\" },\n    { id: \"neutral\", name: \"뉴트럴 (베이지, 아이보리)\" },\n    { id: \"warm-tone\", name: \"웜톤 (브라운, 테라코타)\" },\n    { id: \"cool-tone\", name: \"쿨톤 (블루, 그린 계열)\" },\n    { id: \"wood-accent\", name: \"목재 포인트\" },\n    { id: \"metallic-accent\", name: \"메탈릭 포인트\" },\n  ],\n  facade: [\n    { id: \"vertical-louver\", name: \"수직 루버/핀\" },\n    { id: \"horizontal-louver\", name: \"수평 루버/브리즈 레일\" },\n    { id: \"metal-mesh\", name: \"메탈 메쉬/확장망\" },\n    { id: \"3d-protrusion\", name: \"입체적 돌출/보이드\" },\n    { id: \"ground-floor-glass\", name: \"1층 전면 통유리\" },\n    { id: \"curved-design\", name: \"비정형/곡선 디자인\" },\n  ],\n  signage: [\n    { id: \"led-channel\", name: \"LED 채널 사인\" },\n    { id: \"backlit\", name: \"백라이트 사인\" },\n    { id: \"minimalist-lettering\", name: \"미니멀리즘 레터링\" },\n    { id: \"projecting-sign\", name: \"돌출/플래그 사인\" },\n    { id: \"neon-sign\", name: \"네온 사인\" },\n    { id: \"no-signage\", name: \"사인 없음\" },\n  ],\n  landscaping: [\n    { id: \"planter-box\", name: \"플랜터 박스\" },\n    { id: \"vertical-garden\", name: \"수직 정원/벽면 녹화\" },\n    { id: \"rooftop-garden\", name: \"옥상 정원\" },\n    { id: \"gravel-finish\", name: \"자갈/조약돌 마감\" },\n    { id: \"deck-terrace\", name: \"데크/테라스\" },\n    { id: \"no-landscaping\", name: \"조경 없음\" },\n  ],\n  lighting: [\n    { id: \"linear-lighting\", name: \"라인 조명 (윤곽 강조)\" },\n    { id: \"uplight-spotlight\", name: \"업라이트/스포트라이트\" },\n    { id: \"wall-sconce\", name: \"벽부등\" },\n    { id: \"eaves-indirect\", name: \"처마 간접 조명\" },\n    { id: \"recessed-light\", name: \"계단/바닥 매입등\" },\n    { id: \"no-lighting\", name: \"조명 계획 없음\" },\n  ],\n};\n\n/* 화면에 보이는 순서와 이름 — 웹 시뮬레이터 \"2. 설계 조건 입력\"과 같다 */\nconst RM_GROUPS = [\n  { key: \"materials\", label: \"주요 외장재\" },\n  { key: \"windows\", label: \"창호\" },\n  { key: \"colors\", label: \"색상\" },\n  { key: \"facade\", label: \"파사드 구성\" },\n  { key: \"signage\", label: \"간판/사인\" },\n  { key: \"landscaping\", label: \"조경\" },\n  { key: \"lighting\", label: \"조명\" },\n];\n\n/* 예측 이미지는 1장으로 고정한다 (웹 시뮬레이터는 1~5개). 한 장이면 결과표가 바로 나오고 기사 사진도 명확하다 */\nconst RM_VERSIONS = [1];\nconst RM_RATIOS = [\n  /* 원본과 같게 — 기본값. 세로로 긴 사진을 가로 비율로 강제하면 위층이 잘려 나간다 */\n  { id: \"original\", name: \"원본 (같은 구도)\" },\n  { id: \"1:1\", name: \"1:1 (정방형)\" },\n  { id: \"4:3\", name: \"4:3 (표준)\" },\n  { id: \"3:2\", name: \"3:2 (사진)\" },\n  { id: \"16:9\", name: \"16:9 (와이드)\" },\n];\n\n/* 웹 시뮬레이터의 처음 선택값 (id 로 둔다)\n   버전 수는 1개로 고정한다 — 이미지 한 장이면 결과표가 바로 나온다 (웹은 2개) */\nfunction rmDefaultDesign() {\n  return {\n    materials: [\"stone\"],\n    windows: [\"aluminum-system\", \"curtain-wall\"],\n    colors: [\"monochrome\", \"wood-accent\"],\n    facade: [\"vertical-louver\", \"ground-floor-glass\"],\n    signage: [\"backlit\"],\n    landscaping: [\"planter-box\"],\n    lighting: [\"linear-lighting\", \"uplight-spotlight\"],\n    versions: 1,\n    aspectRatio: \"original\",\n  };\n}\n\n/* 고른 id → 이름 목록 */\nfunction rmNames(key, ids) {\n  const list = RM_OPTIONS[key] || [];\n  return (ids || []).map((id) => (list.find((o) => o.id === id) || {}).name).filter(Boolean);\n}\n\n/* ── 프롬프트 1: 설계 지시서 (웹 시뮬레이터 원문) ── */\nfunction rmBuildSpecPrompt(design) {\n  const n = design || rmDefaultDesign();\n  const join = (key) => rmNames(key, n[key]).join(\", \");\n  return `\n    역할: 당신은 '건물 외관 리모델링 예측 시뮬레이터'의 프롬프트 엔지니어입니다.\n    목표: 사용자가 제공한 설계 조건을 바탕으로, 사실적인 \"예측 렌더\" 이미지를 생성하기 위한 상세한 지시사항과 요약 정보를 JSON 형식으로 생성합니다. 이 JSON의 모든 텍스트는 한국어로 작성되어야 하지만, 'imagePrompt'와 'versionDiffsEn' 필드만은 이미지 생성 모델의 성능을 위해 영어로 작성해야 합니다.\n\n    사용자 입력:\n    - 외장재: ${join(\"materials\")}\n    - 창호: ${join(\"windows\")}\n    - 색상: ${join(\"colors\")}\n    - 파사드 구성: ${join(\"facade\")}\n    - 간판/사인: ${join(\"signage\")}\n    - 조경: ${join(\"landscaping\")}\n    - 조명: ${join(\"lighting\")}\n    - 생성 버전 수: ${n.versions}\n\n    핵심 원칙 준수 (JSON 생성 시 이 원칙들을 반영해주세요):\n    - 구조 보존: 원본 건물의 구조벽, 층수, 창 위치 등은 유지.\n    - 현실성: 포토리얼리스틱 스타일, 과장된 CG/반사 금지. 수직/수평 라인 보정.\n    - 디테일: 재료 질감, 줄눈, 코너 디테일 반영.\n    - 맥락 유지: 주변 환경과 스케일감 약하게 유지.\n    - 개인정보 보호: 차량번호, 얼굴 등은 흐리게 처리.\n    - 텍스트 제한: 이미지 생성 프롬프트(imagePrompt) 작성 시, 간판이나 외벽에 한글 텍스트(Hangul)가 절대 포함되지 않도록 명시하세요. 텍스트가 필요한 경우 반드시 영문을 사용하도록 지시하세요.\n\n    출력 형식(JSON):\n    반드시 아래 스키마를 따르는 JSON 객체를 생성해주세요.\n\n${rmSpecSchemaText(n.versions)}\n\n    ※ imagePrompt 에는 카메라 위치·렌즈·시점·구도·화각(eye-level, tilt-shift, two-point perspective 등)을 쓰지 마십시오.\n      구도는 첨부할 원본 사진을 그대로 따르고, imagePrompt 는 외관의 재료·색·창호·조명·간판·조경만 설명하십시오.\n    ※ 이미지는 아직 만들지 말고, 위 JSON 객체 하나만 코드 블록으로 출력하십시오. 설명 문장은 덧붙이지 마십시오.`;\n}\n\n/* 웹 시뮬레이터가 responseSchema 로 넘기던 형식을 글로 적는다 (필드 설명 원문) */\nfunction rmSpecSchemaText(versions) {\n  return `{\n  \"imagePrompt\": \"string — Photorealistic architectural rendering of a remodeled building exterior. Key features include...\",\n  \"constraints\": \"string — 반드시 유지해야 할 구조, 모듈, 라인 등 제약 및 보존 규칙.\",\n  \"designSpec\": {\n    \"materials\": \"string — 선택된 핵심 외장재 요약.\",\n    \"colors\": \"string — 주요 색상 팔레트 요약.\",\n    \"windows\": \"string — 창호 프레임 및 스타일 요약.\",\n    \"signage\": \"string — 간판/사인 계획 요약.\",\n    \"lighting\": \"string — 조명 계획 요약.\",\n    \"landscaping\": \"string — 조경 요소 요약.\"\n  },\n  \"versionDiffsEn\": [\"string — 각 버전을 차별화할 핵심 변경사항 (재료, 색, 조명 전략 등)을 ${versions}개 항목으로 요약. 이 내용은 기본 imagePrompt에 추가되어 사용됩니다. (영어로 작성)\"],\n  \"versionDiffsKo\": [\"string — versionDiffsEn의 각 항목을 자연스러운 한국어로 번역한 내용. ${versions}개의 항목으로 요약. 이 내용은 사용자에게 표시됩니다. (한국어로 작성)\"],\n  \"disclaimer\": \"string — 결과물은 개념 시뮬레이션이며, 실제 시공, 구조 안전, 법규 적합을 보장하지 않는다는 내용의 주의 문구.\"\n}\n필수 필드: imagePrompt, constraints, designSpec, versionDiffsEn, versionDiffsKo, disclaimer`;\n}\n\n/* ── 프롬프트 2: 예측 이미지 (웹 시뮬레이터 원문 — 글자 하나 바꾸지 않는다) ──\n   웹은 ${imagePrompt}. Version-specific change: ${versionDiffsEn[i]} 를 INSTRUCTIONS 에 넣었다.\n\n   원문은 그대로 두고, 채팅 화면용 보충 문장은 원문 뒤에만 덧붙인다 (사장님 결정 2026-09-28).\n   - \"원본\" 비율을 고르면 원문의 ${aspectRatio} 자리에 \"the same as the source photo\" 를 넣는다 (값만 바뀌고 문장은 원문 그대로).\n   - 구도 유지 보충: Gemini 가 올려다본 원본을 눈높이로 다시 그려 위층이 잘린 일이 있어, 원문 뒤에 붙인다. */\nfunction rmBuildImagePrompt(spec, versionIndex, aspectRatio) {\n  const diff = (spec && spec.versionDiffsEn && spec.versionDiffsEn[versionIndex]) || \"Apply base design.\";\n  const t = `${(spec && spec.imagePrompt) || \"\"}. Version-specific change: ${diff}`;\n  const o = !aspectRatio || aspectRatio === \"original\" ? \"the same as the source photo\" : aspectRatio;\n  return `\n    **PRIMARY GOAL:** Generate a photorealistic architectural rendering of a remodeled building, based on the provided source image(s) and the following instructions.\n    \n    **INSTRUCTIONS:** ${t}.\n    \n    **CRITICAL RULES:**\n    1.  **Preserve Core Structure:** Strictly maintain the original building's structural walls, number of floors, floor heights, column spacing, and core locations from the source image.\n    2.  **Photorealism Only:** The output MUST be a high-fidelity, photorealistic image. Avoid any CG, cartoonish, or overly stylized looks. Reflections and glossiness must be realistic.\n    3.  **Correct Geometry:** Ensure all vertical and horizontal lines are perfectly straight. Correct any lens distortion from the source photo.\n    4.  **Contextual Integrity:** Keep the adjacent sidewalks, roads, and general scale of the surroundings, but ensure the remodeled building is the main focus.\n    5.  **Privacy Blurring:** Automatically blur any recognizable faces or vehicle license plates.\n    6.  **Aspect Ratio:** The final image aspect ratio must be exactly ${o}.\n    7.  **No Korean Text:** Do NOT render any Korean text (Hangul) in the image. If signage is required, use English text or abstract patterns only.\n    `.trim() + RM_IMAGE_APPENDIX;\n}\n\n/* 원문 뒤에 붙이는 채팅 화면용 보충 문장 — 원문 문장은 건드리지 않는다 */\nconst RM_IMAGE_APPENDIX = `\n\n[Additional note for this chat]\n- Use the attached photo(s) of the current building as the source and edit them: keep the same camera position, angle and framing as the source photo, and keep every floor of the building visible.\n- Generate the image now.`;\n\n/* ── AI 답변에서 설계 지시서 JSON 을 꺼낸다 ──\n   코드 블록·앞뒤 설명이 섞여도 첫 번째로 닫히는 { } 를 찾는다. 흔한 오류(끝 쉼표·둥근 따옴표)는 고쳐 본다. */\nfunction rmParseSpec(text) {\n  const raw = String(text || \"\");\n  const start = raw.indexOf(\"{\");\n  if (start < 0) return { ok: false, reason: \"AI 답변에서 JSON 을 찾지 못했습니다.\" };\n  let depth = 0, inStr = false, esc = false, end = -1;\n  for (let i = start; i < raw.length; i++) {\n    const c = raw[i];\n    if (inStr) {\n      if (esc) esc = false;\n      else if (c === \"\\\\\") esc = true;\n      else if (c === '\"') inStr = false;\n      continue;\n    }\n    if (c === '\"') inStr = true;\n    else if (c === \"{\") depth++;\n    else if (c === \"}\") { depth--; if (depth === 0) { end = i; break; } }\n  }\n  if (end < 0) return { ok: false, reason: \"AI 답변의 JSON 이 끝나지 않았습니다. 답변이 다 나온 뒤 다시 눌러 주세요.\" };\n  let body = raw.slice(start, end + 1);\n  let obj = null;\n  for (const fix of [\n    (s) => s,\n    (s) => s.replace(/[“”]/g, '\"').replace(/[‘’]/g, \"'\"),\n    (s) => s.replace(/[“”]/g, '\"').replace(/,\\s*([}\\]])/g, \"$1\"),\n  ]) {\n    try { obj = JSON.parse(fix(body)); break; } catch (_) { /* 다음 방법 */ }\n  }\n  if (!obj) return { ok: false, reason: \"AI 답변의 JSON 을 읽지 못했습니다. AI 탭에서 'JSON 형식으로 다시 출력해줘'라고 요청한 뒤 다시 눌러 주세요.\" };\n\n  const arr = (v) => (Array.isArray(v) ? v.map((x) => String(x || \"\").trim()).filter(Boolean) : []);\n  const spec = {\n    imagePrompt: String(obj.imagePrompt || \"\").trim(),\n    constraints: String(obj.constraints || \"\").trim(),\n    designSpec: obj.designSpec && typeof obj.designSpec === \"object\" ? obj.designSpec : {},\n    versionDiffsEn: arr(obj.versionDiffsEn),\n    versionDiffsKo: arr(obj.versionDiffsKo),\n    disclaimer: String(obj.disclaimer || \"\").trim(),\n  };\n  if (!spec.imagePrompt) return { ok: false, reason: \"지시서에 imagePrompt 가 없습니다. AI 탭에서 스키마대로 다시 출력해 달라고 요청해 주세요.\" };\n  return { ok: true, spec };\n}\n\n/* 결과표의 디자인 사양 이름 — 웹 시뮬레이터 tc 와 같다 */\nconst RM_SPEC_LABELS = {\n  materials: \"외장재\",\n  colors: \"색상\",\n  windows: \"창호\",\n  signage: \"간판/사인\",\n  lighting: \"조명\",\n  landscaping: \"조경\",\n};\n",
 "remodel/remodel-cost.js": "/* ══════════════════════════════════════════════════════════════\n   예상 공사비 — 단가표 × 외벽 면적\n\n   AI 에게 금액을 묻지 않는다. 그럴듯하지만 근거 없는 숫자가 나온다.\n   여기서 계산한 범위를 결과표에 싣고, 기사·블로그·유튜브는 이 숫자만 쓴다.\n\n   ⚠ 단가는 업계 일반 수준으로 잡은 초안이다(부가세·설계비·인허가 제외).\n     사장님이 확정하면 이 표만 고친다. 단위: 만 원.\n   ══════════════════════════════════════════════════════════════ */\n\nconst RM_COST_NOTICE = \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다.\";\n\nconst RM_UNIT = {\n  /* 외장재 — 만원/m² (창을 뺀 벽면에 적용) */\n  materials: {\n    \"stone\": [25, 40],\n    \"ceramic\": [20, 32],\n    \"metal\": [15, 25],\n    \"low-e-glass\": [45, 70],\n    \"brick\": [12, 20],\n    \"stucco\": [5, 9],\n    \"wood\": [12, 22],\n  },\n  /* 창호 — 만원/m² (창 면적에 적용) */\n  windows: {\n    \"aluminum-system\": [35, 55],\n    \"pvc-double\": [20, 30],\n    \"curtain-wall\": [45, 70],\n    \"wood-frame\": [40, 60],\n    \"project-window\": [30, 45],\n    \"fixed-window\": [25, 40],\n  },\n  /* 파사드 구성 — 만원/m² 추가 (외벽 전체) · ground-floor-glass 만 한 건당 */\n  facade: {\n    \"vertical-louver\": [4, 8],\n    \"horizontal-louver\": [4, 8],\n    \"metal-mesh\": [6, 12],\n    \"3d-protrusion\": [8, 15],\n    \"curved-design\": [10, 20],\n  },\n  facadeLump: {\n    \"ground-floor-glass\": [1500, 3500],\n  },\n  /* 간판/사인 — 한 건당 */\n  signage: {\n    \"led-channel\": [300, 800],\n    \"backlit\": [400, 1000],\n    \"minimalist-lettering\": [200, 600],\n    \"projecting-sign\": [150, 400],\n    \"neon-sign\": [200, 500],\n    \"no-signage\": [0, 0],\n  },\n  /* 조경 — 한 건당 */\n  landscaping: {\n    \"planter-box\": [200, 600],\n    \"vertical-garden\": [500, 1500],\n    \"rooftop-garden\": [800, 2500],\n    \"gravel-finish\": [100, 300],\n    \"deck-terrace\": [300, 1000],\n    \"no-landscaping\": [0, 0],\n  },\n  /* 조명 — 한 건당 */\n  lighting: {\n    \"linear-lighting\": [400, 1200],\n    \"uplight-spotlight\": [300, 800],\n    \"wall-sconce\": [150, 400],\n    \"eaves-indirect\": [300, 900],\n    \"recessed-light\": [150, 500],\n    \"no-lighting\": [0, 0],\n  },\n  /* 가설(비계)·철거·폐기물 — 위 합계의 비율 */\n  overhead: [0.15, 0.25],\n  /* 외벽 중 창이 차지하는 비율 */\n  windowRatio: 0.3,\n};\n\n/* 공사비 기준 입력의 처음 값 */\nfunction rmDefaultCostBase() {\n  return { width: 12, depth: 15, floors: 5, floorHeight: 3.3, faces: 1 };\n}\n\n/* 여러 개를 고르면 평균 단가 (한 건물에 섞어 쓰는 것으로 본다) */\nfunction rmAvg(table, ids) {\n  const hits = (ids || []).map((id) => table[id]).filter(Boolean);\n  if (!hits.length) return [0, 0];\n  const sum = hits.reduce((a, [lo, hi]) => [a[0] + lo, a[1] + hi], [0, 0]);\n  return [sum[0] / hits.length, sum[1] / hits.length];\n}\n\nfunction rmSum(table, ids) {\n  return (ids || []).map((id) => table[id]).filter(Boolean).reduce((a, [lo, hi]) => [a[0] + lo, a[1] + hi], [0, 0]);\n}\n\n/* 만 원 → \"1억 2,000만 원\" */\nfunction rmWon(man) {\n  const v = Math.round(Number(man) || 0);\n  if (v <= 0) return \"0원\";\n  const eok = Math.floor(v / 10000);\n  const rest = v % 10000;\n  if (eok && rest) return `${eok}억 ${rest.toLocaleString()}만 원`;\n  if (eok) return `${eok}억 원`;\n  return `${rest.toLocaleString()}만 원`;\n}\n\n/* 백만 원 단위로 반올림 (만 원 기준 100 단위) */\nconst rmRound = (man) => Math.round((Number(man) || 0) / 100) * 100;\n\n/* 고칠 면 — 정면은 가로, 측면은 세로 길이를 쓴다 */\nconst RM_FACES = {\n  1: { label: \"정면만\", len: (w, dp) => w },\n  2: { label: \"정면+측면 1면\", len: (w, dp) => w + dp },\n  3: { label: \"정면+측면 2면\", len: (w, dp) => w + dp * 2 },\n  4: { label: \"전체 4면\", len: (w, dp) => (w + dp) * 2 },\n};\n\n/* ── 계산 ──\n   base: { width 가로(정면 폭 m), depth 세로(측면 깊이 m), floors, floorHeight(m), faces 고칠 면 }  design: 설계 조건(id)\n   외벽 면적 = 고칠 면들의 길이 합 × (층수 × 층고) */\nfunction rmEstimateCost(base, design) {\n  const b = Object.assign(rmDefaultCostBase(), base || {});\n  const d = design || {};\n  const width = Math.max(0, Number(b.width) || 0);\n  const depth = Math.max(0, Number(b.depth) || 0);\n  const height = Math.max(0, (Number(b.floors) || 0) * (Number(b.floorHeight) || 0));\n  const faces = Math.min(4, Math.max(1, Number(b.faces) || 1));\n  const area = RM_FACES[faces].len(width, depth) * height;\n  const windowArea = area * RM_UNIT.windowRatio;\n  const wallArea = area - windowArea;\n\n  const items = [];\n  const push = (label, basis, [lo, hi]) => { if (hi > 0) items.push({ label, basis, min: lo, max: hi }); };\n\n  const mat = rmAvg(RM_UNIT.materials, d.materials);\n  push(\"외장재\", `${rmNames(\"materials\", d.materials).join(\", \") || \"-\"} · 벽면 ${Math.round(wallArea)}m²`, [mat[0] * wallArea, mat[1] * wallArea]);\n\n  const win = rmAvg(RM_UNIT.windows, d.windows);\n  push(\"창호\", `${rmNames(\"windows\", d.windows).join(\", \") || \"-\"} · 창 ${Math.round(windowArea)}m²`, [win[0] * windowArea, win[1] * windowArea]);\n\n  const fac = rmSum(RM_UNIT.facade, d.facade);\n  push(\"파사드 구성\", `${rmNames(\"facade\", (d.facade || []).filter((id) => RM_UNIT.facade[id])).join(\", \")} · 외벽 ${Math.round(area)}m²`, [fac[0] * area, fac[1] * area]);\n  const lump = rmSum(RM_UNIT.facadeLump, d.facade);\n  push(\"1층 전면 통유리\", \"한 건\", lump);\n\n  push(\"간판/사인\", rmNames(\"signage\", d.signage).join(\", \"), rmSum(RM_UNIT.signage, d.signage));\n  push(\"조경\", rmNames(\"landscaping\", d.landscaping).join(\", \"), rmSum(RM_UNIT.landscaping, d.landscaping));\n  push(\"조명\", rmNames(\"lighting\", d.lighting).join(\", \"), rmSum(RM_UNIT.lighting, d.lighting));\n\n  const sub = items.reduce((a, it) => [a[0] + it.min, a[1] + it.max], [0, 0]);\n  const [oLo, oHi] = RM_UNIT.overhead;\n  if (sub[1] > 0) {\n    items.push({ label: \"가설·철거·폐기물\", basis: `위 합계의 ${oLo * 100}~${oHi * 100}%`, min: sub[0] * oLo, max: sub[1] * oHi });\n  }\n\n  const total = items.reduce((a, it) => [a[0] + it.min, a[1] + it.max], [0, 0]);\n  const min = rmRound(total[0]);\n  const max = rmRound(total[1]);\n  return {\n    base: { width, depth, floors: Number(b.floors) || 0, floorHeight: Number(b.floorHeight) || 0, faces },\n    /* \"가로 12m × 세로 15m · 5층 × 층고 3.3m · 정면만\" — 결과표·기사가 같은 문장을 쓴다 */\n    basisText: `가로 ${width}m × 세로 ${depth}m · ${Number(b.floors) || 0}층 × 층고 ${Number(b.floorHeight) || 0}m · ${RM_FACES[faces].label}`,\n    area: Math.round(area),\n    windowArea: Math.round(windowArea),\n    items: items.map((it) => ({ ...it, min: rmRound(it.min), max: rmRound(it.max) })),\n    min,\n    max,\n    rangeText: `약 ${rmWon(min)} ~ ${rmWon(max)}`,\n    notice: RM_COST_NOTICE,\n    excludes: \"부가세·설계비·인허가·구조보강 비용 제외\",\n  };\n}\n\n/* 공실 매물 정보에서 층수를 꺼내 공사비 기준의 처음 값으로 쓴다 (\"5층 중 1층\" · \"지상 5층\" 등) */\nfunction rmFloorsFromVacancy(v) {\n  const text = [(v && v.fields) || []].flat().map((f) => `${f.label} ${f.value}`).join(\" \");\n  const m = text.match(/(?:총|지상)\\s*(\\d{1,2})\\s*층/) || text.match(/(\\d{1,2})\\s*층\\s*중/) || text.match(/\\/\\s*(\\d{1,2})\\s*층/);\n  const n = m ? Number(m[1]) : 0;\n  return n > 0 && n < 60 ? n : 0;\n}\n",
 "remodel/prompt.js": "/* ══════════════════════════════════════════════════════════════\n   공실뉴스 전용 프롬프트 — 기사 기본틀은 여기 한 곳에만 있다\n\n   일반 매물과 경매·공매 물건을 함께 쓴다. 경매·공매 물건은 서버에서 받을 때\n   saleKind(\"경매\"·\"공매\")가 붙어 오므로, 그것으로 어느 지시문을 쓸지 가른다.\n   ══════════════════════════════════════════════════════════════ */\n\n/* 경매·공매 물건인가 */\nfunction gwIsAuction(v) {\n  return Boolean(v && v.saleKind);\n}\n\n/* ── 매물 정보를 프롬프트에 넣을 줄로 만든다 ──\n   상세 표는 매물 종류마다 항목이 다르다. 그래서 정해진 목록을 쓰지 않고\n   화면에서 읽어온 것을 순서 그대로 전부 넘긴다.\n   값이 없는 항목은 아예 쓰지 않는다 — AI 가 빈칸을 상상하지 않도록. */\nfunction gwFactLines(v) {\n  const lines = [];\n  const seen = new Set();\n\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  if (gwIsAuction(v)) {\n    push(\"물건\", v.title);\n    push(\"가격 요약\", v.priceText);\n    for (const f of v.fields || []) push(f.label, f.value);\n    return lines.join(\"\\n\");\n  }\n\n  push(\"매물\", v.title);\n  push(\"금액\", v.priceText);\n  for (const f of v.fields || []) push(f.label, f.value);\n  push(\"특징\", Array.isArray(v.themes) ? v.themes.join(\" \") : v.themes);\n  push(\"주변환경\", v.infra);\n\n  return lines.join(\"\\n\");\n}\n\n/* 표에서 라벨로 값 하나 꺼내기 */\nfunction gwField(v, ...labels) {\n  for (const want of labels) {\n    const hit = (v.fields || []).find((f) => f.label === want);\n    if (hit) return hit.value;\n  }\n  return \"\";\n}\n\n/* 기사 본문에 넣을 매물 표기 이름 */\nfunction gwSubjectName(v) {\n  if (gwIsAuction(v)) {\n    return (\n      (v.title && v.title.trim()) ||\n      gwField(v, \"물건명\", \"소재지(지번)\", \"소재지\") ||\n      \"해당 물건\"\n    );\n  }\n  return (\n    (v.title && v.title.trim()) ||\n    gwField(v, \"단지명\", \"건물명\", \"소재지\") ||\n    \"해당 매물\"\n  );\n}\n\n/* ══════════════════════════════════════════════════════════════\n   수정 요청 — 같은 대화에 이어 붙인다\n\n   매물 정보를 다시 설명하지 않는다. AI 가 앞서 쓴 기사를 기억하고 있다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildRevisePrompt(request, vacancy) {\n  const keep = gwIsAuction(vacancy)\n    ? `- [물건 정보]에 있던 조건(감정가·최저입찰가·유찰 횟수·입찰 일정·면적·주소·관리번호)은 바꾸거나 새로 만들지 마십시오.\n- 투자 권유, 낙찰가·수익 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문은 넣지 마십시오.`\n    : \"- [매물 정보]에 있던 매물 조건(면적·금액·층·주소·번호)은 바꾸거나 새로 만들지 마십시오.\";\n  return `위에서 작성한 기사를 아래 요청대로 고쳐 주십시오.\n\n요청: ${request}\n\n[지킬 것]\n${keep}\n- 그 밖에는 요청하신 대로 자유롭게 고치십시오.\n  분량을 늘리라고 하면 실제로 그만큼 늘리십시오. 앞서 드린 분량 지시는 이 요청으로 대체됩니다.\n- 설명이나 인사말 없이, 고친 기사 전체를 처음과 똑같은 JSON 형식으로\n  \\`\\`\\`json 코드블록 하나에 다시 출력하십시오.\n- body는 문자열 하나가 아니라 문단별 문자열 배열입니다. 배열 항목 하나에 문단 하나만 넣으십시오.\n- 배열 항목 안에 실제 줄바꿈을 넣지 말고, 후행 쉼표 없이 JSON.parse가 가능한 유효한 JSON인지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"subtitle1\": \"\",\n  \"subtitle2\": \"\",\n  \"subtitle3\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   기사 이미지 만들기\n\n   기사 본문에 밀착한 장면을 요구하되, 작업창에서 스타일이나 기사 일부를\n   직접 지정할 수 있다. 입력이 없으면 AI 가 본문에서 핵심 장면을 고른다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_IMAGE_STYLE = {\n  news: {\n    label: \"보도 실사\",\n    prompt: \"한국 언론사의 현장 취재 사진처럼 자연스럽고 사실적인 장면. 과장 없는 담담한 조명과 구도.\",\n  },\n  building: {\n    label: \"건물 전경\",\n    prompt: \"건물의 전체 외관과 출입 동선이 잘 보이는 넓은 구도. 정면 또는 자연스러운 3/4 시점의 사실적인 건축 보도사진.\",\n  },\n  area: {\n    label: \"거리·상권\",\n    prompt: \"건물 하나보다 도로, 보행 환경, 주변 건물과 상권의 분위기가 함께 드러나는 넓은 현장 보도사진.\",\n  },\n  animation: {\n    label: \"애니메이션 일러스트\",\n    prompt: \"부동산 경제 기사에 어울리는 세련된 애니메이션풍 편집 일러스트. 특정 작품이나 작가의 화풍을 모방하지 말고 독창적으로 표현.\",\n  },\n  infographic: {\n    label: \"통계 도표·인포그래픽\",\n    prompt: \"경제 기사에 쓰는 깔끔한 데이터 인포그래픽. 확인된 숫자만 시각화하고, 비교 자료가 없으면 추세나 비교 그래프를 만들지 말고 핵심 수치 카드 형태로 구성.\",\n  },\n};\n\nfunction gwBuildImagePrompt(vacancy, article, opts) {\n  const o = opts || {};\n  const auction = gwIsAuction(vacancy);\n  const subject = vacancy ? gwSubjectName(vacancy) : \"해당 매물\";\n  const where = !vacancy ? \"\"\n    : auction ? gwField(vacancy, \"소재지(지번)\", \"소재지(도로명)\", \"소재지\")\n    : gwField(vacancy, \"소재지\");\n  const kind = !vacancy ? \"\"\n    : auction ? gwField(vacancy, \"물건종류\", \"용도분류\")\n    : gwField(vacancy, \"매물종류\", \"용도구분\", \"주용도\");\n  const style = GW_IMAGE_STYLE[o.style] || GW_IMAGE_STYLE.news;\n  const request = String(o.request || \"\").trim();\n  const customStyle = String(o.customStyle || \"\").trim().slice(0, 50); // 직접 입력한 화풍\n  const articleText = [article && article.title, article && article.body]\n    .filter(Boolean)\n    .join(\"\\n\")\n    .trim();\n  const focus = (request || articleText || subject).slice(0, 1600);\n  const noun = auction ? \"물건\" : \"매물\";\n  const facts = vacancy ? gwFactLines(vacancy) : `- 확인된 ${noun} 정보 없음`;\n  const focusRule = request\n    ? \"아래 입력이 기사 문장이면 그중 시각적으로 표현할 핵심 장면을 고르고, 연출 지시이면 그대로 반영하십시오.\"\n    : \"아래 기사 내용에서 가장 시각적으로 전달력이 높은 한 가지 핵심을 스스로 골라 장면으로 만드십시오.\";\n  /* 화풍을 직접 쓰면 글자 없는 그림으로 — 예전에 고른 통계 도표가 남아 글자가 들어가지 않게 */\n  const textRule = o.style === \"infographic\" && !customStyle\n    ? \"- 한글 문구는 꼭 필요한 짧은 항목명만 쓰고, 숫자와 단위는 아래 확인된 사실과 정확히 일치시킬 것\"\n    : \"- 이미지 안에 글자, 숫자, 로고, 워터마크를 넣지 말 것\";\n\n  return `위 기사에 넣을 이미지 1장을 만들어 주십시오.\n\n${customStyle\n    ? `[화풍·스타일] 사용자 직접 지정: \"${customStyle}\"\n- 이 화풍·그림체를 가장 먼저 지켜 표현하십시오.`\n    : `[선택한 스타일] ${style.label}\n${style.prompt}`}\n\n[이미지로 표현할 내용]\n${focusRule}\n${focus}\n\n[확인된 ${noun} 사실]\n${facts}\n\n[기본 장면 정보]\n- 대상: ${subject}${kind ? ` (${kind})` : \"\"}\n- 위치: ${where || \"대한민국 도심\"}\n- 기사 제목: ${(article && article.title) || \"\"}\n\n[조건]\n- ${o.ratio || \"가로 16:9\"} 비율\n- 위 확인된 사실에 없는 숫자, 통계, 건물명, 업체명, 시설을 만들지 말 것\n- 비교 수치나 증감률이 없으면 임의의 그래프, 비율, 순위를 만들지 말 것\n${textRule}\n- 사람 얼굴과 존재하지 않는 상호·간판 이름을 넣지 말 것\n- 사용자가 입력한 요청은 반영하되, 확인된 사실과 충돌하면 사실을 우선할 것\n\n이미지 1장만 출력하고 설명은 붙이지 마십시오.`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   분량과 기사 스타일 — 작업창에서 고른다\n\n   예전에는 \"600~900자\"가 코드에 박혀 있어, 사장님이 3,000자를 요청해도\n   먼저 준 지시가 이겼다. 이제 여기서 고른 것이 프롬프트로 간다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_LENGTH = {\n  short:  { label: \"짧게\",  chars: \"700~1,000자\",   paras: \"4~5개\",   sections: \"3~4개\" },\n  normal: { label: \"보통\",  chars: \"1,400~1,800자\", paras: \"7~9개\",   sections: \"5~6개\" },\n  long:   { label: \"길게\",  chars: \"2,800~3,500자\", paras: \"12~16개\", sections: \"7~9개\" },\n};\n\nconst GW_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief:\n      \"현재 방식처럼 도입부터 결론까지 문단이 자연스럽게 이어지는 뉴스 기사입니다. \" +\n      \"매물 조건과 지역·수요·계약 전 확인 사항을 기사 흐름 안에서 풀어 주십시오.\",\n    subs: \"1) 입지와 교통  2) 면적·구조  3) 거래 조건\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief:\n      \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 \" +\n      \"독자가 내용을 빠르게 훑어볼 수 있게 작성하십시오.\",\n    subs: \"1) 핵심 매물 조건  2) 입지와 수요  3) 계약 전 확인 사항\",\n  },\n};\n\n/* 경매·공매 물건일 때의 기사 스타일 — 이름은 같고 설명·부제 구성만 다르다 */\nconst GW_AUCTION_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief:\n      \"도입부터 결론까지 문단이 자연스럽게 이어지는 경매·공매 뉴스 기사입니다. \" +\n      \"가격 조건과 물건 현황, 지역, 입찰 일정과 입찰 전 확인할 점을 기사 흐름 안에서 풀어 주십시오.\",\n    subs: \"1) 가격 — 감정가·최저입찰가·유찰  2) 물건 현황과 입지  3) 입찰 일정·방법\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief:\n      \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 \" +\n      \"독자가 내용을 빠르게 훑어볼 수 있게 작성하십시오.\",\n    subs: \"1) 핵심 가격 조건  2) 물건 현황과 입지  3) 입찰 일정과 확인할 점\",\n  },\n};\n\n/* 소제목 기사 본문 규칙 — 일반·경매 공통 */\nfunction gwBodyStyle(o, len) {\n  return o.kind === \"summary\"\n    ? `- 첫 문단은 소제목 없이 기사 전체 핵심을 요약한 리드문으로 쓰십시오.\n- 그 다음부터는 반드시 \"■ 소제목\"을 한 줄에 단독으로 쓰고, 바로 다음 줄에 해당 내용을 설명하는 문단을 쓰십시오.\n- \"■ 소제목 + 설명 문단\" 묶음을 ${len.sections}로 구성하십시오.\n- 소제목 앞에는 정확히 ■ 기호 하나만 쓰십시오. ##, 번호, 불릿 목록, 굵은 글씨 표시는 쓰지 마십시오.`\n    : `- 일반 뉴스 기사처럼 도입부터 결론까지 자연스러운 문단으로 이어 쓰십시오.\n- 본문 중간에 소제목, ■ 기호, 번호, 불릿 목록을 넣지 마십시오.`;\n}\n\n/* 기사 JSON 출력 형식 — 일반·경매 공통 */\nconst GW_ARTICLE_OUTPUT = `[출력 형식]\n설명이나 인사말 없이, 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 반드시 JSON 배열이어야 하며, 각 문단과 \"■ 소제목\" 한 줄을 각각 별도 문자열 항목으로 넣으십시오.\n- 문자열 항목 안에 실제 줄바꿈을 넣지 마십시오. 문단 구분은 배열 항목으로만 표현하십시오.\n- 모든 문자열은 큰따옴표로 감싸고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한 유효한 JSON인지 괄호와 쉼표를 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"subtitle1\": \"\",\n  \"subtitle2\": \"\",\n  \"subtitle3\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n\n/* ══════════════════════════════════════════════════════════════\n   기사 작성 프롬프트\n\n   핵심은 두 구역을 가르는 것이다.\n   - 사실 구역: 표에 있는 것만. 지어내면 표시광고 문제가 된다\n   - 해설 구역: 기자가 아는 일반 지식으로 쓴다. 여기가 AI 를 쓰는 값어치다\n\n   전에는 둘 다 막아 놔서 AI 가 표를 문장으로 옮겨 적는 일밖에 못 했다.\n   경매·공매 물건은 아래 gwBuildAuctionPrompt 로 넘긴다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildPrompt(v, opts) {\n  if (gwIsAuction(v)) return gwBuildAuctionPrompt(v, opts);\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = GW_KIND[o.kind] || GW_KIND.news;\n  const facts = gwFactLines(v);\n  const subject = gwSubjectName(v);\n  const bodyStyle = gwBodyStyle(o, len);\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경제 담당 기자입니다.\n아래 매물을 소재로 기사 1건을 작성하십시오.\n\n[매물 정보 — 확인된 사실]\n${facts}\n\n════════ 두 구역을 구분해서 쓰십시오 ════════\n\n【사실 구역】 위 [매물 정보]에 적힌 것\n- 면적·금액·층수·방·주소·번호·관리비 등 이 매물의 조건은\n  한 글자도 바꾸거나 더하지 마십시오.\n- 위에 없는 항목(준공연도·옵션·주차 등)을 추측해 채우지 마십시오.\n  없으면 그 이야기를 아예 하지 마십시오.\n- 소재지가 시·군·동까지만 주어졌다면 기사도 거기까지만 쓰십시오.\n\n【해설 구역】 기자로서 쓰는 부분   ★ 기사 분량의 절반 이상을 여기에 쓰십시오\n당신이 아는 일반 지식으로 자유롭게 쓰십시오.\n- 이 지역이 어떤 곳인지 — 업무지구·학군·상권·교통의 성격, 동네 분위기\n- 위 조건들이 실제로 무엇을 뜻하는지 — 이 면적과 구조가 어떤 쓰임에 맞는지\n- 어떤 임차인·수요자에게 맞는 물건인지, 반대로 누구에게는 맞지 않는지\n- 이런 조건의 물건을 볼 때 계약 전 확인해야 할 점\n- 같은 종류의 물건을 고를 때 쓰는 일반적인 판단 기준\n\n해설 구역에서도 다음은 금지합니다.\n- 구체적 수치 예측 — \"3년 내 20% 상승\", \"수익률 6% 예상\"\n- 단정 — \"확실하다\", \"보장된다\", \"반드시 오른다\"\n- 이 매물의 스펙이나 가격을 지어내기\n- 실재하지 않는 단지명·업체명·기관명을 만들어 쓰기\n- 특정 시점의 시세 수치를 아는 것처럼 쓰기\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 【해설 구역】을 더 쓰십시오.\n  매물 스펙을 다시 늘어놓아 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했습니다\" 아닌 \"~했다\")\n- 매물은 \"${subject}\"로 지칭\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [공실열람 보도] 로 시작\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${kind.subs}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${bodyStyle}\n              마지막 문단은 \"자세한 내용은 공실뉴스 공실열람에서 확인할 수 있다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·매물종류·거래구분을 포함할 것\n\n${GW_ARTICLE_OUTPUT}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 기사 작성 프롬프트\n\n   두 구역을 가른다.\n   - 사실 구역: 서버에서 받은 물건 정보에 있는 것만. 가격·일정을 지어내면 큰 사고다\n   - 해설 구역: 경매·공매 제도와 지역에 대한 기자의 일반 지식\n   투자 권유·낙찰가 예측은 어느 구역에서도 쓰지 않는다.\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildAuctionPrompt(v, opts) {\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = GW_AUCTION_KIND[o.kind] || GW_AUCTION_KIND.news;\n  const facts = gwFactLines(v);\n  const subject = gwSubjectName(v);\n  const saleKind = v && v.saleKind === \"경매\" ? \"경매\" : \"공매\";\n  const saleName = saleKind === \"공매\" ? \"공매(온비드)\" : \"법원 경매\";\n  const bodyStyle = gwBodyStyle(o, len);\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경매·공매 담당 기자입니다.\n아래 ${saleName} 물건을 소재로 기사 1건을 작성하십시오.\n\n[물건 정보 — 확인된 사실]\n${facts}\n\n════════ 두 구역을 구분해서 쓰십시오 ════════\n\n【사실 구역】 위 [물건 정보]에 적힌 것\n- 감정가·최저입찰가·감정가 대비 비율·유찰 횟수·입찰 시작/마감·개찰일시·입찰보증금·면적·주소·관리번호(사건번호)·공고번호·집행기관은\n  한 글자도 바꾸거나 더하지 마십시오. 금액은 원 단위 숫자와 억·만원 표기가 일치해야 합니다.\n- 위에 없는 항목(권리관계·임차인·선순위 채권·체납액·건물 연식 등)을 추측해 채우지 마십시오.\n  없으면 그 이야기를 아예 하지 마십시오.\n- 소재지가 주어진 범위까지만 쓰십시오.\n- 입찰 일정이 없으면 날짜를 만들지 마십시오.\n\n【해설 구역】 기자로서 쓰는 부분   ★ 기사 분량의 절반 가까이를 여기에 쓰십시오\n당신이 아는 일반 지식으로 쓰십시오.\n- 이 지역이 어떤 곳인지 — 업무지구·학군·상권·교통의 성격\n- 이 물건 종류와 면적이 일반적으로 어떤 쓰임에 맞는지\n- ${saleKind} 제도의 일반 설명 — 유찰되면 최저입찰가가 어떻게 낮아지는지, 입찰보증금, 개찰 절차, 명도의 의미 등\n- ${saleKind} 물건을 볼 때 일반적으로 확인하는 점 — 현장 상태, 점유·명도, 권리관계, 추가 비용(관리비 체납 등)\n\n해설 구역에서도 다음은 금지합니다.\n- 투자 권유 — \"싸게 살 기회\", \"놓치지 말아야 할\", \"적극 추천\", \"수익이 기대된다\"\n- 낙찰가·낙찰가율·수익률·시세 상승 예측\n- 단정 — \"안전한 물건이다\", \"권리상 문제가 없다\", \"반드시 낙찰된다\"\n- 이 물건의 조건이나 가격을 지어내기\n- 실재하지 않는 단지명·업체명·기관명을 만들어 쓰기\n\n[넣지 말 것]\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호)\n- \"본 정보는 참고용 데이터이며… 법적 책임을 지지 않습니다\" 같은 입찰 전 법적 주의사항 안내문\n  (단, 마지막 문단의 한 줄 확인 문구는 아래 [구성]대로 넣으십시오)\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 【해설 구역】을 더 쓰십시오.\n  물건 정보를 다시 늘어놓아 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했습니다\" 아닌 \"~했다\")\n- 물건은 \"${subject}\"로 지칭\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [공실열람 ${saleKind}] 로 시작. 지역·물건 종류·최저입찰가(또는 유찰 횟수)를 담을 것\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${kind.subs}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${bodyStyle}\n              첫 문단에 ${saleKind} 구분, 소재지, 물건 종류, 감정가와 최저입찰가를 밝힐 것\n              마지막 문단은 \"권리관계와 물건 상태는 입찰 전 공고문과 현장에서 직접 확인할 필요가 있다. 자세한 내용은 공실뉴스 공실열람 경매/공매에서 확인할 수 있다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·물건 종류·\"${saleKind}\"를 포함할 것\n\n${GW_ARTICLE_OUTPUT}`;\n}\n",
 "remodel/remodel-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   리모델링 결과표 → 기사 · 블로그 · 유튜브 대본 지시문\n\n   원자료는 1 · 시뮬레이션의 결과표 하나다.\n   - 결과표에 있는 설계 조건·예측 모습·예상 공사비만 사실로 쓴다\n   - 공사비는 확장이 계산한 범위를 그대로 쓰고, AI 가 새 금액을 만들지 않는다\n   - \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다\" 를 반드시 넣는다\n   - 개념 시뮬레이션이다. 실제 공사 계획·확정된 사업처럼 쓰지 않는다\n\n   출력 JSON 형식은 기사 작성기와 같다 (article-json · 블로그 · youtube-json 이 그대로 읽는다).\n   ══════════════════════════════════════════════════════════════ */\n\n/* 결과표 → \"확인된 사실\" 글 */\nfunction rmResultFactLines(r) {\n  if (!r) return \"(결과표 없음)\";\n  const lines = [];\n  const seen = new Set(); // 같은 항목(예: 소재지)이 결과표와 매물 정보에 겹치면 한 번만\n  const push = (k, v) => {\n    const t = String(v == null ? \"\" : v).trim();\n    const key = `${k}:${t}`;\n    if (!t || seen.has(key)) return;\n    seen.add(key);\n    lines.push(`- ${k}: ${t}`);\n  };\n  if (rmIsListing(r)) {\n    lines.push(r.saleKind\n      ? `[공실뉴스 ${r.saleKind} 물건 정보 — 공실열람에 게재된 확인된 사실]`\n      : \"[공실뉴스 매물 정보 — 공실열람에 등록된 확인된 사실]\");\n    push(r.saleKind ? `${r.saleKind} 물건` : \"매물\", r.title);\n    push(\"소재지\", r.location);\n    push(\"금액\", r.priceText);\n    for (const f of (r.vacancyFacts || []).slice(0, 20)) push(f.label, f.value);\n    push(\"특징\", (r.themes || []).join(\" \"));\n    push(\"주변환경\", r.infra);\n  } else {\n    lines.push(\"[대상 건물 — 사용자가 직접 올린 사진 (공실 매물 아님)]\");\n    push(\"대상 건물\", r.title);\n    push(\"소재지\", r.location);\n  }\n  lines.push(\"\");\n  lines.push(\"[설계 조건 — 사용자가 고른 것]\");\n  for (const [label, names] of Object.entries(r.design || {})) push(label, (names || []).join(\", \"));\n  lines.push(\"\");\n  lines.push(\"[예측 결과 — AI 시뮬레이션]\");\n  const spec = r.designSpec || {};\n  for (const key of Object.keys(RM_SPEC_LABELS)) push(`디자인 사양 · ${RM_SPEC_LABELS[key]}`, spec[key]);\n  (r.versions || []).forEach((v) => push(`예측 버전 ${v.index}`, v.diffKo));\n  push(\"보존한 구조\", r.constraints);\n  lines.push(\"\");\n  const c = r.cost;\n  if (c) {\n    lines.push(\"[예상 공사비 — 공실뉴스 단가표로 계산한 개략 범위. 이 숫자만 쓸 것]\");\n    push(\"합계\", c.rangeText);\n    push(\"계산 기준\", `외벽 약 ${c.area}m² (${c.basisText}), 창 약 ${c.windowArea}m²`);\n    for (const it of c.items) push(`항목 · ${it.label}`, `${rmWon(it.min)} ~ ${rmWon(it.max)} (${it.basis || \"\"})`);\n    push(\"제외\", c.excludes);\n    push(\"필수 문구\", c.notice);\n  }\n  push(\"주의\", r.disclaimer);\n  return lines.join(\"\\n\");\n}\n\n/* 공실열람에서 가져온 매물인가 — 매물이면 \"이 가격에 나온 건물\" 이야기로 쓴다 */\nfunction rmIsListing(r) {\n  return Boolean(r && (r.vacancyId || r.priceText || (r.vacancyFacts || []).length));\n}\n\n/* 공실 매물일 때의 글 흐름 — 매물 보도로 열고 시뮬레이션으로 잇는다 */\nfunction rmStoryFlow(r) {\n  return rmIsListing(r)\n    ? `[글의 흐름 — 공실 매물]\n${r.saleKind\n    ? `① 첫 문단: 이 건물이 ${r.saleKind}로 나왔다는 것부터 연다 (소재지·건물 종류·감정가·최저입찰가)\n   예: \"서울 강남구 논현동 5층 건물이 ${r.saleKind}로 나왔다. 감정가 50억 원, 최저입찰가 40억 원이다.\"`\n    : `① 첫 문단: 공실뉴스(공실열람)에 이 건물이 어떤 조건으로 나왔는지 매물 보도로 연다 (소재지·건물 종류·거래 구분·금액)\n   예: \"공실뉴스 공실열람에 서울 강남구 논현동 5층 건물이 매매 50억 원에 나왔다.\"`}\n② 지금 건물의 조건 — 층수·면적·준공 연도·특징 등 [공실뉴스 매물 정보]에 있는 것\n③ 이 건물 외관을 [설계 조건]으로 바꾸면 어떤 모습이 예상되는지 — 시뮬레이션 결과\n④ 예상 공사비 — [예상 공사비]의 범위 그대로, 필수 문구와 함께\n⑤ 해설 — 주변환경에 맞는 디자인, 가치에 미칠 수 있는 영향, 리모델링과 신축 중 무엇을 검토할지, 확인할 점\n매물 금액과 예상 공사비는 각각 사실로 나란히 전하고, 둘을 더하거나 나눈 비율·총투자비를 계산하지 마십시오.`\n    : `[글의 흐름 — 직접 올린 사진]\n① 어떤 건물을 시뮬레이션했는지 ② 고른 설계 조건 ③ 예측된 모습 ④ 예상 공사비 ⑤ 해설과 확인할 점\n공실 매물이 아니므로 금액·매물 조건을 쓰지 마십시오.`;\n}\n\n/* 해설로 쓸 수 있는 것 / 없는 것 — 가능성은 쓰되 단정·수치는 쓰지 않는다 */\nconst RM_OPINION_RULES = `[해설 원칙 — 기자로서 판단을 쓰는 부분]\n쓸 수 있는 것 (반드시 \"~일 수 있다\", \"~를 검토해 볼 만하다\", \"~할 여지가 있다\" 같은 가능성 표현으로):\n- 주변환경(역세권·상권·주거지·학교 등)에 비추어 어떤 외관 디자인이 어울리거나 유리할 수 있는지\n  예: \"상권이 발달한 역세권이라 1층 통유리와 간판 계획이 임차인 모집에 도움이 될 수 있다\"\n- 외관 개선이 건물 인상·임차 수요·가치에 긍정적으로 작용할 여지가 있다는 점\n  예: \"노후한 외관을 바꾸면 건물 가치가 오를 여지가 있다\"\n- 준공 연도·층수·구조를 볼 때 외관 리모델링보다 신축(재건축)을 함께 검토해 볼 만한지\n  예: \"준공 30년이 넘은 저층 건물이라면 리모델링과 신축을 함께 비교해 볼 필요가 있다\"\n- 실제로 진행하려면 확인할 점 — 정밀 견적, 구조 안전 검토, 건축 인허가·용적률, 공사 중 임차인 영향\n쓸 수 없는 것:\n- 수치 전망: \"가치 20% 상승\", \"임대료 30% 인상\", \"수익률 ○%\", \"몇 년 안에 회수\"\n- 단정·보장: \"반드시\", \"확실히\", \"무조건 이득\", \"보장된다\"\n- 근거 없는 해설: [결과표]에 없는 주변 시설·개발 호재·시세를 지어내서 판단의 근거로 쓰기\n- 매수·투자 권유: \"지금 사야 한다\", \"놓치지 마라\"\n- 신축·리모델링 결론을 대신 내리기 — 두 방법을 비교할 점만 쓰고 결정은 \"전문가와 검토가 필요하다\"로 맺을 것`;\n\n/* 모든 글에 공통으로 박는 원칙 */\nconst RM_FACT_RULES = `[사실 원칙 — 가장 먼저 지킬 것]\n- 이 글의 소재는 \"외관 리모델링 예측 시뮬레이션\"입니다. 실제 공사 계획이나 확정된 사업이 아닙니다.\n  \"~로 바뀐다\", \"공사한다\"처럼 확정된 일로 쓰지 말고 \"~로 바꾸면 이런 모습이 예상된다\", \"시뮬레이션해 보니\"처럼 쓰십시오.\n- 설계 조건·예측 결과·공사비는 위 [결과표]에 있는 것만 쓰십시오. 없는 자재·공법·업체·일정을 만들지 마십시오.\n- 매물 금액·면적·층수 등 매물 조건은 [공실뉴스 매물 정보]에 있는 그대로 쓰십시오. 한 글자도 바꾸지 마십시오.\n- 공사비는 [예상 공사비]의 범위를 그대로 쓰고, 새 금액·평당 단가·수익률·임대료 상승폭을 만들지 마십시오.\n- 공사비를 말할 때는 반드시 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다\"라는 뜻을 함께 쓰십시오.\n- 건물 소재지·매물 조건은 [결과표]에 있는 범위까지만 쓰십시오. 더 상세한 주소를 추측하지 마십시오.\n- 구조 안전·인허가·실제 시공 가능 여부를 단정하지 마십시오. 필요하면 \"전문가 확인이 필요하다\"로 쓰십시오.\n- 중개사무소 이름·연락처·링크는 쓰지 마십시오.`;\n\n/* ═════════════ 기사 ═════════════ */\nconst RM_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief: \"도입부터 결론까지 문단이 자연스럽게 이어지는 뉴스 기사입니다. 아래 [글의 흐름] 순서대로 풀어 주십시오.\",\n    subs: \"1) 어떤 건물이 어떤 조건으로 나왔나  2) 외관을 바꾸면 어떤 모습인가  3) 예상 공사비와 검토할 점\",\n    subsPhoto: \"1) 어떤 건물을 시뮬레이션했나  2) 어떤 조건으로 바꾸면 어떤 모습인가  3) 예상 공사비와 확인할 점\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief: \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 독자가 빠르게 훑어볼 수 있게 쓰십시오. 소제목 순서는 아래 [글의 흐름]을 따르십시오.\",\n    subs: \"1) 매물 조건  2) 예측 외관의 특징  3) 예상 공사비와 검토할 점\",\n    subsPhoto: \"1) 대상 건물과 설계 조건  2) 예측 외관의 특징  3) 예상 공사비와 확인할 점\",\n  },\n};\n\nfunction gwBuildRemodelArticlePrompt(result, opts) {\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = RM_KIND[o.kind] || RM_KIND.news;\n  const listing = rmIsListing(result);\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 건축·부동산 담당 기자입니다.\n아래 결과표를 소재로 기사 1건을 작성하십시오.\n${listing\n    ? \"독자가 \\\"공실뉴스에 이 조건으로 나온 건물이, 외관을 이렇게 바꾸면 이런 모습이 되고 공사비는 대략 이 정도\\\"를 알 수 있게 씁니다.\"\n    : \"독자가 \\\"이 건물 외관을 이런 조건으로 바꾸면 이렇게 달라지고, 공사비는 대략 이 정도\\\"를 알 수 있게 씁니다.\"}\n\n[결과표 — 확인된 사실]\n${rmResultFactLines(result)}\n\n${RM_FACT_RULES}\n\n${rmStoryFlow(result)}\n\n${RM_OPINION_RULES}\n- 해설에는 고른 외장재·창호·파사드·조명의 일반적인 성격과 장단점(내구성·관리·단열·분위기)도 쓸 수 있습니다.\n- ★ 해설(⑤)에 기사 분량의 3분의 1 이상을 쓰십시오.\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 해설 구역을 더 쓰십시오. 결과표 항목을 되풀이해 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 경제 기사체 (\"~했다\", \"~로 예상된다\")\n- 과장 광고 표현을 쓰지 마십시오\n\n[구성]\n- title     : 25~45자. 대괄호 말머리 [리모델링 시뮬레이션] 으로 시작${listing ? \"\\n              지역·건물 종류·금액을 넣을 것 (예: [리모델링 시뮬레이션] 논현동 5층 건물 50억 매물, 외관 바꾸면)\" : \"\"}\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것\n              ${listing ? kind.subs : kind.subsPhoto}\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${gwBodyStyle(o, len)}\n              공사비 문단에는 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요하다\"는 문장을 넣을 것\n              마지막 문단은 \"이번 결과는 공실뉴스 리모델링 예측 시뮬레이션으로 만든 개념 이미지로, 실제 시공 전에는 전문가의 정밀 검토가 필요하다.\"로 맺을 것\n- keywords  : 5~8개. # 없이 낱말만. 지역명·건물 종류·리모델링·주요 외장재를 포함할 것${listing ? \"·거래 구분\" : \"\"}\n\n${GW_ARTICLE_OUTPUT}`;\n}\n\n/* ═════════════ 블로그 ═════════════\n   칩 자리(listing·visit·story·report·consult·shortform)는 기사 작성기와 같고 뜻만 리모델링용이다. */\nconst RM_BLOG_STYLE = {\n  listing: {\n    label: \"리모델링 소개형\", fit: \"모든 건물\", design: \"basic\",\n    titleExample: \"논현동 5층 건물, 외관을 바꾸면 이렇게 달라진다\",\n    guide: \"깔끔하고 정보 중심으로 쓴다. 첫 문단에서 어떤 건물을 어떤 조건으로 시뮬레이션했는지 밝히고, 예측 모습과 공사비를 정리한다.\",\n    structure: \"소제목 3~4개 (예: ■ 지금 외관 / ■ 고른 설계 조건 / ■ 예측된 모습 / ■ 예상 공사비와 확인할 점)\",\n  },\n  visit: {\n    label: \"전·후 비교형\", fit: \"상가·빌딩\", design: \"magazine\",\n    titleExample: \"낡은 외벽이 석재·통유리로… 전후를 비교해 보니\",\n    guide: \"현재 외관과 예측 외관을 부분별로 나란히 비교한다(외벽·창호·1층·간판·조명). 실제 공사를 한 것처럼 쓰지 않는다.\",\n    structure: \"소제목 4~5개, 부분별 비교 (예: ■ 외벽 / ■ 창호 / ■ 1층과 간판 / ■ 밤의 모습 / ■ 예상 공사비)\",\n  },\n  story: {\n    label: \"스토리텔링형\", fit: \"노후 건물\", design: \"magazine\",\n    titleExample: \"20년 된 건물, 외관만 바꾸면 달라질까?\",\n    guide: \"질문이나 상황으로 시작해 시뮬레이션 과정을 따라가듯 풀어 쓴다. 인물·사례를 지어내지 않는다.\",\n    structure: \"소제목 3~4개 (예: ■ 질문 하나 / ■ 조건을 골라 보니 / ■ 달라진 모습 / ■ 비용과 현실)\",\n  },\n  report: {\n    label: \"공사비 분석형\", fit: \"투자·임대 건물\", design: \"news\",\n    titleExample: \"외관 리모델링, 항목별로 얼마나 들까\",\n    guide: \"예상 공사비를 항목별로 풀어 설명한다. 결과표의 계산 기준과 범위만 쓰고, 새 금액·수익률을 만들지 않는다.\",\n    structure: \"소제목 4~5개 (예: ■ 계산 기준 / ■ 외장재·창호 / ■ 파사드·간판·조명 / ■ 부대비용 / ■ 확인할 점)\",\n  },\n  consult: {\n    label: \"친근한 해설형\", fit: \"건물주\", design: \"qna\",\n    titleExample: \"석재와 메탈 패널, 무엇이 다를까\",\n    guide: \"고른 자재·창호·조명을 쉬운 말로 풀어 설명한다. 부드러운 존댓말(~습니다)을 쓰되 권유 표현은 쓰지 않는다.\",\n    structure: \"소제목 3~5개, 질문형 (예: ■ 이 외장재는 어떤 재료일까 / ■ 창호를 바꾸면 무엇이 달라질까 / ■ 비용은)\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\", fit: \"SNS 연계\", design: \"news\",\n    titleExample: \"[리모델링] 논현동 5층 건물 외관 예측 공개\",\n    guide: \"짧은 문장으로 사실만 빠르게 전한다.\",\n    structure: \"소제목 2~3개, 짧게 (예: ■ 무엇을 바꿨나 / ■ 얼마나 드나)\",\n  },\n};\n\nfunction gwBuildRemodelBlogPrompt(source, opts) {\n  const o = opts || {};\n  const style = RM_BLOG_STYLE[o.style] || RM_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = (source && source.article) || {};\n  return `당신은 부동산·건축 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 리모델링 시뮬레이션 결과표와 공실뉴스 기사를 참고해 블로그 초안 1건을 작성하십시오.\n\n[결과표 — 확인된 사실]\n${rmResultFactLines(source && source.remodel)}\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n${RM_FACT_RULES}\n\n${rmStoryFlow(source && source.remodel)}\n선택한 스타일에 맞게 순서와 비중은 조절해도 되지만, 공실 매물이면 첫 문단은 반드시 매물 보도(①)로 여십시오.\n\n${RM_OPINION_RULES}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 건물: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n\n[보도 원칙]\n- 이 글은 ${rmIsListing(source && source.remodel)\n    ? \"\\\"공실뉴스에 이런 매물이 나왔고, 외관을 바꾸면 이런 모습이 예상된다\\\"는 객관적인 보도입니다. 중개사무소 정보는 본문에 쓰지 말고 글 끝 출처에 맡기십시오\"\n    : \"\\\"공실뉴스 리모델링 예측 시뮬레이션으로 이 건물 외관을 바꿔 보니\\\"라는 객관적인 소개입니다\"}. 3인칭 전달체로 쓰십시오.\n- 첫 문단에서 ${rmIsListing(source && source.remodel) ? \"소재지·건물 종류·거래 구분·금액과, 외관 시뮬레이션을 해 봤다는 점\" : \"대상 건물(소재지·종류)과 시뮬레이션이라는 점\"}을 밝히십시오.\n- 권유·호객 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"지금이 기회\" 등.\n\n[블로그 구성]\n- title: 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 한 문단을 2~4문장으로 짧게. 첫 문단은 2문장 이내의 핵심 요약\n- 소제목은 한 줄짜리 독립 문단으로 쓰고 반드시 \"■ \"로 시작할 것. 소제목 바로 다음에는 본문 문단이 올 것\n- 공사비를 다룬 문단에 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다\"를 넣을 것\n- 마지막 문단은 시뮬레이션 결과와 확인할 점(정밀 견적·구조 검토·인허가)을 객관적으로 정리할 것\n- 기사 문장을 그대로 길게 복사하지 말 것\n- keywords: 지역명·건물 종류·리모델링·외장재를 포함한 검색용 핵심어 7~12개. # 제외\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ═════════════ 유튜브 ═════════════ */\nconst RM_YT_VIDEO_TYPE = {\n  listing: { label: \"리모델링 소개\", structure: \"훅(전·후 한 문장) → 대상 건물 → 고른 조건 → 예측 모습 → 예상 공사비 → 확인할 점 → 마무리\" },\n  news: { label: \"전·후 비교\", structure: \"헤드라인 → 지금 외관 → 외벽·창호·1층·조명 부분별 비교 → 예상 공사비 → 정리\" },\n  area: { label: \"공사비 분석\", structure: \"질문 훅(얼마나 들까) → 계산 기준 → 항목별 공사비 → 부대비용 → 확인할 점 → 정리\" },\n};\n\nfunction gwBuildRemodelYtPrompt(source, settings) {\n  const s = settings || {};\n  const type = RM_YT_VIDEO_TYPE[s.videoType] || RM_YT_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n  const article = (source && source.article) || {};\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 유튜브 대본 작가입니다.\n아래 리모델링 시뮬레이션 결과표와 공실뉴스 기사만 사용해 \"${type.label}\" 영상의 내레이션 원고를 작성하십시오.\n\n[결과표 — 확인된 사실]\n${rmResultFactLines(source && source.remodel)}\n\n[참조 기사]\n[기사 제목] ${article.title || \"\"}\n[기사 본문] ${article.body || \"\"}\n\n${RM_FACT_RULES}\n\n${RM_OPINION_RULES}\n${rmIsListing(source && source.remodel)\n    ? \"- 공실 매물이므로 원고 앞부분(훅 다음)에서 소재지·건물 종류·거래 구분·금액을 밝히고, 그다음 외관 시뮬레이션으로 넘어가십시오. 중개사무소 이름·전화번호는 원고에 넣지 마십시오.\"\n    : \"- 공실 매물이 아니므로 금액·매물 조건을 말하지 마십시오.\"}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 공사비를 말한 뒤에는 \"대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다.\"를 읽으십시오.\n- 마지막은 \"이번 결과는 리모델링 예측 시뮬레이션입니다. 자세한 내용은 공실뉴스에서 확인할 수 있습니다.\"로 맺습니다.\n\n${GW_YT_OUTPUT}`;\n}\n",
 "remodel/article-json.js": "/* ══════════════════════════════════════════════════════════════\n   AI 기사 JSON 읽기\n\n   새 형식은 body 를 문단 배열로 받는다. 긴 본문을 JSON 문자열 하나에 넣을 때\n   생기는 줄바꿈·괄호 오류를 피하기 위해서다. 예전 문자열 형식도 계속 받으며,\n   AI 가 흔히 만드는 원시 줄바꿈·후행 쉼표·body 닫기 괄호 오류는 안전하게\n   복구한다. eval 은 사용하지 않는다.\n   ══════════════════════════════════════════════════════════════ */\n(() => {\n  \"use strict\";\n\n  function extractCandidate(rawText) {\n    const text = String(rawText || \"\").trim();\n    if (!text) return \"\";\n\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced && fenced[1]) return fenced[1].trim();\n\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first !== -1 && last > first ? text.slice(first, last + 1).trim() : \"\";\n  }\n\n  function hasCompleteObject(rawText) {\n    const text = String(rawText || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n\n    for (let i = first; i < text.length; i += 1) {\n      const ch = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') inString = true;\n      else if (ch === \"{\") depth += 1;\n      else if (ch === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n\n    return false;\n  }\n\n  function escapeRawControlsInStrings(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n\n      if (inString) {\n        if (escaped) {\n          out += ch;\n          escaped = false;\n        } else if (ch === \"\\\\\") {\n          out += ch;\n          escaped = true;\n        } else if (ch === '\"') {\n          out += ch;\n          inString = false;\n        } else if (ch === \"\\n\") {\n          out += \"\\\\n\";\n        } else if (ch === \"\\r\") {\n          if (input[i + 1] === \"\\n\") i += 1;\n          out += \"\\\\n\";\n        } else if (ch === \"\\t\") {\n          out += \"\\\\t\";\n        } else {\n          out += ch;\n        }\n      } else {\n        out += ch;\n        if (ch === '\"') inString = true;\n      }\n    }\n\n    return out;\n  }\n\n  function stripTrailingCommas(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n      if (inString) {\n        out += ch;\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') {\n        inString = true;\n        out += ch;\n        continue;\n      }\n\n      if (ch === \",\") {\n        let next = i + 1;\n        while (next < input.length && /\\s/.test(input[next])) next += 1;\n        if (input[next] === \"}\" || input[next] === \"]\") continue;\n      }\n\n      out += ch;\n    }\n\n    return out;\n  }\n\n  function repairCommonJson(candidate) {\n    return stripTrailingCommas(escapeRawControlsInStrings(candidate));\n  }\n\n  function keyMatch(input, key, fromIndex = 0) {\n    const escapedKey = key.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n    const regex = new RegExp(`\"${escapedKey}\"\\\\s*:`, \"g\");\n    regex.lastIndex = fromIndex;\n    return regex.exec(input);\n  }\n\n  function extractSection(input, key, nextKeys) {\n    const current = keyMatch(input, key);\n    if (!current) return \"\";\n\n    const start = current.index + current[0].length;\n    let end = input.length;\n    for (const nextKey of nextKeys || []) {\n      const next = keyMatch(input, nextKey, start);\n      if (next && next.index < end) end = next.index;\n    }\n\n    let section = input.slice(start, end).trim();\n    section = section.replace(/,\\s*$/, \"\").trim();\n    return section;\n  }\n\n  function manualUnquote(value) {\n    let text = String(value || \"\").trim();\n    while (text.startsWith('\"') && /[}\\]]$/.test(text)) {\n      text = text.slice(0, -1).trim();\n    }\n    if (text.startsWith('\"')) text = text.slice(1);\n    if (text.endsWith('\"')) text = text.slice(0, -1);\n\n    return text\n      .replace(/\\\\r\\\\n/g, \"\\n\")\n      .replace(/\\\\n/g, \"\\n\")\n      .replace(/\\\\t/g, \"\\t\")\n      .replace(/\\\\\"/g, '\"')\n      .replace(/\\\\\\\\/g, \"\\\\\")\n      .trim();\n  }\n\n  function parseLooseValue(section) {\n    let value = String(section || \"\").trim().replace(/,\\s*$/, \"\").trim();\n    if (!value) return \"\";\n\n    /* 스크린샷처럼 문자열 body 뒤에 잘못 붙은 ] 를 제거한다. */\n    if (value.startsWith('\"')) {\n      while (value.endsWith(\"]\")) value = value.slice(0, -1).trim();\n    }\n\n    const attempts = [value, repairCommonJson(value)];\n    if (value.startsWith(\"[\") && !value.endsWith(\"]\")) {\n      attempts.push(repairCommonJson(value + \"]\"));\n    }\n\n    for (const attempt of attempts) {\n      try {\n        return JSON.parse(attempt);\n      } catch (_error) {\n        /* 다음 안전한 복구를 시도한다. */\n      }\n    }\n\n    if (value.startsWith(\"[\")) {\n      const strings = [];\n      const regex = /\"((?:\\\\.|[^\"\\\\])*)\"/g;\n      let match;\n      while ((match = regex.exec(value))) strings.push(manualUnquote(`\"${match[1]}\"`));\n      if (strings.length) return strings;\n    }\n\n    return manualUnquote(value);\n  }\n\n  function normalizeBody(value) {\n    if (Array.isArray(value)) {\n      return value\n        .map((item) => {\n          if (typeof item === \"string\") return item.trim();\n          if (item && typeof item === \"object\") {\n            return String(item.text || item.content || item.paragraph || \"\").trim();\n          }\n          return \"\";\n        })\n        .filter(Boolean)\n        .join(\"\\n\\n\");\n    }\n\n    if (value && typeof value === \"object\") {\n      return normalizeBody(value.paragraphs || value.body || value.content || value.text || \"\");\n    }\n\n    return typeof value === \"string\" ? value.trim() : \"\";\n  }\n\n  function normalizeArticle(data) {\n    if (!data || typeof data !== \"object\") return null;\n\n    const title = String(data.title || \"\").trim();\n    const subtitleValues = Array.isArray(data.subtitles)\n      ? data.subtitles\n      : [data.subtitle1, data.subtitle2, data.subtitle3];\n    const subtitles = subtitleValues\n      .map((value) => String(value || \"\").trim())\n      .filter(Boolean)\n      .slice(0, 3);\n    const body = normalizeBody(data.body || data.paragraphs || data.content || \"\");\n    const rawKeywords = Array.isArray(data.keywords)\n      ? data.keywords\n      : String(data.keywords || \"\").split(/[,\\n]/);\n    const keywords = rawKeywords\n      .map((keyword) => String(keyword || \"\").replace(/^#/, \"\").trim())\n      .filter(Boolean);\n\n    if (!title || !body) return null;\n    return { title, subtitles, body, keywords };\n  }\n\n  function parseLooseArticle(candidate) {\n    const title = parseLooseValue(extractSection(candidate, \"title\", [\"subtitle1\", \"subtitles\", \"body\"]));\n    const subtitlesValue = parseLooseValue(extractSection(candidate, \"subtitles\", [\"body\"]));\n    const subtitle1 = parseLooseValue(extractSection(candidate, \"subtitle1\", [\"subtitle2\", \"subtitle3\", \"body\"]));\n    const subtitle2 = parseLooseValue(extractSection(candidate, \"subtitle2\", [\"subtitle3\", \"body\"]));\n    const subtitle3 = parseLooseValue(extractSection(candidate, \"subtitle3\", [\"body\"]));\n    const body = parseLooseValue(extractSection(candidate, \"body\", [\"keywords\"]));\n\n    let keywordsSection = extractSection(candidate, \"keywords\", []);\n    while (keywordsSection.endsWith(\"}\")) keywordsSection = keywordsSection.slice(0, -1).trim();\n    const keywords = parseLooseValue(keywordsSection);\n\n    return {\n      title,\n      subtitles: Array.isArray(subtitlesValue)\n        ? subtitlesValue\n        : [subtitle1, subtitle2, subtitle3].filter(Boolean),\n      body,\n      keywords: Array.isArray(keywords) ? keywords : [],\n    };\n  }\n\n  function parse(rawText) {\n    if (!rawText || !String(rawText).trim()) {\n      return { ok: false, reason: \"AI 응답이 비어 있습니다.\" };\n    }\n\n    const candidate = extractCandidate(rawText);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON 을 찾지 못했습니다.\" };\n\n    let data = null;\n    let repaired = false;\n\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repairCommonJson(candidate));\n        repaired = true;\n      } catch (_repairError) {\n        data = parseLooseArticle(candidate);\n        repaired = true;\n      }\n    }\n\n    const article = normalizeArticle(data);\n    if (!article) {\n      return { ok: false, reason: \"AI 응답에 제목 또는 본문이 없거나 복구할 수 없는 JSON 입니다.\" };\n    }\n\n    return { ok: true, article, repaired };\n  }\n\n  const api = { parse, hasCompleteObject, extractCandidate, repairCommonJson, normalizeBody };\n  globalThis.GWArticleJson = api;\n\n  if (typeof module !== \"undefined\" && module.exports) {\n    module.exports = api;\n  }\n})();\n",
 "remodel/blog-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   네이버 블로그 초안 전용 프롬프트\n\n   기사 작성 프롬프트와 분리한다. 블로그에서 스타일이나 분량을 바꿔도\n   2번 '초안 다듬기'의 기사 프롬프트에는 아무 영향이 없다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_BLOG_LENGTH = {\n  short:  { label: \"짧게\", chars: \"700~1,000자\", paras: \"5~7개\" },\n  normal: { label: \"중간\", chars: \"1,500~2,000자\", paras: \"9~12개\" },\n  long:   { label: \"길게\", chars: \"2,500~3,500자\", paras: \"14~20개\" },\n};\n\nconst GW_BLOG_STYLE = {\n  listing: {\n    label: \"기본 매물소개형\",\n    fit: \"모든 매물\",\n    titleExample: \"논현동 아크로힐스 매매 15억, 3룸 남향\",\n    guide:\n      \"깔끔하고 정보 중심으로 쓴다. 제목과 첫 문단에서 지역·매물·거래 조건을 분명히 보여 주고, \" +\n      \"본문은 핵심 조건, 입지, 내부 구성, 확인할 점의 순서로 정리한다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 3~4개, 명사형으로 짧게 (예: ■ 입지와 교통 / ■ 내부 구성 / ■ 계약 전 확인할 점). \" +\n      \"핵심 요약 → 입지 → 내부 구성 → 확인할 점 순서\",\n  },\n  visit: {\n    label: \"현장답사형\",\n    fit: \"아파트·상가·빌딩\",\n    titleExample: \"논현동 아크로힐스, 단지 안팎을 사진으로 살펴보니\",\n    guide:\n      \"현장을 차례로 둘러보는 듯한 흐름으로 쓴다. 다만 실제 방문·촬영·인터뷰를 했다고 거짓말하지 말고, \" +\n      \"제공된 기사와 사진에서 확인할 수 있는 동선과 인상만 관찰형 문장으로 풀어낸다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 3~5개, 둘러보는 동선 순서의 장소형 (예: ■ 단지 입구에서 / ■ 거실과 주방 / ■ 주변 거리). \" +\n      \"바깥에서 안으로, 다시 주변으로 이어지는 흐름\",\n  },\n  story: {\n    label: \"스토리텔링형\",\n    fit: \"주택·아파트\",\n    titleExample: \"강남에서 15억으로 찾는다면?\",\n    guide:\n      \"독자가 실제로 집이나 매물을 찾는 상황, 또는 한 가지 질문으로 시작한다. \" +\n      \"과장된 허구의 고객 사례는 만들지 말고 확인된 조건을 따라 자연스럽게 해답을 제시한다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 1~2개, 질문형 (예: ■ 15억이면 무엇을 먼저 봐야 할까?). \" +\n      \"상황 제시 → 질문 → 확인된 조건으로 해답 순서. 소제목보다 문단 흐름을 중시\",\n  },\n  report: {\n    label: \"분석·리포트형\",\n    fit: \"빌딩·토지·투자매물\",\n    titleExample: \"논현동 50억 건물, 조건을 하나씩 살펴보니\",\n    guide:\n      \"조건과 장점, 한계, 계약 전 확인 사항을 균형 있게 분석한다. \" +\n      \"확인되지 않은 수익률·시세·개발 호재를 추정하지 않는다.\",\n    design: \"news\",\n    structure:\n      \"소제목 4~5개, 명사형으로 고정 (■ 핵심 조건 / ■ 장점 / ■ 한계와 확인할 부분 / ■ 계약 전 체크포인트). \" +\n      \"각 구역은 1~2문단\",\n  },\n  consult: {\n    label: \"친근한 해설형\",\n    fit: \"실수요 매물\",\n    titleExample: \"방 3개 아파트 매물, 어떤 가구에 맞을까\",\n    guide:\n      \"매물 조건을 독자가 이해하기 쉽게 풀어 설명하는 해설 기사로 쓴다. 부드러운 존댓말은 허용하지만 \" +\n      \"권유하지 말고, 어떤 가구에 맞는 조건인지와 확인할 점을 객관적으로 짚는다.\",\n    design: \"qna\",\n    structure:\n      \"소제목 3~4개, 고객이 실제로 물어볼 질문형 (예: ■ 관리비는 얼마인가요? / ■ 주차는 가능한가요?). \" +\n      \"각 소제목 바로 다음 문단이 그 질문에 대한 답\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\",\n    fit: \"SNS 연계 매물\",\n    titleExample: \"[매물] 강남 논현동 아파트 15억 매매 등록\",\n    guide:\n      \"속보 기사처럼 첫 두 문장에 무엇이 어디에 얼마로 나왔는지를 짧게 전한다. 문장을 짧게 끊고 사실만 빠르게 전달하되, \" +\n      \"낚시성 표현·과도한 감탄·확인되지 않은 단정은 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 0~2개, 한 줄로 짧게. 강한 첫 두 문장 → 핵심 조건 3가지 → 한 줄 정리. \" +\n      \"문단은 1~2문장으로 짧게 끊을 것\",\n  },\n};\n\nfunction gwBlogFactLines(v) {\n  if (!v || typeof v !== \"object\") return \"- 별도 매물표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n\n  const lines = [];\n  const seen = new Set();\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  push(\"매물\", v.title);\n  push(\"금액\", v.priceText);\n  for (const field of v.fields || []) push(field.label, field.value);\n  push(\"특징\", Array.isArray(v.themes) ? v.themes.join(\" \") : v.themes);\n  push(\"주변환경\", v.infra);\n  return lines.length ? lines.join(\"\\n\") : \"- 별도 매물표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n}\n\nfunction gwBlogArticleText(article) {\n  const a = article || {};\n  const subtitles = Array.isArray(a.subtitles) ? a.subtitles : [];\n  return [\n    `[제목] ${String(a.title || \"\").trim()}`,\n    subtitles.length ? `[부제] ${subtitles.join(\" / \")}` : \"\",\n    `[본문]\\n${String(a.body || \"\").trim()}`,\n  ].filter(Boolean).join(\"\\n\");\n}\n\nfunction gwBuildBlogPrompt(source, opts) {\n  /* 리모델링 작성기: 결과표가 원자료다 */\n  if (source && source.remodel && typeof gwBuildRemodelBlogPrompt === \"function\") return gwBuildRemodelBlogPrompt(source, opts);\n  if (source && source.vacancy && source.vacancy.saleKind) return gwBuildAuctionBlogPrompt(source, opts);\n  const input = source || {};\n  const o = opts || {};\n  const style = GW_BLOG_STYLE[o.style] || GW_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = input.article || {};\n\n  return `당신은 부동산 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 공실뉴스 기사와 확인된 매물 정보를 참고해 블로그 초안 1건을 작성하십시오.\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n[확인된 매물 정보]\n${gwBlogFactLines(input.vacancy)}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 매물: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n- 같은 매물 조건을 반복해 분량을 억지로 늘리지 말 것\n\n[보도 원칙 — 모든 스타일 공통, 가장 먼저 지킬 것]\n- 이 글은 \"공실뉴스에 이런 매물이 나왔다\"는 객관적인 매물 보도입니다. 위 스타일은 전개 방식만 정하고 이 틀은 바꾸지 않습니다\n- 3인칭 전달체로 쓸 것 (예: \"~로 등록됐다\", \"~인 것으로 나타났다\", \"~로 확인된다\"). 기본·분석·속보형은 기사체(~다), 현장답사·스토리텔링·해설형은 부드러운 존댓말(~습니다)도 허용\n- 첫 문단에서 공실뉴스에 등록된 매물이라는 점과 소재지·매물 종류·거래 조건을 밝힐 것 (예: \"공실뉴스에 서울 강남구 논현동 아파트 매매 매물이 등록됐다.\")\n- 출처를 분명히 할 것 (예: \"공실뉴스에 등록된 매물 정보에 따르면\")\n- 권유·호객·광고 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"연락 주세요\", \"놓치지 마세요\", \"강력 추천\", \"지금이 기회\" 등\n- 독자에게 직접 권하는 2인칭 문장을 쓰지 말 것. 조언이 필요하면 \"~라면 ~를 확인할 필요가 있다\"처럼 객관적으로 쓸 것\n- 위치·학군·지하철역·버스정류장·쇼핑시설·병원 등 주변 정보는 기사 가치가 있으므로 적극 전할 것. 단 [확인된 매물 정보]와 [참조 기사]에 있는 것만 쓰고, 자료에 없는 거리·도보 시간은 만들지 말 것\n- 중개사무소 이름·연락처·링크는 본문에 쓰지 말 것 (글 끝 \"매물 정보 출처\"에 자동으로 들어갑니다)\n\n[가장 중요한 사실 원칙]\n- 금액·면적·층·방·주소·관리비·입주일·주차·옵션 등 매물 고유 조건은\n  [확인된 매물 정보] 또는 [참조 기사]에 실제로 있는 내용만 쓸 것\n- 두 자료가 다르면 [확인된 매물 정보]를 우선할 것\n- 없는 수치, 현장 방문, 인터뷰, 고객 반응, 시세, 수익률, 개발 호재를 만들어내지 말 것\n- 소재지가 시·군·동까지만 공개됐다면 더 상세한 주소를 추측하지 말 것\n- 장점과 함께 계약 전 직접 확인할 점도 균형 있게 안내할 것\n\n[블로그 구성]\n- title: 검색어를 억지로 나열하지 않은 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 모바일에서도 읽기 쉽도록 한 문단을 2~4문장으로 짧게 구성할 것\n- 첫 문단은 2문장 이내의 핵심 요약으로 쓸 것 (인사말 없이 바로 본론, 위 보도 원칙의 첫 문단 규칙 포함). 이 문단은 블로그 맨 위 요약으로 쓰입니다\n- 소제목은 위 [선택한 스타일]의 구성대로 넣고, 한 줄짜리 독립 문단으로 쓰며 반드시 \"■ \"로 시작할 것\n  (\"■\"는 소제목 위치를 알리는 표시이며 화면 모양은 블로그 디자인이 따로 정합니다)\n- 소제목 바로 다음에는 반드시 본문 문단이 올 것 (소제목을 연달아 쓰거나 글 맨 끝에 두지 말 것)\n- 마지막 문단은 매물 조건과 확인할 점을 객관적으로 정리하는 한 문단으로 쓸 것. 권유·연락처·문의 안내·링크는 쓰지 말 것\n- 기사 문장을 그대로 길게 복사하지 말고 블로그 독자를 위한 새 문장으로 재구성할 것\n- keywords: 지역명·매물 종류·거래 조건을 포함한 검색용 핵심어 7~12개. # 기호는 제외할 것\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nfunction gwBuildBlogRevisePrompt(request, vacancy) {\n  if (vacancy && vacancy.saleKind) return gwBuildAuctionBlogRevisePrompt(request);\n  return `위에서 작성한 블로그 글을 아래 요청대로 고쳐 주십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 매물의 금액·면적·층·주소·번호 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 사용자의 수정 요청을 반영하되 과장 광고, 허위 방문, 허위 고객 사례를 만들지 마십시오.\n- 소제목 문단은 처음처럼 \"■ \"로 시작하고, 첫 문단은 핵심 요약으로 유지하십시오.\n- \"공실뉴스에 이런 매물이 나왔다\"는 객관적 보도 형식을 유지하고, 권유·호객 표현이나 중개사무소 연락처를 넣지 마십시오.\n- 고친 블로그 글 전체를 다시 출력하십시오. 수정된 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n- body는 문단별 문자열 배열이며 JSON.parse가 가능한 유효한 JSON이어야 합니다.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 물건 블로그 — 스타일 이름·순서는 일반 매물과 같고,\n   예시·지침·사실 원칙이 경매·공매에 맞춰져 있다.\n   블로그 탭은 gwBlogStyles(vacancy) 로 어느 쪽 스타일을 쓸지 고른다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_AUCTION_BLOG_STYLE = {\n  listing: {\n    label: \"기본 물건소개형\",\n    fit: \"모든 물건\",\n    titleExample: \"역삼동 오피스텔 공매, 최저입찰가 291만원\",\n    guide:\n      \"깔끔하고 정보 중심으로 쓴다. 제목과 첫 문단에서 경매·공매 구분, 지역, 물건 종류, 감정가와 최저입찰가를 분명히 보여 주고, \" +\n      \"본문은 가격 조건, 물건 현황과 입지, 입찰 일정, 확인할 점의 순서로 정리한다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 3~4개, 명사형으로 짧게 (예: ■ 가격 조건 / ■ 물건 현황과 입지 / ■ 입찰 일정 / ■ 입찰 전 확인할 점). \" +\n      \"핵심 요약 → 가격 → 현황·입지 → 일정 → 확인할 점 순서\",\n  },\n  visit: {\n    label: \"현장답사형\",\n    fit: \"아파트·상가·빌딩\",\n    titleExample: \"역삼동 경매 오피스텔, 주변을 사진으로 살펴보니\",\n    guide:\n      \"물건 주변을 차례로 둘러보는 듯한 흐름으로 쓴다. 다만 실제 방문·촬영·인터뷰를 했다고 거짓말하지 말고, \" +\n      \"제공된 기사와 사진·지도·로드뷰에서 확인할 수 있는 동선과 인상만 관찰형 문장으로 풀어낸다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 3~5개, 둘러보는 동선 순서의 장소형 (예: ■ 건물 외관 / ■ 진입로와 주변 거리 / ■ 가까운 교통). \" +\n      \"바깥에서 주변으로 이어지는 흐름. 마지막 소제목은 입찰 조건 정리\",\n  },\n  story: {\n    label: \"스토리텔링형\",\n    fit: \"주택·아파트\",\n    titleExample: \"감정가의 절반에 나온 아파트, 무엇을 봐야 할까?\",\n    guide:\n      \"독자가 경매·공매 물건을 처음 살펴보는 상황, 또는 한 가지 질문으로 시작한다. \" +\n      \"과장된 허구의 사례는 만들지 말고 확인된 조건을 따라 자연스럽게 해답을 제시한다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 1~2개, 질문형 (예: ■ 유찰이 거듭되면 무엇이 달라질까?). \" +\n      \"상황 제시 → 질문 → 확인된 조건으로 해답 순서. 소제목보다 문단 흐름을 중시\",\n  },\n  report: {\n    label: \"분석·리포트형\",\n    fit: \"빌딩·토지·상가\",\n    titleExample: \"3회 유찰된 논현동 건물, 입찰 조건을 살펴보니\",\n    guide:\n      \"가격 조건과 물건 현황, 한계, 입찰 전 확인 사항을 균형 있게 분석한다. \" +\n      \"확인되지 않은 낙찰가·수익률·시세·개발 호재를 추정하지 않는다.\",\n    design: \"news\",\n    structure:\n      \"소제목 4~5개, 명사형으로 고정 (■ 핵심 가격 조건 / ■ 물건 현황 / ■ 한계와 확인할 부분 / ■ 입찰 일정과 방법). \" +\n      \"각 구역은 1~2문단\",\n  },\n  consult: {\n    label: \"친근한 해설형\",\n    fit: \"주거용 물건\",\n    titleExample: \"공매 오피스텔, 입찰 절차는 어떻게 될까\",\n    guide:\n      \"경매·공매 물건의 조건과 입찰 절차를 독자가 이해하기 쉽게 풀어 설명하는 해설 기사로 쓴다. 부드러운 존댓말은 허용하지만 \" +\n      \"권유하지 말고, 조건의 의미와 확인할 점을 객관적으로 짚는다.\",\n    design: \"qna\",\n    structure:\n      \"소제목 3~4개, 독자가 실제로 물어볼 질문형 (예: ■ 최저입찰가는 어떻게 정해졌나요? / ■ 입찰보증금은 얼마인가요?). \" +\n      \"각 소제목 바로 다음 문단이 그 질문에 대한 답\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\",\n    fit: \"SNS 연계 물건\",\n    titleExample: \"[공매] 강남 역삼동 오피스텔 최저가 291만원\",\n    guide:\n      \"속보 기사처럼 첫 두 문장에 어떤 물건이 어디서 얼마에 경매·공매로 나왔는지를 짧게 전한다. 문장을 짧게 끊고 사실만 빠르게 전달하되, \" +\n      \"낚시성 표현·과도한 감탄·확인되지 않은 단정은 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 0~2개, 한 줄로 짧게. 강한 첫 두 문장 → 핵심 조건 3가지(감정가·최저입찰가·입찰 일정) → 한 줄 정리. \" +\n      \"문단은 1~2문장으로 짧게 끊을 것\",\n  },\n};\n\nfunction gwAuctionBlogFactLines(v) {\n  if (!v || typeof v !== \"object\") return \"- 별도 물건표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n\n  const lines = [];\n  const seen = new Set();\n  const push = (label, value) => {\n    const val = value == null ? \"\" : String(value).trim();\n    if (!label || !val || val === \"-\" || seen.has(label)) return;\n    seen.add(label);\n    lines.push(`- ${label}: ${val}`);\n  };\n\n  push(\"물건\", v.title);\n  push(\"가격 요약\", v.priceText);\n  for (const field of v.fields || []) push(field.label, field.value);\n  return lines.length ? lines.join(\"\\n\") : \"- 별도 물건표 없음 — 아래 참조 기사에 나온 사실만 사용할 것\";\n}\n\nfunction gwBuildAuctionBlogPrompt(source, opts) {\n  const input = source || {};\n  const o = opts || {};\n  const style = GW_AUCTION_BLOG_STYLE[o.style] || GW_AUCTION_BLOG_STYLE.listing;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const article = input.article || {};\n\n  const saleKind = input.vacancy && input.vacancy.saleKind === \"공매\" ? \"공매\" : \"경매\";\n\n  return `당신은 부동산 경매·공매 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 공실뉴스 기사와 확인된 ${saleKind} 물건 정보를 참고해 블로그 초안 1건을 작성하십시오.\n\n[참조 기사]\n${gwBlogArticleText(article)}\n\n[확인된 물건 정보]\n${gwAuctionBlogFactLines(input.vacancy)}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 물건: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n- 같은 물건 조건을 반복해 분량을 억지로 늘리지 말 것\n\n[보도 원칙 — 모든 스타일 공통, 가장 먼저 지킬 것]\n- 이 글은 \"공실뉴스 공실열람에 이런 ${saleKind} 물건이 나왔다\"는 객관적인 보도입니다. 위 스타일은 전개 방식만 정하고 이 틀은 바꾸지 않습니다\n- 3인칭 전달체로 쓸 것 (예: \"~로 나왔다\", \"~인 것으로 나타났다\", \"~로 확인된다\"). 기본·분석·속보형은 기사체(~다), 현장답사·스토리텔링·해설형은 부드러운 존댓말(~습니다)도 허용\n- 첫 문단에서 ${saleKind} 물건이라는 점과 소재지·물건 종류·감정가·최저입찰가를 밝힐 것 (예: \"서울 강남구 역삼동 오피스텔이 ${saleKind}로 나왔다.\")\n- 출처를 분명히 할 것 (예: \"공실뉴스 공실열람의 ${saleKind} 물건 정보에 따르면\")\n- 투자 권유·호객 표현 금지: \"싸게 살 기회\", \"놓치지 마세요\", \"추천합니다\", \"지금이 기회\", \"수익이 기대된다\" 등\n- 낙찰가·낙찰가율·수익률·시세 상승을 예측하지 말 것\n- 독자에게 직접 권하는 2인칭 문장을 쓰지 말 것. 조언이 필요하면 \"~라면 ~를 확인할 필요가 있다\"처럼 객관적으로 쓸 것\n- 위치·교통·주변 시설 정보는 적극 전하되, [확인된 물건 정보]와 [참조 기사]에 있는 것만 쓰고 거리·도보 시간을 만들지 말 것\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호), \"본 정보는 참고용이며 법적 책임을 지지 않는다\"는 식의 입찰 전 법적 주의사항 안내문은 쓰지 말 것\n- 링크는 본문에 쓰지 말 것 (글 끝 \"물건 정보 출처\"에 자동으로 들어갑니다)\n\n[가장 중요한 사실 원칙]\n- 감정가·최저입찰가·유찰 횟수·입찰 일정·입찰보증금·면적·주소·관리번호(사건번호)·집행기관은\n  [확인된 물건 정보] 또는 [참조 기사]에 실제로 있는 내용만 쓸 것\n- 두 자료가 다르면 [확인된 물건 정보]를 우선할 것\n- 권리관계·임차인·체납액·현장 방문·인터뷰·낙찰 결과를 만들어내지 말 것\n- 입찰 일정이 없으면 날짜를 만들지 말 것\n- 가격 조건과 함께 입찰 전 직접 확인할 점(현장 상태·점유와 명도·권리관계)도 균형 있게 짚을 것\n\n[블로그 구성]\n- title: 검색어를 억지로 나열하지 않은 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 모바일에서도 읽기 쉽도록 한 문단을 2~4문장으로 짧게 구성할 것\n- 첫 문단은 2문장 이내의 핵심 요약으로 쓸 것 (인사말 없이 바로 본론, 위 보도 원칙의 첫 문단 규칙 포함). 이 문단은 블로그 맨 위 요약으로 쓰입니다\n- 소제목은 위 [선택한 스타일]의 구성대로 넣고, 한 줄짜리 독립 문단으로 쓰며 반드시 \"■ \"로 시작할 것\n  (\"■\"는 소제목 위치를 알리는 표시이며 화면 모양은 블로그 디자인이 따로 정합니다)\n- 소제목 바로 다음에는 반드시 본문 문단이 올 것 (소제목을 연달아 쓰거나 글 맨 끝에 두지 말 것)\n- 마지막 문단은 가격·일정 조건과 입찰 전 확인할 점을 객관적으로 정리하는 한 문단으로 쓸 것. 권유·연락처·링크는 쓰지 말 것\n- 기사 문장을 그대로 길게 복사하지 말고 블로그 독자를 위한 새 문장으로 재구성할 것\n- keywords: 지역명·물건 종류·\"${saleKind}\"를 포함한 검색용 핵심어 7~12개. # 기호는 제외할 것\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nfunction gwBuildAuctionBlogRevisePrompt(request) {\n  return `위에서 작성한 블로그 글을 아래 요청대로 고쳐 주십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 물건의 감정가·최저입찰가·유찰 횟수·입찰 일정·면적·주소·관리번호 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 사용자의 수정 요청을 반영하되 과장 광고, 허위 방문, 허위 고객 사례를 만들지 마십시오.\n- 소제목 문단은 처음처럼 \"■ \"로 시작하고, 첫 문단은 핵심 요약으로 유지하십시오.\n- \"공실뉴스 공실열람에 이런 경매·공매 물건이 나왔다\"는 객관적 보도 형식을 유지하고, 투자 권유·낙찰가 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문을 넣지 마십시오.\n- 고친 블로그 글 전체를 다시 출력하십시오. 수정된 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n- body는 문단별 문자열 배열이며 JSON.parse가 가능한 유효한 JSON이어야 합니다.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\n/* 물건 종류에 맞는 블로그 스타일 표 — 경매·공매면 경매용 */\nfunction gwBlogStyles(vacancy) {\n  if (typeof RM_BLOG_STYLE !== \"undefined\") return RM_BLOG_STYLE; // 리모델링 작성기\n  return vacancy && vacancy.saleKind ? GW_AUCTION_BLOG_STYLE : GW_BLOG_STYLE;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_BLOG_LENGTH,\n    GW_BLOG_STYLE,\n    GW_AUCTION_BLOG_STYLE,\n    gwBlogStyles,\n    gwBlogFactLines,\n    gwAuctionBlogFactLines,\n    gwBlogArticleText,\n    gwBuildBlogPrompt,\n    gwBuildBlogRevisePrompt,\n  };\n}\n",
 "remodel/naver-blog.js": "/* 네이버 블로그 탭과 글쓰기 탭을 구분하는 공통 규칙 */\n(function initNaverBlog(global) {\n  \"use strict\";\n\n  const HOME_URL = \"https://blog.naver.com/\";\n  const WRITE_URL = \"https://blog.naver.com/GoBlogWrite.naver\";\n\n  function isNaverBlogUrl(rawUrl) {\n    try {\n      const url = new URL(rawUrl);\n      return url.protocol === \"https:\" && (\n        url.hostname === \"blog.naver.com\" ||\n        url.hostname === \"blog.editor.naver.com\"\n      );\n    } catch (_) {\n      return false;\n    }\n  }\n\n  function isLikelyWriteUrl(rawUrl) {\n    if (!isNaverBlogUrl(rawUrl)) return false;\n    const value = String(rawUrl).toLowerCase();\n    return (\n      value.includes(\"goblogwrite\") ||\n      value.includes(\"postwrite\") ||\n      value.includes(\"postwriteform\") ||\n      value.includes(\"redirect=write\") ||\n      value.includes(\"blog.editor.naver.com\")\n    );\n  }\n\n  function selectLikelyWriteTab(tabs) {\n    return (Array.isArray(tabs) ? tabs : [])\n      .filter((tab) => tab && tab.id && isLikelyWriteUrl(tab.url))\n      .sort((a, b) => {\n        if (Boolean(a.active) !== Boolean(b.active)) return a.active ? -1 : 1;\n        return (b.lastAccessed || 0) - (a.lastAccessed || 0);\n      })[0] || null;\n  }\n\n  function splitParagraphs(body) {\n    return String(body || \"\")\n      .split(/\\n{2,}|\\n/)\n      .map((value) => value.trim())\n      .filter(Boolean);\n  }\n\n  /* 대표가 아닌 사진을 문단 사이 칸(0 = 첫 문단 앞, n = n번째 문단 뒤)에 배치한다.\n     insertAfterParagraph가 있으면 그 칸, 없으면 두 문단마다 한 장씩, 남으면 글 끝. */\n  function layoutMediaSlots(paragraphCount, media) {\n    const slots = Array.from({ length: paragraphCount + 1 }, () => []);\n    const automatic = [];\n\n    (Array.isArray(media) ? media : []).forEach((item, index) => {\n      if (!item || item.isCover) return;\n      if (Number.isInteger(item.insertAfterParagraph)) {\n        const slot = Math.max(0, Math.min(item.insertAfterParagraph, paragraphCount));\n        slots[slot].push({ media: item, index });\n      } else {\n        automatic.push({ media: item, index });\n      }\n    });\n\n    let autoIndex = 0;\n    for (let slot = 2; slot < paragraphCount && autoIndex < automatic.length; slot += 2) {\n      slots[slot].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    while (autoIndex < automatic.length) {\n      slots[paragraphCount].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    return slots;\n  }\n\n  function escapeHtml(value) {\n    return String(value).replace(/[&<>\"']/g, (ch) => ({\n      \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\",\n    })[ch]);\n  }\n\n  /* ── 블로그 디자인 ──\n     네이버 편집기가 붙여넣기로 받아들이는 요소만 쓴다 (2026-09-25 실제 화면에서 확인):\n     <blockquote> → 인용구(따옴표형), <hr> → 구분선, <table> → 표, 문단 정렬·글자색·크기·링크.\n     굵게(<b>·<strong>·font-weight)는 붙여넣기로 적용되지 않으므로 소제목은 크기와 색으로 강조한다.\n     붙여넣기 조각을 빈 문단으로 끝내지 않으면 다음 조각이 마지막 문단에 이어 붙고 글자색·크기도 번진다.\n     문단 순서는 모든 디자인이 같다. 그래서 사진 위치(문단 사이 칸)가 미리보기와 어긋나지 않는다. */\n  const DESIGNS = {\n    basic: { label: \"기본형\", hint: \"요약 인용구 · 매물표 · 큰 소제목. 어떤 매물에나 무난합니다.\" },\n    magazine: { label: \"매거진형\", hint: \"가운데 정렬 · 번호 소제목 · 핵심 문장 강조. 고급·신축 매물에 어울립니다.\" },\n    qna: { label: \"Q&A형\", hint: \"소제목을 질문으로, 본문을 답변으로. 질문형 검색에 유리합니다.\" },\n    news: { label: \"뉴스기사형\", hint: \"큰 리드문 · 기사체 · 공실뉴스 서명. 언론사 느낌을 살립니다.\" },\n  };\n  /* 경매·공매 물건일 때 바뀌는 디자인 설명 */\n  const AUCTION_HINTS = {\n    basic: \"요약 인용구 · 물건표 · 큰 소제목. 어떤 물건에나 무난합니다.\",\n    magazine: \"가운데 정렬 · 번호 소제목 · 핵심 문장 강조. 아파트·건물 물건에 어울립니다.\",\n  };\n  function designHint(design, auction) {\n    return (auction && AUCTION_HINTS[design]) || DESIGNS[design]?.hint || \"\";\n  }\n  const ACCENT = \"#2563eb\";\n  const MUTED = \"#888888\";\n  const SKY = \"#dbeafe\"; // 매거진형 소제목 하늘색 배경(형광펜)\n  const BLANK = \"<p><br></p>\";\n  const SITE_URL = \"https://www.gongsilnews.com\"; // gongsilnews.com은 www로 넘어간다. 로그인 쿠키도 www에 있다\n\n  /* 매물표 항목: 부동산 인터넷 표시·광고 필수 항목 순서.\n     소재지·매물종류·거래형태는 출처 API(listing), 나머지는 공실광고정보 탭 항목(vacancy.fields)에서 찾는다. */\n  const FACT_ORDER = [\n    /^(금액)$/,\n    /관리비/,\n    /면적/,\n    /해당층|총층|건물규모/,\n    /방\\/욕실|방수|욕실/,\n    /방향/,\n    /준공|사용승인/,\n    /주차/,\n    /입주가능|사용 가능일/,\n  ];\n\n  /* 경매·공매 물건표 항목: 경매·공매 물건을 볼 때 먼저 찾는 순서.\n     소재지·물건종류는 출처 API(listing), 나머지는 서버에서 받은 물건 정보(vacancy.fields)에서 찾는다.\n     정보제공처 연락처와 입찰 전 주의사항은 서버가 애초에 보내지 않는다. */\n  const AUCTION_FACT_ORDER = [\n    /^구분$/,\n    /^감정가$/,\n    /^최저입찰가$/,\n    /감정가 대비/,\n    /유찰/,\n    /토지면적|건물면적/,\n    /입찰 시작|입찰 마감|개찰일시/,\n    /입찰보증금$/,\n    /명도책임/,\n    /관리번호|사건번호/,\n    /집행기관|관할법원/,\n  ];\n\n  /* 경매·공매 물건인가 — 출처 API 나 물건 정보에 경매·공매 구분이 붙어 있다 */\n  const isAuction = (vacancy, listing) => Boolean(listing?.saleKind || vacancy?.saleKind);\n\n  function isHeading(paragraph) {\n    return String(paragraph).startsWith(\"■\");\n  }\n\n  function stripHeading(paragraph) {\n    return String(paragraph).replace(/^■\\s*/, \"\");\n  }\n\n  /* 매물표: 표시·광고 필수 항목을 정해진 순서로 (개수 제한 없음) */\n  function factRows(vacancy, listing) {\n    const rows = [];\n    const seen = new Set();\n    const push = (label, value) => {\n      const text = value == null ? \"\" : String(value).trim();\n      if (!label || !text || text === \"-\" || seen.has(label)) return;\n      seen.add(label);\n      rows.push([label, text]);\n    };\n    const fields = (Array.isArray(vacancy?.fields) ? vacancy.fields : []).filter((field) => field && field.label);\n\n    if (isAuction(vacancy, listing)) {\n      push(\"소재지\", fields.find((field) => field.label === \"소재지(지번)\")?.value || listing?.location);\n      push(\"물건종류\", listing?.propertyType || fields.find((field) => field.label === \"물건종류\")?.value);\n      AUCTION_FACT_ORDER.forEach((pattern) => {\n        fields.filter((field) => pattern.test(field.label)).forEach((field) => push(field.label, field.value));\n      });\n      if (!seen.has(\"최저입찰가\")) push(\"가격\", vacancy?.priceText);\n      return rows;\n    }\n\n    push(\"소재지\", listing?.location);\n    push(\"매물종류\", listing?.propertyType);\n    push(\"거래형태\", listing?.tradeType || fields.find((field) => /거래구분/.test(field.label))?.value);\n    FACT_ORDER.forEach((pattern) => {\n      fields.filter((field) => pattern.test(field.label)).forEach((field) => push(field.label, field.value));\n    });\n    if (!seen.has(\"금액\")) push(\"금액\", vacancy?.priceText);\n    return rows;\n  }\n\n  /* 링크: 매물 고정 상세 주소 → 없으면 처음 매물을 본 공실뉴스 주소 */\n  function listingUrl(vacancy, listing) {\n    if (listing?.detailUrl) return listing.detailUrl;\n    const url = String(vacancy?.url || \"\");\n    return /^https:\\/\\/([a-z0-9-]+\\.)?gongsilnews\\.com\\//i.test(url) ? url : \"\";\n  }\n\n  function formatDate(value) {\n    const date = value ? new Date(value) : new Date();\n    if (Number.isNaN(date.getTime())) return \"\";\n    const pad = (n) => String(n).padStart(2, \"0\");\n    return `${date.getFullYear()}.${pad(date.getMonth() + 1)}.${pad(date.getDate())}`;\n  }\n\n  /* 전송 전 검사: 표시·광고 필수 정보가 빠졌으면 이유를 돌려준다 */\n  function listingProblems(listing, auction = false) {\n    /* 경매·공매: 물건 정보를 서버에서 받았는지만 본다 */\n    if (auction || listing?.saleKind) {\n      if (!listing) return [\"경매·공매 물건 정보\"];\n      return listing.saleKind ? [] : [\"경매·공매 구분\"];\n    }\n    if (!listing) return [\"매물 출처 정보(중개사무소)\"];\n    const owner = listing.owner || {};\n    if (owner.type !== \"agency\") return owner.name ? [] : [\"등록자 이름\"];\n    return [\n      [\"중개사무소 명칭\", owner.name],\n      [\"대표자\", owner.ceo],\n      [\"등록번호\", owner.regNo],\n      [\"소재지\", owner.address],\n      [\"연락처\", owner.phone],\n    ].filter(([, value]) => !String(value || \"\").trim()).map(([label]) => label);\n  }\n\n  /* 글 끝 \"매물 정보 출처\" — 모든 디자인 공통. 문의처가 아니라 출처로 표현한다. */\n  function sourceBlockLines(listing, url) {\n    /* 경매·공매: 정보제공처(온비드 고객센터) 연락처와 입찰 전 법적 주의사항 안내문은 넣지 않는다 */\n    if (listing?.saleKind) {\n      const saleKind = listing.saleKind;\n      const lines = [`공실뉴스 공실열람 ${saleKind} 물건 정보 (${formatDate(listing.capturedAt)} 기준)`];\n      const numberLabel = listing.caseLabel || (saleKind === \"공매\" ? \"관리번호\" : \"사건번호\");\n      const parts = [\n        listing.caseNo ? `${numberLabel} ${listing.caseNo}` : \"\",\n        listing.agency ? `${saleKind === \"공매\" ? \"집행기관\" : \"관할법원\"} ${listing.agency}` : \"\",\n      ].filter(Boolean);\n      if (parts.length) lines.push(parts.join(\" | \"));\n      lines.push(\"※ 입찰 조건은 공고 시점 기준이며 변경될 수 있습니다.\");\n      return { lines, url };\n    }\n    /* 리모델링 작성기: 예측 이미지·공사비의 출처는 모든 글에 붙인다 */\n    const REMODEL_LINE = \"리모델링 예측 이미지·예상 공사비: 공실뉴스 리모델링 예측 시뮬레이션 (대략적인 예상 공사비이며, 꼭 실질적인 확인이 필요합니다)\";\n\n    /* 직접 올린 사진 — 공실 매물이 아니다 */\n    if (!listing && !url) {\n      return { lines: [`공실뉴스 리모델링 예측 시뮬레이션 결과 (${formatDate()} 기준)`, REMODEL_LINE], url };\n    }\n\n    const owner = listing?.owner || {};\n    const lines = [`공실뉴스 매물 등록 정보 (${formatDate(listing?.capturedAt)} 기준)`];\n    const office = (label, a) => {\n      lines.push(`${label}: ${a.name}${a.ceo ? ` | 대표 ${a.ceo}` : \"\"}`);\n      const reg = [a.regNo ? `등록번호 ${a.regNo}` : \"\", a.address || \"\"].filter(Boolean).join(\" | \");\n      if (reg) lines.push(reg);\n      if (a.phone) lines.push(`전화 ${a.phone}`);\n    };\n    if (owner.type === \"agency\" && owner.name) {\n      office(\"등록 중개사무소\", owner);\n    } else if (owner.name) {\n      lines.push(`등록자: ${owner.name} (일반회원 등록 매물)`);\n    } else {\n      lines.push(\"매물 정보 출처: 공실뉴스 공실열람\");\n    }\n    lines.push(\"※ 매물 조건은 등록 시점 기준이며 실제와 다를 수 있습니다.\");\n    lines.push(REMODEL_LINE);\n    return { lines, url };\n  }\n\n  function paragraphHtml(text, { align, size, color, background, bold } = {}) {\n    let inner = escapeHtml(text);\n    const styles = [\n      size ? `font-size:${size}px` : \"\",\n      color ? `color:${color}` : \"\",\n      background ? `background-color:${background}` : \"\",\n      bold ? \"font-weight:700\" : \"\",\n    ].filter(Boolean).join(\";\");\n    if (styles) inner = `<span style=\"${styles}\">${inner}</span>`;\n    return align ? `<p style=\"text-align:${align}\">${inner}</p>` : `<p>${inner}</p>`;\n  }\n\n  function quoteHtml(text) {\n    return `<blockquote><p>${escapeHtml(text)}</p></blockquote>`;\n  }\n\n  function tableHtml(rows) {\n    if (!rows.length) return \"\";\n    const body = rows\n      .map(([label, value]) => `<tr><td><b>${escapeHtml(label)}</b></td><td>${escapeHtml(value)}</td></tr>`)\n      .join(\"\");\n    return `<table><tbody>${body}</tbody></table>`;\n  }\n\n  function linkHtml(url, text, align) {\n    if (!url) return \"\";\n    const style = align ? ` style=\"text-align:${align}\"` : \"\";\n    return `<p${style}><a href=\"${escapeHtml(url)}\">${escapeHtml(text)}</a></p>`;\n  }\n\n  function firstSentence(text) {\n    const match = /^(.+?[.!?])(\\s|$)/.exec(String(text || \"\").trim());\n    return match ? match[1] : String(text || \"\").trim();\n  }\n\n  /* 네이버 편집기에 차례로 붙여넣을 조각을 만든다.\n     글 조각은 HTML, 사진은 media 배열의 위치만 담는다.\n     글 조각은 사진이 끼어들 때만 끊고, 문단 뒤와 조각 끝에는 빈 문단을 둔다. */\n  function buildNaverBlocks(body, media, options = {}) {\n    const design = DESIGNS[options.design] ? options.design : \"basic\";\n    const list = Array.isArray(media) ? media : [];\n    const paragraphs = splitParagraphs(body);\n    const slots = layoutMediaSlots(paragraphs.length, list);\n    const rows = factRows(options.vacancy, options.listing);\n    const noun = isAuction(options.vacancy, options.listing) ? \"물건\" : \"매물\";\n    const url = listingUrl(options.vacancy, options.listing);\n    const blocks = [];\n    let buffer = [];\n\n    const flush = () => {\n      if (!buffer.length) return;\n      if (buffer[buffer.length - 1] !== BLANK) buffer.push(BLANK);\n      blocks.push({ type: \"html\", html: buffer.join(\"\") });\n      buffer = [];\n    };\n    // 문단 뒤에는 빈 문단 한 칸 (tight: 번호처럼 바로 아래 줄과 붙어야 하는 문단)\n    const html = (value, { tight = false } = {}) => {\n      if (!value) return;\n      buffer.push(value);\n      if (!tight && value.startsWith(\"<p\")) buffer.push(BLANK);\n    };\n    const addImages = (indexes) => {\n      if (!indexes.length) return;\n      flush();\n      indexes.forEach((index) => blocks.push({ type: \"image\", mediaIndex: index }));\n    };\n\n    const leadIndex = paragraphs.length && !isHeading(paragraphs[0]) ? 0 : -1;\n    const firstHeadingIndex = paragraphs.findIndex(isHeading);\n    let headingNumber = 0;\n    let answerPending = false;\n    let pullQuote = \"\";\n    let pullQuoteDone = false;\n\n    // 대표 사진 (뉴스기사형은 사진 설명을 작게 붙인다)\n    const coverIndex = list.findIndex((item) => item && item.isCover);\n    if (coverIndex >= 0) {\n      addImages([coverIndex]);\n      const caption = String(list[coverIndex].caption || \"\").trim();\n      if (design === \"news\" && caption) html(paragraphHtml(caption, { align: \"center\", size: 13, color: MUTED }));\n    }\n    if (design === \"magazine\" && options.title) {\n      html(paragraphHtml(options.title, { align: \"center\", size: 24, bold: true }));\n    }\n    addImages(slots[0].map((item) => item.index));\n\n    // 도입부가 끝나고 첫 소제목이 오기 전에 넣는 장식\n    const afterIntro = () => {\n      if (design === \"basic\") {\n        html(tableHtml(rows));\n        html(\"<hr>\");\n      } else if (design === \"magazine\") {\n        html(\"<hr>\");\n      }\n    };\n\n    let carried = [];\n    paragraphs.forEach((paragraph, index) => {\n      if (index === firstHeadingIndex) afterIntro();\n\n      if (index === leadIndex) {\n        if (design === \"basic\" || design === \"qna\") html(quoteHtml(paragraph));\n        else if (design === \"magazine\") html(paragraphHtml(paragraph, { align: \"center\", color: MUTED }));\n        else html(paragraphHtml(paragraph, { size: 17, bold: true }));\n        if (design === \"qna\") html(tableHtml(rows));\n      } else if (isHeading(paragraph)) {\n        const text = stripHeading(paragraph);\n        headingNumber += 1;\n        if (design === \"magazine\" && headingNumber === 2 && pullQuote) {\n          html(quoteHtml(pullQuote));\n          pullQuoteDone = true;\n        }\n        if (design === \"basic\") {\n          html(paragraphHtml(`■ ${text}`, { size: 19, bold: true }), { tight: true });\n        } else if (design === \"magazine\") {\n          html(paragraphHtml(String(headingNumber).padStart(2, \"0\"), { align: \"center\", color: ACCENT, bold: true }), { tight: true });\n          html(paragraphHtml(text, { align: \"center\", size: 19, background: SKY, bold: true }), { tight: true });\n        } else if (design === \"qna\") {\n          html(paragraphHtml(/^Q[.\\s]/.test(text) ? text : `Q. ${text}`, { size: 19, color: ACCENT, bold: true }), { tight: true });\n          answerPending = true;\n        } else {\n          html(paragraphHtml(text, { size: 19, bold: true }), { tight: true });\n        }\n      } else if (design === \"qna\" && answerPending) {\n        html(`<p><span style=\"color:${ACCENT}\">A.</span> ${escapeHtml(paragraph)}</p>`);\n        answerPending = false;\n      } else {\n        if (design === \"magazine\" && headingNumber === 1 && !pullQuote) pullQuote = firstSentence(paragraph);\n        html(paragraphHtml(paragraph, design === \"magazine\" ? { align: \"center\" } : {}));\n      }\n\n      // 소제목과 첫 문단 사이에는 사진을 두지 않는다 — 다음 문단 뒤로 넘긴다\n      const images = [...carried, ...slots[index + 1].map((item) => item.index)];\n      if (isHeading(paragraph) && index < paragraphs.length - 1) {\n        carried = images;\n      } else {\n        carried = [];\n        addImages(images);\n      }\n    });\n    addImages(carried);\n\n    if (firstHeadingIndex < 0) afterIntro();\n\n    // 글 끝: 디자인별 마무리\n    if (design === \"magazine\") {\n      if (pullQuote && !pullQuoteDone) html(quoteHtml(pullQuote));\n      html(\"<hr>\");\n      html(tableHtml(rows));\n    } else if (design === \"qna\") {\n      if (leadIndex < 0) html(tableHtml(rows));\n    } else if (design === \"news\") {\n      if (rows.length) {\n        html(paragraphHtml(noun === \"물건\" ? \"[물건 정보]\" : \"[매물 정보]\", { size: 17, bold: true }), { tight: true });\n        html(tableHtml(rows));\n      }\n    }\n\n    // 모든 디자인 공통: 매물 정보 출처 (표시·광고 필수 정보) + 고정 상세 링크 + 공실뉴스 서명\n    const source = sourceBlockLines(options.listing, url);\n    html(\"<hr>\");\n    html(paragraphHtml(`[${noun} 정보 출처]`, { size: 13, color: MUTED, bold: true }), { tight: true });\n    source.lines.forEach((line) => html(paragraphHtml(line, { size: 13, color: MUTED }), { tight: true }));\n    html(BLANK, { tight: true });\n    html(linkHtml(source.url, noun === \"물건\" ? \"▶ 공실뉴스 경매·공매 물건 상세 보기\" : \"▶ 공실뉴스 매물 상세 보기\"));\n    html(paragraphHtml(\"공실뉴스 · gongsilnews.com\", { size: 13, color: MUTED }));\n    flush();\n    return blocks;\n  }\n\n  /* 발행 창 태그 칸용: # 제거, 중복 제거, 네이버 최대 30개 */\n  function normalizeTags(keywords) {\n    const seen = new Set();\n    return (Array.isArray(keywords) ? keywords : [])\n      .map((keyword) => String(keyword || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n      .filter((keyword) => keyword && !seen.has(keyword) && seen.add(keyword))\n      .slice(0, 30);\n  }\n\n  const api = {\n    HOME_URL, WRITE_URL, isNaverBlogUrl, isLikelyWriteUrl, selectLikelyWriteTab,\n    splitParagraphs, layoutMediaSlots, buildNaverBlocks, normalizeTags,\n    DESIGNS, designHint, factRows, listingProblems, SITE_URL,\n    sourceBlockLines, listingUrl, // SNS 글 끝 출처·링크도 블로그와 같은 문구를 쓴다 (sns.js)\n  };\n  global.GWNaverBlog = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})(typeof globalThis !== \"undefined\" ? globalThis : self);\n",
 "remodel/youtube-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   4 · 유튜브 대본 — AI 지시문\n\n   2번 초안 다듬기의 기사와 1번에서 가져온 물건 정보를 자료로 쓴다.\n   기사 프롬프트(prompt.js)와 분리해, 여기서 무엇을 바꿔도 기사 작성에는 영향이 없다.\n\n   일반 매물과 경매·공매 물건은 지시문이 다르다.\n   경매·공매 물건은 1번에서 가져올 때 saleKind(\"경매\"·\"공매\")가 붙어 오므로 그것으로 가른다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_YT_VIDEO_TYPE = {\n  listing: { label: \"매물 소개\", structure: \"훅 → 위치 → 핵심 조건 → 장점 → 확인할 점 → 마무리\" },\n  news: { label: \"부동산 뉴스\", structure: \"헤드라인 → 배경 → 핵심 사실 → 의미 → 확인할 점\" },\n  area: { label: \"지역 분석\", structure: \"지역 소개 → 교통 → 생활권 → 물건 조건 → 정리\" },\n};\n\n/* 경매·공매 물건 — 칩 자리(listing·news·area)는 같고 이름과 흐름이 다르다 */\nconst GW_YT_AUCTION_VIDEO_TYPE = {\n  listing: {\n    label: \"물건 소개\",\n    structure: \"훅 → 위치·물건 종류 → 가격(감정가·최저입찰가·유찰) → 입찰 일정·방법 → 입찰 전 확인할 점 → 마무리\",\n  },\n  news: {\n    label: \"경매 뉴스\",\n    structure: \"헤드라인 → 어떤 물건이 나왔나 → 가격과 유찰 → 이 조건이 뜻하는 것 → 입찰 전 확인할 점\",\n  },\n  area: {\n    label: \"지역 분석\",\n    structure: \"지역 소개 → 교통 → 생활권 → 물건 조건과 가격 → 입찰 일정 → 정리\",\n  },\n};\n\nconst GW_YT_DURATION = {\n  short: { label: \"60초 쇼츠\", seconds: 60, chars: \"약 280~380자\" },\n  medium: { label: \"약 2분\", seconds: 120, chars: \"약 600~850자\" },\n  long: { label: \"약 5분\", seconds: 300, chars: \"약 1,500~2,100자\" },\n};\n\nconst GW_YT_TONE = {\n  news: { label: \"뉴스형\", prompt: \"정확하고 신뢰감 있는 뉴스 앵커형\" },\n  friendly: { label: \"친근한 설명\", prompt: \"부드럽고 친근한 설명형 (존댓말)\" },\n  expert: { label: \"전문가 분석\", prompt: \"차분하고 논리적인 부동산 전문가 분석형\" },\n};\n\n/* 경매·공매 물건인가 */\nconst gwYtIsAuction = (vacancy) => Boolean(vacancy && vacancy.saleKind);\n\n/* 물건 종류에 맞는 콘텐츠 유형 표 */\nfunction gwYtVideoTypes(vacancy) {\n  if (typeof RM_YT_VIDEO_TYPE !== \"undefined\") return RM_YT_VIDEO_TYPE; // 리모델링 작성기\n  return gwYtIsAuction(vacancy) ? GW_YT_AUCTION_VIDEO_TYPE : GW_YT_VIDEO_TYPE;\n}\n\nfunction gwYtSourceText(source) {\n  const input = source || {};\n  const article = input.article || {};\n  const lines = [];\n  const push = (label, value) => {\n    const text = String(value == null ? \"\" : value).trim();\n    if (text) lines.push(`[${label}] ${text}`);\n  };\n  push(\"기사 제목\", article.title);\n  push(\"기사 부제\", Array.isArray(article.subtitles) ? article.subtitles.join(\" / \") : \"\");\n  push(\"기사 본문\", article.body);\n\n  const facts = input.vacancy && typeof gwFactLines === \"function\" ? gwFactLines(input.vacancy) : \"\";\n  return lines.join(\"\\n\") + (facts ? `\\n\\n[물건 정보 — 확인된 사실]\\n${facts}` : \"\");\n}\n\n/* ══════════════════════════════════════════════════════════════\n   대본 쓰기 — AI 는 읽을 원고 전체(완성 대본)만 쓴다\n   ══════════════════════════════════════════════════════════════ */\nconst GW_YT_SCRIPT_SHAPE = `\\`\\`\\`json\n{\n  \"title\": \"유튜브 제목\",\n  \"narration\": [\"읽을 원고 첫 문단\", \"둘째 문단\"]\n}\n\\`\\`\\``;\n\n/* 원고 모양·출력 형식 — 일반·경매 공통 */\nconst GW_YT_OUTPUT = `[출력 형식]\n설명이나 인사말 없이 아래 형식의 유효한 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- narration 은 문단별 문자열 배열입니다. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n\nfunction gwBuildYtScriptPrompt(source, settings) {\n  /* 리모델링 작성기: 결과표가 원자료다 */\n  if (source && source.remodel && typeof gwBuildRemodelYtPrompt === \"function\") return gwBuildRemodelYtPrompt(source, settings);\n  if (gwYtIsAuction(source && source.vacancy)) return gwBuildYtAuctionScriptPrompt(source, settings);\n  const s = settings || {};\n  const type = GW_YT_VIDEO_TYPE[s.videoType] || GW_YT_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 유튜브 대본 작가입니다.\n아래 공실뉴스 기사와 확인된 물건 정보만 사용해 ${type.label} 영상의 내레이션 원고를 작성하십시오.\n\n${gwYtSourceText(source)}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[보도 원칙]\n- \"공실뉴스에 이런 물건이 나왔다\"는 객관적인 소개입니다. 3인칭 전달체로 쓰십시오.\n- 권유·호객 표현을 쓰지 마십시오: \"지금 바로 문의하세요\", \"놓치지 마세요\", \"강력 추천\", \"지금이 기회\" 등.\n- 중개사무소 이름·전화번호를 원고에 넣지 마십시오.\n\n[사실 원칙]\n- 자료에 없는 가격·면적·주소·시세·수익률·교통 시간·개발 호재·인터뷰를 만들지 마십시오.\n- 숫자와 고유명사는 자료 그대로 쓰십시오.\n- 실제 사진으로 확인되지 않은 내부·외관을 사실처럼 단정하지 마십시오.\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 마지막은 핵심 조건과 확인할 점을 정리하고 \"자세한 내용은 공실뉴스에서 확인할 수 있습니다.\"로 맺습니다.\n\n${GW_YT_OUTPUT}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   경매·공매 물건 대본\n\n   기사(경매 기사 프롬프트)와 같은 원칙을 따른다.\n   - 가격·일정·번호는 자료 그대로. 지어내면 큰 사고다\n   - 경매·공매 제도의 일반 설명은 해도 되지만, 투자 권유·낙찰가 예측은 어디서도 하지 않는다\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildYtAuctionScriptPrompt(source, settings) {\n  const s = settings || {};\n  const type = GW_YT_AUCTION_VIDEO_TYPE[s.videoType] || GW_YT_AUCTION_VIDEO_TYPE.listing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n  const vacancy = (source && source.vacancy) || {};\n  const saleKind = vacancy.saleKind === \"공매\" ? \"공매\" : \"경매\";\n  const saleName = saleKind === \"공매\" ? \"공매(온비드)\" : \"법원 경매\";\n\n  return `당신은 부동산 전문 매체 \"공실뉴스\"의 경매·공매 담당 유튜브 대본 작가입니다.\n아래 공실뉴스 기사와 확인된 ${saleName} 물건 정보만 사용해 ${type.label} 영상의 내레이션 원고를 작성하십시오.\n\n${gwYtSourceText(source)}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[보도 원칙]\n- \"공실뉴스 공실열람에 이런 ${saleKind} 물건이 나왔다\"는 객관적인 소개입니다. 3인칭 전달체로 쓰십시오.\n- 투자 권유·호객 표현을 쓰지 마십시오: \"싸게 살 기회\", \"놓치지 마세요\", \"지금이 기회\", \"강력 추천\", \"수익이 기대된다\", \"반값에 잡으세요\" 등.\n- 온비드 고객센터 등 정보제공업체 연락처(전화번호)를 넣지 마십시오.\n- \"본 정보는 참고용이며 법적 책임을 지지 않습니다\" 같은 입찰 전 법적 주의사항 안내문을 읽지 마십시오.\n\n[사실 원칙]\n- 감정가·최저입찰가·감정가 대비 비율·유찰 횟수·입찰 시작/마감·개찰일시·입찰보증금·면적·주소·사건번호(관리번호)·집행기관(관할법원)은 자료 그대로 쓰십시오.\n- 금액은 귀로 듣기 쉽게 억·만원 단위로 읽되(예: 2억 9,100만원) 자료의 숫자와 한 자리도 달라지면 안 됩니다.\n- 입찰 일정이 자료에 없으면 날짜를 만들지 마십시오.\n- 자료에 없는 권리관계·임차인·선순위 채권·체납액·건물 연식·낙찰 결과를 만들지 마십시오.\n- 낙찰가·낙찰가율·수익률·시세 상승을 예측하지 마십시오.\n- \"안전한 물건이다\", \"권리상 문제가 없다\", \"반드시 낙찰된다\" 같은 단정을 하지 마십시오.\n- 실제 사진으로 확인되지 않은 내부·외관을 사실처럼 단정하지 마십시오.\n\n[해설로 쓸 수 있는 것]\n- ${saleKind} 제도의 일반 설명은 한두 문장으로 짧게 넣어도 됩니다 — 유찰되면 최저입찰가가 낮아지는 구조, 입찰보증금, 개찰 절차, 명도의 의미 등.\n- ${saleKind} 물건을 볼 때 일반적으로 확인하는 점 — 현장 상태, 점유와 명도, 권리관계, 관리비 체납 같은 추가 비용.\n\n[원고 원칙]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다. 지역·물건 종류와 함께 최저입찰가나 유찰 횟수처럼 자료에 있는 사실로 시작하십시오. 과장하지 마십시오.\n- 첫 부분에서 ${saleKind} 물건이라는 점, 소재지, 물건 종류, 감정가와 최저입찰가를 밝히십시오.\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문은 쓰지 마십시오. 읽을 문장만 씁니다.\n- 마지막은 가격·일정 조건을 정리하고 \"권리관계와 물건 상태는 입찰 전 공고문과 현장에서 직접 확인할 필요가 있습니다. 자세한 내용은 공실뉴스 공실열람에서 확인할 수 있습니다.\"로 맺습니다.\n- title 은 [공실열람 ${saleKind}] 로 시작하고 지역·물건 종류·최저입찰가(또는 유찰 횟수)를 담으십시오.\n\n${GW_YT_OUTPUT}`;\n}\n\n/* 수정 요청 — 같은 대화에 이어 붙인다. 작업창에서 직접 고친 원고를 함께 보낸다. */\nfunction gwBuildYtRevisePrompt(full, request, vacancy) {\n  const current = {\n    title: full?.title || \"\",\n    narration: String(full?.text || \"\").split(/\\n{2,}/).map((p) => p.trim()).filter(Boolean),\n  };\n  const keep = gwYtIsAuction(vacancy)\n    ? `- 감정가·최저입찰가·유찰 횟수·입찰 일정·입찰보증금·면적·주소·사건번호(관리번호) 등 사실과 숫자는 바꾸거나 새로 만들지 마십시오.\n- 투자 권유, 낙찰가·수익 예측, 온비드 고객센터 연락처, 입찰 전 법적 주의사항 안내문을 넣지 마십시오.`\n    : `- 기사와 물건 정보의 사실·숫자는 바꾸거나 새로 만들지 마십시오.\n- 권유·호객 표현과 중개사무소 연락처를 넣지 마십시오.`;\n  return `아래 현재 유튜브 원고를 요청대로 고쳐 주십시오.\n\n[수정 요청]\n${String(request || \"\").trim()}\n\n[현재 원고]\n${JSON.stringify(current, null, 2)}\n\n[지킬 것]\n${keep}\n- 읽을 문장만 쓰고, 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 원고 전체를 빠짐없이 다시 출력하십시오. 고친 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n}\n\n/* ── 원고 길이 — 한국어 내레이션은 1초에 약 5.5글자(공백 제외)로 읽는다고 본다 ── */\nconst GW_YT_CHARS_PER_SEC = 5.5;\n\nconst gwYtCharCount = (text) => String(text || \"\").replace(/\\s/g, \"\").length;\n\nfunction gwYtSpeechSeconds(text) {\n  return Math.round(gwYtCharCount(text) / GW_YT_CHARS_PER_SEC);\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_YT_VIDEO_TYPE,\n    GW_YT_AUCTION_VIDEO_TYPE,\n    GW_YT_DURATION,\n    GW_YT_TONE,\n    gwYtVideoTypes,\n    gwYtSourceText,\n    gwBuildYtScriptPrompt,\n    gwBuildYtAuctionScriptPrompt,\n    gwBuildYtRevisePrompt,\n    gwYtCharCount,\n    gwYtSpeechSeconds,\n  };\n}\n",
 "remodel/youtube-json.js": "/* AI가 작성한 유튜브 장면 JSON 검증·정규화 */\n(() => {\n  \"use strict\";\n\n  function extract(raw) {\n    const text = String(raw || \"\").trim();\n    if (!text) return \"\";\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced?.[1]) return fenced[1].trim();\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first >= 0 && last > first ? text.slice(first, last + 1) : \"\";\n  }\n\n  function hasCompleteObject(raw) {\n    const text = String(raw || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n    for (let i = first; i < text.length; i += 1) {\n      const char = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (char === \"\\\\\") escaped = true;\n        else if (char === '\"') inString = false;\n        continue;\n      }\n      if (char === '\"') inString = true;\n      else if (char === \"{\") depth += 1;\n      else if (char === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n    return false;\n  }\n\n  function repair(raw) {\n    let output = \"\";\n    let inString = false;\n    let escaped = false;\n    for (let i = 0; i < raw.length; i += 1) {\n      const char = raw[i];\n      if (inString) {\n        if (escaped) {\n          output += char;\n          escaped = false;\n        } else if (char === \"\\\\\") {\n          output += char;\n          escaped = true;\n        } else if (char === '\"') {\n          output += char;\n          inString = false;\n        } else if (char === \"\\n\" || char === \"\\r\") {\n          if (char === \"\\r\" && raw[i + 1] === \"\\n\") i += 1;\n          output += \"\\\\n\";\n        } else if (char === \"\\t\") output += \"\\\\t\";\n        else output += char;\n        continue;\n      }\n      if (char === '\"') {\n        inString = true;\n        output += char;\n        continue;\n      }\n      if (char === \",\") {\n        let next = i + 1;\n        while (next < raw.length && /\\s/.test(raw[next])) next += 1;\n        if (raw[next] === \"}\" || raw[next] === \"]\") continue;\n      }\n      output += char;\n    }\n    return output;\n  }\n\n  function cleanText(value) {\n    return String(value == null ? \"\" : value).trim();\n  }\n\n  function normalizeScene(scene, index) {\n    if (!scene || typeof scene !== \"object\") return null;\n    const narration = cleanText(scene.narration || scene.script || scene.voiceover || scene.text);\n    const heading = cleanText(scene.heading || scene.title || `장면 ${index + 1}`);\n    const caption = cleanText(scene.caption || scene.subtitle || scene.onScreenText);\n    const visualPrompt = cleanText(scene.visualPrompt || scene.imagePrompt || scene.visual || scene.screen);\n    const visualType = cleanText(scene.visualType || scene.shotType || \"auto\");\n    if (!narration) return null;\n    return {\n      sceneId: cleanText(scene.sceneId),\n      heading,\n      narration,\n      caption,\n      visualType,\n      visualPrompt,\n    };\n  }\n\n  function normalize(data) {\n    if (!data || typeof data !== \"object\") return null;\n    const title = cleanText(data.title || data.videoTitle);\n    const description = cleanText(data.description || data.videoDescription);\n    const rawScenes = Array.isArray(data.scenes) ? data.scenes : [];\n    const scenes = rawScenes.map(normalizeScene).filter(Boolean);\n    if (!title || !scenes.length) return null;\n    return { title, description, scenes };\n  }\n\n  function parse(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    let data;\n    let repaired = false;\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repair(candidate));\n        repaired = true;\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n    const script = normalize(data);\n    if (!script) return { ok: false, reason: \"제목 또는 유효한 장면 대본이 없습니다.\" };\n    return { ok: true, script, repaired };\n  }\n\n  /* 모양을 따지지 않고 JSON 객체만 꺼낸다 — 완성 대본·장면 설명처럼 형식이 다른 답변에 쓴다 */\n  function parseObject(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    try {\n      return { ok: true, data: JSON.parse(candidate), repaired: false };\n    } catch (_strictError) {\n      try {\n        return { ok: true, data: JSON.parse(repair(candidate)), repaired: true };\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n  }\n\n  const api = { extract, hasCompleteObject, normalize, parse, parseObject };\n  globalThis.GWYoutubeJson = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})();\n\n",
 "remodel/sns-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   3 · SNS 작성 — 페이스북 · 인스타그램 · 스레드\n\n   - AI 에 한 번 요청해 세 플랫폼 글을 함께 받는다 (무료 체험도 \"SNS\" 1번).\n   - 리모델링 작성기: 공사 후 모습·예상 비용은 AI 시뮬레이션 \"예측\"이다. 글에서 확정처럼 쓰지 않고,\n     글 끝에 \"AI 예측 이미지\" 안내를 코드가 붙인다. 예측 이미지(kind \"ai\")는 실제 사진으로 치지 않는다 (AI 레이블 안내).\n   - 블로그와 같은 객관 보도 원칙. 스레드만 말투를 대화체로.\n   - 링크·출처(표시·광고 필수 정보)·해시태그는 AI 가 아니라 코드가 붙인다 (gwSnsCompose).\n   - 사진은 2번 기사 사진을 플랫폼별로 다시 고르고 비율대로 자른다 (gwSnsPickMedia · sns.js).\n   기획: docs/2026-10-03_sns_writer_tabs_meeting.md\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_SNS_CHANNELS = {\n  facebook: {\n    label: \"페이스북\",\n    badge: \"Facebook\",\n    homeUrl: \"https://www.facebook.com/\",\n    ratio: 1, // 정사각 1:1\n    ratioText: \"정사각 1:1\",\n    size: [1080, 1080],\n    maxMedia: 10,\n    maxChars: 0, // 사실상 제한 없음\n    maxTags: 5,\n  },\n  instagram: {\n    label: \"인스타그램\",\n    badge: \"Instagram\",\n    homeUrl: \"https://www.instagram.com/\",\n    ratio: 4 / 5, // 세로 4:5\n    ratioText: \"세로 4:5\",\n    size: [1080, 1350],\n    maxMedia: 10,\n    maxChars: 2200,\n    maxTags: 30,\n  },\n  threads: {\n    label: \"스레드\",\n    badge: \"Threads\",\n    homeUrl: \"https://www.threads.com/\",\n    ratio: 0, // 원본 비율\n    ratioText: \"원본 비율\",\n    size: [1600, 1600],\n    maxMedia: 10,\n    maxChars: 500, // 글 하나마다\n    maxTags: 1,\n  },\n};\n\nconst GW_SNS_ORDER = [\"facebook\", \"instagram\", \"threads\"];\n\nfunction gwSnsNoun(vacancy) {\n  return vacancy && vacancy.saleKind ? \"물건\" : \"매물\";\n}\n\nfunction gwBuildSnsPrompt(source) {\n  const input = source || {};\n  const noun = gwSnsNoun(input.vacancy);\n  const auction = noun === \"물건\";\n\n  return `당신은 부동산 정보를 정확하게 전하는 공실뉴스의 SNS 에디터입니다.\n아래 공실뉴스 기사와 확인된 ${noun} 정보로 페이스북·인스타그램·스레드 글을 한 번에 작성하십시오.\n세 글은 같은 사실을 전하지만 플랫폼마다 모양이 다릅니다. 같은 문장을 돌려 쓰지 마십시오.\n\n[참조 기사]\n${gwBlogArticleText(input.article)}\n\n[확인된 ${noun} 정보]\n${gwBlogFactLines(input.vacancy)}\n\n[보도 원칙 — 세 플랫폼 공통, 가장 먼저 지킬 것]\n- \"공실뉴스에 이런 ${noun}이 나왔다\"는 객관적인 ${auction ? \"물건\" : \"매물\"} 소식입니다. 광고 문구가 아닙니다\n- 권유·호객·광고 표현 금지: \"보세요\", \"추천합니다\", \"문의하세요\", \"연락 주세요\", \"DM 주세요\", \"놓치지 마세요\", \"급매\", \"지금이 기회\", \"역대급\" 등\n- 금액·면적·층·주소·관리비·입주일·주차·옵션 등 고유 조건은 위 두 자료에 실제로 있는 것만 쓸 것. 두 자료가 다르면 [확인된 ${noun} 정보]를 우선\n- 없는 수치·시세·수익률·개발 호재·현장 방문·고객 반응을 만들지 말 것. 자료에 없는 거리·도보 시간도 만들지 말 것\n- 소재지가 동까지만 공개됐다면 더 자세한 주소를 추측하지 말 것\n- 중개사무소 이름·연락처·링크·\"프로필 링크\" 안내는 쓰지 말 것 (글 끝에 자동으로 붙습니다)\n- 공사 후 모습·예상 공사비는 공실뉴스 리모델링 AI 시뮬레이션의 \"예측\"입니다. 확정된 결과처럼 쓰지 말고 \"예측\", \"예상\", \"시뮬레이션에 따르면\"으로 쓸 것\n- 시공 업체를 추천하거나 공사를 권하지 말 것\n\n[페이스북 — facebook]\n- 기사 소개형. 첫 문단 1~2문장이 피드에서 \"더 보기\" 전에 보이는 곳이므로 무엇이 어디에 어떤 조건으로 나왔는지 결론부터\n- 문단 3~5개, 문단마다 2~3문장, 전체 300~600자. 기사체 또는 부드러운 존댓말\n- 순서: 결론 → 위치·면적·금액 → 특징 → 주변 교통·생활 정보 → 확인할 점 한 문장\n- hashtags: 3~5개 (지역명·${noun} 종류 중심)\n\n[인스타그램 — instagram]\n- 사진이 주인공이고 글은 짧은 설명입니다. 한 줄에 정보 하나\n- lines 첫 줄: 25자 안팎의 훅 (지역 + ${noun} 핵심, 이모지 1개). 예: \"양재역 인근 36평 사무실 📍\"\n- 이어서 핵심 정보 3~5줄, 줄마다 알맞은 이모지 하나로 시작 (📍 위치 · 📐 면적 · 💰 금액 · 🚇 교통 · ✅ 특징 · 🏢 건물 등)\n- 마지막 1~2줄: 조건을 객관적으로 정리하는 한 문장\n- 전체 lines 6~10줄, 500자 이내\n- hashtags: 8~12개 (지역·동네·${noun} 종류·용도·거래 형태). 띄어쓰기 없이\n\n[스레드 — threads]\n- 말하듯 쓰는 짧은 글. 부드러운 존댓말 대화체(~네요, ~입니다)는 허용하되 사실 원칙은 같습니다\n- posts 첫 글: 450자 이내. 이것만 읽어도 무엇이 어디에 얼마로 나왔는지 알 수 있게\n- 첫 글은 독자의 생각을 묻는 질문 한 문장으로 끝낼 것 (예: \"이 조건이면 어떤 팀에 맞을까요?\"). 문의·연락을 유도하는 질문은 금지\n- 이어 쓰기 글 0~2개 (posts 둘째·셋째 항목): 교통·주변·확인할 점. 글마다 300자 이내\n- topic: 주제 태그 1개 (지역+${noun} 종류, 예: \"양재역사무실\")\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- 배열 한 항목에 문단(줄·글) 하나만 넣고, 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n- hashtags·topic 에는 # 기호를 넣지 마십시오. 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"facebook\": { \"paragraphs\": [\"첫 문단\", \"둘째 문단\"], \"hashtags\": [] },\n  \"instagram\": { \"lines\": [\"훅 한 줄\", \"📍 ...\"], \"hashtags\": [] },\n  \"threads\": { \"posts\": [\"첫 글\"], \"topic\": \"\" }\n}\n\\`\\`\\``;\n}\n\n/* 플랫폼 하나만 고친다 — 고친 플랫폼만 같은 JSON 모양으로 받는다 */\nfunction gwBuildSnsRevisePrompt(channel, request) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const shape = {\n    facebook: '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }',\n    instagram: '{ \"instagram\": { \"lines\": [], \"hashtags\": [] } }',\n    threads: '{ \"threads\": { \"posts\": [], \"topic\": \"\" } }',\n  }[channel] || '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }';\n  return `위에서 작성한 SNS 글 중 [${info.label}] 글만 아래 요청대로 고쳐 주십시오. 다른 플랫폼 글은 출력하지 마십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 금액·면적·층·주소 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 처음의 보도 원칙(권유·호객 표현 금지, 연락처·링크 쓰지 않기)과 ${info.label} 형식 규칙을 그대로 지키십시오.\n\n[출력 형식]\n설명 없이 아래 모양의 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n\\`\\`\\`json\n${shape}\n\\`\\`\\``;\n}\n\n/* ── AI 답변 → 편집용 모양 ──\n   facebook: { body: \"문단\\n\\n문단\", hashtags: [] }\n   instagram: { body: \"줄\\n줄\", hashtags: [] }\n   threads: { posts: [\"글\", …], topic: \"\" }\n   답변에 있는 플랫폼만 돌려준다 (수정 답변은 하나만 온다). */\nfunction gwSnsCleanTags(tags, max) {\n  const seen = new Set();\n  return (Array.isArray(tags) ? tags : String(tags || \"\").split(/[\\s,]+/))\n    .map((tag) => String(tag || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n    .filter((tag) => tag && !seen.has(tag) && seen.add(tag))\n    .slice(0, max || 30);\n}\n\nfunction gwSnsLines(value) {\n  return (Array.isArray(value) ? value : String(value || \"\").split(/\\n+/))\n    .map((line) => String(line == null ? \"\" : line).trim())\n    .filter(Boolean);\n}\n\nfunction gwSnsNormalize(data) {\n  if (!data || typeof data !== \"object\") return null;\n  const out = {};\n  const fb = data.facebook;\n  if (fb && typeof fb === \"object\") {\n    const paragraphs = gwSnsLines(fb.paragraphs || fb.text || fb.body);\n    if (paragraphs.length) out.facebook = { body: paragraphs.join(\"\\n\\n\"), hashtags: gwSnsCleanTags(fb.hashtags, GW_SNS_CHANNELS.facebook.maxTags) };\n  }\n  const ig = data.instagram;\n  if (ig && typeof ig === \"object\") {\n    const lines = gwSnsLines(ig.lines || ig.caption || ig.body);\n    if (lines.length) out.instagram = { body: lines.join(\"\\n\"), hashtags: gwSnsCleanTags(ig.hashtags, GW_SNS_CHANNELS.instagram.maxTags) };\n  }\n  const th = data.threads;\n  if (th && typeof th === \"object\") {\n    const posts = gwSnsLines(th.posts || th.text || th.body);\n    if (posts.length) out.threads = { posts, topic: gwSnsCleanTags([th.topic], 1)[0] || \"\" };\n  }\n  return Object.keys(out).length ? out : null;\n}\n\nfunction gwSnsParse(raw) {\n  const parsed = GWYoutubeJson.parseObject(raw); // ```json 상자 꺼내기·깨진 JSON 고치기는 유튜브와 같다\n  if (!parsed.ok) return parsed;\n  const posts = gwSnsNormalize(parsed.data);\n  if (!posts) return { ok: false, reason: \"페이스북·인스타그램·스레드 글을 찾지 못했습니다.\" };\n  return { ok: true, posts, repaired: parsed.repaired };\n}\n\n/* ── 글 끝에 붙는 것: 링크 · 출처(표시·광고 필수 정보) · 해시태그 ──\n   출처 문구는 블로그와 같다 (GWNaverBlog.sourceBlockLines). */\nfunction gwSnsSourceText(listing, noun) {\n  if (!listing) return \"\";\n  const { lines } = GWNaverBlog.sourceBlockLines(listing, \"\");\n  return [`[${noun} 정보 출처]`, ...lines].join(\"\\n\");\n}\n\n/* 글 끝에 늘 붙는 안내 — 예측 이미지를 실제 모습으로 오해하지 않게 */\nconst GW_SNS_SIM_NOTICE = \"※ 공사 후 모습은 공실뉴스 리모델링 AI 예측 이미지이며 실제와 다를 수 있습니다.\";\n\nfunction gwSnsCompose(channel, post, ctx) {\n  const c = ctx || {};\n  const notice = c.notice === undefined ? GW_SNS_SIM_NOTICE : c.notice;\n  /* 매물과 연결되지 않은 시뮬레이션 — \"매물\"이라고 하지 않는다 */\n  const linkLine = (u) => (c.noVacancy ? `▶ 공실뉴스에서 더 보기\\n${u}` : `▶ 공실뉴스에서 ${c.noun || \"매물\"} 자세히 보기\\n${u}`);\n  const noun = c.noun || \"매물\";\n  const url = c.url || \"\";\n  const source = gwSnsSourceText(c.listing, noun);\n  const tagLine = (tags) => (tags || []).map((tag) => `#${tag}`).join(\" \");\n\n  if (channel === \"threads\") {\n    const posts = (post?.posts || []).map((text) => String(text || \"\").trim()).filter(Boolean);\n    if (!posts.length) return { posts: [], text: \"\" };\n    if (post.topic) posts[0] = `${posts[0]}\\n\\n#${post.topic}`;\n    const tail = [notice, url ? linkLine(url) : \"\", source || c.credit || \"\"].filter(Boolean).join(\"\\n\\n\");\n    if (tail) {\n      const last = posts.length - 1;\n      if (posts[last].length + tail.length + 2 <= GW_SNS_CHANNELS.threads.maxChars) posts[last] = `${posts[last]}\\n\\n${tail}`;\n      else posts.push(tail);\n    }\n    return { posts, text: posts.join(\"\\n\\n―――\\n\\n\") };\n  }\n\n  const body = String(post?.body || \"\").trim();\n  if (!body) return { posts: [], text: \"\" };\n  const parts = [body];\n  if (channel === \"instagram\") {\n    /* 인스타 캡션의 링크는 눌리지 않는다 — 프로필 링크 안내를 먼저, 주소는 복사해 갈 수 있게 글자로 함께 */\n    const what = c.noVacancy ? \"자세한 내용은\" : `자세한 ${noun} 정보는`;\n    parts.push(url ? `${what} 프로필 링크 → 공실뉴스\\n${url}` : `${what} 프로필 링크 → 공실뉴스`);\n  } else if (url) {\n    parts.push(linkLine(url));\n  }\n  if (notice) parts.push(notice);\n  if (source) parts.push(source);\n  else if (c.credit) parts.push(c.credit);\n  const tags = tagLine(post.hashtags);\n  if (tags) parts.push(tags);\n  const text = parts.join(\"\\n\\n\");\n  return { posts: [text], text };\n}\n\n/* ── 사진 고르기: 2번 기사 사진 → 플랫폼별 순서·장수 ──\n   - 실제 사진(대표 먼저) → 공실목록 캡처(proof) → 지도·로드뷰 카드 → AI 이미지 순.\n   - 플랫폼 허용 장수(페이스북 4, 스레드 4, 인스타 10)까지 최대한 담고, 화면에서 직접 고르거나 뺄 수 있게 한다.\n   - 대표(1번)는 실제 사진이 있으면 반드시 실제 사진 — AI 이미지로 매물 사진을 대신하지 않는다. */\n/* 시뮬레이션 예측 이미지는 real 표시가 있어도 AI 가 그린 그림이다 — AI 레이블 안내·대표 규칙에서 AI 로 친다 */\nfunction gwSnsIsAi(item) {\n  return Boolean(item && item.kind === \"ai\");\n}\n\nfunction gwSnsPickMedia(channel, media) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const list = (Array.isArray(media) ? media : []).filter((item) => item && item.url);\n  const isCard = (item) => item.kind === \"map\" || item.kind === \"roadview\";\n  const isProof = (item) => item.kind === \"proof\";\n  const real = list.filter((item) => !gwSnsIsAi(item) && !isCard(item) && !isProof(item));\n  real.sort((a, b) => Number(Boolean(b.isCover)) - Number(Boolean(a.isCover)));\n  const proofs = list.filter(isProof);\n  const cards = list.filter(isCard);\n  const ai = list.filter(gwSnsIsAi);\n  return [...real, ...proofs, ...cards, ...ai]\n    .slice(0, info.maxMedia)\n    .map((item) => ({ url: item.url, kind: item.kind || \"photo\", caption: item.caption || \"\", ai: gwSnsIsAi(item) }));\n}\n\n/* 1번(대표) 자리에 AI 이미지를 둘 수 있는가 — 실제 사진이 하나라도 있으면 안 된다 */\nfunction gwSnsCanLead(list, index) {\n  const item = list && list[index];\n  if (!item || !item.ai) return true;\n  return !list.some((other) => other && !other.ai);\n}\n\n/* AI 이미지가 올라갈 사진에 섞여 있으면 \"게시할 때 AI 레이블을 켜세요\" 안내.\n   메타(페이스북·인스타·스레드)의 AI 레이블은 사진·영상용이라, 실제 사진만 올리면 켤 필요가 없다. */\nconst GW_SNS_AI_LABEL_WHERE = {\n  facebook: \"게시물 만들기 창의 이름 아래 [AI 레이블] 단추를 눌러 켜 주세요.\",\n  instagram: \"공유하기 전 캡션 화면의 [고급 설정]에서 [AI 레이블 추가]를 켜 주세요.\",\n  threads: \"게시하기 전 글쓰기 화면의 [AI 레이블] 설정을 켜 주세요.\",\n};\n\nfunction gwSnsAiLabelNote(channel, media) {\n  const info = GW_SNS_CHANNELS[channel];\n  if (!info) return \"\";\n  const count = (Array.isArray(media) ? media : []).slice(0, info.maxMedia).filter((item) => item && item.ai).length;\n  if (!count) return \"\";\n  return `AI로 만든 이미지 ${count}장이 들어 있습니다 — ${GW_SNS_AI_LABEL_WHERE[channel]}`;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_SNS_CHANNELS, GW_SNS_ORDER, gwBuildSnsPrompt, gwBuildSnsRevisePrompt,\n    GW_SNS_SIM_NOTICE, gwSnsNormalize, gwSnsParse, gwSnsCompose, gwSnsPickMedia, gwSnsCanLead, gwSnsCleanTags, gwSnsAiLabelNote,\n  };\n}\n",
 "marketing/marketing-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   공실마케팅 AI 채우기 — AI 매물보고서 · AI 유리창홍보지 (2026-10-15)\n\n   공실뉴스 스튜디오 앱이 회원이 구독한 ChatGPT 로 쓴다 (API 비용 없음).\n   도구가 지금 칸 글(틀 문구)을 보내면, 이 매물의 확인된 정보로 같은 칸을 충실하게 다시 쓴다.\n   - 숫자(금액·면적·층·관리비)는 매물 정보 그대로. 칸 글에 숫자를 새로 만들지 않는다\n   - 매물 정보에 없는 시세·수익률·개발 호재·역 이름·시설을 지어내지 않는다\n   - 표시·광고법: \"최고·유일·100%·무조건\" 같은 과장 금지\n   - 칸 길이는 지금 글과 비슷하게 (인쇄물 칸에 맞아야 한다)\n   이 파일은 서버 묶음으로만 앱에 내려간다 (studio-app/scripts/sync-ext.mjs, 설치 파일에 넣지 않음).\n   개인정보(집주인·의뢰인 이름·연락처·메모)는 앱이 매물 정보에서 아예 빼고 보낸다 (gwMkFacts 허용 목록).\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_MK_KIND = {\n  flyer: { label: \"유리창 홍보지\", role: \"사무실 유리창과 온라인에 붙이는 A4 한 장 매물 홍보지\" },\n  report: { label: \"매물보고서\", role: \"손님에게 보내거나 인쇄해 건네는 여러 페이지짜리 매물 소개 보고서\" },\n};\n\n/* 칸마다 쓰임과 길이 — 없는 칸은 \"지금 글과 같은 성격·길이\" */\nconst GW_MK_GUIDE = {\n  // 유리창 홍보지\n  promotionText: \"홍보지 위쪽에 크게 들어가는 한 줄 홍보 문구. 15~25자. 이 매물의 가장 큰 장점 하나. 금액은 따로 크게 들어가므로 넣지 말 것\",\n  subTitle: \"매물 특징 3가지를 ' | '로 이은 한 줄. 특징마다 4~12자 (예: 남향 채광 | 즉시 입주 | 주차 가능)\",\n  noticeTitle: \"코멘트 칸 제목. 8~16자\",\n  noticeContent: \"줄마다 '◼︎ '로 시작하는 4~5줄 (줄바꿈 \\\\n). 줄마다 15~32자. 손님이 알고 싶은 장점·조건을 매물 정보의 사실로만\",\n  // 매물보고서\n  coverTitle: \"표지 큰 제목. 지금 글과 비슷한 길이\",\n  coverSubtitle: \"표지 부제. 지금 글과 비슷한 길이\",\n  \"investmentSummary.box1Title\": \"요약 박스 1 제목. 영어 대문자 짧게(지금 형식 유지)\",\n  \"investmentSummary.box1Text\": \"요약 박스 1 글. 2줄(줄바꿈 \\\\n), 줄마다 6~14자\",\n  \"investmentSummary.box2Title\": \"요약 박스 2 제목. 영어 대문자 짧게\",\n  \"investmentSummary.box2Text\": \"요약 박스 2 글. 2줄, 줄마다 6~14자\",\n  \"investmentSummary.box3Title\": \"요약 박스 3 제목. 영어 대문자 짧게\",\n  \"investmentSummary.box3Text\": \"요약 박스 3 글. 2줄, 줄마다 6~14자\",\n  highlights: \"핵심 장점 목록. 지금과 같은 개수, 항목마다 12~30자\",\n  valuationText: \"가격·조건을 정리하는 해설 2~3문장. 매물 정보의 금액·조건만 쓰고 시세 비교·상승 전망을 만들지 말 것\",\n  page2HighlightBoxTitle: \"핵심 장점 상자 제목. 짧게\",\n  chartAdviseText: \"시세 그래프 아래 해설 2문장. 그래프 숫자는 중개사가 따로 넣는 값이므로 시세 수치·가치 상승 전망을 쓰지 말고, 이 매물의 금액·조건 정리와 '주변 시세는 상담 때 실거래 자료로 함께 확인' 같은 안내로 쓸 것\",\n  areaTargetName: \"입지 배지. 2줄(줄바꿈 \\\\n): 1줄 '○○동 일대', 2줄 입지 특징 한 마디\",\n  areaTargetDesc: \"입지 설명 2~3문장. 주변환경 정보에 있는 시설·교통만\",\n  areaBox1Title: \"입지 상자 1 제목. 지금 형식 유지 (예: TRANSIT / 교통)\",\n  areaBox1Text: \"입지 상자 1 글. 1~2문장, 40~70자. 교통 — 주변환경에 있는 것만\",\n  areaBox2Title: \"입지 상자 2 제목. 지금 형식 유지\",\n  areaBox2Text: \"입지 상자 2 글. 1~2문장, 40~70자. 생활 인프라 — 주변환경에 있는 것만\",\n  areaBox3Title: \"입지 상자 3 제목. 지금 형식 유지\",\n  areaBox3Text: \"입지 상자 3 글. 1~2문장, 40~70자. 이 매물의 쓰임새·장점 (개발 호재·가치 상승 전망은 쓰지 말 것)\",\n  page4TargetTitle: \"입지 지도 제목. 지금 글과 비슷한 길이\",\n  leaseRightTitle: \"임대 조건 상자 제목. 8~16자\",\n  leaseRightText: \"임대 조건 요약. 줄마다 '• '로 시작하는 3~5줄(줄바꿈 \\\\n). 매물 정보의 금액·관리비·면적·층·입주·주차만\",\n  page6FooterQuote: \"마지막 페이지 아래 인용 한 문장. 큰따옴표로 감쌀 것. 25~45자\",\n  \"roadmap.box1Title\": \"추천 포인트 카드 1 제목. 8~16자\",\n  \"roadmap.box1Text\": \"추천 포인트 카드 1 글. 2문장, 50~90자\",\n  \"roadmap.box2Title\": \"추천 포인트 카드 2 제목. 8~16자\",\n  \"roadmap.box2Text\": \"추천 포인트 카드 2 글. 2문장, 50~90자\",\n  \"roadmap.box3Title\": \"추천 포인트 카드 3 제목. 8~16자\",\n  \"roadmap.box3Text\": \"추천 포인트 카드 3 글. 2문장, 50~90자\",\n  \"roadmap.box4Title\": \"추천 포인트 카드 4 제목. 8~16자\",\n  \"roadmap.box4Text\": \"추천 포인트 카드 4 글. 2문장, 50~90자\",\n};\n\n/* ── 매물 정보 → 사실 줄 (허용 목록만 — 개인정보는 들어가지 않는다) ── */\nconst GW_MK_LABELS = {\n  building_name: \"건물·단지명\", sido: \"시도\", sigungu: \"시군구\", dong: \"동\", detail_addr: \"번지\",\n  property_type: \"물건 종류\", sub_category: \"세부 종류\", trade_type: \"거래 구분\",\n  deposit: \"보증금·매매가\", monthly_rent: \"월세\", maintenance_fee: \"관리비\",\n  exclusive_m2: \"전용면적(㎡)\", supply_m2: \"공급면적(㎡)\", current_floor: \"해당 층\", total_floor: \"전체 층\",\n  room_count: \"방 수\", bathroom_count: \"욕실 수\", direction: \"방향\", parking: \"주차\", move_in_date: \"입주 가능일\",\n  options: \"옵션\", description: \"매물 설명(중개사 작성)\", themes: \"특징 태그\",\n  approval_year: \"사용승인 연도\", constructor_name: \"건설사\", total_units: \"총 세대수\",\n};\nconst GW_MK_META_SKIP = /phone|memo|owner|landlord|client|contact|mobile|email|_flyer|secret|private|password|token/i;\n\nfunction gwMkWon(v) {\n  const n = Number(v) || 0;\n  if (n <= 0) return \"\";\n  const man = Math.round(n / 10000);\n  const eok = Math.floor(man / 10000);\n  const rest = man % 10000;\n  if (eok && rest) return `${eok}억 ${rest.toLocaleString()}만 원`;\n  if (eok) return `${eok}억 원`;\n  return `${man.toLocaleString()}만 원`;\n}\n\nfunction gwMkFacts(v) {\n  const x = v || {};\n  const lines = [];\n  const push = (label, value) => {\n    const t = Array.isArray(value) ? value.join(\", \") : String(value == null ? \"\" : value).trim();\n    if (t && t !== \"-\" && t !== \"null\") lines.push(`- ${label}: ${t.length > 600 ? `${t.slice(0, 600)}…` : t}`);\n  };\n  for (const [key, label] of Object.entries(GW_MK_LABELS)) {\n    let value = x[key];\n    if (value == null && x.metadata) value = x.metadata[key];\n    if ([\"deposit\", \"monthly_rent\", \"maintenance_fee\"].includes(key)) value = gwMkWon(value);\n    push(label, value);\n  }\n  // 주변환경 (공실 등록 때 모은 주변 시설·교통)\n  const infra = x.infrastructure && typeof x.infrastructure === \"object\" ? x.infrastructure : null;\n  if (infra) {\n    for (const [k, val] of Object.entries(infra)) {\n      if (k.startsWith(\"_\") || GW_MK_META_SKIP.test(k)) continue;\n      if (val && typeof val === \"object\" && !Array.isArray(val)) continue;\n      push(`주변환경 · ${k}`, val);\n    }\n  }\n  // 그 밖의 등록 정보 (토지 용도지역·도로 폭 등)\n  const meta = x.metadata && typeof x.metadata === \"object\" ? x.metadata : null;\n  if (meta) {\n    for (const [k, val] of Object.entries(meta)) {\n      if (GW_MK_LABELS[k] || GW_MK_META_SKIP.test(k)) continue;\n      if (val == null || typeof val === \"object\") continue;\n      push(`등록 정보 · ${k}`, val);\n    }\n  }\n  return lines.join(\"\\n\") || \"- (등록된 정보가 거의 없음 — 칸 글을 일반적이고 사실에 어긋나지 않게만 다듬을 것)\";\n}\n\n/* 지금 칸 글 → \"키: 쓰임 / 지금 글\" 목록 */\nfunction gwMkFieldLines(fields) {\n  const lines = [];\n  for (const [key, value] of Object.entries(fields || {})) {\n    if (value && typeof value === \"object\" && !Array.isArray(value)) {\n      for (const [sub, v] of Object.entries(value)) {\n        const k = `${key}.${sub}`;\n        lines.push(`- ${k}: ${GW_MK_GUIDE[k] || \"지금 글과 같은 성격·길이\"}\\n  지금 글: ${JSON.stringify(v)}`);\n      }\n    } else {\n      lines.push(`- ${key}: ${GW_MK_GUIDE[key] || \"지금 글과 같은 성격·길이\"}\\n  지금 글: ${JSON.stringify(value)}`);\n    }\n  }\n  return lines.join(\"\\n\");\n}\n\nfunction gwBuildMarketingPrompt(kind, vacancy, fields) {\n  const k = GW_MK_KIND[kind] || GW_MK_KIND.flyer;\n  return `당신은 부동산 중개사무소의 매물 마케팅 카피라이터입니다.\n아래 [매물 정보]만으로 \"${k.label}\"(${k.role})의 글 칸을 충실하게 채워 주십시오.\n지금 칸에는 어느 매물에나 쓰는 틀 문구가 들어 있습니다. 이 매물에 꼭 맞는 구체적인 문장으로 바꿔 주십시오.\n\n[매물 정보 — 공실뉴스에 등록된 확인된 사실]\n${gwMkFacts(vacancy)}\n\n[채울 칸 — 키: 쓰임과 길이 / 지금 글]\n${gwMkFieldLines(fields)}\n\n[사실 원칙 — 가장 먼저 지킬 것]\n- 금액·면적·층·관리비·방 수 같은 숫자는 [매물 정보]에 있는 그대로만 쓰십시오. 새 숫자를 만들거나 계산하지 마십시오.\n- [매물 정보]에 없는 시세·수익률·개발 호재·역 이름·학교·상가 이름·보안 설비·편의시설을 지어내지 마십시오.\n  주변환경이 없으면 교통·인프라 칸은 매물 자체의 장점(면적·층·방향·주차·입주일 등)으로 채우십시오.\n- \"최고\", \"유일\", \"100%\", \"무조건\", \"확실한 수익\" 같은 과장·단정 표현을 쓰지 마십시오 (부동산 표시·광고 기준).\n- 중개사무소 이름·전화번호는 칸에 쓰지 마십시오 (홍보지에 따로 들어갑니다).\n- [채울 칸]의 모든 칸을 빠짐없이 출력하십시오. 틀 문구를 그대로 두지 말고 이 매물에 맞게 새로 쓰십시오.\n\n[문체와 모양]\n- 손님이 한눈에 읽는 홍보물입니다. 짧고 분명하게, 따뜻하지만 차분한 말투로 쓰십시오.\n- 칸마다 [채울 칸]에 적힌 길이를 지키십시오. 인쇄물 칸에 맞아야 합니다.\n- 지금 글이 영어 제목 형식이면 그 형식을 유지하십시오.\n- 줄바꿈이 필요한 칸은 문자열 안에 \\\\n 으로 쓰십시오.\n\n[출력 형식]\n설명 없이 아래처럼 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- 키는 [채울 칸]의 키 그대로 쓰고, 점(.)이 있는 키는 점 앞 이름의 객체 안에 넣으십시오. 예: \"roadmap.box1Title\" → { \"roadmap\": { \"box1Title\": \"…\" } }\n- 목록 칸(배열)은 지금과 같은 개수의 문자열 배열로 쓰십시오.\n- JSON.parse 가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{ \"키\": \"새 글\" }\n\\`\\`\\``;\n}\n\n/* AI 답변 → 지금 칸과 같은 모양만 골라 돌려준다 (없는 키·모양이 다른 값은 버린다) */\nfunction gwParseMarketing(text, fields) {\n  const raw = String(text || \"\");\n  const start = raw.indexOf(\"{\");\n  if (start < 0) return { ok: false, reason: \"AI 답변에서 JSON 을 찾지 못했습니다.\" };\n  let depth = 0, inStr = false, esc = false, end = -1;\n  for (let i = start; i < raw.length; i++) {\n    const c = raw[i];\n    if (inStr) {\n      if (esc) esc = false;\n      else if (c === \"\\\\\") esc = true;\n      else if (c === '\"') inStr = false;\n      continue;\n    }\n    if (c === '\"') inStr = true;\n    else if (c === \"{\") depth++;\n    else if (c === \"}\" && --depth === 0) { end = i; break; }\n  }\n  if (end < 0) return { ok: false, reason: \"AI 답변이 끝나지 않았습니다.\" };\n  let obj = null;\n  const body = raw.slice(start, end + 1);\n  for (const fix of [(s) => s, (s) => s.replace(/[“”]/g, '\"').replace(/,\\s*([}\\]])/g, \"$1\")]) {\n    try { obj = JSON.parse(fix(body)); break; } catch (_) { /* 다음 */ }\n  }\n  if (!obj || typeof obj !== \"object\") return { ok: false, reason: \"AI 답변의 JSON 을 읽지 못했습니다.\" };\n\n  const out = {};\n  const clean = (v) => String(v).trim();\n  for (const [key, cur] of Object.entries(fields || {})) {\n    // \"roadmap.box1Title\" 처럼 점으로 펴서 준 경우도 받는다\n    let val = obj[key];\n    if (cur && typeof cur === \"object\" && !Array.isArray(cur)) {\n      const next = {};\n      for (const sub of Object.keys(cur)) {\n        const v = (val && typeof val === \"object\" ? val[sub] : undefined) ?? obj[`${key}.${sub}`];\n        if (typeof v === \"string\" && v.trim()) next[sub] = clean(v);\n      }\n      if (Object.keys(next).length) out[key] = { ...cur, ...next };\n    } else if (Array.isArray(cur)) {\n      if (Array.isArray(val)) {\n        const list = val.map((v) => clean(v)).filter(Boolean);\n        if (list.length) out[key] = list.slice(0, Math.max(cur.length, 1) + 1);\n      }\n    } else if (typeof val === \"string\" && val.trim()) {\n      out[key] = clean(val);\n    }\n  }\n  if (!Object.keys(out).length) return { ok: false, reason: \"AI 답변에 채울 글이 없습니다.\" };\n  return { ok: true, fields: out };\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = { GW_MK_KIND, GW_MK_GUIDE, gwMkFacts, gwBuildMarketingPrompt, gwParseMarketing };\n}\n",
 "newsmaker/sections.js": "/* ══════════════════════════════════════════════════════════════\n   공실뉴스 뉴스 카테고리 — 기사쓰기 폼(NewsWriteForm)의 1·2차 섹션과 글자까지 같아야 한다\n\n   매물 전용인 \"공실뉴스\" 섹션은 뺐다. \"자유\"는 AI 가 아래 표에서 맞는 섹션을 고른다.\n   부동산·경제 · 라이프·오피니언의 가운뎃점은 U+00B7(·)이다. 폼의 option value 와 한 글자라도 다르면\n   기사쓰기 폼에서 섹션이 선택되지 않는다.\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_SECTIONS = {\n  \"부동산·경제\": {\n    short: \"부동산·경제\",\n    guide: \"부동산 시장·정책·경제 흐름을 독자의 집과 돈 문제로 풀어 주는 경제 기사\",\n    subs: {\n      \"부동산정책/정치\": \"정책·제도 변화가 무엇이고, 누가 어떤 영향을 받는지 풀어 주는 정책 해설\",\n      \"경제/재테크/주식\": \"금리·물가·자산 흐름을 생활 속 돈 관리 관점에서 풀어 주는 재테크 기사\",\n      \"세무/법률/기타\": \"세금·계약·법률 제도를 사례 중심으로 쉽게 풀어 주는 생활 법률 기사\",\n    },\n  },\n  \"AI마케팅\": {\n    short: \"AI마케팅\",\n    guide: \"AI 도구와 온라인 마케팅을 부동산 실무자·소상공인이 바로 써먹을 수 있게 풀어 주는 실무 기사\",\n    subs: {\n      \"AI/NEWS\": \"AI 서비스·기술 소식이 무엇이고 실무에 어떤 의미가 있는지 전하는 IT 기사\",\n      \"부동산유튜브/블로그\": \"유튜브·블로그 운영과 콘텐츠 제작 요령을 실무 관점에서 전하는 기사\",\n      \"공실/임대관리\": \"공실을 줄이고 임대를 관리하는 방법을 실무 사례 중심으로 전하는 기사\",\n    },\n  },\n  \"라이프·오피니언\": {\n    short: \"라이프\",\n    guide: \"일상에서 바로 도움이 되는 생활 정보와 사람 이야기를 흥미롭게 전하는 라이프 기사\",\n    subs: {\n      \"인물/인터뷰\": \"인물의 활동과 생각을 소개하는 인물 기사 (실제 인터뷰가 없으면 공개된 활동만 소개)\",\n      \"중개실무/인테리어Tip\": \"중개 현장과 집 꾸미기에서 바로 써먹는 요령을 전하는 생활 실무 기사\",\n      \"맛집/여행/건강\": \"먹거리·나들이·건강 정보를 실생활에 도움이 되게 전하는 생활 기사\",\n      \"스포츠/연예/기타\": \"스포츠·연예·화제 소식을 흥미롭게 전하는 가벼운 기사\",\n    },\n  },\n};\n\n/* 작업창의 1차 칩 — 자유는 섹션이 아니라 \"AI 가 골라 줘\"라는 뜻이다 */\nconst GW_SECTION_FREE = \"자유\";\n\nfunction gwSectionNames() {\n  return Object.keys(GW_SECTIONS);\n}\n\nfunction gwSubSectionNames(section1) {\n  const table = GW_SECTIONS[section1];\n  return table ? Object.keys(table.subs) : [];\n}\n\n/* 1·2차가 폼에 실제로 있는 조합인가 */\nfunction gwIsValidSection(section1, section2) {\n  const table = GW_SECTIONS[section1];\n  return Boolean(table && (!section2 || Object.prototype.hasOwnProperty.call(table.subs, section2)));\n}\n\n/* AI 가 고른 섹션은 가운뎃점·공백이 조금 달라도 폼의 이름으로 맞춰 준다. 못 맞추면 빈 값 */\nfunction gwNormalizeSection(section1, section2) {\n  const squash = (value) => String(value || \"\").replace(/[\\s·ㆍ•.\\-]/g, \"\").toLowerCase();\n  const first = gwSectionNames().find((name) => squash(name) === squash(section1)) || \"\";\n  if (!first) return { section1: \"\", section2: \"\" };\n  const second = gwSubSectionNames(first).find((name) => squash(name) === squash(section2)) || \"\";\n  return { section1: first, section2: second };\n}\n\n/* 프롬프트에 넣을 \"고를 수 있는 섹션\" 목록 */\nfunction gwSectionMenuText() {\n  return gwSectionNames()\n    .map((first) => `- ${first}: ${gwSubSectionNames(first).join(\" / \")}`)\n    .join(\"\\n\");\n}\n\n/* 고른 섹션의 글 성격 안내 */\nfunction gwSectionGuide(section1, section2) {\n  const table = GW_SECTIONS[section1];\n  if (!table) return \"\";\n  const sub = section2 && table.subs[section2];\n  return sub ? `${table.guide}. 세부 분야: ${section2} — ${sub}` : table.guide;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_SECTIONS,\n    GW_SECTION_FREE,\n    gwSectionNames,\n    gwSubSectionNames,\n    gwIsValidSection,\n    gwNormalizeSection,\n    gwSectionMenuText,\n    gwSectionGuide,\n  };\n}\n",
 "newsmaker/market-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   2단계 소재 — \"단지 시세\" · \"우리동네 시세\" (국토부 실거래가)\n\n   단지 이름이나 동 이름만 넣으면 공실뉴스 서버(/api/extension/apt-trades)가 국토교통부 실거래가에서\n   숫자를 계산해 돌려준다. AI 는 그 숫자로 문장만 쓴다 — 숫자·인용·전망을 지어내지 않게.\n   기획: docs/2026-10-03_newsmaker_complex_and_local_plan.md (회의로 고친 방향)\n\n   source.complex = { query, data, view, asking }   // data = 서버 응답, view = 분석 관점, asking = 호가(선택, 사용자 입력)\n   source.local   = { query, data, view, themes[] } // view = 분석 관점(기본 객관적 브리핑), themes = 동네 테마 칩\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_MARKET_VIEWS = {\n  brief: { label: \"객관적 브리핑\", guide: \"최근 거래 사실을 중립적으로 정리하는 시세 브리핑. 오르내림을 평가하지 말고 숫자를 순서대로 전할 것\" },\n  high: { label: \"신고가·회복\", guide: \"기간 최고가와 최근 거래를 비교해 가격 회복·신고가 여부를 짚을 것. 표에 최고가 기록이 없으면 '신고가'라고 쓰지 말 것\" },\n  flow: { label: \"거래 흐름\", guide: \"면적별 거래 건수와 거래 시점의 흐름을 중심으로 쓸 것. 매수·매도자의 심리나 분위기를 지어내지 말 것\" },\n  jeonse: { label: \"전세가율\", guide: \"최근 전세 거래와 전세가율(매매가 대비 전세가 비율)을 중심으로, 실거주·임대 수요 관점에서 쓸 것\" },\n};\n\nconst GW_LOCAL_VIEWS = {\n  brief: { label: \"객관적 브리핑\", guide: \"동네 거래 건수·가격 변화와 거래 많은 단지를 중립적으로 정리하는 브리핑. 좋다·나쁘다 평가 없이 숫자를 차례로 전할 것\" },\n  story: { label: \"동네 흐름 해설\", guide: \"숫자가 동네 실수요자에게 어떤 의미인지 풀어 주는 해설. 고른 테마를 관점으로 삼되 자료에 없는 사실은 쓰지 말 것\" },\n};\n\nconst GW_LOCAL_THEMES = [\"학군\", \"역세권·교통\", \"재건축·재개발\", \"거래량 변화\", \"전세 시장\"];\n\n/* 만원 → \"24억 5,000만 원\" */\nfunction gwPrice(manwon) {\n  const value = Number(manwon) || 0;\n  if (!value) return \"-\";\n  const eok = Math.floor(value / 10000);\n  const rest = value % 10000;\n  if (!eok) return `${rest.toLocaleString(\"ko-KR\")}만 원`;\n  return rest ? `${eok}억 ${rest.toLocaleString(\"ko-KR\")}만 원` : `${eok}억 원`;\n}\n\nconst gwTradeLine = (t) => (t ? `${t.date} ${gwPrice(t.price)} (${t.floor}층, 전용 ${t.area}㎡)` : \"기록 없음\");\n\nfunction gwMarketReady(source) {\n  if (!source) return false;\n  if (source.mode === \"complex\") return Boolean(source.complex && source.complex.data && source.complex.data.summary && source.complex.data.summary.tradeCount > 0);\n  if (source.mode === \"local\") return Boolean(source.local && source.local.data && source.local.data.summary && (source.local.data.summary.recentCount + source.local.data.summary.beforeCount) > 0);\n  return false;\n}\n\nfunction gwMarketLabel(source) {\n  if (source.mode === \"complex\") {\n    const d = source.complex && source.complex.data;\n    return d ? `${d.complexName || d.target.name} 실거래 시세` : \"\";\n  }\n  const d = source.local && source.local.data;\n  return d ? `${d.target.name} 아파트 시세` : \"\";\n}\n\n/* 서버 자료 → AI 에 주는 표 (사람이 읽어도 되는 모양) */\nfunction gwComplexDataText(c) {\n  const d = c.data;\n  const s = d.summary;\n  const lines = [\n    `- 단지: ${d.complexName || d.target.name}`,\n    `- 소재지: ${d.target.address}`,\n    s.buildYear ? `- 준공: ${s.buildYear}년` : \"\",\n    `- 자료 기간: ${d.period}`,\n    `- 기간 안 매매 신고: ${s.tradeCount}건`,\n  ].filter(Boolean);\n  for (const a of s.areas.slice(0, 4)) {\n    lines.push(`\\n[전용 ${a.areaKey} · 약 ${a.pyeong}평] 매매 ${a.tradeCount}건`);\n    lines.push(`- 가장 최근 매매: ${gwTradeLine(a.latest)}`);\n    if (a.previous) lines.push(`- 그 직전 매매: ${gwTradeLine(a.previous)}`);\n    lines.push(`- 기간 최고가: ${gwTradeLine(a.high)}`);\n    lines.push(`- 기간 최저가: ${gwTradeLine(a.low)}`);\n    if (a.latestJeonse) lines.push(`- 가장 최근 전세: ${a.latestJeonse.date} 보증금 ${gwPrice(a.latestJeonse.deposit)} (${a.latestJeonse.floor}층)`);\n    if (a.jeonseRatio) lines.push(`- 전세가율(최근 6개월 전세 중앙값 ÷ 매매 중앙값): 약 ${a.jeonseRatio}%`);\n  }\n  const asking = String(c.asking || \"\").trim();\n  lines.push(`\\n[호가 — 사용자가 직접 적은 현재 매물 가격]\\n${asking || \"없음 — 호가·매물 분위기는 쓰지 말 것\"}`);\n  return lines.join(\"\\n\");\n}\n\nfunction gwLocalDataText(l) {\n  const d = l.data;\n  const s = d.summary;\n  const change = (now, before) => (before ? `${now > before ? \"+\" : \"\"}${Math.round(((now - before) / before) * 1000) / 10}%` : \"비교 불가\");\n  const lines = [\n    `- 지역: ${d.target.name}`,\n    `- 자료 기간: ${d.period}`,\n    `- 아파트 매매 신고 (최근 ${s.periodRecent}): ${s.recentCount}건 · 3.3㎡당 중앙값 ${gwPrice(s.recentMedianPerPyeong)}`,\n    `- 아파트 매매 신고 (그 전 ${s.periodBefore}): ${s.beforeCount}건 · 3.3㎡당 중앙값 ${gwPrice(s.beforeMedianPerPyeong)}`,\n    `- 변화: 거래 건수 ${change(s.recentCount, s.beforeCount)} · 3.3㎡당 중앙값 ${change(s.recentMedianPerPyeong, s.beforeMedianPerPyeong)}`,\n    `- 전세 신고 (최근 ${s.periodRecent}): ${s.recentJeonseCount}건 · 3.3㎡당 보증금 중앙값 ${gwPrice(s.recentJeonseMedianPerPyeong)}`,\n    `- 신고 진행 중이라 비교에서 뺀 달: ${s.pendingMonths} (이 기간 매매 ${s.pendingCount}건이 지금까지 신고됨 — 더 늘어날 수 있음)`,\n    `- 최근 ${s.periodRecent} 매매가 있었던 단지 수: ${s.complexCount}곳`,\n    `\\n[거래가 많았던 단지 — 최근 ${s.periodRecent}]`,\n  ];\n  s.topComplexes.forEach((c, i) => {\n    lines.push(`${i + 1}. ${c.name}: 매매 ${c.tradeCount}건 · 3.3㎡당 중앙값 ${gwPrice(c.medianPerPyeong)} · 가장 최근 ${gwTradeLine(c.latest)}`);\n  });\n  const themes = (l.themes || []).filter((t) => GW_LOCAL_THEMES.includes(t));\n  lines.push(`\\n[사용자가 고른 동네 테마 — 기사 관점]\\n${themes.length ? themes.join(\", \") : \"없음\"}`);\n  return lines.join(\"\\n\");\n}\n\nfunction gwMarketText(source) {\n  const angle = String(source.angle || \"\").trim();\n  const angleText = angle ? `\\n\\n[추가 요청 — 사용자가 바라는 관점]\\n${angle}` : \"\";\n  if (source.mode === \"complex\") {\n    const view = GW_MARKET_VIEWS[source.complex.view] || GW_MARKET_VIEWS.brief;\n    return `[아파트 단지 실거래 자료 — 국토교통부 실거래가 공개 자료를 공실뉴스가 정리]\\n${gwComplexDataText(source.complex)}\\n\\n[분석 관점] ${view.label}\\n- ${view.guide}${angleText}`;\n  }\n  const localView = GW_LOCAL_VIEWS[source.local.view] || GW_LOCAL_VIEWS.brief;\n  return `[동네 아파트 실거래 자료 — 국토교통부 실거래가 공개 자료를 공실뉴스가 정리]\\n${gwLocalDataText(source.local)}\\n\\n[분석 관점] ${localView.label}\\n- ${localView.guide}${angleText}`;\n}\n\nfunction gwMarketIntro(source) {\n  return source.mode === \"complex\"\n    ? \"아래 아파트 단지의 실거래 자료로 공실뉴스 독자를 위한 시세 기사 1건을 작성하십시오.\"\n    : \"아래 동네의 아파트 실거래 자료로 공실뉴스 우리동네뉴스에 실을 동네 시세 기사 1건을 작성하십시오.\";\n}\n\nfunction gwMarketRules(source) {\n  const local = source.mode === \"local\";\n  return `════════ 실거래 기사 원칙 — 가장 먼저 지키십시오 ════════\n\n【숫자 원칙】\n- 금액·면적·층·건수·날짜·비율은 위 자료에 있는 숫자만 쓰십시오. 계산하거나 반올림해 새 숫자를 만들지 마십시오.\n- 출처를 밝히십시오: \"국토교통부 실거래가 공개시스템에 따르면\", \"신고 기준\" 같은 표현을 넣으십시오.\n- 실거래는 계약 후 30일 안에 신고되므로 최근 거래는 더 늘어날 수 있다는 점을 한 번 밝히십시오.\n- 자료에 없는 시세·호가·대출·금리·입주 물량·개발 계획·학교 배정 같은 사실이나 수치를 만들지 마십시오.\n- ${local ? \"고른 테마는 기사의 관점일 뿐입니다. 자료에 없는 학군 순위·역 개통 일정·재건축 진행 단계 같은 구체적 사실은 쓰지 말고, 필요하면 \\\"~를 확인할 필요가 있다\\\"로 쓰십시오.\" : \"호가는 사용자가 적은 내용이 있을 때만 \\\"현재 매물 호가는 ~로 확인된다\\\"처럼 쓰십시오. 없으면 호가·매물 분위기를 쓰지 마십시오.\"}\n\n【인용·전망 금지】\n- 중개업소·전문가·주민의 말을 인용하지 마십시오. 인터뷰한 것처럼 쓰지 마십시오.\n- 가격 전망(\"오를 것\", \"바닥을 찍었다\")을 단정하지 마십시오. 해석이 필요하면 자료로 확인되는 범위에서 \"~로 나타났다\"로 쓰십시오.\n- 매수·매도를 권하거나 집값을 부추기는 표현(\"지금이 기회\", \"막차\", \"급등\")을 쓰지 마십시오.\n\n【쉽게 쓰기】   ★ 부동산을 잘 모르는 독자도 읽게\n- 전세가율·3.3㎡당 가격·중앙값·전용면적·실거래가 신고 기준 같은 말은 처음 나올 때 쉬운 말로 한 번 풀어 주십시오.\n  (예: \"전세가율, 즉 매매가 대비 전세가 비율은\", \"3.3㎡(1평)당 가격의 가운데 값은\")\n- 큰 금액은 \"31억 3,000만 원\"처럼 읽기 쉽게 쓰고, 한 문장에 숫자를 세 개 넘게 몰아 넣지 마십시오.\n\n【구성】\n- 첫 문단에 ${local ? \"동네 이름과 최근 거래 흐름(건수·3.3㎡당 가격 변화)\" : \"단지 이름과 가장 최근 실거래(날짜·면적·가격)\"}을 밝히십시오.\n- ${local ? \"특정 단지를 띄우지 말고 동네 전체 흐름을 먼저 전한 뒤 거래가 많았던 단지를 차례로 비교하십시오.\" : \"면적별로 최근 거래, 직전 거래 대비 변화, 기간 최고·최저가를 비교하십시오.\"}\n- 마지막 문단은 자료의 한계(신고 기준, 최근 달 집계 중)와 실제 거래 전에 확인할 점으로 마무리하십시오.`;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_MARKET_VIEWS, GW_LOCAL_VIEWS, GW_LOCAL_THEMES, gwPrice, gwMarketReady, gwMarketLabel, gwMarketText, gwMarketIntro, gwMarketRules,\n  };\n}\n",
 "newsmaker/prompt.js": "/* ══════════════════════════════════════════════════════════════\n   뉴스메이커 기사 프롬프트 — 기사 기본틀은 여기 한 곳에만 있다\n\n   소재(source)는 네 가지다.\n   - news    : 가져온 뉴스 원문. 사실만 뽑아 공실뉴스 기사로 \"완전히 새로\" 쓴다 (원문 문장 옮기기 금지, 출처 표기)\n   - complex : 아파트 단지 이름 → 국토부 실거래가로 계산한 표 (shared/market-prompt.js)\n   - local   : 동 이름 → 그 동네 아파트 실거래 흐름 (shared/market-prompt.js)\n   - topic   : 사용자가 넣은 주제와 참고 메모. 확정된 일반 지식과 메모의 사실로 쓴다 (수치·인물·통계 지어내기 금지)\n\n   source = {\n     mode: \"news\" | \"complex\" | \"local\" | \"topic\",\n     complex: { query, data, view, asking },  local: { query, data, themes[] },   // market-prompt.js 머리말\n     news: { title, publisher, publishedAt, url, body, truncated } | null,\n     topic: { subject, intro, points[], outro, memo },   // 서론·본론(여러 개)·결론은 비워도 된다\n     angle: \"\",                    // 추가로 바라는 관점·요청 (두 소재 공통)\n     section1: \"부동산·경제\" | … | \"자유\",\n     section2: \"\" | 2차 섹션,\n   }\n   섹션 표는 shared/sections.js 에 있다.\n   ══════════════════════════════════════════════════════════════ */\n\n/* 소재가 쓸 만큼 준비됐는가 */\nconst gwIsMarket = (source) => Boolean(source && (source.mode === \"complex\" || source.mode === \"local\"));\n\nfunction gwSourceReady(source) {\n  if (!source) return false;\n  if (gwIsMarket(source)) return gwMarketReady(source); // shared/market-prompt.js\n  if (source.mode === \"news\") return Boolean(source.news && source.news.title && source.news.body);\n  return Boolean(source.topic && String(source.topic.subject || \"\").trim());\n}\n\n/* 소재 한 줄 이름 — 화면 표시·이미지 프롬프트용 */\nfunction gwSourceLabel(source) {\n  if (!source) return \"\";\n  if (gwIsMarket(source)) return gwMarketLabel(source);\n  if (source.mode === \"news\" && source.news) {\n    return `${source.news.publisher ? `[${source.news.publisher}] ` : \"\"}${source.news.title}`;\n  }\n  return String((source.topic && source.topic.subject) || \"\").trim();\n}\n\n/* 뉴스 보도일을 \"2026년 9월 29일\"처럼 — 못 읽으면 원래 글자 그대로 */\nfunction gwNewsDate(value) {\n  const text = String(value || \"\").trim();\n  if (!text) return \"\";\n  const date = new Date(text);\n  if (Number.isNaN(date.getTime())) return text;\n  return `${date.getFullYear()}년 ${date.getMonth() + 1}월 ${date.getDate()}일`;\n}\n\n/* 소재를 프롬프트에 넣을 글로 */\nfunction gwSourceText(source) {\n  const s = source || {};\n  if (gwIsMarket(s)) return gwMarketText(s);\n  const angle = String(s.angle || \"\").trim();\n  const angleText = angle ? `\\n\\n[추가 요청 — 사용자가 바라는 관점]\\n${angle}` : \"\";\n\n  if (s.mode === \"news\" && s.news) {\n    const n = s.news;\n    return `[원문 기사 — 사실 자료]\n- 언론사: ${n.publisher || \"확인 안 됨\"}\n- 원문 제목: ${n.title}\n${n.publishedAt ? `- 보도일: ${gwNewsDate(n.publishedAt)}\\n` : \"\"}- 원문 본문${n.truncated ? \" (길어서 앞부분만 옮김)\" : \"\"}:\n${n.body}${angleText}`;\n  }\n\n  const t = s.topic || {};\n  const memo = String(t.memo || \"\").trim();\n  const outline = gwOutlineText(t);\n  return `[주제]\n${String(t.subject || \"\").trim()}\n${outline ? `\\n[글 뼈대 — 사용자가 정한 순서]\\n${outline}\\n` : \"\"}\n[참고 메모 — 사용자가 준 자료]\n${memo || \"없음 — 널리 확정된 일반 지식으로만 쓸 것\"}${angleText}`;\n}\n\n/* 주제의 서론·본론·결론 칸 — 채운 칸만 모은다 */\nfunction gwOutlinePoints(topic) {\n  return (Array.isArray(topic && topic.points) ? topic.points : [])\n    .map((point) => String(point || \"\").trim())\n    .filter(Boolean);\n}\n\nfunction gwHasOutline(topic) {\n  const t = topic || {};\n  return Boolean(String(t.intro || \"\").trim() || String(t.outro || \"\").trim() || gwOutlinePoints(t).length);\n}\n\nfunction gwOutlineText(topic) {\n  if (!gwHasOutline(topic)) return \"\";\n  const t = topic || {};\n  const empty = \"(비워 둠 — 주제에 맞게 직접 채울 것)\";\n  const lines = [`- 서론: ${String(t.intro || \"\").trim() || empty}`];\n  const points = gwOutlinePoints(t);\n  if (points.length) points.forEach((point, i) => lines.push(`- 본론 ${i + 1}: ${point}`));\n  else lines.push(`- 본론: ${empty}`);\n  lines.push(`- 결론: ${String(t.outro || \"\").trim() || empty}`);\n  return lines.join(\"\\n\");\n}\n\n/* ── 섹션 지시 ── 자유면 AI 가 고르고, 1차만 골랐으면 2차를 AI 가 고른다 */\nfunction gwSectionText(source) {\n  const s = source || {};\n  const first = s.section1;\n  if (!first || first === GW_SECTION_FREE || !GW_SECTIONS[first]) {\n    return `[공실뉴스 섹션] 아래 목록에서 이 기사에 가장 맞는 1차·2차 섹션을 하나씩 골라 JSON 의 section1·section2 에 목록 글자 그대로 쓰십시오.\n${gwSectionMenuText()}`;\n  }\n  if (!s.section2) {\n    return `[공실뉴스 섹션] ${first}\n- 글 성격: ${gwSectionGuide(first)}\n- 2차 섹션은 다음 중 가장 맞는 것을 골라 JSON 의 section2 에 글자 그대로 쓰십시오: ${gwSubSectionNames(first).join(\" / \")}\n- section1 에는 \"${first}\" 를 그대로 쓰십시오.`;\n  }\n  return `[공실뉴스 섹션] ${first} > ${s.section2}\n- 글 성격: ${gwSectionGuide(first, s.section2)}\n- JSON 의 section1 에는 \"${first}\", section2 에는 \"${s.section2}\" 를 그대로 쓰십시오.`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   분량과 기사 스타일 — 작업창에서 고른다\n   ══════════════════════════════════════════════════════════════ */\nconst GW_LENGTH = {\n  short:  { label: \"짧게\",  chars: \"700~1,000자\",   paras: \"4~5개\",   sections: \"3~4개\" },\n  normal: { label: \"보통\",  chars: \"1,400~1,800자\", paras: \"7~9개\",   sections: \"5~6개\" },\n  long:   { label: \"길게\",  chars: \"2,800~3,500자\", paras: \"12~16개\", sections: \"7~9개\" },\n};\n\nconst GW_KIND = {\n  news: {\n    label: \"뉴스기사형\",\n    brief: \"도입부터 결론까지 문단이 자연스럽게 이어지는 뉴스 기사입니다. 핵심 사실, 배경, 독자 생활에 미치는 영향, 확인할 점을 기사 흐름 안에서 풀어 주십시오.\",\n  },\n  summary: {\n    label: \"단락별 요약\",\n    brief: \"첫 문단에서 기사 전체를 요약한 뒤, 핵심 내용을 '■ 소제목' 단위로 나누어 독자가 내용을 빠르게 훑어볼 수 있게 작성하십시오.\",\n  },\n};\n\nfunction gwBodyStyle(o, len) {\n  return o.kind === \"summary\"\n    ? `- 첫 문단은 소제목 없이 기사 전체 핵심을 요약한 리드문으로 쓰십시오.\n- 그 다음부터는 반드시 \"■ 소제목\"을 한 줄에 단독으로 쓰고, 바로 다음 줄에 해당 내용을 설명하는 문단을 쓰십시오.\n- \"■ 소제목 + 설명 문단\" 묶음을 ${len.sections}로 구성하십시오.\n- 소제목 앞에는 정확히 ■ 기호 하나만 쓰십시오. ##, 번호, 불릿 목록, 굵은 글씨 표시는 쓰지 마십시오.`\n    : `- 일반 뉴스 기사처럼 도입부터 결론까지 자연스러운 문단으로 이어 쓰십시오.\n- 본문 중간에 소제목, ■ 기호, 번호, 불릿 목록을 넣지 마십시오.`;\n}\n\n/* 기사 JSON 모양 — 섹션을 맨 앞에 둔다 (JSON 이 깨져 느슨하게 읽을 때도 섹션을 찾을 수 있게) */\nconst GW_ARTICLE_SHAPE = `\\`\\`\\`json\n{\n  \"section1\": \"\",\n  \"section2\": \"\",\n  \"title\": \"\",\n  \"subtitle1\": \"\",\n  \"subtitle2\": \"\",\n  \"subtitle3\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n\nconst GW_ARTICLE_OUTPUT = `[출력 형식]\n설명이나 인사말 없이, 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 반드시 JSON 배열이어야 하며, 각 문단과 \"■ 소제목\" 한 줄을 각각 별도 문자열 항목으로 넣으십시오.\n- 문자열 항목 안에 실제 줄바꿈을 넣지 마십시오. 문단 구분은 배열 항목으로만 표현하십시오.\n- 모든 문자열은 큰따옴표로 감싸고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 인터넷 검색을 했더라도 출처 표시(cite 기호)·각주 번호·링크·참고 문헌 목록은 본문에 넣지 마십시오. 문장만 쓰십시오.\n- 출력 전에 JSON.parse가 가능한 유효한 JSON인지 괄호와 쉼표를 확인하십시오.\n\n${GW_ARTICLE_SHAPE}`;\n\n/* ── 소재별 사실 원칙 ── */\nfunction gwNewsRules(news) {\n  const publisher = (news && news.publisher) || \"원문 언론사\";\n  return `════════ 세 가지 원칙을 지키십시오 ════════\n\n【사실 구역】 [원문 기사]에 적힌 것\n- 숫자·날짜·금액·비율·기관명·인물명·지명·정책 이름은 원문과 한 글자도 다르게 쓰지 마십시오.\n- 원문에 없는 사실·수치·일정을 추측해 더하지 마십시오. 없으면 그 이야기를 아예 하지 마십시오.\n- 발언 인용은 원문에 실제로 있는 발언만, 누가 한 말인지 밝혀서 쓰십시오. 원문에 없는 전문가·관계자 발언을 만들지 마십시오.\n\n【새로 쓰기 — 저작권 원칙】   ★ 가장 먼저 지킬 것\n- 원문 기사의 문장·문단 구성·제목·리드를 그대로 옮기지 마십시오. 사실만 뽑아 공실뉴스 기자가 처음부터 다시 쓴 기사여야 합니다.\n- 원문과 같은 표현이 연달아 10어절 넘게 이어지지 않게 하십시오.\n- 본문 안에서 \"${publisher} 보도에 따르면\"처럼 출처를 한 번 이상 밝히십시오.\n- 마지막 문단 끝에 \"(참고: ${publisher} 보도)\"를 한 줄로 붙이십시오.\n\n【해설 구역】 기자로서 쓰는 부분   ★ 기사 분량의 절반 가까이를 여기에 쓰십시오\n- 이 소식이 독자의 집·돈·일·생활에 어떤 의미인지\n- 소식을 이해하는 데 필요한 배경 지식과 제도 설명\n- 비슷한 상황의 독자가 확인해 볼 점\n해설 구역에서도 원문에 없는 구체적 수치 예측(\"3개월 안에 10% 오른다\"), 단정(\"반드시\", \"확실하다\"), 특정 시점 시세를 아는 것처럼 쓰는 것은 금지합니다.`;\n}\n\n/* 글 뼈대가 있으면 그 순서와 내용을 따르게 한다. 단락별 요약이면 본론 하나가 ■ 소제목 하나 */\nfunction gwOutlineRules(topic, o) {\n  if (!gwHasOutline(topic)) return \"\";\n  const points = gwOutlinePoints(topic);\n  const headings = o.kind === \"summary\" && points.length\n    ? `\\n- 단락별 요약이므로 본론 ${points.length}개를 각각 \"■ 소제목\" 하나로 삼으십시오. 소제목은 그 본론 내용을 짧게 줄인 말로 쓰고, 서론은 첫 리드 문단, 결론은 마지막 문단으로 쓰십시오.`\n    : \"\";\n  return `【글 뼈대】   ★ 반드시 지키십시오\n- [글 뼈대]의 순서 그대로 서론 → 본론${points.length > 1 ? ` 1~${points.length}` : \"\"} → 결론으로 쓰십시오. 순서를 바꾸거나 항목을 빼지 마십시오.\n- 사용자가 적은 칸은 그 내용을 중심으로 살을 붙여 풀어 쓰십시오. 적힌 말을 그대로 옮기지 말고 기사 문장으로 다듬으십시오.\n- 비워 둔 칸은 주제와 앞뒤 흐름에 맞게 직접 채우십시오.\n- 분량은 본론에 가장 많이 쓰고, 본론끼리는 비슷한 길이로 나누십시오.${headings}\n\n`;\n}\n\nfunction gwTopicRules(topic, o) {\n  return `${gwOutlineRules(topic, o || {})}════════ 두 가지 원칙을 지키십시오 ════════\n\n【사실 원칙】\n- [참고 메모]에 있는 사실·숫자는 그대로 쓰고 바꾸지 마십시오.\n- 메모에 없는 구체적 수치는 법정 기준처럼 널리 확정된 것만 쓰십시오.\n  금리·시세·최근 통계·개정 예정 제도처럼 시점에 따라 바뀌는 수치는 지어내지 마십시오.\n  꼭 필요하면 \"최신 수치는 관계 기관 발표로 확인할 필요가 있다\"처럼 확인을 권하는 문장으로 대신하십시오.\n- 실재하지 않는 인물·전문가·기관·업체·설문조사·통계를 만들지 마십시오. 인터뷰한 것처럼 쓰지 마십시오.\n- 이해를 돕는 사례가 필요하면 \"예를 들어 ~라고 가정하면\"처럼 가정한 사례임을 분명히 밝히십시오.\n\n【재미와 쓸모】   ★ 독자가 끝까지 읽게 하십시오\n- 첫 문단은 독자가 \"내 얘기네\" 하고 느낄 생활 장면이나 질문으로 여십시오. 낚시성 과장은 쓰지 마십시오.\n- 어려운 용어는 처음 나올 때 쉬운 말로 풀어 주십시오.\n- 읽고 나서 바로 써먹을 수 있는 확인 요령·순서·주의할 점을 담으십시오.`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   기사 작성 프롬프트\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildPrompt(source, opts) {\n  const s = source || {};\n  const o = opts || {};\n  const len = GW_LENGTH[o.length] || GW_LENGTH.normal;\n  const kind = GW_KIND[o.kind] || GW_KIND.news;\n  const isNews = s.mode === \"news\";\n  const isMarket = gwIsMarket(s);\n  const intro = isMarket ? gwMarketIntro(s)\n    : isNews\n      ? \"아래 원문 기사의 사실을 바탕으로, 공실뉴스 독자를 위한 기사 1건을 새로 작성하십시오.\"\n      : \"아래 주제로 공실뉴스 독자에게 흥미롭고 실생활에 유익한 기사 1건을 작성하십시오.\";\n\n  return `당신은 생활·경제 전문 매체 \"공실뉴스\"의 기자입니다.\n${intro}\n\n${gwSourceText(s)}\n\n${gwSectionText(s)}\n\n${isMarket ? gwMarketRules(s) : isNews ? gwNewsRules(s.news) : gwTopicRules(s.topic, o)}\n\n[기사 스타일] ${kind.label}\n${kind.brief}\n\n[분량]   ★ 반드시 지키십시오\n- 본문 전체 ${len.chars}\n- 문단 ${len.paras}\n- 분량이 모자라면 해설(의미·배경·확인할 점)을 더 쓰십시오. 같은 사실을 반복해 길이를 채우지 마십시오.\n\n[문체]\n- 평서체 기사체 (\"~했습니다\" 아닌 \"~했다\")\n- 과장·광고 표현, 독자에게 직접 권하는 2인칭 문장(\"~하세요\")을 쓰지 마십시오. 조언은 \"~라면 ~를 확인할 필요가 있다\"처럼 쓰십시오.\n\n[구성]\n- title     : 25~45자. 핵심을 담은 자연스러운 제목. 낚시성 물음·과장 금지\n- subtitle  : 세 줄. 각 30~50자, 마침표 없이 끝낼 것. 기사 핵심을 세 갈래로 나눠 요약\n- body      : 위 분량대로 쓴 문단별 문자열 배열. 배열 항목 하나가 문단 하나이며 HTML 태그를 쓰지 말 것\n${gwBodyStyle(o, len)}\n- keywords  : 5~8개. # 없이 낱말만. 검색에 쓰일 핵심어\n\n${GW_ARTICLE_OUTPUT}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   수정 요청 — 같은 대화에 이어 붙인다 (AI 가 앞서 쓴 기사와 소재를 기억하고 있다)\n   ══════════════════════════════════════════════════════════════ */\nfunction gwBuildRevisePrompt(request, source) {\n  const keep = gwIsMarket(source)\n    ? `- 실거래 자료의 금액·면적·층·건수·날짜·비율은 바꾸거나 새로 만들지 마십시오. \"국토교통부 실거래가\" 출처 표기는 유지하십시오.\n- 인용·가격 전망·매수 권유를 새로 넣지 마십시오.`\n    : source && source.mode === \"news\"\n      ? `- [원문 기사]의 숫자·날짜·이름·기관명은 바꾸거나 새로 만들지 마십시오.\n- 원문 문장을 그대로 옮기지 말고, 출처 표기(\"${(source.news && source.news.publisher) || \"원문 언론사\"} 보도에 따르면\", 마지막 줄 참고 표기)는 유지하십시오.`\n      : `- [참고 메모]의 사실은 바꾸지 말고, 실재하지 않는 인물·통계·수치를 새로 만들지 마십시오.`;\n  return `위에서 작성한 기사를 아래 요청대로 고쳐 주십시오.\n\n요청: ${request}\n\n[지킬 것]\n${keep}\n- 그 밖에는 요청하신 대로 자유롭게 고치십시오.\n  분량을 늘리라고 하면 실제로 그만큼 늘리십시오. 앞서 드린 분량 지시는 이 요청으로 대체됩니다.\n- section1·section2 는 처음 값을 그대로 두십시오.\n- 설명이나 인사말 없이, 고친 기사 전체를 처음과 똑같은 JSON 형식으로 \\`\\`\\`json 코드블록 하나에 다시 출력하십시오.\n- body는 문자열 하나가 아니라 문단별 문자열 배열입니다. 배열 항목 하나에 문단 하나만 넣으십시오.\n- 배열 항목 안에 실제 줄바꿈을 넣지 말고, 후행 쉼표 없이 JSON.parse가 가능한 유효한 JSON인지 확인하십시오.\n\n${GW_ARTICLE_SHAPE}`;\n}\n\n/* ══════════════════════════════════════════════════════════════\n   기사 이미지 만들기\n\n   기사 본문에 밀착한 장면을 요구하되, 작업창에서 스타일이나 기사 일부를\n   직접 지정할 수 있다. 입력이 없으면 AI 가 본문에서 핵심 장면을 고른다.\n   ══════════════════════════════════════════════════════════════ */\nconst GW_IMAGE_STYLE = {\n  /* AI 추천 — 아래 다섯 가지 가운데 본문 내용에 가장 맞는 것을 AI 가 고른다. 초안의 자동 대표 이미지도 이것을 쓴다 */\n  auto: {\n    label: \"AI 추천\",\n    prompt: \"\",\n  },\n  news: {\n    label: \"보도 실사\",\n    prompt: \"한국 언론사의 현장 취재 사진처럼 자연스럽고 사실적인 장면. 과장 없는 담담한 조명과 구도.\",\n  },\n  life: {\n    label: \"생활 현장\",\n    prompt: \"기사 내용이 실제로 벌어지는 한국의 일상 공간(집·가게·사무실·거리)을 담은 사실적인 생활 사진. 따뜻하고 자연스러운 빛.\",\n  },\n  city: {\n    label: \"도시·건물\",\n    prompt: \"한국 도시의 건물·거리·주거지 풍경을 넓게 담은 사실적인 보도사진. 특정 건물이 드러나지 않는 일반적인 풍경.\",\n  },\n  animation: {\n    label: \"애니메이션 일러스트\",\n    prompt: \"생활·경제 기사에 어울리는 세련된 애니메이션풍 편집 일러스트. 특정 작품이나 작가의 화풍을 모방하지 말고 독창적으로 표현.\",\n  },\n  infographic: {\n    label: \"통계 도표·인포그래픽\",\n    prompt: \"기사에 쓰는 깔끔한 데이터 인포그래픽. 기사에 나온 숫자만 시각화하고, 비교 자료가 없으면 추세나 비교 그래프를 만들지 말고 핵심 수치 카드 형태로 구성.\",\n  },\n};\n\n/* AI 추천일 때 고를 수 있는 스타일 목록 */\nfunction gwImageStyleMenu() {\n  return Object.entries(GW_IMAGE_STYLE)\n    .filter(([key]) => key !== \"auto\")\n    .map(([, style]) => `- ${style.label}: ${style.prompt}`)\n    .join(\"\\n\");\n}\n\n/* opts = { style, request, cover }\n   cover: 초안이 나오자마자 자동으로 만드는 대표 이미지 — 기사 전체를 대표하는 장면 한 장 */\nfunction gwBuildImagePrompt(source, article, opts) {\n  const o = opts || {};\n  const auto = !GW_IMAGE_STYLE[o.style] || o.style === \"auto\";\n  const style = auto ? GW_IMAGE_STYLE.auto : GW_IMAGE_STYLE[o.style];\n  const request = String(o.request || \"\").trim();\n  const customStyle = String(o.customStyle || \"\").trim().slice(0, 50); // 직접 입력한 화풍\n  const articleText = [article && article.title, article && article.body]\n    .filter(Boolean)\n    .join(\"\\n\")\n    .trim();\n  const focus = (request || articleText || gwSourceLabel(source)).slice(0, 1600);\n  const focusRule = request\n    ? \"아래 입력이 기사 문장이면 그중 시각적으로 표현할 핵심 장면을 고르고, 연출 지시이면 그대로 반영하십시오.\"\n    : o.cover\n      ? \"이 이미지는 기사 맨 위에 들어가는 대표 이미지입니다. 아래 기사 본문을 읽고, 기사 전체 내용을 한눈에 보여 주는 장면 하나를 스스로 골라 만드십시오.\"\n      : \"아래 기사 내용에서 가장 시각적으로 전달력이 높은 한 가지 핵심을 스스로 골라 장면으로 만드십시오.\";\n  const styleText = customStyle\n    ? `[화풍·스타일] 사용자 직접 지정: \"${customStyle}\"\n- 이 화풍·그림체를 가장 먼저 지켜 표현하십시오.`\n    : auto\n    ? `[스타일] 아래 가운데 기사 본문 내용에 가장 잘 맞는 것 하나를 스스로 고르십시오.\n${gwImageStyleMenu()}\n- 기사에 비교할 숫자가 여럿 있을 때만 통계 도표·인포그래픽을 고르십시오.`\n    : `[선택한 스타일] ${style.label}\n${style.prompt}`;\n  const textRule = customStyle\n    ? \"- 이미지 안에 글자, 숫자, 로고, 워터마크를 넣지 말 것\"\n    : o.style === \"infographic\"\n    ? \"- 한글 문구는 꼭 필요한 짧은 항목명만 쓰고, 숫자와 단위는 기사에 나온 것과 정확히 일치시킬 것\"\n    : auto\n      ? \"- 통계 도표를 고른 경우가 아니면 이미지 안에 글자, 숫자, 로고, 워터마크를 넣지 말 것. 통계 도표라면 기사 숫자와 정확히 일치시킬 것\"\n      : \"- 이미지 안에 글자, 숫자, 로고, 워터마크를 넣지 말 것\";\n\n  return `위 기사에 넣을 ${o.cover ? \"대표 \" : \"\"}이미지 1장을 만들어 주십시오.\n\n${styleText}\n\n[이미지로 표현할 내용]\n${focusRule}\n${focus}\n\n[기본 장면 정보]\n- 기사 제목: ${(article && article.title) || gwSourceLabel(source)}\n- 배경: 대한민국\n\n[조건]\n- ${o.ratio || \"가로 16:9\"} 비율\n- 기사에 없는 숫자, 통계, 건물명, 업체명, 시설을 만들지 말 것\n- 비교 수치나 증감률이 없으면 임의의 그래프, 비율, 순위를 만들지 말 것\n${textRule}\n- 실존 인물의 얼굴, 알아볼 수 있는 사람 얼굴, 존재하지 않는 상호·간판 이름을 넣지 말 것\n- 뉴스 원문 사진을 흉내 내거나 베끼지 말고 새로 구성할 것\n- 사용자가 입력한 요청은 반영하되, 기사 사실과 충돌하면 사실을 우선할 것\n\n이미지 1장만 출력하고 설명은 붙이지 마십시오.`;\n}\n\n/* AI 이미지 설명글 — 기사 본문에 그대로 들어간다 */\nfunction gwAiImageCaption(article) {\n  const title = String((article && article.title) || \"\").trim();\n  return title ? `${title} (AI 생성 이미지)` : \"기사 내용을 바탕으로 만든 AI 생성 이미지\";\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_LENGTH,\n    GW_KIND,\n    GW_IMAGE_STYLE,\n    gwSourceReady,\n    gwSourceLabel,\n    gwSourceText,\n    gwSectionText,\n    gwNewsDate,\n    gwHasOutline,\n    gwOutlineText,\n    gwBuildPrompt,\n    gwBuildRevisePrompt,\n    gwBuildImagePrompt,\n    gwAiImageCaption,\n  };\n}\n",
 "newsmaker/blog-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   네이버 블로그 초안 전용 프롬프트 (뉴스메이커)\n\n   기사 작성 프롬프트와 분리한다. 블로그에서 스타일이나 분량을 바꿔도\n   2번 '초안 다듬기'의 기사 프롬프트에는 아무 영향이 없다.\n\n   input = { article, source }  — article 은 2번의 공실뉴스 기사, source 는 1번의 소재(뉴스·주제)\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_BLOG_LENGTH = {\n  short:  { label: \"짧게\", chars: \"700~1,000자\", paras: \"5~7개\" },\n  normal: { label: \"중간\", chars: \"1,500~2,000자\", paras: \"9~12개\" },\n  long:   { label: \"길게\", chars: \"2,500~3,500자\", paras: \"14~20개\" },\n};\n\nconst GW_BLOG_STYLE = {\n  info: {\n    label: \"기본 정보형\",\n    fit: \"모든 주제\",\n    titleExample: \"전세 계약 전 꼭 확인할 3가지, 달라진 기준 정리\",\n    guide:\n      \"깔끔하고 정보 중심으로 쓴다. 제목과 첫 문단에서 무엇에 관한 글인지 분명히 보여 주고, \" +\n      \"본문은 핵심 내용, 배경, 생활에 미치는 영향, 확인할 점의 순서로 정리한다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 3~4개, 명사형으로 짧게 (예: ■ 무엇이 달라졌나 / ■ 누구에게 해당되나 / ■ 확인할 점). \" +\n      \"핵심 요약 → 내용 → 영향 → 확인할 점 순서\",\n  },\n  story: {\n    label: \"스토리텔링형\",\n    fit: \"생활·재테크\",\n    titleExample: \"월세 사는 30대 직장인이라면, 이번 변화 무엇이 달라질까?\",\n    guide:\n      \"독자가 실제로 겪을 법한 생활 장면이나 한 가지 질문으로 시작한다. \" +\n      \"사례는 '예를 들어 ~라고 가정하면'처럼 가정임을 밝히고, 실재하는 사람인 것처럼 꾸미지 않는다.\",\n    design: \"magazine\",\n    structure:\n      \"소제목 1~2개, 질문형 (예: ■ 그래서 내 생활은 무엇이 바뀔까?). \" +\n      \"상황 제시 → 질문 → 확인된 사실로 해답 순서. 소제목보다 문단 흐름을 중시\",\n  },\n  qna: {\n    label: \"Q&A 해설형\",\n    fit: \"제도·법률·세금\",\n    titleExample: \"새 임대차 제도, 세입자가 가장 많이 묻는 5가지\",\n    guide:\n      \"독자가 실제로 궁금해할 질문을 뽑아 하나씩 답하는 해설 글로 쓴다. 부드러운 존댓말은 허용하지만 \" +\n      \"권유하지 말고, 사실과 확인할 점을 객관적으로 짚는다.\",\n    design: \"qna\",\n    structure:\n      \"소제목 3~5개, 독자가 물어볼 질문형 (예: ■ 언제부터 적용되나요? / ■ 기존 계약도 해당되나요?). \" +\n      \"각 소제목 바로 다음 문단이 그 질문에 대한 답\",\n  },\n  report: {\n    label: \"분석·리포트형\",\n    fit: \"정책·시장·경제\",\n    titleExample: \"금리 동결 이후 부동산 시장, 쟁점을 하나씩 살펴보니\",\n    guide:\n      \"배경, 핵심 쟁점, 영향, 남은 과제를 균형 있게 분석한다. \" +\n      \"자료에 없는 전망 수치·시세·수익률을 추정하지 않는다.\",\n    design: \"news\",\n    structure:\n      \"소제목 4~5개, 명사형으로 고정 (■ 배경 / ■ 핵심 쟁점 / ■ 누구에게 어떤 영향 / ■ 앞으로 확인할 점). \" +\n      \"각 구역은 1~2문단\",\n  },\n  tips: {\n    label: \"생활 꿀팁형\",\n    fit: \"생활정보·실무 요령\",\n    titleExample: \"이사 전날 꼭 챙길 체크리스트 7가지\",\n    guide:\n      \"읽고 바로 따라 할 수 있는 요령을 순서대로 정리한다. 각 요령마다 왜 필요한지 한두 문장으로 이유를 붙이고, \" +\n      \"과장된 효과나 확인되지 않은 수치는 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 4~7개, 번호 없이 행동형으로 짧게 (예: ■ 계약서 특약부터 확인하기). \" +\n      \"각 소제목 뒤에 1문단으로 방법과 이유\",\n  },\n  shortform: {\n    label: \"숏폼·속보형\",\n    fit: \"SNS 연계 소식\",\n    titleExample: \"[속보] 내년부터 달라지는 청약 기준 한눈에\",\n    guide:\n      \"속보 기사처럼 첫 두 문장에 무엇이 어떻게 됐는지를 짧게 전한다. 문장을 짧게 끊고 사실만 빠르게 전달하되, \" +\n      \"낚시성 표현·과도한 감탄·확인되지 않은 단정은 쓰지 않는다.\",\n    design: \"basic\",\n    structure:\n      \"소제목 0~2개, 한 줄로 짧게. 강한 첫 두 문장 → 핵심 3가지 → 한 줄 정리. \" +\n      \"문단은 1~2문장으로 짧게 끊을 것\",\n  },\n};\n\nfunction gwBlogArticleText(article) {\n  const a = article || {};\n  const subtitles = Array.isArray(a.subtitles) ? a.subtitles : [];\n  return [\n    `[제목] ${String(a.title || \"\").trim()}`,\n    subtitles.length ? `[부제] ${subtitles.join(\" / \")}` : \"\",\n    `[본문]\\n${String(a.body || \"\").trim()}`,\n  ].filter(Boolean).join(\"\\n\");\n}\n\n/* 소재 요약 — 뉴스면 원문 출처, 주제면 참고 메모. 원문 본문은 다시 넣지 않는다 (기사에 이미 녹아 있다) */\nfunction gwBlogSourceLines(source) {\n  const s = source || {};\n  if (s.mode === \"news\" && s.news) {\n    return [\n      `- 소재: 뉴스 기사`,\n      `- 원문 언론사: ${s.news.publisher || \"확인 안 됨\"}`,\n      `- 원문 제목: ${s.news.title || \"\"}`,\n    ].join(\"\\n\");\n  }\n  if (s.mode === \"complex\" || s.mode === \"local\") {\n    return [\n      `- 소재: ${s.mode === \"complex\" ? \"아파트 단지\" : \"동네\"} 실거래 시세${typeof gwSourceLabel === \"function\" ? ` — ${gwSourceLabel(s)}` : \"\"}`,\n      \"- 자료: 국토교통부 실거래가 공개시스템 (신고 기준, 최근 거래는 집계 중)\",\n      \"- 숫자는 [참조 기사]에 있는 것만 쓰고, 본문에서 \\\"국토교통부 실거래가에 따르면\\\"처럼 출처를 한 번 밝힐 것\",\n    ].join(\"\\n\");\n  }\n  const t = s.topic || {};\n  const memo = String(t.memo || \"\").trim();\n  return [`- 소재: 주제 — ${String(t.subject || \"\").trim()}`, memo ? `- 참고 메모: ${memo}` : \"\"]\n    .filter(Boolean)\n    .join(\"\\n\");\n}\n\nfunction gwBuildBlogPrompt(input, opts) {\n  const src = input || {};\n  const o = opts || {};\n  const style = GW_BLOG_STYLE[o.style] || GW_BLOG_STYLE.info;\n  const length = GW_BLOG_LENGTH[o.length] || GW_BLOG_LENGTH.normal;\n  const source = src.source || {};\n  const isNews = source.mode === \"news\" && source.news;\n  const publisher = (isNews && source.news.publisher) || \"원문 언론사\";\n\n  return `당신은 생활·경제 정보를 정확하고 읽기 쉽게 풀어쓰는 네이버 블로그 전문 에디터입니다.\n아래 공실뉴스 기사를 참고해 블로그 초안 1건을 작성하십시오.\n\n[참조 기사 — 공실뉴스]\n${gwBlogArticleText(src.article)}\n\n[소재 정보]\n${gwBlogSourceLines(source)}\n\n[선택한 스타일] ${style.label}\n- 잘 맞는 주제: ${style.fit}\n- 제목 방향 예시: ${style.titleExample}\n- 작성 지침: ${style.guide}\n- 구성: ${style.structure}\n\n[글자 수]\n- 본문 ${length.chars}\n- 문단 ${length.paras}\n- 같은 내용을 반복해 분량을 억지로 늘리지 말 것\n\n[전달 원칙 — 모든 스타일 공통, 가장 먼저 지킬 것]\n- 이 글은 공실뉴스가 독자에게 전하는 객관적인 정보 글입니다. 위 스타일은 전개 방식만 정하고 이 틀은 바꾸지 않습니다\n- 기본·분석·속보형은 기사체(~다), 스토리텔링·Q&A·꿀팁형은 부드러운 존댓말(~습니다)도 허용\n- 광고·호객 표현 금지: \"추천합니다\", \"문의하세요\", \"놓치지 마세요\", \"지금이 기회\", \"강력 추천\" 등\n- 독자에게 무엇을 사라·팔라고 권하지 말 것. 조언이 필요하면 \"~라면 ~를 확인할 필요가 있다\"처럼 쓸 것\n${isNews ? `- 본문에서 \"${publisher} 보도에 따르면\"처럼 원문 출처를 한 번 이상 밝힐 것 (원문 링크는 글 끝 \"참고 자료\"에 자동으로 들어갑니다)\n- 원문 기사의 문장을 그대로 옮기지 말 것` : \"- 링크는 본문에 쓰지 말 것\"}\n\n[가장 중요한 사실 원칙]\n- 숫자·날짜·금액·기관명·인물명·제도 이름은 [참조 기사]에 실제로 있는 내용만 쓸 것\n- 기사에 없는 수치·통계·전망·인터뷰·후기·현장 방문을 만들어내지 말 것\n- 실재하지 않는 인물·업체·기관을 만들지 말 것. 사례가 필요하면 가정한 사례임을 밝힐 것\n\n[블로그 구성]\n- title: 검색어를 억지로 나열하지 않은 자연스러운 제목 1개. 선택한 스타일을 분명히 반영할 것\n- body: 모바일에서도 읽기 쉽도록 한 문단을 2~4문장으로 짧게 구성할 것\n- 첫 문단은 2문장 이내의 핵심 요약으로 쓸 것 (인사말 없이 바로 본론). 이 문단은 블로그 맨 위 요약으로 쓰입니다\n- 소제목은 위 [선택한 스타일]의 구성대로 넣고, 한 줄짜리 독립 문단으로 쓰며 반드시 \"■ \"로 시작할 것\n  (\"■\"는 소제목 위치를 알리는 표시이며 화면 모양은 블로그 디자인이 따로 정합니다)\n- 소제목 바로 다음에는 반드시 본문 문단이 올 것 (소제목을 연달아 쓰거나 글 맨 끝에 두지 말 것)\n- 마지막 문단은 핵심과 확인할 점을 객관적으로 정리하는 한 문단으로 쓸 것\n- 기사 문장을 그대로 길게 복사하지 말고 블로그 독자를 위한 새 문장으로 재구성할 것\n- keywords: 검색용 핵심어 7~12개. # 기호는 제외할 것\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- body는 문단별 문자열 배열입니다. 배열 한 항목에 문단 하나만 넣으십시오.\n- 문자열 안에 실제 줄바꿈을 넣지 말고, 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 인터넷 검색을 했더라도 출처 표시(cite 기호)·각주 번호·링크·참고 문헌 목록은 본문에 넣지 마십시오. 문장만 쓰십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nfunction gwBuildBlogRevisePrompt(request) {\n  return `위에서 작성한 블로그 글을 아래 요청대로 고쳐 주십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 앞서 제공한 기사의 숫자·날짜·이름·기관명 등 사실은 바꾸거나 새로 만들지 마십시오.\n- 사용자의 수정 요청을 반영하되 과장 광고, 허위 후기·인터뷰·통계를 만들지 마십시오.\n- 소제목 문단은 처음처럼 \"■ \"로 시작하고, 첫 문단은 핵심 요약으로 유지하십시오.\n- 광고·호객 표현을 넣지 말고, 원문 출처 표기가 있었다면 유지하십시오.\n- 고친 블로그 글 전체를 다시 출력하십시오. 수정된 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n- body는 문단별 문자열 배열이며 JSON.parse가 가능한 유효한 JSON이어야 합니다.\n\n\\`\\`\\`json\n{\n  \"title\": \"\",\n  \"body\": [\"첫 문단\", \"둘째 문단\"],\n  \"keywords\": []\n}\n\\`\\`\\``;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_BLOG_LENGTH,\n    GW_BLOG_STYLE,\n    gwBlogArticleText,\n    gwBlogSourceLines,\n    gwBuildBlogPrompt,\n    gwBuildBlogRevisePrompt,\n  };\n}\n",
 "newsmaker/sns-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   3 · SNS 작성 — 페이스북 · 인스타그램 · 스레드 (뉴스메이커)\n\n   기사작성기 V30(gongsilwriter30)의 SNS 와 같은 모양. 다른 점:\n   - 매물 광고가 아니라 중개사무소 출처(표시·광고 필수 정보)를 붙이지 않는다.\n     대신 소재에 맞는 출처 줄을 붙인다 — 뉴스: \"출처: ○○ 보도 재구성\", 시세: \"자료: 국토교통부 실거래가\", 주제: \"공실뉴스\".\n   - 링크는 \"발행한 기사 주소\"를 넣으면 그 주소, 아니면 공실뉴스 홈.\n   - 시세표 그림(kind \"chart\")은 자르지 않고 여백을 넣어 맞춘다 (sns.js).\n   - 링크·출처·해시태그는 AI 가 아니라 코드가 붙인다 (gwSnsCompose).\n   기획: docs/2026-10-03_sns_writer_tabs_meeting.md\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_SNS_CHANNELS = {\n  facebook: {\n    label: \"페이스북\", badge: \"Facebook\", homeUrl: \"https://www.facebook.com/\",\n    ratio: 1, ratioText: \"정사각 1:1\", size: [1080, 1080], maxMedia: 10, maxChars: 0, maxTags: 5,\n  },\n  instagram: {\n    label: \"인스타그램\", badge: \"Instagram\", homeUrl: \"https://www.instagram.com/\",\n    ratio: 4 / 5, ratioText: \"세로 4:5\", size: [1080, 1350], maxMedia: 10, maxChars: 2200, maxTags: 30,\n  },\n  threads: {\n    label: \"스레드\", badge: \"Threads\", homeUrl: \"https://www.threads.com/\",\n    ratio: 0, ratioText: \"원본 비율\", size: [1600, 1600], maxMedia: 10, maxChars: 500, maxTags: 1,\n  },\n};\n\nconst GW_SNS_ORDER = [\"facebook\", \"instagram\", \"threads\"];\nconst GW_SNS_HOME = \"https://www.gongsilnews.com\";\n\nconst gwSnsIsMarket = (source) => Boolean(source && (source.mode === \"complex\" || source.mode === \"local\"));\n\n/* 소재에 맞는 원칙 한 줄 */\nfunction gwSnsSourceRule(source) {\n  const s = source || {};\n  if (s.mode === \"news\" && s.news) {\n    return `- 원문 뉴스(${s.news.publisher || \"원문 언론사\"})의 문장을 그대로 옮기지 말고 새 문장으로 쓸 것. 원문에 없는 사실·숫자·발언을 만들지 말 것`;\n  }\n  if (gwSnsIsMarket(s)) {\n    return \"- 금액·건수·비율·날짜는 [참조 기사]에 있는 숫자만 쓸 것. 계산해 새 숫자를 만들지 말고, 가격 전망·매수 권유를 쓰지 말 것\";\n  }\n  return \"- [참조 기사]에 없는 최신 수치·통계·인물·발언을 만들지 말 것\";\n}\n\nfunction gwBuildSnsPrompt(source) {\n  const input = source || {};\n  return `당신은 생활·경제 정보를 정확하게 전하는 공실뉴스의 SNS 에디터입니다.\n아래 공실뉴스 기사로 페이스북·인스타그램·스레드 글을 한 번에 작성하십시오.\n세 글은 같은 내용을 전하지만 플랫폼마다 모양이 다릅니다. 같은 문장을 돌려 쓰지 마십시오.\n\n[참조 기사 — 공실뉴스]\n${gwBlogArticleText(input.article)}\n\n[소재 정보]\n${gwBlogSourceLines(input.source)}\n\n[원칙 — 세 플랫폼 공통, 가장 먼저 지킬 것]\n- 공실뉴스 기사를 소개하는 글입니다. 광고·호객 표현 금지: \"꼭 보세요\", \"추천합니다\", \"놓치지 마세요\", \"지금이 기회\", \"역대급\" 등\n${gwSnsSourceRule(input.source)}\n- 링크·출처·\"프로필 링크\" 안내는 쓰지 말 것 (글 끝에 자동으로 붙습니다)\n- 어려운 용어는 쉬운 말로 한 번 풀어 줄 것\n\n[페이스북 — facebook]\n- 기사 소개형. 첫 문단 1~2문장이 피드에서 \"더 보기\" 전에 보이는 곳이므로 핵심부터\n- 문단 3~5개, 문단마다 2~3문장, 전체 300~600자. 기사체 또는 부드러운 존댓말\n- hashtags: 3~5개\n\n[인스타그램 — instagram]\n- 사진이 주인공이고 글은 짧은 설명입니다. 한 줄에 정보 하나\n- lines 첫 줄: 25자 안팎의 훅 (핵심 + 이모지 1개)\n- 이어서 핵심 내용 3~5줄, 줄마다 알맞은 이모지 하나로 시작\n- 마지막 1~2줄: 내용을 객관적으로 정리하는 한 문장\n- 전체 lines 6~10줄, 500자 이내\n- hashtags: 8~12개. 띄어쓰기 없이\n\n[스레드 — threads]\n- 말하듯 쓰는 짧은 글. 부드러운 존댓말 대화체(~네요, ~입니다)는 허용하되 원칙은 같습니다\n- posts 첫 글: 450자 이내. 이것만 읽어도 핵심을 알 수 있게\n- 첫 글은 독자의 생각을 묻는 질문 한 문장으로 끝낼 것. 구매·가입·문의를 유도하는 질문은 금지\n- 이어 쓰기 글 0~2개 (posts 둘째·셋째 항목): 배경·확인할 점. 글마다 300자 이내\n- topic: 주제 태그 1개\n\n[출력 형식]\n설명이나 인사말 없이 아래 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- 배열 한 항목에 문단(줄·글) 하나만 넣고, 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n- hashtags·topic 에는 # 기호를 넣지 마십시오. 마지막 항목 뒤에 쉼표를 넣지 마십시오.\n- 출력 전에 JSON.parse가 가능한지 확인하십시오.\n\n\\`\\`\\`json\n{\n  \"facebook\": { \"paragraphs\": [\"첫 문단\", \"둘째 문단\"], \"hashtags\": [] },\n  \"instagram\": { \"lines\": [\"훅 한 줄\", \"📌 ...\"], \"hashtags\": [] },\n  \"threads\": { \"posts\": [\"첫 글\"], \"topic\": \"\" }\n}\n\\`\\`\\``;\n}\n\n/* 플랫폼 하나만 고친다 — 고친 플랫폼만 같은 JSON 모양으로 받는다 */\nfunction gwBuildSnsRevisePrompt(channel, request) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const shape = {\n    facebook: '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }',\n    instagram: '{ \"instagram\": { \"lines\": [], \"hashtags\": [] } }',\n    threads: '{ \"threads\": { \"posts\": [], \"topic\": \"\" } }',\n  }[channel] || '{ \"facebook\": { \"paragraphs\": [], \"hashtags\": [] } }';\n  return `위에서 작성한 SNS 글 중 [${info.label}] 글만 아래 요청대로 고쳐 주십시오. 다른 플랫폼 글은 출력하지 마십시오.\n\n요청: ${String(request || \"\").trim()}\n\n[지킬 것]\n- 기사에 있는 사실·숫자는 바꾸거나 새로 만들지 마십시오.\n- 처음의 원칙(광고·호객 표현 금지, 링크 쓰지 않기)과 ${info.label} 형식 규칙을 그대로 지키십시오.\n\n[출력 형식]\n설명 없이 아래 모양의 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n\\`\\`\\`json\n${shape}\n\\`\\`\\``;\n}\n\n/* ── AI 답변 → 편집용 모양 (V30 과 같다) ── */\nfunction gwSnsCleanTags(tags, max) {\n  const seen = new Set();\n  return (Array.isArray(tags) ? tags : String(tags || \"\").split(/[\\s,]+/))\n    .map((tag) => String(tag || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n    .filter((tag) => tag && !seen.has(tag) && seen.add(tag))\n    .slice(0, max || 30);\n}\n\nfunction gwSnsLines(value) {\n  return (Array.isArray(value) ? value : String(value || \"\").split(/\\n+/))\n    .map((line) => String(line == null ? \"\" : line).trim())\n    .filter(Boolean);\n}\n\nfunction gwSnsNormalize(data) {\n  if (!data || typeof data !== \"object\") return null;\n  const out = {};\n  const fb = data.facebook;\n  if (fb && typeof fb === \"object\") {\n    const paragraphs = gwSnsLines(fb.paragraphs || fb.text || fb.body);\n    if (paragraphs.length) out.facebook = { body: paragraphs.join(\"\\n\\n\"), hashtags: gwSnsCleanTags(fb.hashtags, GW_SNS_CHANNELS.facebook.maxTags) };\n  }\n  const ig = data.instagram;\n  if (ig && typeof ig === \"object\") {\n    const lines = gwSnsLines(ig.lines || ig.caption || ig.body);\n    if (lines.length) out.instagram = { body: lines.join(\"\\n\"), hashtags: gwSnsCleanTags(ig.hashtags, GW_SNS_CHANNELS.instagram.maxTags) };\n  }\n  const th = data.threads;\n  if (th && typeof th === \"object\") {\n    const posts = gwSnsLines(th.posts || th.text || th.body);\n    if (posts.length) out.threads = { posts, topic: gwSnsCleanTags([th.topic], 1)[0] || \"\" };\n  }\n  return Object.keys(out).length ? out : null;\n}\n\nfunction gwSnsParse(raw) {\n  const parsed = GWYoutubeJson.parseObject(raw);\n  if (!parsed.ok) return parsed;\n  const posts = gwSnsNormalize(parsed.data);\n  if (!posts) return { ok: false, reason: \"페이스북·인스타그램·스레드 글을 찾지 못했습니다.\" };\n  return { ok: true, posts, repaired: parsed.repaired };\n}\n\n/* ── 글 끝에 붙는 것: 출처 줄 · 링크 · 해시태그 ── */\nfunction gwSnsCredit(source) {\n  const s = source || {};\n  if (s.mode === \"news\" && s.news) return `출처: ${s.news.publisher || \"원문 언론사\"} 보도 내용 재구성 · 공실뉴스`;\n  if (gwSnsIsMarket(s)) return \"자료: 국토교통부 실거래가 (신고 기준) · 공실뉴스 정리\";\n  return \"공실뉴스\";\n}\n\n/* ctx = { url, credit } — url 은 발행한 기사 주소 또는 공실뉴스 홈 */\nfunction gwSnsCompose(channel, post, ctx) {\n  const c = ctx || {};\n  const url = c.url || GW_SNS_HOME;\n  const credit = c.credit || \"공실뉴스\";\n  const linkLine = url === GW_SNS_HOME ? `▶ 공실뉴스에서 더 보기\\n${url}` : `▶ 공실뉴스 기사 전문 보기\\n${url}`;\n  const tagLine = (tags) => (tags || []).map((tag) => `#${tag}`).join(\" \");\n\n  if (channel === \"threads\") {\n    const posts = (post?.posts || []).map((text) => String(text || \"\").trim()).filter(Boolean);\n    if (!posts.length) return { posts: [], text: \"\" };\n    if (post.topic) posts[0] = `${posts[0]}\\n\\n#${post.topic}`;\n    const tail = `${linkLine}\\n\\n${credit}`;\n    const last = posts.length - 1;\n    if (posts[last].length + tail.length + 2 <= GW_SNS_CHANNELS.threads.maxChars) posts[last] = `${posts[last]}\\n\\n${tail}`;\n    else posts.push(tail);\n    return { posts, text: posts.join(\"\\n\\n―――\\n\\n\") };\n  }\n\n  const body = String(post?.body || \"\").trim();\n  if (!body) return { posts: [], text: \"\" };\n  const parts = [body];\n  /* 인스타 캡션의 링크는 눌리지 않는다 — 프로필 링크 안내를 먼저, 주소는 복사해 갈 수 있게 글자로 함께 */\n  parts.push(channel === \"instagram\" ? `자세한 내용은 프로필 링크 → 공실뉴스\\n${url}` : linkLine);\n  parts.push(credit);\n  const tags = tagLine(post.hashtags);\n  if (tags) parts.push(tags);\n  const text = parts.join(\"\\n\\n\");\n  return { posts: [text], text };\n}\n\n/* ── 사진 고르기 — AI 이미지가 아닌 것(시세표·직접 올린 사진) 먼저, 그다음 AI 이미지 ── */\nfunction gwSnsIsAi(item) {\n  return Boolean(item && item.kind === \"ai\" && !item.real);\n}\n\nfunction gwSnsPickMedia(channel, media) {\n  const info = GW_SNS_CHANNELS[channel] || GW_SNS_CHANNELS.facebook;\n  const list = (Array.isArray(media) ? media : []).filter((item) => item && item.url);\n  const real = list.filter((item) => !gwSnsIsAi(item));\n  real.sort((a, b) => Number(Boolean(b.isCover)) - Number(Boolean(a.isCover)));\n  const ai = list.filter(gwSnsIsAi);\n  ai.sort((a, b) => Number(Boolean(b.isCover)) - Number(Boolean(a.isCover)));\n  return [...real, ...ai]\n    .slice(0, info.maxMedia)\n    .map((item) => ({ url: item.url, kind: item.kind || \"upload\", caption: item.caption || \"\", ai: gwSnsIsAi(item) }));\n}\n\n/* 1번(대표) 자리에 AI 이미지를 둘 수 있는가 — AI 가 아닌 사진이 하나라도 있으면 안 된다 */\nfunction gwSnsCanLead(list, index) {\n  const item = list && list[index];\n  if (!item || !item.ai) return true;\n  return !list.some((other) => other && !other.ai);\n}\n\n/* AI 이미지가 올라갈 사진에 섞여 있으면 \"게시할 때 AI 레이블을 켜세요\" */\nconst GW_SNS_AI_LABEL_WHERE = {\n  facebook: \"게시물 만들기 창의 이름 아래 [AI 레이블] 단추를 눌러 켜 주세요.\",\n  instagram: \"공유하기 전 캡션 화면의 [고급 설정]에서 [AI 레이블 추가]를 켜 주세요.\",\n  threads: \"게시하기 전 글쓰기 화면의 [AI 레이블] 설정을 켜 주세요.\",\n};\n\nfunction gwSnsAiLabelNote(channel, media) {\n  const info = GW_SNS_CHANNELS[channel];\n  if (!info) return \"\";\n  const count = (Array.isArray(media) ? media : []).slice(0, info.maxMedia).filter((item) => item && item.ai).length;\n  if (!count) return \"\";\n  return `AI로 만든 이미지 ${count}장이 들어 있습니다 — ${GW_SNS_AI_LABEL_WHERE[channel]}`;\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_SNS_CHANNELS, GW_SNS_ORDER, GW_SNS_HOME, gwBuildSnsPrompt, gwBuildSnsRevisePrompt,\n    gwSnsNormalize, gwSnsParse, gwSnsCompose, gwSnsCredit, gwSnsPickMedia, gwSnsCanLead, gwSnsCleanTags, gwSnsAiLabelNote,\n  };\n}\n",
 "newsmaker/naver-blog.js": "/* 네이버 블로그 탭과 글쓰기 탭을 구분하는 공통 규칙 */\n(function initNaverBlog(global) {\n  \"use strict\";\n\n  const HOME_URL = \"https://blog.naver.com/\";\n  const WRITE_URL = \"https://blog.naver.com/GoBlogWrite.naver\";\n\n  function isNaverBlogUrl(rawUrl) {\n    try {\n      const url = new URL(rawUrl);\n      return url.protocol === \"https:\" && (\n        url.hostname === \"blog.naver.com\" ||\n        url.hostname === \"blog.editor.naver.com\"\n      );\n    } catch (_) {\n      return false;\n    }\n  }\n\n  function isLikelyWriteUrl(rawUrl) {\n    if (!isNaverBlogUrl(rawUrl)) return false;\n    const value = String(rawUrl).toLowerCase();\n    return (\n      value.includes(\"goblogwrite\") ||\n      value.includes(\"postwrite\") ||\n      value.includes(\"postwriteform\") ||\n      value.includes(\"redirect=write\") ||\n      value.includes(\"blog.editor.naver.com\")\n    );\n  }\n\n  function selectLikelyWriteTab(tabs) {\n    return (Array.isArray(tabs) ? tabs : [])\n      .filter((tab) => tab && tab.id && isLikelyWriteUrl(tab.url))\n      .sort((a, b) => {\n        if (Boolean(a.active) !== Boolean(b.active)) return a.active ? -1 : 1;\n        return (b.lastAccessed || 0) - (a.lastAccessed || 0);\n      })[0] || null;\n  }\n\n  function splitParagraphs(body) {\n    return String(body || \"\")\n      .split(/\\n{2,}|\\n/)\n      .map((value) => value.trim())\n      .filter(Boolean);\n  }\n\n  /* 대표가 아닌 사진을 문단 사이 칸(0 = 첫 문단 앞, n = n번째 문단 뒤)에 배치한다.\n     insertAfterParagraph가 있으면 그 칸, 없으면 두 문단마다 한 장씩, 남으면 글 끝. */\n  function layoutMediaSlots(paragraphCount, media) {\n    const slots = Array.from({ length: paragraphCount + 1 }, () => []);\n    const automatic = [];\n\n    (Array.isArray(media) ? media : []).forEach((item, index) => {\n      if (!item || item.isCover) return;\n      if (Number.isInteger(item.insertAfterParagraph)) {\n        const slot = Math.max(0, Math.min(item.insertAfterParagraph, paragraphCount));\n        slots[slot].push({ media: item, index });\n      } else {\n        automatic.push({ media: item, index });\n      }\n    });\n\n    let autoIndex = 0;\n    for (let slot = 2; slot < paragraphCount && autoIndex < automatic.length; slot += 2) {\n      slots[slot].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    while (autoIndex < automatic.length) {\n      slots[paragraphCount].push(automatic[autoIndex]);\n      autoIndex += 1;\n    }\n    return slots;\n  }\n\n  function escapeHtml(value) {\n    return String(value).replace(/[&<>\"']/g, (ch) => ({\n      \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\",\n    })[ch]);\n  }\n\n  /* ── 블로그 디자인 ──\n     네이버 편집기가 붙여넣기로 받아들이는 요소만 쓴다 (2026-09-25 실제 화면에서 확인):\n     <blockquote> → 인용구(따옴표형), <hr> → 구분선, 문단 정렬·글자색·크기·링크.\n     굵게(<b>·<strong>·font-weight)는 붙여넣기로 적용되지 않으므로 소제목은 크기와 색으로 강조한다.\n     붙여넣기 조각을 빈 문단으로 끝내지 않으면 다음 조각이 마지막 문단에 이어 붙고 글자색·크기도 번진다.\n     문단 순서는 모든 디자인이 같다. 그래서 사진 위치(문단 사이 칸)가 미리보기와 어긋나지 않는다. */\n  const DESIGNS = {\n    basic: { label: \"기본형\", hint: \"요약 인용구 · 큰 소제목. 어떤 주제에나 무난합니다.\" },\n    magazine: { label: \"매거진형\", hint: \"가운데 정렬 · 번호 소제목 · 핵심 문장 강조. 생활·라이프 글에 어울립니다.\" },\n    qna: { label: \"Q&A형\", hint: \"소제목을 질문으로, 본문을 답변으로. 질문형 검색에 유리합니다.\" },\n    news: { label: \"뉴스기사형\", hint: \"큰 리드문 · 기사체 · 공실뉴스 서명. 언론사 느낌을 살립니다.\" },\n  };\n  function designHint(design) {\n    return DESIGNS[design]?.hint || \"\";\n  }\n  const ACCENT = \"#ea7a00\"; // 뉴스메이커 주황\n  const MUTED = \"#888888\";\n  const SKY = \"#ffedd5\"; // 매거진형 소제목 연주황 배경(형광펜)\n  const BLANK = \"<p><br></p>\";\n  const SITE_URL = \"https://www.gongsilnews.com\"; // gongsilnews.com은 www로 넘어간다. 로그인 쿠키도 www에 있다\n\n  function isHeading(paragraph) {\n    return String(paragraph).startsWith(\"■\");\n  }\n\n  function stripHeading(paragraph) {\n    return String(paragraph).replace(/^■\\s*/, \"\");\n  }\n\n  function formatDate(value) {\n    const date = value ? new Date(value) : new Date();\n    if (Number.isNaN(date.getTime())) return \"\";\n    const pad = (n) => String(n).padStart(2, \"0\");\n    return `${date.getFullYear()}.${pad(date.getMonth() + 1)}.${pad(date.getDate())}`;\n  }\n\n  /* 글 끝 \"참고 자료\" — 뉴스를 소재로 썼으면 원문 언론사·제목·링크를 밝힌다. 주제로 썼으면 붙이지 않는다. */\n  function sourceBlockLines(source) {\n    if (source && (source.mode === \"complex\" || source.mode === \"local\")) {\n      return { lines: [\"국토교통부 실거래가 공개시스템 (신고 기준 · 공실뉴스 정리)\"], url: \"https://rt.molit.go.kr/\" };\n    }\n    const news = source && source.mode === \"news\" ? source.news : null;\n    if (!news || !news.title) return null;\n    const when = news.publishedAt ? formatDate(news.publishedAt) : \"\";\n    const lines = [`${news.publisher || \"원문\"} 「${news.title}」${when ? ` (${when})` : \"\"}`];\n    const url = /^https?:\\/\\//i.test(String(news.url || \"\")) ? news.url : \"\";\n    return { lines, url };\n  }\n\n  function paragraphHtml(text, { align, size, color, background, bold } = {}) {\n    let inner = escapeHtml(text);\n    const styles = [\n      size ? `font-size:${size}px` : \"\",\n      color ? `color:${color}` : \"\",\n      background ? `background-color:${background}` : \"\",\n      bold ? \"font-weight:700\" : \"\",\n    ].filter(Boolean).join(\";\");\n    if (styles) inner = `<span style=\"${styles}\">${inner}</span>`;\n    return align ? `<p style=\"text-align:${align}\">${inner}</p>` : `<p>${inner}</p>`;\n  }\n\n  function quoteHtml(text) {\n    return `<blockquote><p>${escapeHtml(text)}</p></blockquote>`;\n  }\n\n  function linkHtml(url, text, align) {\n    if (!url) return \"\";\n    const style = align ? ` style=\"text-align:${align}\"` : \"\";\n    return `<p${style}><a href=\"${escapeHtml(url)}\">${escapeHtml(text)}</a></p>`;\n  }\n\n  function firstSentence(text) {\n    const match = /^(.+?[.!?])(\\s|$)/.exec(String(text || \"\").trim());\n    return match ? match[1] : String(text || \"\").trim();\n  }\n\n  /* 네이버 편집기에 차례로 붙여넣을 조각을 만든다.\n     글 조각은 HTML, 사진은 media 배열의 위치만 담는다.\n     글 조각은 사진이 끼어들 때만 끊고, 문단 뒤와 조각 끝에는 빈 문단을 둔다. */\n  function buildNaverBlocks(body, media, options = {}) {\n    const design = DESIGNS[options.design] ? options.design : \"basic\";\n    const list = Array.isArray(media) ? media : [];\n    const paragraphs = splitParagraphs(body);\n    const slots = layoutMediaSlots(paragraphs.length, list);\n    const blocks = [];\n    let buffer = [];\n\n    const flush = () => {\n      if (!buffer.length) return;\n      if (buffer[buffer.length - 1] !== BLANK) buffer.push(BLANK);\n      blocks.push({ type: \"html\", html: buffer.join(\"\") });\n      buffer = [];\n    };\n    // 문단 뒤에는 빈 문단 한 칸 (tight: 번호처럼 바로 아래 줄과 붙어야 하는 문단)\n    const html = (value, { tight = false } = {}) => {\n      if (!value) return;\n      buffer.push(value);\n      if (!tight && value.startsWith(\"<p\")) buffer.push(BLANK);\n    };\n    const addImages = (indexes) => {\n      if (!indexes.length) return;\n      flush();\n      indexes.forEach((index) => blocks.push({ type: \"image\", mediaIndex: index }));\n    };\n\n    const leadIndex = paragraphs.length && !isHeading(paragraphs[0]) ? 0 : -1;\n    const firstHeadingIndex = paragraphs.findIndex(isHeading);\n    let headingNumber = 0;\n    let answerPending = false;\n    let pullQuote = \"\";\n    let pullQuoteDone = false;\n\n    // 대표 사진 (뉴스기사형은 사진 설명을 작게 붙인다)\n    const coverIndex = list.findIndex((item) => item && item.isCover);\n    if (coverIndex >= 0) {\n      addImages([coverIndex]);\n      const caption = String(list[coverIndex].caption || \"\").trim();\n      if (design === \"news\" && caption) html(paragraphHtml(caption, { align: \"center\", size: 13, color: MUTED }));\n    }\n    if (design === \"magazine\" && options.title) {\n      html(paragraphHtml(options.title, { align: \"center\", size: 24, bold: true }));\n    }\n    addImages(slots[0].map((item) => item.index));\n\n    // 도입부가 끝나고 첫 소제목이 오기 전에 넣는 장식\n    const afterIntro = () => {\n      if (design === \"basic\" || design === \"magazine\") html(\"<hr>\");\n    };\n\n    let carried = [];\n    paragraphs.forEach((paragraph, index) => {\n      if (index === firstHeadingIndex) afterIntro();\n\n      if (index === leadIndex) {\n        if (design === \"basic\" || design === \"qna\") html(quoteHtml(paragraph));\n        else if (design === \"magazine\") html(paragraphHtml(paragraph, { align: \"center\", color: MUTED }));\n        else html(paragraphHtml(paragraph, { size: 17, bold: true }));\n      } else if (isHeading(paragraph)) {\n        const text = stripHeading(paragraph);\n        headingNumber += 1;\n        if (design === \"magazine\" && headingNumber === 2 && pullQuote) {\n          html(quoteHtml(pullQuote));\n          pullQuoteDone = true;\n        }\n        if (design === \"basic\") {\n          html(paragraphHtml(`■ ${text}`, { size: 19, bold: true }), { tight: true });\n        } else if (design === \"magazine\") {\n          html(paragraphHtml(String(headingNumber).padStart(2, \"0\"), { align: \"center\", color: ACCENT, bold: true }), { tight: true });\n          html(paragraphHtml(text, { align: \"center\", size: 19, background: SKY, bold: true }), { tight: true });\n        } else if (design === \"qna\") {\n          html(paragraphHtml(/^Q[.\\s]/.test(text) ? text : `Q. ${text}`, { size: 19, color: ACCENT, bold: true }), { tight: true });\n          answerPending = true;\n        } else {\n          html(paragraphHtml(text, { size: 19, bold: true }), { tight: true });\n        }\n      } else if (design === \"qna\" && answerPending) {\n        html(`<p><span style=\"color:${ACCENT}\">A.</span> ${escapeHtml(paragraph)}</p>`);\n        answerPending = false;\n      } else {\n        if (design === \"magazine\" && headingNumber === 1 && !pullQuote) pullQuote = firstSentence(paragraph);\n        html(paragraphHtml(paragraph, design === \"magazine\" ? { align: \"center\" } : {}));\n      }\n\n      // 소제목과 첫 문단 사이에는 사진을 두지 않는다 — 다음 문단 뒤로 넘긴다\n      const images = [...carried, ...slots[index + 1].map((item) => item.index)];\n      if (isHeading(paragraph) && index < paragraphs.length - 1) {\n        carried = images;\n      } else {\n        carried = [];\n        addImages(images);\n      }\n    });\n    addImages(carried);\n\n    if (firstHeadingIndex < 0) afterIntro();\n\n    // 글 끝: 디자인별 마무리\n    if (design === \"magazine\" && pullQuote && !pullQuoteDone) html(quoteHtml(pullQuote));\n\n    // 모든 디자인 공통: 참고 자료(뉴스 원문 출처) + 공실뉴스 서명\n    html(\"<hr>\");\n    const source = sourceBlockLines(options.source);\n    if (source) {\n      html(paragraphHtml(\"[참고 자료]\", { size: 13, color: MUTED, bold: true }), { tight: true });\n      source.lines.forEach((line) => html(paragraphHtml(line, { size: 13, color: MUTED }), { tight: true }));\n      html(BLANK, { tight: true });\n      html(linkHtml(source.url, \"▶ 원문 기사 보기\"));\n    }\n    html(paragraphHtml(\"공실뉴스 · gongsilnews.com\", { size: 13, color: MUTED }));\n    flush();\n    return blocks;\n  }\n\n  /* 발행 창 태그 칸용: # 제거, 중복 제거, 네이버 최대 30개 */\n  function normalizeTags(keywords) {\n    const seen = new Set();\n    return (Array.isArray(keywords) ? keywords : [])\n      .map((keyword) => String(keyword || \"\").replace(/^#+/, \"\").replace(/\\s+/g, \"\").trim())\n      .filter((keyword) => keyword && !seen.has(keyword) && seen.add(keyword))\n      .slice(0, 30);\n  }\n\n  const api = {\n    HOME_URL, WRITE_URL, isNaverBlogUrl, isLikelyWriteUrl, selectLikelyWriteTab,\n    splitParagraphs, layoutMediaSlots, buildNaverBlocks, normalizeTags,\n    DESIGNS, designHint, sourceBlockLines, SITE_URL,\n  };\n  global.GWNaverBlog = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})(typeof globalThis !== \"undefined\" ? globalThis : self);\n",
 "newsmaker/article-json.js": "/* ══════════════════════════════════════════════════════════════\n   AI 기사 JSON 읽기\n\n   새 형식은 body 를 문단 배열로 받는다. 긴 본문을 JSON 문자열 하나에 넣을 때\n   생기는 줄바꿈·괄호 오류를 피하기 위해서다. 예전 문자열 형식도 계속 받으며,\n   AI 가 흔히 만드는 원시 줄바꿈·후행 쉼표·body 닫기 괄호 오류는 안전하게\n   복구한다. eval 은 사용하지 않는다.\n   ══════════════════════════════════════════════════════════════ */\n(() => {\n  \"use strict\";\n\n  function extractCandidate(rawText) {\n    const text = String(rawText || \"\").trim();\n    if (!text) return \"\";\n\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced && fenced[1]) return fenced[1].trim();\n\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first !== -1 && last > first ? text.slice(first, last + 1).trim() : \"\";\n  }\n\n  function hasCompleteObject(rawText) {\n    const text = String(rawText || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n\n    for (let i = first; i < text.length; i += 1) {\n      const ch = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') inString = true;\n      else if (ch === \"{\") depth += 1;\n      else if (ch === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n\n    return false;\n  }\n\n  function escapeRawControlsInStrings(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n\n      if (inString) {\n        if (escaped) {\n          out += ch;\n          escaped = false;\n        } else if (ch === \"\\\\\") {\n          out += ch;\n          escaped = true;\n        } else if (ch === '\"') {\n          out += ch;\n          inString = false;\n        } else if (ch === \"\\n\") {\n          out += \"\\\\n\";\n        } else if (ch === \"\\r\") {\n          if (input[i + 1] === \"\\n\") i += 1;\n          out += \"\\\\n\";\n        } else if (ch === \"\\t\") {\n          out += \"\\\\t\";\n        } else {\n          out += ch;\n        }\n      } else {\n        out += ch;\n        if (ch === '\"') inString = true;\n      }\n    }\n\n    return out;\n  }\n\n  function stripTrailingCommas(input) {\n    let out = \"\";\n    let inString = false;\n    let escaped = false;\n\n    for (let i = 0; i < input.length; i += 1) {\n      const ch = input[i];\n      if (inString) {\n        out += ch;\n        if (escaped) escaped = false;\n        else if (ch === \"\\\\\") escaped = true;\n        else if (ch === '\"') inString = false;\n        continue;\n      }\n\n      if (ch === '\"') {\n        inString = true;\n        out += ch;\n        continue;\n      }\n\n      if (ch === \",\") {\n        let next = i + 1;\n        while (next < input.length && /\\s/.test(input[next])) next += 1;\n        if (input[next] === \"}\" || input[next] === \"]\") continue;\n      }\n\n      out += ch;\n    }\n\n    return out;\n  }\n\n  function repairCommonJson(candidate) {\n    return stripTrailingCommas(escapeRawControlsInStrings(candidate));\n  }\n\n  function keyMatch(input, key, fromIndex = 0) {\n    const escapedKey = key.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n    const regex = new RegExp(`\"${escapedKey}\"\\\\s*:`, \"g\");\n    regex.lastIndex = fromIndex;\n    return regex.exec(input);\n  }\n\n  function extractSection(input, key, nextKeys) {\n    const current = keyMatch(input, key);\n    if (!current) return \"\";\n\n    const start = current.index + current[0].length;\n    let end = input.length;\n    for (const nextKey of nextKeys || []) {\n      const next = keyMatch(input, nextKey, start);\n      if (next && next.index < end) end = next.index;\n    }\n\n    let section = input.slice(start, end).trim();\n    section = section.replace(/,\\s*$/, \"\").trim();\n    return section;\n  }\n\n  function manualUnquote(value) {\n    let text = String(value || \"\").trim();\n    while (text.startsWith('\"') && /[}\\]]$/.test(text)) {\n      text = text.slice(0, -1).trim();\n    }\n    if (text.startsWith('\"')) text = text.slice(1);\n    if (text.endsWith('\"')) text = text.slice(0, -1);\n\n    return text\n      .replace(/\\\\r\\\\n/g, \"\\n\")\n      .replace(/\\\\n/g, \"\\n\")\n      .replace(/\\\\t/g, \"\\t\")\n      .replace(/\\\\\"/g, '\"')\n      .replace(/\\\\\\\\/g, \"\\\\\")\n      .trim();\n  }\n\n  function parseLooseValue(section) {\n    let value = String(section || \"\").trim().replace(/,\\s*$/, \"\").trim();\n    if (!value) return \"\";\n\n    /* 스크린샷처럼 문자열 body 뒤에 잘못 붙은 ] 를 제거한다. */\n    if (value.startsWith('\"')) {\n      while (value.endsWith(\"]\")) value = value.slice(0, -1).trim();\n    }\n\n    const attempts = [value, repairCommonJson(value)];\n    if (value.startsWith(\"[\") && !value.endsWith(\"]\")) {\n      attempts.push(repairCommonJson(value + \"]\"));\n    }\n\n    for (const attempt of attempts) {\n      try {\n        return JSON.parse(attempt);\n      } catch (_error) {\n        /* 다음 안전한 복구를 시도한다. */\n      }\n    }\n\n    if (value.startsWith(\"[\")) {\n      const strings = [];\n      const regex = /\"((?:\\\\.|[^\"\\\\])*)\"/g;\n      let match;\n      while ((match = regex.exec(value))) strings.push(manualUnquote(`\"${match[1]}\"`));\n      if (strings.length) return strings;\n    }\n\n    return manualUnquote(value);\n  }\n\n  /* ChatGPT 가 인터넷 검색을 하면 문장 끝에 출처 표시를 단다.\n     화면에는 \"cite turn0search2\" 처럼 보이는데, 실제로는 사용자 영역 문자(U+E000~U+F8FF)로 감싼 기호다.\n     예전 형식인 【4†source】 와 함께 모두 지우고, 지운 자리의 공백을 정리한다. */\n  const CITE_TOKEN = /[-]*\\b(?:cite|navlist|image_group|entity)(?:[-]+[\\w.-]*)+[-]*/g;\n  /* 복사 과정에서 감싼 문자가 빠지면 \"citeturn0search1turn0news2\" 처럼 붙어서 온다 */\n  const TURN_REF = /(?:\\bcite)?(?:turn\\d+(?:search|news|view|fetch|image|file)\\d+)+/g;\n  const OLD_CITE = /【\\d+(?::\\d+)?†[^】]*】/g;\n\n  function stripCitations(value) {\n    return String(value == null ? \"\" : value)\n      .replace(CITE_TOKEN, \"\")\n      .replace(OLD_CITE, \"\")\n      .replace(TURN_REF, \"\")\n      .replace(/[-]/g, \"\")\n      .replace(/[ \\t]+([.,!?。)」』])/g, \"$1\")\n      .replace(/[ \\t]{2,}/g, \" \")\n      .trim();\n  }\n\n  function normalizeBody(value) {\n    if (Array.isArray(value)) {\n      return value\n        .map((item) => {\n          if (typeof item === \"string\") return stripCitations(item);\n          if (item && typeof item === \"object\") {\n            return stripCitations(item.text || item.content || item.paragraph || \"\");\n          }\n          return \"\";\n        })\n        .filter(Boolean)\n        .join(\"\\n\\n\");\n    }\n\n    if (value && typeof value === \"object\") {\n      return normalizeBody(value.paragraphs || value.body || value.content || value.text || \"\");\n    }\n\n    return typeof value === \"string\" ? stripCitations(value) : \"\";\n  }\n\n  function normalizeArticle(data) {\n    if (!data || typeof data !== \"object\") return null;\n\n    const title = stripCitations(data.title);\n    const subtitleValues = Array.isArray(data.subtitles)\n      ? data.subtitles\n      : [data.subtitle1, data.subtitle2, data.subtitle3];\n    const subtitles = subtitleValues\n      .map((value) => stripCitations(value))\n      .filter(Boolean)\n      .slice(0, 3);\n    const body = normalizeBody(data.body || data.paragraphs || data.content || \"\");\n    const rawKeywords = Array.isArray(data.keywords)\n      ? data.keywords\n      : String(data.keywords || \"\").split(/[,\\n]/);\n    const keywords = rawKeywords\n      .map((keyword) => stripCitations(keyword).replace(/^#/, \"\").trim())\n      .filter(Boolean);\n\n    if (!title || !body) return null;\n    const article = { title, subtitles, body, keywords };\n    /* 뉴스메이커: AI 가 고른 공실뉴스 섹션 (있을 때만) */\n    const section1 = String(data.section1 || \"\").trim();\n    const section2 = String(data.section2 || \"\").trim();\n    if (section1) article.section1 = section1;\n    if (section2) article.section2 = section2;\n    return article;\n  }\n\n  function parseLooseArticle(candidate) {\n    const section1 = parseLooseValue(extractSection(candidate, \"section1\", [\"section2\", \"title\"]));\n    const section2 = parseLooseValue(extractSection(candidate, \"section2\", [\"title\"]));\n    const title = parseLooseValue(extractSection(candidate, \"title\", [\"subtitle1\", \"subtitles\", \"body\"]));\n    const subtitlesValue = parseLooseValue(extractSection(candidate, \"subtitles\", [\"body\"]));\n    const subtitle1 = parseLooseValue(extractSection(candidate, \"subtitle1\", [\"subtitle2\", \"subtitle3\", \"body\"]));\n    const subtitle2 = parseLooseValue(extractSection(candidate, \"subtitle2\", [\"subtitle3\", \"body\"]));\n    const subtitle3 = parseLooseValue(extractSection(candidate, \"subtitle3\", [\"body\"]));\n    const body = parseLooseValue(extractSection(candidate, \"body\", [\"keywords\"]));\n\n    let keywordsSection = extractSection(candidate, \"keywords\", []);\n    while (keywordsSection.endsWith(\"}\")) keywordsSection = keywordsSection.slice(0, -1).trim();\n    const keywords = parseLooseValue(keywordsSection);\n\n    return {\n      section1: typeof section1 === \"string\" ? section1 : \"\",\n      section2: typeof section2 === \"string\" ? section2 : \"\",\n      title,\n      subtitles: Array.isArray(subtitlesValue)\n        ? subtitlesValue\n        : [subtitle1, subtitle2, subtitle3].filter(Boolean),\n      body,\n      keywords: Array.isArray(keywords) ? keywords : [],\n    };\n  }\n\n  function parse(rawText) {\n    if (!rawText || !String(rawText).trim()) {\n      return { ok: false, reason: \"AI 응답이 비어 있습니다.\" };\n    }\n\n    const candidate = extractCandidate(rawText);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON 을 찾지 못했습니다.\" };\n\n    let data = null;\n    let repaired = false;\n\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repairCommonJson(candidate));\n        repaired = true;\n      } catch (_repairError) {\n        data = parseLooseArticle(candidate);\n        repaired = true;\n      }\n    }\n\n    const article = normalizeArticle(data);\n    if (!article) {\n      return { ok: false, reason: \"AI 응답에 제목 또는 본문이 없거나 복구할 수 없는 JSON 입니다.\" };\n    }\n\n    return { ok: true, article, repaired };\n  }\n\n  const api = { parse, hasCompleteObject, extractCandidate, repairCommonJson, normalizeBody, stripCitations };\n  globalThis.GWArticleJson = api;\n\n  if (typeof module !== \"undefined\" && module.exports) {\n    module.exports = api;\n  }\n})();\n",
 "newsmaker/youtube-json.js": "/* AI가 작성한 유튜브 장면 JSON 검증·정규화 */\n(() => {\n  \"use strict\";\n\n  function extract(raw) {\n    const text = String(raw || \"\").trim();\n    if (!text) return \"\";\n    const fenced = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/i);\n    if (fenced?.[1]) return fenced[1].trim();\n    const first = text.indexOf(\"{\");\n    const last = text.lastIndexOf(\"}\");\n    return first >= 0 && last > first ? text.slice(first, last + 1) : \"\";\n  }\n\n  function hasCompleteObject(raw) {\n    const text = String(raw || \"\");\n    const first = text.indexOf(\"{\");\n    if (first < 0) return false;\n    let depth = 0;\n    let inString = false;\n    let escaped = false;\n    for (let i = first; i < text.length; i += 1) {\n      const char = text[i];\n      if (inString) {\n        if (escaped) escaped = false;\n        else if (char === \"\\\\\") escaped = true;\n        else if (char === '\"') inString = false;\n        continue;\n      }\n      if (char === '\"') inString = true;\n      else if (char === \"{\") depth += 1;\n      else if (char === \"}\") {\n        depth -= 1;\n        if (depth === 0) return true;\n      }\n    }\n    return false;\n  }\n\n  function repair(raw) {\n    let output = \"\";\n    let inString = false;\n    let escaped = false;\n    for (let i = 0; i < raw.length; i += 1) {\n      const char = raw[i];\n      if (inString) {\n        if (escaped) {\n          output += char;\n          escaped = false;\n        } else if (char === \"\\\\\") {\n          output += char;\n          escaped = true;\n        } else if (char === '\"') {\n          output += char;\n          inString = false;\n        } else if (char === \"\\n\" || char === \"\\r\") {\n          if (char === \"\\r\" && raw[i + 1] === \"\\n\") i += 1;\n          output += \"\\\\n\";\n        } else if (char === \"\\t\") output += \"\\\\t\";\n        else output += char;\n        continue;\n      }\n      if (char === '\"') {\n        inString = true;\n        output += char;\n        continue;\n      }\n      if (char === \",\") {\n        let next = i + 1;\n        while (next < raw.length && /\\s/.test(raw[next])) next += 1;\n        if (raw[next] === \"}\" || raw[next] === \"]\") continue;\n      }\n      output += char;\n    }\n    return output;\n  }\n\n  function cleanText(value) {\n    return String(value == null ? \"\" : value).trim();\n  }\n\n  function normalizeScene(scene, index) {\n    if (!scene || typeof scene !== \"object\") return null;\n    const narration = cleanText(scene.narration || scene.script || scene.voiceover || scene.text);\n    const heading = cleanText(scene.heading || scene.title || `장면 ${index + 1}`);\n    const caption = cleanText(scene.caption || scene.subtitle || scene.onScreenText);\n    const visualPrompt = cleanText(scene.visualPrompt || scene.imagePrompt || scene.visual || scene.screen);\n    const visualType = cleanText(scene.visualType || scene.shotType || \"auto\");\n    if (!narration) return null;\n    return {\n      sceneId: cleanText(scene.sceneId),\n      heading,\n      narration,\n      caption,\n      visualType,\n      visualPrompt,\n    };\n  }\n\n  function normalize(data) {\n    if (!data || typeof data !== \"object\") return null;\n    const title = cleanText(data.title || data.videoTitle);\n    const description = cleanText(data.description || data.videoDescription);\n    const rawScenes = Array.isArray(data.scenes) ? data.scenes : [];\n    const scenes = rawScenes.map(normalizeScene).filter(Boolean);\n    if (!title || !scenes.length) return null;\n    return { title, description, scenes };\n  }\n\n  function parse(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    let data;\n    let repaired = false;\n    try {\n      data = JSON.parse(candidate);\n    } catch (_strictError) {\n      try {\n        data = JSON.parse(repair(candidate));\n        repaired = true;\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n    const script = normalize(data);\n    if (!script) return { ok: false, reason: \"제목 또는 유효한 장면 대본이 없습니다.\" };\n    return { ok: true, script, repaired };\n  }\n\n  /* 모양을 따지지 않고 JSON 객체만 꺼낸다 — 완성 대본·장면 설명처럼 형식이 다른 답변에 쓴다 */\n  function parseObject(raw) {\n    const candidate = extract(raw);\n    if (!candidate) return { ok: false, reason: \"AI 응답에서 JSON을 찾지 못했습니다.\" };\n    try {\n      return { ok: true, data: JSON.parse(candidate), repaired: false };\n    } catch (_strictError) {\n      try {\n        return { ok: true, data: JSON.parse(repair(candidate)), repaired: true };\n      } catch (error) {\n        return { ok: false, reason: `AI JSON 형식이 깨져 있습니다: ${error.message}` };\n      }\n    }\n  }\n\n  const api = { extract, hasCompleteObject, normalize, parse, parseObject };\n  globalThis.GWYoutubeJson = api;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})();\n\n",
 "newsmaker/youtube-prompt.js": "/* ══════════════════════════════════════════════════════════════\n   4 · 유튜브 대본 — AI 지시문 (뉴스메이커)\n\n   2번 초안 다듬기의 기사와 1번 소재(뉴스·주제)를 자료로 쓴다.\n   기사 프롬프트(prompt.js)와 분리해, 여기서 무엇을 바꿔도 기사 작성에는 영향이 없다.\n   \"흥미 있고 실생활에 재미있고 유익한 이야기\"가 목표다 — 훅과 생활 사례로 끌고, 사실은 정확하게.\n   숫자는 기본으로 TTS 가 바로 읽게 한글 발음으로 쓴다 (AI 스튜디오 공실스터디 대본기의 원칙).\n   ══════════════════════════════════════════════════════════════ */\n\nconst GW_YT_VIDEO_TYPE = {\n  briefing: { label: \"뉴스 브리핑\", structure: \"훅 → 무슨 일인가 → 배경 → 내 생활에 미치는 영향 → 확인할 점 → 마무리\" },\n  info: { label: \"생활 정보\", structure: \"훅(생활 속 질문) → 핵심 답 → 알아 둘 내용 2~3가지 → 따라 할 요령 → 마무리\" },\n  story: { label: \"이야기형\", structure: \"훅(가정한 생활 장면) → 문제 → 알게 된 사실 → 해결 요령 → 교훈 정리\" },\n};\n\nconst GW_YT_DURATION = {\n  short: { label: \"60초 쇼츠\", seconds: 60, chars: \"약 280~380자\" },\n  mid: { label: \"약 3분\", seconds: 180, chars: \"약 900~1,100자\" },\n  long: { label: \"약 6분\", seconds: 360, chars: \"약 1,800~2,200자\" },\n  xlong: { label: \"약 10분\", seconds: 600, chars: \"약 3,000~3,600자\" },\n};\n\nconst GW_YT_TONE = {\n  news: { label: \"뉴스형\", prompt: \"정확하고 신뢰감 있는 뉴스 앵커형\" },\n  friendly: { label: \"친근한 이야기\", prompt: \"옆집 선배가 들려주듯 부드럽고 친근한 이야기형 (존댓말)\" },\n  expert: { label: \"전문가 해설\", prompt: \"차분하고 논리적인 전문가 해설형\" },\n};\n\nconst GW_YT_NUMBER = {\n  hangul: { label: \"한글 읽기\", prompt: \"금액과 숫자는 TTS가 그대로 읽도록 한글 발음으로 쓰십시오. (예: 1억 5,000만 원 → 일억 오천만 원, 3.5% → 삼 점 오 퍼센트, 2026년 → 이천이십육 년)\" },\n  digit: { label: \"숫자 그대로\", prompt: \"금액과 숫자는 자막으로 보기 쉽게 아라비아 숫자로 쓰십시오. (예: 1억 5,000만 원)\" },\n};\n\nfunction gwYtSourceText(input) {\n  const src = input || {};\n  const article = src.article || {};\n  const lines = [];\n  const push = (label, value) => {\n    const text = String(value == null ? \"\" : value).trim();\n    if (text) lines.push(`[${label}] ${text}`);\n  };\n  push(\"기사 제목\", article.title);\n  push(\"기사 부제\", Array.isArray(article.subtitles) ? article.subtitles.join(\" / \") : \"\");\n  push(\"기사 본문\", article.body);\n\n  const source = src.source || {};\n  if (source.mode === \"news\" && source.news) {\n    push(\"원문 출처\", `${source.news.publisher || \"원문 언론사\"} 「${source.news.title || \"\"}」`);\n  } else if (source.mode === \"complex\" || source.mode === \"local\") {\n    push(\"자료 출처\", \"국토교통부 실거래가 공개시스템 (신고 기준) — 원고 안에서 출처를 한 번 밝힐 것\");\n  } else if (source.topic && source.topic.subject) {\n    push(\"주제\", source.topic.subject);\n  }\n  return lines.join(\"\\n\");\n}\n\n/* ══════════════════════════════════════════════════════════════\n   대본 쓰기 — AI 는 읽을 원고 전체(완성 대본)만 쓴다\n   ══════════════════════════════════════════════════════════════ */\nconst GW_YT_SCRIPT_SHAPE = `\\`\\`\\`json\n{\n  \"title\": \"유튜브 제목\",\n  \"titles\": [\"다른 제목 후보 1\", \"다른 제목 후보 2\", \"다른 제목 후보 3\"],\n  \"narration\": [\"읽을 원고 첫 문단\", \"둘째 문단\"]\n}\n\\`\\`\\``;\n\nconst GW_YT_OUTPUT = `[출력 형식]\n설명이나 인사말 없이 아래 형식의 유효한 JSON 하나만 \\`\\`\\`json 코드블록으로 출력하십시오.\n- narration 은 문단별 문자열 배열입니다. 문자열 안에 실제 줄바꿈을 넣지 마십시오.\n- 인터넷 검색을 했더라도 출처 표시(cite 기호)·각주 번호·링크·참고 문헌 목록은 본문에 넣지 마십시오. 문장만 쓰십시오.\n- titles 에는 title 과 다른 방향의 제목 후보 3개를 넣으십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n\nfunction gwBuildYtScriptPrompt(input, settings) {\n  const s = settings || {};\n  const type = GW_YT_VIDEO_TYPE[s.videoType] || GW_YT_VIDEO_TYPE.briefing;\n  const duration = GW_YT_DURATION[s.duration] || GW_YT_DURATION.short;\n  const tone = GW_YT_TONE[s.tone] || GW_YT_TONE.news;\n  const number = GW_YT_NUMBER[s.number] || GW_YT_NUMBER.hangul;\n  const source = (input && input.source) || {};\n  const isNews = source.mode === \"news\" && source.news;\n  const publisher = (isNews && source.news.publisher) || \"\";\n\n  return `당신은 생활·경제 전문 매체 \"공실뉴스\"의 유튜브 대본 작가입니다.\n아래 공실뉴스 기사의 사실만 사용해, 시청자가 끝까지 보고 싶어지는 흥미롭고 실생활에 유익한 ${type.label} 영상의 내레이션 원고를 작성하십시오.\n\n${gwYtSourceText(input)}\n\n[영상 설정]\n- 유형: ${type.label}\n- 흐름: ${type.structure}\n- 길이: ${duration.label}. 원고 전체 ${duration.chars} (소리 내어 읽는 속도 기준)\n- 말투: ${tone.prompt}\n\n[재미와 쓸모]\n- 첫 문장은 3초 안에 관심을 끄는 짧은 훅입니다. 시청자 생활과 맞닿은 질문이나 장면으로 여십시오. 낚시성 과장은 쓰지 마십시오.\n- 어려운 용어는 처음 나올 때 쉬운 말로 풀어 주십시오.\n- 사례가 필요하면 \"예를 들어 ~라고 해 볼까요\"처럼 가정한 사례임을 분명히 하십시오. 실제 인물인 것처럼 꾸미지 마십시오.\n- 끝부분에는 시청자가 바로 써먹을 수 있는 확인 요령이나 한 줄 정리를 넣으십시오.\n\n[사실 원칙]\n- 숫자·날짜·금액·기관명·인물명·제도 이름은 기사에 있는 것만, 기사와 똑같이 쓰십시오.\n- 기사에 없는 수치·통계·전망·인터뷰·후기를 만들지 마십시오.\n- \"반드시 오른다\", \"무조건 이득\" 같은 단정과 투자 권유를 하지 마십시오.\n${isNews ? `- 원고 안에서 \"${publisher} 보도에 따르면\"처럼 원문 출처를 한 번 밝히십시오.\\n` : \"\"}\n[원고 원칙]\n- ${number.prompt}\n- 소리 내어 읽기 좋게 한 문장을 짧게 끊으십시오. 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 장면 제목·자막·화면 설명·괄호 지시문·이모지는 쓰지 마십시오. 읽을 문장만 씁니다.\n- 마지막은 핵심을 정리하고 \"더 자세한 소식은 공실뉴스에서 확인할 수 있습니다.\"로 맺습니다.\n- title 은 호기심을 끌되 과장 없는 40자 이내 제목입니다.\n\n${GW_YT_OUTPUT}`;\n}\n\n/* 수정 요청 — 같은 대화에 이어 붙인다. 작업창에서 직접 고친 원고를 함께 보낸다. */\nfunction gwBuildYtRevisePrompt(full, request) {\n  const current = {\n    title: (full && full.title) || \"\",\n    narration: String((full && full.text) || \"\").split(/\\n{2,}/).map((p) => p.trim()).filter(Boolean),\n  };\n  return `아래 현재 유튜브 원고를 요청대로 고쳐 주십시오.\n\n[수정 요청]\n${String(request || \"\").trim()}\n\n[현재 원고]\n${JSON.stringify(current, null, 2)}\n\n[지킬 것]\n- 기사의 사실·숫자는 바꾸거나 새로 만들지 마십시오. 숫자 표기 방식(한글 읽기·숫자 그대로)은 현재 원고를 따르십시오.\n- 과장·투자 권유를 넣지 말고, 원문 출처를 밝혔다면 유지하십시오.\n- 읽을 문장만 쓰고, 모든 문장은 마침표·물음표·느낌표로 끝내십시오.\n- 원고 전체를 빠짐없이 다시 출력하십시오. 고친 부분만 출력하지 마십시오.\n- 설명 없이 처음과 같은 JSON 형식의 \\`\\`\\`json 코드블록 하나만 출력하십시오.\n\n${GW_YT_SCRIPT_SHAPE}`;\n}\n\n/* ── 원고 길이 — 한국어 내레이션은 1초에 약 5.5글자(공백 제외)로 읽는다고 본다 ── */\nconst GW_YT_CHARS_PER_SEC = 5.5;\n\nconst gwYtCharCount = (text) => String(text || \"\").replace(/\\s/g, \"\").length;\n\nfunction gwYtSpeechSeconds(text) {\n  return Math.round(gwYtCharCount(text) / GW_YT_CHARS_PER_SEC);\n}\n\nif (typeof module !== \"undefined\" && module.exports) {\n  module.exports = {\n    GW_YT_VIDEO_TYPE,\n    GW_YT_DURATION,\n    GW_YT_TONE,\n    GW_YT_NUMBER,\n    gwYtSourceText,\n    gwBuildYtScriptPrompt,\n    gwBuildYtRevisePrompt,\n    gwYtCharCount,\n    gwYtSpeechSeconds,\n  };\n}\n",
 "newsmaker/news-extract.js": "/* ══════════════════════════════════════════════════════════════\n   뉴스 기사 페이지에서 제목·언론사·날짜·본문 읽기\n\n   두 곳에서 쓴다.\n   1) 지금 보고 있는 탭 — 작업창이 이 파일을 그 탭에 넣고(scripting) gwNewsExtract(document) 를 부른다\n   2) 주소 붙여넣기 — 작업창이 페이지를 받아 DOMParser 로 만든 문서를 넘긴다\n\n   그래서 이 파일은 바깥 것(작업창 상태·chrome API)을 전혀 쓰지 않는다.\n   광고·기자 이메일·저작권 문구 같은 부속 글은 빼고 본문 문단만 남긴다.\n   ══════════════════════════════════════════════════════════════ */\n(function initNewsExtract(global) {\n  \"use strict\";\n\n  const MAX_BODY = 8000; // AI 에 보내는 원문 길이 한도 — 이보다 길면 앞부분만 쓴다\n  const MIN_BODY = 60;   // 정해진 본문 자리에서 이만큼은 읽혀야 본문으로 본다 (짧은 속보도 받는다)\n  const MIN_GUESS = 200; // 자리를 몰라 짐작할 때는 더 길어야 믿는다\n\n  /* 본문이 들어 있는 자리 — 많이 쓰이는 언론사 화면부터 */\n  const BODY_SELECTORS = [\n    \"#dic_area\",                      // 네이버 뉴스\n    \"#newsct_article\",\n    \"#articleBodyContents\",\n    \"#articeBody\",\n    \".article_view\",                  // 다음 뉴스\n    \"[itemprop='articleBody']\",\n    \"#article-view-content-div\",      // 지역·전문지 공통 CMS\n    \"#articleBody\", \"#article_body\", \"#articletxt\", \"#newsContent\", \"#news_body_area\",\n    \".article_body\", \".article-body\", \".article_txt\", \".art_txt\", \".news_body\", \".news_text\",\n    \".view_con\", \".story-news\", \".article-view-content\", \".article_content\", \".news-article-body\",\n    \"article\",\n  ];\n\n  /* 본문 안에서 뺄 것 */\n  const JUNK_SELECTORS = [\n    \"script\", \"style\", \"noscript\", \"iframe\", \"figure\", \"figcaption\", \"aside\", \"table\", \"form\", \"button\",\n    \".reporter\", \".byline\", \".copyright\", \".article_copy\", \".related\", \".relation\", \".ad\", \".ads\",\n    \"[class*='banner']\", \"[class*='promotion']\", \"[class*='subscribe']\", \"[class*='share']\",\n    \".img_desc\", \".photo_desc\", \".end_photo_org\", \".vod_player_wrap\",\n  ];\n\n  /* 본문 줄 가운데 부속 글로 보고 버리는 것 */\n  const JUNK_LINE = [\n    /무단\\s*(전재|복제)|재배포\\s*금지|Copyright|ⓒ|©|All rights reserved/i,\n    /^\\s*[▶▷☞■◆●※]\\s*.{0,60}$/,         // 짧은 관련기사·바로가기 줄\n    /^[\\w.+-]+@[\\w-]+\\.[\\w.]+$/,           // 기자 이메일만 있는 줄\n    /기자\\s*[\\w.+-]+@[\\w-]+\\.[\\w.]+/,      // \"홍길동 기자 abc@...\" 서명\n    /^[가-힣]{2,4}\\s?(기자|특파원|통신원)$/,  // 본문 맨 위 \"홍길동기자\" 한 줄\n    /^\\s*(사진|그래픽|영상)\\s*[=:]/,\n    /구독(하기)?|좋아요|댓글|공유하기|제보하기/,\n    /^(ADVERTISEMENT|광고|AD)$/i,               // 본문 사이 광고 자리 표시\n  ];\n\n  const BLOCK_TAGS = new Set([\n    \"P\", \"DIV\", \"SECTION\", \"ARTICLE\", \"LI\", \"UL\", \"OL\", \"H1\", \"H2\", \"H3\", \"H4\", \"H5\", \"H6\",\n    \"BLOCKQUOTE\", \"HEADER\", \"FOOTER\", \"TR\",\n  ]);\n\n  const clean = (text) => String(text || \"\").replace(/ /g, \" \").replace(/[ \\t]+/g, \" \").trim();\n\n  function meta(doc, ...names) {\n    for (const name of names) {\n      const node = doc.querySelector(`meta[property=\"${name}\"], meta[name=\"${name}\"], meta[itemprop=\"${name}\"]`);\n      const value = clean(node && node.getAttribute(\"content\"));\n      if (value) return value;\n    }\n    return \"\";\n  }\n\n  /* 화면에 그려지지 않은 문서(DOMParser)에서도 문단이 나뉘도록 직접 글을 모은다 */\n  function blockText(root) {\n    const parts = [];\n    const walk = (node) => {\n      if (node.nodeType === 3) {\n        parts.push(node.nodeValue);\n        return;\n      }\n      if (node.nodeType !== 1) return;\n      if (node.tagName === \"BR\") {\n        parts.push(\"\\n\");\n        return;\n      }\n      const block = BLOCK_TAGS.has(node.tagName);\n      if (block) parts.push(\"\\n\\n\");\n      node.childNodes.forEach(walk);\n      if (block) parts.push(\"\\n\\n\");\n    };\n    walk(root);\n    return parts.join(\"\");\n  }\n\n  function paragraphsOf(node) {\n    const copy = node.cloneNode(true);\n    JUNK_SELECTORS.forEach((selector) => {\n      try {\n        copy.querySelectorAll(selector).forEach((junk) => junk.remove());\n      } catch (_) {\n        /* 이 브라우저가 모르는 셀렉터는 건너뛴다 */\n      }\n    });\n    return blockText(copy)\n      .split(/\\n+/)\n      .map(clean)\n      .filter((line) => line.length >= 2 && !JUNK_LINE.some((rule) => rule.test(line)));\n  }\n\n  const textSize = (lines) => lines.reduce((sum, line) => sum + line.length, 0);\n\n  /* 정해진 자리에 본문이 없으면, 긴 문단을 가장 많이 품은 칸을 본문으로 본다 */\n  function guessBodyNode(doc) {\n    let best = null;\n    let bestScore = 0;\n    doc.querySelectorAll(\"div, section, article, main\").forEach((node) => {\n      const score = Array.from(node.children)\n        .filter((child) => child.tagName === \"P\")\n        .reduce((sum, p) => {\n          const size = clean(p.textContent).length;\n          return size >= 40 ? sum + size : sum;\n        }, 0);\n      if (score > bestScore) {\n        best = node;\n        bestScore = score;\n      }\n    });\n    return bestScore >= MIN_GUESS ? best : null;\n  }\n\n  function findBody(doc) {\n    for (const selector of BODY_SELECTORS) {\n      const node = doc.querySelector(selector);\n      if (!node) continue;\n      const lines = paragraphsOf(node);\n      if (textSize(lines) >= MIN_BODY) return lines;\n    }\n    const guessed = guessBodyNode(doc);\n    return guessed ? paragraphsOf(guessed) : [];\n  }\n\n  /* 언론사 이름: 포털 언론사 로고 → 사이트 이름 → 기사 작성자 칸 순서.\n     네이버·다음은 사이트 이름이 포털이라 건너뛰고 작성자(언론사) 칸을 쓴다.\n     언론사 누리집은 작성자 칸에 기자 이름이 들어 있는 곳이 많아(연합뉴스 등) 사이트 이름을 먼저 본다. */\n  function findPublisher(doc, url) {\n    const author = meta(doc, \"og:article:author\", \"article:author\").split(\"|\")[0].trim();\n    const logo = doc.querySelector(\".media_end_head_top_logo img[alt], .press_logo img[alt], .media_end_head_top_logo_img[alt]\");\n    const candidates = [\n      clean(logo && logo.getAttribute(\"alt\")),\n      meta(doc, \"og:site_name\", \"twitter:site\", \"application-name\"),\n      author && !/^https?:/i.test(author) && !/기자/.test(author) ? author : \"\",\n    ];\n    const found = candidates.find((name) => name && !/^(네이버|NAVER|다음|Daum)(\\s*뉴스)?$/i.test(name));\n    if (found) return found.replace(/^@/, \"\");\n    try {\n      return new URL(url).hostname.replace(/^www\\./, \"\");\n    } catch (_) {\n      return \"\";\n    }\n  }\n\n  function findDate(doc) {\n    const stamp = doc.querySelector(\"[data-date-time], time[datetime]\");\n    return (\n      meta(doc, \"article:published_time\", \"og:regDate\", \"pubdate\", \"publish-date\", \"datePublished\", \"date\") ||\n      clean(stamp && (stamp.getAttribute(\"data-date-time\") || stamp.getAttribute(\"datetime\")))\n    );\n  }\n\n  function findTitle(doc) {\n    const h1 = doc.querySelector(\"h2.media_end_head_headline, h1, h2#title_area\");\n    return (\n      meta(doc, \"og:title\", \"twitter:title\") ||\n      clean(h1 && h1.textContent) ||\n      clean(doc.title)\n    ).replace(/\\s*[|:\\-–]\\s*(네이버|다음)?\\s*뉴스\\s*$/, \"\");\n  }\n\n  /* 제목 끝의 \" - 언론사\" · \" | 언론사\" 꼬리를 뗀다 */\n  function stripPublisherTail(title, publisher) {\n    if (!publisher) return title;\n    const escaped = publisher.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n    return title.replace(new RegExp(`\\\\s*[-|:–]\\\\s*${escaped}\\\\s*$`), \"\").trim() || title;\n  }\n\n  /* 첫 줄의 \"(서울=연합뉴스) 홍길동 기자 =\" 같은 발신 머리를 뗀다 */\n  const DATELINE = /^\\s*[(\\[][^()[\\]]{1,20}=[^()[\\]]{1,20}[)\\]]\\s*([^=]{1,25}(기자|특파원|통신원)\\s*=\\s*)?/;\n\n  function gwNewsExtract(doc, href) {\n    try {\n      const url = String(href || (doc.location && doc.location.href) || \"\");\n      const publisher = findPublisher(doc, url);\n      const title = stripPublisherTail(findTitle(doc), publisher);\n      const lines = findBody(doc);\n      if (lines.length) lines[0] = lines[0].replace(DATELINE, \"\").trim() || lines[0];\n      let body = lines.join(\"\\n\\n\");\n      const truncated = body.length > MAX_BODY;\n      if (truncated) body = body.slice(0, MAX_BODY).replace(/\\s+\\S*$/, \"\") + \" …\";\n\n      if (!title || body.length < MIN_BODY) {\n        return {\n          ok: false,\n          reason: \"이 페이지에서 뉴스 본문을 찾지 못했습니다. 뉴스 기사 한 건이 열린 화면에서 다시 눌러 주세요. \" +\n            \"안 되면 [주제 입력]으로 바꿔 기사 내용을 직접 붙여넣어 주세요.\",\n        };\n      }\n      return {\n        ok: true,\n        news: {\n          title,\n          publisher,\n          publishedAt: findDate(doc),\n          url,\n          body,\n          truncated,\n        },\n      };\n    } catch (e) {\n      return { ok: false, reason: \"뉴스 페이지를 읽다가 오류가 났습니다: \" + (e && e.message ? e.message : String(e)) };\n    }\n  }\n\n  /* 받은 HTML 바이트를 글로 바꾼다 — EUC-KR 로 된 언론사 페이지가 아직 많다 */\n  function decodeHtml(buffer, contentType) {\n    const bytes = new Uint8Array(buffer);\n    const pick = (text) => {\n      const hit = /charset\\s*=\\s*[\"']?\\s*([\\w-]+)/i.exec(text || \"\");\n      return hit ? hit[1].toLowerCase() : \"\";\n    };\n    let charset = pick(contentType);\n    if (!charset) {\n      const head = new TextDecoder(\"ascii\").decode(bytes.slice(0, 4096));\n      charset = pick(head);\n    }\n    if (/^(ks_c_5601-1987|euc-kr|cp949|x-windows-949)$/.test(charset)) charset = \"euc-kr\";\n    try {\n      return new TextDecoder(charset || \"utf-8\").decode(bytes);\n    } catch (_) {\n      return new TextDecoder(\"utf-8\").decode(bytes);\n    }\n  }\n\n  const api = { gwNewsExtract, decodeHtml, MAX_BODY };\n  global.GWNewsExtract = api;\n  global.gwNewsExtract = gwNewsExtract;\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n})(typeof globalThis !== \"undefined\" ? globalThis : self);\n"
};
